## 2. Plugin Registry

### Registry Interface

```typescript
// src/plugin-system/registry.ts

export interface PluginManifest {
  apiVersion: string;
  metadata: {
    id: string;
    name: string;
    version: string;
    author: string;
    [key: string]: any;
  };
  requirements: {
    minFrameworkVersion: string;
    maxFrameworkVersion?: string;
    requiredAPIVersions: string[];
  };
  capabilities: Capability[];
  dependencies: Dependency[];
  permissions: Permission[];
  hooks?: Record<string, string>;
  main: string;
  types?: string;
  stability: "stable" | "beta" | "alpha";
  security: SecurityMetadata;
}

export interface Capability {
  type: "datasource" | "visualization" | "transformer" | "export" | "custom";
  id: string;
  exports: string[];
  config: ConfigSchema;
}

export interface Permission {
  resource: "network" | "filesystem" | "memory" | "cpu" | "api";
  actions: string[];
  scope?: string;
  limit?: string;
}

export interface Dependency {
  id: string;
  versionRange: string;
  required: boolean;
}

export interface PluginMetadata {
  manifest: PluginManifest;
  loadedAt: Date;
  state: "loading" | "loaded" | "active" | "failed" | "unloading" | "unloaded";
  error?: Error;
  instance?: PluginInstance;
  capabilities: Map<string, Capability>;
}

export class PluginRegistry {
  private registry: Map<string, PluginMetadata> = new Map();
  private capabilityIndex: Map<string, Set<string>> = new Map(); // capability type -> plugin ids
  private versionConstraints = new VersionResolver();

  /**
   * Register a plugin from its manifest
   */
  async register(manifest: PluginManifest): Promise<void> {
    if (this.registry.has(manifest.metadata.id)) {
      throw new Error(`Plugin ${manifest.metadata.id} already registered`);
    }

    // Validate manifest schema
    await this.validateManifest(manifest);

    // Check version compatibility
    this.versionConstraints.assertCompatible(manifest.requirements);

    // Check dependencies exist
    for (const dep of manifest.dependencies || []) {
      if (dep.required && !this.hasPlugin(dep.id, dep.versionRange)) {
        throw new Error(
          `Required dependency ${dep.id}@${dep.versionRange} not found`
        );
      }
    }

    const metadata: PluginMetadata = {
      manifest,
      loadedAt: new Date(),
      state: "loading",
      capabilities: new Map(
        manifest.capabilities.map((c) => [c.id, c])
      ),
    };

    this.registry.set(manifest.metadata.id, metadata);

    // Index capabilities
    for (const cap of manifest.capabilities) {
      const key = cap.type;
      if (!this.capabilityIndex.has(key)) {
        this.capabilityIndex.set(key, new Set());
      }
      this.capabilityIndex.get(key)!.add(manifest.metadata.id);
    }
  }

  /**
   * Get plugin by ID, optionally with version constraint
   */
  getPlugin(
    id: string,
    versionRange?: string
  ): PluginMetadata | undefined {
    const metadata = this.registry.get(id);
    if (!metadata) return undefined;

    if (
      versionRange &&
      !this.versionConstraints.satisfies(metadata.manifest.metadata.version, versionRange)
    ) {
      return undefined;
    }

    return metadata;
  }

  /**
   * List all plugins providing a capability type
   */
  getCapabilityProviders(
    type: "datasource" | "visualization" | "transformer" | "export"
  ): PluginMetadata[] {
    const pluginIds = this.capabilityIndex.get(type) || new Set();
    return Array.from(pluginIds)
      .map((id) => this.registry.get(id)!)
      .filter((m) => m.state === "active");
  }

  /**
   * Query plugins by capability and config schema
   */
  queryCapabilities(
    type: string,
    predicate?: (cap: Capability) => boolean
  ): Array<{ plugin: PluginMetadata; capability: Capability }> {
    const results: Array<{ plugin: PluginMetadata; capability: Capability }> = [];

    for (const [, metadata] of this.registry) {
      if (metadata.state !== "active") continue;

      for (const cap of metadata.capabilities.values()) {
        if (cap.type === type && (!predicate || predicate(cap))) {
          results.push({ plugin: metadata, capability: cap });
        }
      }
    }

    return results;
  }

  /**
   * List all registered plugins
   */
  listPlugins(filter?: { state?: string; type?: string }): PluginMetadata[] {
    return Array.from(this.registry.values()).filter((m) => {
      if (filter?.state && m.state !== filter.state) return false;
      if (
        filter?.type &&
        !Array.from(m.capabilities.values()).some((c) => c.type === filter.type)
      ) {
        return false;
      }
      return true;
    });
  }

  /**
   * Update plugin state
   */
  setState(pluginId: string, state: PluginMetadata["state"]): void {
    const metadata = this.registry.get(pluginId);
    if (metadata) {
      metadata.state = state;
    }
  }

  /**
   * Unregister a plugin
   */
  unregister(pluginId: string): void {
    const metadata = this.registry.get(pluginId);
    if (!metadata) return;

    // Remove from capability index
    for (const cap of metadata.capabilities.values()) {
      this.capabilityIndex.get(cap.type)?.delete(pluginId);
    }

    this.registry.delete(pluginId);
  }

  private async validateManifest(manifest: PluginManifest): Promise<void> {
    // JSON Schema validation
    const validator = new ManifestValidator();
    const errors = await validator.validate(manifest);
    if (errors.length > 0) {
      throw new ValidationError(`Manifest validation failed: ${errors.join(", ")}`);
    }
  }
}
```

