## 3. Plugin Lifecycle Manager

### Lifecycle States

```
┌────────┐
│ init   │ (manifest loaded)
│        │
└───┬────┘
    │
    ▼
┌────────┐
│loading │ (loading phase, before hooks execute)
│        │
└───┬────┘
    │
    ▼
┌────────────────────────────────┐
│ load hook executed             │ (onLoad)
│ (plugin can initialize)        │
└───┬────────────────────────────┘
    │
    ▼
┌────────┐
│ loaded │ (in memory, ready)
│        │
└───┬────┘
    │
    ▼
┌────────┐
│ active │ (serving requests)
│        │
└───┬────┘
    │ (reload requested)
    ├──────────────────────┐
    │                      │
    ▼                      │
┌──────────┐               │
│ unloading│               │
└───┬──────┘               │
    │                      │
    ▼                      │
┌────────────────────────┐ │
│ unload hook executed   │◄─┘
│ (cleanup)              │
└───┬────────────────────┘
    │
    ▼
┌──────────┐
│unloaded  │
└──────────┘
```

### Lifecycle Implementation

```typescript
// src/plugin-system/lifecycle.ts

export type PluginState =
  | "init"
  | "loading"
  | "loaded"
  | "active"
  | "unloading"
  | "unloaded"
  | "failed";

export interface PluginInstance {
  id: string;
  manifest: PluginManifest;
  exports: Record<string, any>;
  context: PluginContext;
}

export interface PluginContext {
  // Framework-provided APIs
  api: VersionedAPI;
  config: PluginConfig;
  logger: Logger;
  cache: CacheStore;

  // Lifecycle info
  state: PluginState;
  version: string;

  // Permission checker
  checkPermission(resource: string, action: string): boolean;
}

export class PluginLifecycleManager {
  private registry: PluginRegistry;
  private sandbox: SandboxExecutor;
  private hooks: Map<string, PluginHookHandler[]> = new Map();
  private activeInstances: Map<string, PluginInstance> = new Map();

  constructor(registry: PluginRegistry, sandbox: SandboxExecutor) {
    this.registry = registry;
    this.sandbox = sandbox;
  }

  /**
   * Load a plugin: parse manifest, validate, instantiate, execute onLoad hook
   */
  async load(pluginPath: string): Promise<PluginInstance> {
    const manifestPath = join(pluginPath, "plugin.yaml");
    const manifest = await this.parseManifest(manifestPath);

    const metadata = this.registry.register(manifest);
    this.registry.setState(manifest.metadata.id, "loading");

    try {
      // Load plugin code in sandbox
      const pluginCode = await readFile(join(pluginPath, manifest.main), "utf-8");

      const context: PluginContext = {
        api: new VersionedAPI(manifest.requirements.requiredAPIVersions),
        config: await this.loadConfig(manifest.metadata.id),
        logger: new ScopedLogger(manifest.metadata.id),
        cache: new PluginCacheStore(manifest.metadata.id),
        state: "loading",
        version: manifest.metadata.version,
        checkPermission: (resource, action) =>
          this.checkPermission(manifest.metadata.id, resource, action),
      };

      const exports = await this.sandbox.execute(pluginCode, context, {
        permissions: manifest.permissions,
        memoryLimit: this.parseLimit(manifest.permissions, "memory"),
        cpuLimit: this.parseLimit(manifest.permissions, "cpu"),
      });

      const instance: PluginInstance = {
        id: manifest.metadata.id,
        manifest,
        exports,
        context,
      };

      this.activeInstances.set(manifest.metadata.id, instance);
      this.registry.setState(manifest.metadata.id, "loaded");

      // Execute load hook
      if (manifest.hooks?.load) {
        const [moduleName, exportName] = manifest.hooks.load.split(".");
        const hookFn = exports[exportName];
        if (hookFn) {
          await this.sandbox.executeHook(
            hookFn,
            { type: "load", instance },
            { timeout: 30000 }
          );
        }
      }

      this.registry.setState(manifest.metadata.id, "active");
      return instance;
    } catch (error) {
      this.registry.setState(manifest.metadata.id, "failed");
      throw new PluginLoadError(
        `Failed to load plugin ${manifest.metadata.id}: ${error.message}`
      );
    }
  }

  /**
   * Unload a plugin: execute onUnload hook, cleanup
   */
  async unload(pluginId: string): Promise<void> {
    const instance = this.activeInstances.get(pluginId);
    if (!instance) {
      throw new Error(`Plugin ${pluginId} not loaded`);
    }

    this.registry.setState(pluginId, "unloading");

    try {
      // Execute unload hook
      if (instance.manifest.hooks?.unload) {
        const [moduleName, exportName] = instance.manifest.hooks.unload.split(".");
        const hookFn = instance.exports[exportName];
        if (hookFn) {
          await this.sandbox.executeHook(
            hookFn,
            { type: "unload", instance },
            { timeout: 10000 }
          );
        }
      }

      // Cleanup
      await instance.context.cache.clear();
      this.activeInstances.delete(pluginId);
      this.registry.setState(pluginId, "unloaded");
    } catch (error) {
      this.registry.setState(pluginId, "failed");
      throw new PluginUnloadError(
        `Failed to unload plugin ${pluginId}: ${error.message}`
      );
    }
  }

  /**
   * Reload a plugin: unload and reload
   */
  async reload(pluginId: string): Promise<PluginInstance> {
    const instance = this.activeInstances.get(pluginId);
    if (!instance) {
      throw new Error(`Plugin ${pluginId} not loaded`);
    }

    const pluginPath = instance.manifest.main;
    await this.unload(pluginId);
    return this.load(pluginPath);
  }

  /**
   * Subscribe to plugin lifecycle events
   */
  on(
    event: "load" | "unload" | "reload" | "error",
    handler: (evt: PluginEvent) => void
  ): void {
    if (!this.hooks.has(event)) {
      this.hooks.set(event, []);
    }
    this.hooks.get(event)!.push(handler);
  }

  /**
   * Get active plugin instance
   */
  getInstance(pluginId: string): PluginInstance | undefined {
    return this.activeInstances.get(pluginId);
  }

  private async parseManifest(path: string): Promise<PluginManifest> {
    const content = await readFile(path, "utf-8");
    return YAML.parse(content);
  }

  private checkPermission(
    pluginId: string,
    resource: string,
    action: string
  ): boolean {
    const instance = this.activeInstances.get(pluginId);
    if (!instance) return false;

    const permissions = instance.manifest.permissions || [];
    return permissions.some(
      (p) => p.resource === resource && p.actions.includes(action)
    );
  }
}
