## 4. Sandboxed Execution Boundary

### Sandbox Design

Plugins run in **isolated contexts** with resource limits:

```typescript
// src/plugin-system/sandbox.ts

export interface SandboxOptions {
  permissions: Permission[];
  memoryLimit?: string;        // e.g., "512MB"
  cpuLimit?: string;           // e.g., "50%"
  timeout?: number;            // milliseconds
  allowedModules?: string[];   // Whitelist of npm packages
}

export class SandboxExecutor {
  /**
   * Execute plugin code in an isolated context
   */
  async execute(
    code: string,
    context: PluginContext,
    options: SandboxOptions
  ): Promise<Record<string, any>> {
    const vm = new WorkerThread(code, {
      env: this.buildIsolatedEnv(context, options),
      timeout: options.timeout || 30000,
      memoryLimit: this.parseMemory(options.memoryLimit || "512MB"),
    });

    try {
      const result = await vm.run({
        contextData: context,
        permissionChecker: (resource: string, action: string) =>
          this.checkPermission(options.permissions, resource, action),
      });

      return result;
    } catch (error) {
      throw new SandboxExecutionError(
        `Plugin execution failed: ${error.message}`
      );
    } finally {
      await vm.terminate();
    }
  }

  /**
   * Execute a hook function with timeout
   */
  async executeHook(
    hookFn: Function,
    event: PluginEvent,
    options: { timeout?: number } = {}
  ): Promise<void> {
    const timeout = options.timeout || 10000;

    try {
      await Promise.race([
        hookFn(event),
        this.delay(timeout).then(() => {
          throw new Error(`Hook timeout after ${timeout}ms`);
        }),
      ]);
    } catch (error) {
      throw new HookExecutionError(`Hook execution failed: ${error.message}`);
    }
  }

  /**
   * Enforce network permissions: intercept all HTTP calls
   */
  private buildIsolatedEnv(
    context: PluginContext,
    options: SandboxOptions
  ): Record<string, any> {
    const permissionChecker = (resource: string, action: string): boolean => {
      return this.checkPermission(options.permissions, resource, action);
    };

    return {
      // Safe APIs only
      console: context.logger,

      // Restricted fetch with permission check
      fetch: async (url: string, init?: RequestInit) => {
        if (!permissionChecker("network", "http:GET")) {
          throw new Error("Network access denied by sandbox");
        }
        // Additional scope checking
        if (!this.urlMatchesScope(url, options.permissions)) {
          throw new Error(`URL ${url} not in permitted scope`);
        }
        return globalThis.fetch(url, init);
      },

      // Restricted filesystem with permission check
      fs: {
        readFile: async (path: string) => {
          if (!permissionChecker("filesystem", "read")) {
            throw new Error("Filesystem read denied");
          }
          if (!this.pathInScope(path, options.permissions)) {
            throw new Error(`Path ${path} not in permitted scope`);
          }
          return fs.promises.readFile(path);
        },
      },

      // API context
      reportingAPI: context.api.getExports(),
    };
  }

  private checkPermission(
    permissions: Permission[],
    resource: string,
    action: string
  ): boolean {
    return permissions.some(
      (p) => p.resource === resource && p.actions.includes(action)
    );
  }

  private urlMatchesScope(url: string, permissions: Permission[]): boolean {
    const netPerm = permissions.find((p) => p.resource === "network");
    if (!netPerm?.scope) return true; // No scope = all allowed

    return new URL(url).origin.match(new RegExp(netPerm.scope)) !== null;
  }

  private pathInScope(path: string, permissions: Permission[]): boolean {
    const fsPerm = permissions.find((p) => p.resource === "filesystem");
    if (!fsPerm?.scope) return true;

    return path.startsWith(fsPerm.scope);
  }

  private parseMemory(str: string): number {
    const match = str.match(/^(\d+)(MB|GB|KB)$/);
    if (!match) throw new Error(`Invalid memory limit: ${str}`);

    const [, num, unit] = match;
    const multipliers = { KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 };
    return parseInt(num) * multipliers[unit as keyof typeof multipliers];
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
```

### Security Guarantees

| Threat | Mitigation |
|--------|-----------|
| Memory exhaustion | `WorkerThread` memory limit, periodic GC |
| Infinite loops | Execution timeout (default 30s) |
| Network scanning | Permission check + scope validation |
| File system access | Path whitelist, permission check |
| Process spawning | Disabled in sandbox; `child_process` not available |
| Eval/Function() | Disabled; only transpiled code in VM |
| Global state mutation | WorkerThread isolation |

