## 5. Versioned API Contract

### API Versioning Strategy

Plugins declare which **API versions** they use. This allows the framework to evolve without breaking plugins.

```typescript
// src/plugin-system/api.ts

/**
 * Data API v2 - Query and transform data
 */
export interface DataAPIv2 {
  /**
   * Query data from datasources
   * @param query - Query definition
   * @param options - Query options (filters, limits, etc.)
   * @returns Promise<QueryResult>
   */
  query(query: QueryDefinition, options?: QueryOptions): Promise<QueryResult>;

  /**
   * Aggregate data
   * @param aggregation - Aggregation pipeline
   * @returns Promise<AggregationResult>
   */
  aggregate(aggregation: Aggregation): Promise<AggregationResult>;

  /**
   * Transform dataset
   * @param transform - Transformation rule
   * @returns Promise<Dataset>
   */
  transform(transform: Transform): Promise<Dataset>;

  /**
   * Get datasource metadata
   */
  describeDatasource(id: string): Promise<DatasourceMetadata>;
}

/**
 * Data API v1 - Legacy, deprecated
 * @deprecated Use DataAPIv2 instead
 */
export interface DataAPIv1 {
  fetch(source: string, query: string): Promise<any>;
}

/**
 * UI API v1 - User notifications and interactions
 */
export interface UIAPIv1 {
  /**
   * Notify user
   * @param level - 'info' | 'warn' | 'error'
   * @param message - Notification message
   * @param options - Display options (timeout, action, etc.)
   */
  notify(
    level: "info" | "warn" | "error",
    message: string,
    options?: NotifyOptions
  ): void;

  /**
   * Prompt user for input
   */
  prompt(title: string, schema: JSONSchema): Promise<Record<string, any>>;

  /**
   * Open modal dialog
   */
  modal(config: ModalConfig): Promise<any>;
}

/**
 * Versioned API container
 */
export class VersionedAPI {
  private apis: Map<string, Map<number, any>> = new Map();

  constructor(requestedVersions: string[]) {
    // Register available APIs and versions
    this.registerAPI("data", {
      2: new DataAPIv2Impl(),
      1: new DataAPIv1Impl(), // deprecated
    });

    this.registerAPI("ui", {
      1: new UIAPIv1Impl(),
    });

    // Validate requested versions are available
    for (const versionStr of requestedVersions) {
      const [apiName, versionNum] = versionStr.split(".");
      if (!this.apis.has(apiName)) {
        throw new Error(`Unknown API: ${apiName}`);
      }
      const versions = this.apis.get(apiName)!;
      const version = parseInt(versionNum);
      if (!versions.has(version)) {
        throw new Error(
          `API ${apiName} version ${version} not available. Available: ${Array.from(versions.keys()).join(", ")}`
        );
      }
    }
  }

  /**
   * Get API implementation by version
   */
  getAPI<T>(name: string, version: number): T {
    const versions = this.apis.get(name);
    if (!versions) throw new Error(`Unknown API: ${name}`);

    const api = versions.get(version);
    if (!api) throw new Error(`API ${name} version ${version} not found`);

    return api;
  }

  /**
   * Get all exported APIs for plugin context
   */
  getExports(): Record<string, any> {
    return {
      data: this.getAPI("data", 2), // Default to latest
      ui: this.getAPI("ui", 1),
    };
  }

  private registerAPI(
    name: string,
    versions: Record<number, any>
  ): void {
    this.apis.set(name, new Map(Object.entries(versions).map(([v, api]) => [parseInt(v), api])));
  }
}

/**
 * Compatibility helpers for plugins using older APIs
 */
export function provideDeprecationWarnings(pluginId: string, manifest: PluginManifest): void {
  const warnings: string[] = [];

  if (manifest.requirements.requiredAPIVersions.includes("data.v1")) {
    warnings.push(
      `⚠️  Plugin uses deprecated data.v1 API. Migrate to data.v2 by Q4 2026. See migration guide: https://docs.company.com/migrate-data-v1-v2`
    );
  }

  if (warnings.length > 0) {
    console.warn(`Plugin ${pluginId} deprecation warnings:\n${warnings.join("\n")}`);
  }
}
```

### API Evolution Policy

1. **New features**: Add to latest version
2. **Breaking changes**: Increment major version (e.g., data.v2 → data.v3)
3. **Deprecation timeline**: Support N-1 versions for 12 months minimum
4. **Versioning**: Use semantic versioning (major.minor.patch)

**Example: Upgrading from data.v1 to data.v2**

```diff
// plugin.yaml
- requiredAPIVersions: ["data.v1", "ui.v1"]
+ requiredAPIVersions: ["data.v2", "ui.v1"]

// index.ts
- const results = await reportingAPI.data.fetch("sales", "SELECT * FROM deals");
+ const results = await reportingAPI.data.query({
+   datasource: "sales",
+   table: "deals",
+ });
```

