capabilities:
  - type: "export"
    id: "slack"
    exports: ["SlackExporter"]
    config:
      schema:
        properties:
          webhookUrl:
            type: "string"
            description: "Slack webhook URL"
            required: true
            sensitive: true
          channel:
            type: "string"
            description: "Target channel"
            required: false

dependencies:
  - id: "com.company.security.oauth2"
    versionRange: ">=1.0.0"
    required: true

permissions:
  - resource: "network"
    actions: ["http:POST"]
    scope: "https://hooks.slack.com/*"
  - resource: "api"
    actions: ["data.v2:query", "ui.v1:notify"]

hooks:
  load: "index.onLoad"
  unload: "index.onUnload"

main: "dist/index.js"
types: "dist/index.d.ts"
security:
  auditedAt: "2026-09-01"
  auditedBy: "security-team@company.com"
