```typescript
// slack-export-plugin/src/index.ts
import type { PluginContext, ExportDefinition, Dataset } from "@reporting/plugin-api";

export async function onLoad(event: any) {
  console.log("Slack exporter loaded");
}

export async function onUnload(event: any) {
  console.log("Slack exporter unloaded");
}

export class SlackExporter {
  constructor(private context: PluginContext) {}

  /**
   * Export dataset to Slack
   */
  async export(dataset: Dataset, config: any): Promise<{ success: boolean; url?: string }> {
    const webhookUrl = config.webhookUrl;
    if (!this.context.checkPermission("network", "http:POST")) {
      throw new Error("Network access denied");
    }

    try {
      // Format data for Slack
      const message = this.formatForSlack(dataset);

      // Send to Slack (permission checked by sandbox)
      const response = await fetch(webhookUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(message),
      });

      if (!response.ok) {
        throw new Error(`Slack API error: ${response.statusText}`);
      }

      // Notify user
      this.context.api.ui.notify("info", "Report sent to Slack", {
        timeout: 3000,
      });

      return { success: true };
    } catch (error) {
      this.context.logger.error(`Export failed: ${error.message}`);
      throw error;
    }
  }

  private formatForSlack(dataset: Dataset): Record<string, any> {
    // Convert dataset to Slack message format
    const blocks = [
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*Report Export*\n${dataset.name}`,
        },
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `\`\`\`${JSON.stringify(dataset.rows.slice(0, 10), null, 2)}\`\`\``,
        },
      },
    ];

    return { blocks };
  }
}
```

