## 4. Plugin API Contract & Versioning

### 4.1 Versioned API Structure

The core API is versioned to allow gradual evolution without breaking existing plugins:

```typescript
// API v1.0 - Base contract (all plugins must implement)
interface ReportingPluginAPI_v1 {
  // Metadata
  getManifest(): PluginManifest;
  getVersion(): string;

  // Capabilities
  getCapabilities(): string[];

  // Lifecycle
  initialize(config: PluginConfig): Promise<void>;
  shutdown(): Promise<void>;

  // Health
  healthCheck(): Promise<HealthStatus>;
}

// API v1.1 - Added incremental updates (backward compatible)
interface ReportingPluginAPI_v1_1 extends ReportingPluginAPI_v1 {
  onHotReload(previousState: PluginState): Promise<void>;
}

// API v2.0 - Breaking changes (separate instance)
interface ReportingPluginAPI_v2 extends ReportingPluginAPI_v1_1 {
  // New features in v2
  async execute(request: PluginRequest): Promise<PluginResponse>;
  // v1-style methods are REMOVED (breaking change)
}

// Plugin implementation targets ONE version
interface DataSourcePlugin extends ReportingPluginAPI_v1_1 {
  query(sql: string): Promise<QueryResult>;
  describe(): Promise<SchemaDescription>;
}

// Runtime bridges across API versions
class APIVersionBridge {
  // Convert v1 calls to v2 internally
  static adaptV1ToV2(v1Api: ReportingPluginAPI_v1): ReportingPluginAPI_v2 {
    return {
      getManifest: () => v1Api.getManifest(),
      // ... implement v2 by wrapping v1 methods
    };
  }
}
```

### 4.2 API Exposure

Each sandboxed plugin context receives only the APIs it declared:

```typescript
// Request model
interface APIRequest {
  version: "1.0" | "1.1" | "2.0"; // Plugin declares in manifest
  features: string[]; // e.g., ["datasources", "reporting"]
  scope: {
    permissions: string[];
    environment: Record<string, string>;
  };
}

// Provided APIs (based on request)
interface InjectedAPIs {
  // Always available
  logger: Logger;
  metrics: MetricsCollector;

  // Conditional on `features: ["datasources"]`
  datasources?: {
    query(sql: string): Promise<QueryResult>;
    list(): Promise<DataSource[]>;
  };

  // Conditional on `features: ["reporting"]`
  reporting?: {
    generateReport(spec: ReportSpec): Promise<Report>;
    saveReport(report: Report): Promise<string>;
  };

  // Conditional on `features: ["permissions"]`
  permissions?: {
    check(action: string, resource: string): Promise<boolean>;
    getCurrentUser(): Promise<User>;
  };
}
```

### 4.3 Version Negotiation

```typescript
function negotiateAPIVersion(
  manifest: PluginManifest
): { version: string; apis: InjectedAPIs } {
  const supported = ["1.0", "1.1", "2.0"];
  const required = manifest.api.required;

  // Find highest compatible version
  const compatible = supported.filter(v => 
    semverInRange(v, required.minimum, required.maximum)
  );

  if (!compatible.length) {
    throw new IncompatiblePluginError(
      `No compatible API version. Required: ${required.minimum}-${required.maximum}, ` +
      `supported: ${supported.join(", ")}`
    );
  }

  const selectedVersion = compatible[compatible.length - 1];
  const apis = buildAPIs(selectedVersion, manifest.api.required.features);

  return { version: selectedVersion, apis };
}
```

## 5. Lifecycle Hooks

### 5.1 Plugin Lifecycle States

```
    ┌─────────────────────────────────────────┐
    │        MANIFEST_VALIDATED               │
    └────────────┬────────────────────────────┘
                 │ register()
                 ▼
    ┌─────────────────────────────────────────┐
    │        REGISTERED (on disk)             │
    └────────────┬────────────────────────────┘
                 │ load()
                 ▼
    ┌─────────────────────────────────────────┐
    │        LOADING (resources acquired)     │
    └────────────┬───────────┬────────────────┘
                 │           │ [Error]
                 ▼           ▼
    ┌──────────────────┐  ┌─────────────────┐
    │     ACTIVE       │  │   LOAD_ERROR    │
    │(initialized)     │  │  (quarantined)  │
    └────────┬─────────┘  └─────────────────┘
             │
    ┌────────┴─────────────┐
    │   reload() request   │
    ▼                      ▼
┌──────────┐          ┌──────────────────┐
│ UNLOADING│          │ ACTIVE (v2)      │
└──────────┘          └──────────────────┘
    │
    ▼
┌──────────────────────────────────────────┐
│        UNLOADED (resources released)     │
└──────────────────────────────────────────┘
```

### 5.2 Lifecycle Hooks Interface

```typescript
interface PluginLifecycleHooks {
  // Called once during module load, before initialize
  // Use for: setup, dependencies, module-level state
  onLoad?(): Promise<void>;

  // Called when plugin becomes active (first time or after reload)
  // Arguments: persisted state from previous instance
  // Use for: connecting to databases, starting workers, initializing state
  initialize(config: PluginConfig, previousState?: PluginState): Promise<void>;

  // Called periodically to verify health
  // Should respond within 5 seconds
  healthCheck(): Promise<HealthStatus>;

  // Called when hot-reload requested
  // Arguments: state to serialize before unload
  // Return: state to pass to initialize() in new instance
  onBeforeUnload?(): Promise<PluginState>;

  // Called after unload, new instance is initialize(d)
  // Use for: cleanup after reload, migration logic
  onAfterReload?(previousState: PluginState): Promise<void>;

  // Called when plugin is permanently disabled
  // Use for: releasing resources, closing connections
  shutdown(): Promise<void>;

  // Called when errors occur in sandbox
  // Use for: logging, alerting, recovery attempts
  onError(error: PluginError): Promise<void>;

  // Called when permission is denied at runtime
  onPermissionDenied(permission: string, context: string): Promise<void>;
}

// Example implementation
class MyDataSourcePlugin implements ReportingPluginAPI_v1_1 {
  private connection: DatabaseConnection;

  async initialize(config: PluginConfig) {
    this.connection = await DatabaseConnection.create(config.dbUrl);
    console.log("DataSource plugin initialized");
  }

  async onBeforeUnload(): Promise<PluginState> {
    return {
      lastQueryTime: Date.now(),
      activeConnections: this.connection.activeCount()
    };
  }

  async onAfterReload(previous: PluginState) {
    console.log(`Reloaded after ${Date.now() - previous.lastQueryTime}ms`);
  }

  async shutdown() {
    await this.connection.close();
  }

  async healthCheck(): Promise<HealthStatus> {
    const canConnect = await this.connection.ping();
    return {
      status: canConnect ? "healthy" : "unhealthy",
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };
  }
}
```

### 5.3 Hot Reload Contract

```typescript
interface HotReloadManager {
  // Request graceful reload
  reload(pluginId: string, options?: ReloadOptions): Promise<void>;

  // State preservation
  captureState(instance: PluginInstance): Promise<PluginState>;
  restoreState(newInstance: PluginInstance, state: PluginState): Promise<void>;

  // Rollback on failure
  rollbackToVersion(pluginId: string, version: string): Promise<void>;

  // Events
  on("reload:start", (id: string) => void): void;
  on("reload:success", (id: string) => void): void;
  on("reload:error", (id: string, error: Error) => void): void;
}

// Hot reload execution flow
async function performHotReload(registry: PluginRegistry, pluginId: string) {
  const current = registry.get(pluginId);
  if (!current?.instance) return;

  // 1. Capture state from current instance
  let previousState: PluginState | undefined;
  if (current.instance.onBeforeUnload) {
    previousState = await current.instance.onBeforeUnload();
  }

  // 2. Unload old instance
  try {
    await current.instance.shutdown();
  } catch (e) {
    console.error("Error during shutdown:", e);
  }

  // 3. Load new module
  const newModule = reloadModule(current.path);

  // 4. Create new instance in fresh sandbox
  const newInstance = createPluginInstance(newModule, current.manifest);

  // 5. Initialize with previous state
  try {
    await newInstance.initialize(current.config, previousState);
    if (previousState && newInstance.onAfterReload) {
      await newInstance.onAfterReload(previousState);
    }
  } catch (e) {
    // Reload failed - restore old instance
    await rollbackReload(current);
    throw e;
  }

  // 6. Atomic swap
  registry.updateInstance(pluginId, newInstance);

  // 7. Notify listeners
  registry.emit("plugin:reloaded", pluginId);
}
```

## 6. Sandbox & Security Model

### 6.1 Execution Boundary

Each plugin runs in an isolated sandbox with strict resource and API boundaries:

```typescript
interface SandboxEnvironment {
  // Isolated execution context
  context: VMContext;

  // Resource limits
  limits: {
    memoryMb: number;           // Hard memory ceiling
    cpuPercent: number;           // CPU time percentage
    executionTimeoutMs: number;   // Per-call timeout
    fileDescriptors: number;      // Max open files
  };

  // Injected APIs (constrained by permissions)
  apis: InjectedAPIs;

  // Permission enforcement
  permissionProxy: PermissionChecker;

  // Audit trail
  auditLog: AuditEventLog;
}

// Sandbox creation
function createPluginSandbox(
  manifest: PluginManifest,
  apiVersion: string
): SandboxEnvironment {
  // 1. Create isolated VM context
  const context = new VMContext({
    timeout: manifest.lifecycle.maxLoadTimeMs,
    sandbox: {
      // Explicitly allow only what we provide
      global: undefined,
      process: undefined, // No process access
      require: createSafeRequire(manifest), // Vetted dependencies only
      fetch: createBoundFetch(manifest.permissions),
    }
  });

  // 2. Enforce resource limits
  const monitor = new ResourceMonitor({
    memoryLimit: manifest.lifecycle.maxMemoryMb,
    cpuLimit: manifest.lifecycle.maxCpuPercent
  });
  monitor.start(context);

  // 3. Build permission-aware APIs
  const permChecker = new PermissionChecker(manifest.permissions);
  const apis = buildAPIs(apiVersion, manifest.api.required.features);
  const proxiedAPIs = wrapWithPermissionChecks(apis, permChecker);

  // 4. Set up audit logging
  const auditLog = new AuditEventLog(manifest.id);
  const auditProxies = wrapWithAudit(proxiedAPIs, auditLog);

  context.freeze(auditProxies);

  return { context, limits: manifest.lifecycle, apis: auditProxies, permissionProxy: permChecker, auditLog };
}
```

### 6.2 Permission Model

```typescript
// Permission types: resource:action:scope
type Permission = 
  // File system
  | "fs:read:data-directory"
  | "fs:write:data-directory"
  | "fs:read:logs"

  // Network
  | "network:http:external-api"
  | "network:http:internal-api"
  | "network:websocket"

  // Database
  | "database:read:custom-tables"
  | "database:write:custom-tables"
  | "database:admin"

  // Environment
  | "env:read:API_KEY"
  | "env:read:*"

  // System
  | "system:spawn-process"
  | "system:load-native-module";

// Permission checking at API boundary
class PermissionChecker {
  private permissions: Set<Permission>;

  check(permission: Permission, context?: any): boolean {
    if (!this.permissions.has(permission)) {
      throw new PermissionDeniedError(
        `Plugin does not have permission: ${permission}`,
        { permission, context }
      );
    }
    return true;
  }
}

// Example: Wrapping datasource API with permission checks
const proxiedAPI = {
  query: async (sql: string) => {
    permChecker.check("database:read:custom-tables", { sql });
    return realAPI.query(sql);
  },

  write: async (data: any) => {
    permChecker.check("database:write:custom-tables", { data });
    return realAPI.write(data);
  }
};
```

### 6.3 Trust Levels & Sandboxing Strength

```typescript
type TrustLevel = "trusted" | "verified" | "untrusted";

// Trust level determines sandbox strength
const SANDBOX_RULES = {
  trusted: {
    // Minimal sandboxing - likely internal plugins
    allowNativeModules: true,
    allowSubprocesses: true,
    memoryLimitMb: 1024,
    allowDirectFilesystem: true,
  },

  verified: {
    // Strong sandboxing - third-party with review
    allowNativeModules: false,
    allowSubprocesses: false,
    memoryLimitMb: 256,
    allowDirectFilesystem: false, // Use permission layer
    whitelistedRequires: ["lodash", "axios"], // Audited only
  },

  untrusted: {
    // Maximum sandboxing - isolated untrusted code
    allowNativeModules: false,
    allowSubprocesses: false,
    memoryLimitMb: 64,
    allowDirectFilesystem: false,
    whitelistedRequires: [], // No external requires
    timeoutMs: 5000,
    cpuLimitPercent: 10,
  }
};

// Escalating trust via verification
class TrustManager {
  private trustEscalationPath = [
    "untrusted" as const,
    "verified" as const,
    "trusted" as const
  ];

  // Audit review -> escalate trust level
  escalateTrust(pluginId: string, auditReport: AuditReport): Promise<void> {
    if (auditReport.securityScore > 85) {
      this.setTrust(pluginId, "verified");
    }
    if (auditReport.securityScore > 95 && auditReport.reviewedBy.length > 3) {
      this.setTrust(pluginId, "trusted");
    }
  }
}
