## 7. Complete Integration Example

```typescript
// How everything works together
async function main() {
  // 1. Initialize registry
  const registry = new PluginRegistry();

  // 2. Discover and register plugins
  const pluginDir = "./plugins";
  const manifests = await discoverPlugins(pluginDir);

  for (const manifest of manifests) {
    try {
      // Validate manifest
      const validation = registry.validateManifest(manifest);
      if (!validation.valid) {
        console.error(`Invalid manifest: ${validation.errors}`);
        continue;
      }

      // Check compatibility
      const compat = registry.checkCompatibility(manifest);
      if (!compat.compatible) {
        console.warn(`Plugin incompatible: ${compat.reason}`);
        continue;
      }

      // Register plugin
      await registry.register(manifest, path.join(pluginDir, manifest.id));
    } catch (e) {
      console.error(`Failed to register plugin: ${e.message}`);
    }
  }

  // 3. Listen to registry events
  registry.on("plugin:loaded", (pluginId) => {
    console.log(`✓ Plugin loaded: ${pluginId}`);
  });

  registry.on("plugin:error", (pluginId, error) => {
    console.error(`✗ Plugin error: ${pluginId} - ${error.message}`);
  });

  // 4. Load plugins in dependency order
  const loadOrder = registry.resolveDependencies();
  for (const pluginId of loadOrder) {
    await registry.load(pluginId);
  }

  // 5. Use plugins
  const datasourcePlugins = registry.getByCapability("datasource:read");
  for (const plugin of datasourcePlugins) {
    const result = await plugin.instance.query("SELECT * FROM users");
    console.log(result);
  }

  // 6. Hot reload during development
  registry.on("file:changed", async (pluginPath) => {
    const pluginId = getPluginIdForPath(pluginPath);
    console.log(`Reloading ${pluginId}...`);
    try {
      await registry.reload(pluginId);
      console.log(`✓ Reloaded ${pluginId}`);
    } catch (e) {
      console.error(`✗ Reload failed: ${e.message}`);
    }
  });

  // 7. Graceful shutdown
  process.on("SIGTERM", async () => {
    console.log("Shutting down plugins...");
    for (const plugin of registry.getAll()) {
      try {
        await plugin.instance.shutdown();
      } catch (e) {
        console.error(`Error shutting down ${plugin.id}: ${e.message}`);
      }
    }
  });
}

// Advanced: Multi-version API handling
class PluginExecutor {
  async execute(pluginId: string, request: PluginRequest): Promise<any> {
    const plugin = this.registry.get(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    // Get negotiated API version
    const { version, apis } = negotiateAPIVersion(plugin.manifest);

    // Wrap execution with safety
    return this.sandbox.execute(
      plugin,
      async () => {
        if (version === "1.0") {
          return await plugin.instance.legacyExecute(request);
        } else if (version === "1.1") {
          return await plugin.instance.execute(request);
        } else if (version === "2.0") {
          return await plugin.instance.executeAsync(request);
        }
      },
      {
        apis,
        timeout: 30000,
        onError: (error) => plugin.instance.onError?.(error)
      }
    );
  }
}
