## 9. Dependency Management

Plugins can depend on shared libraries, but with constraints:

```typescript
// Declare dependencies in manifest
{
  "dependencies": {
    "reporting-common": "^1.2.0",      // Vetted shared library
    "lodash": "^4.17.0"                 // Pin major.minor
  },

  // Forbidden (security)
  // "malicious-package": "*",          // Banned package
  // "exec": "*",                       // Native compilation
  // "private-internal-lib": "*"        // Private packages
}

// Registry validates:
const validateDependencies = (manifest) => {
  const forbidden = new Set(["os-command", "child_process", "eval"]);
  const vetted = new Map([
    ["lodash", "^4.17.0"],
    ["axios", "^0.27.0"],
    ["reporting-common", "^1.0.0"]
  ]);

  for (const [dep, version] of Object.entries(manifest.dependencies)) {
    if (forbidden.has(dep)) {
      throw new SecurityError(`Forbidden dependency: ${dep}`);
    }
    if (!vetted.has(dep)) {
      throw new SecurityError(`Unvetted dependency: ${dep}`);
    }
    // Check version compatibility with vetting
  }
};
```

