### 2.2 Manifest Validation Rules

```typescript
interface PluginManifest {
  // Required fields
  id: string;                    // Unique identifier: reverse-domain notation
  name: string;                  // Display name
  version: string;               // Semantic version (MAJOR.MINOR.PATCH)
  description: string;           // 1-2 sentence description

  // Required versioning
  engines: {
    reportingTool: string;       // Semver range (^3.0.0, ~2.5.0, etc.)
    node: string;                // Node.js version range
  };

  // Optional but recommended
  publisher?: string;
  license?: string;
  homepage?: string;
  repository?: {
    type: "git" | "svn" | "hg";
    url: string;
  };

  // Plugin behavior
  activationEvents: string[];    // When plugin loads
  contributes?: Record<string, unknown>;

  // Entry points
  activationCode?: string;       // Runs on activation
  mainModule?: string;           // Plugin exports

  // Security model
  sandbox?: SandboxConfig;

  // Dependencies (must be in lock file, pinned or ranged)
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
}

// Validation rules:
// - `id` must match pattern: ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$
// - `version` must follow semver strictly (no "v" prefix)
// - `engines.reportingTool` must be a valid semver range
// - All declared dependencies must exist in node_modules or lock file
// - No circular `contributes` dependencies (e.g., exporter depending on itself)
```

---

## 3. Plugin Registry

The registry is the runtime catalog of all plugins, their state, and capabilities.

### 3.1 Registry Architecture

```typescript
// Core registry interface
interface PluginRegistry {
  // Lifecycle management
  register(manifest: PluginManifest): Promise<RegisteredPlugin>;
  unregister(pluginId: string): Promise<void>;
  reload(pluginId: string): Promise<void>;

  // Discovery
  get(pluginId: string): RegisteredPlugin | null;
  getAll(): RegisteredPlugin[];
  findByCapability(capability: string): RegisteredPlugin[];

  // Query
  isEnabled(pluginId: string): boolean;
  hasConflicts(pluginId: string): Conflict[];

  // Events
  on(event: 'loaded' | 'unloaded' | 'failed', handler: EventHandler): Unsubscribe;
}

interface RegisteredPlugin {
  manifest: PluginManifest;
  state: PluginState;
  loadedAt: Date | null;
  error: PluginError | null;
  resources: ResourceSnapshot;
  exports: Record<string, unknown>;
  dependencies: DependencyGraph;
}

type PluginState = 'registered' | 'activating' | 'active' | 'deactivating' | 'inactive' | 'failed';

interface PluginError {
  code: string;
  message: string;
  stack?: string;
  timestamp: Date;
}

interface ResourceSnapshot {
  memoryUsageMB: number;
  cpuPercent: number;
  activeConnections: number;
}

interface DependencyGraph {
  dependsOn: string[];         // Plugins this depends on
  dependedOnBy: string[];      // Plugins depending on this
  requiresAPI: { name: string; minVersion: string }[];
}

interface Conflict {
  type: 'version' | 'capability' | 'resource';
  message: string;
  relatedPlugin: string;
  severity: 'warning' | 'error';
}
```

### 3.2 Registry Initialization

```typescript
class DefaultPluginRegistry implements PluginRegistry {
  private plugins = new Map<string, RegisteredPlugin>();
  private graph = new DependencyGraph();
  private eventBus = new EventEmitter();

  async register(manifest: PluginManifest): Promise<RegisteredPlugin> {
    // 1. Validate manifest
    validateManifest(manifest);

    // 2. Check ID uniqueness
    if (this.plugins.has(manifest.id)) {
      throw new Error(`Plugin ${manifest.id} already registered`);
    }

    // 3. Check engine compatibility
    if (!semver.satisfies(TOOL_VERSION, manifest.engines.reportingTool)) {
      throw new IncompatibleEngineError(manifest.id);
    }

    // 4. Check for conflicts
    const conflicts = this.detectConflicts(manifest);
    if (conflicts.some(c => c.severity === 'error')) {
      throw new ConflictError(conflicts);
    }

    // 5. Create plugin record
    const plugin: RegisteredPlugin = {
      manifest,
      state: 'registered',
      loadedAt: null,
      error: null,
      resources: { memoryUsageMB: 0, cpuPercent: 0, activeConnections: 0 },
      exports: {},
      dependencies: { dependsOn: [], dependedOnBy: [], requiresAPI: [] }
    };

    // 6. Register in graph
    this.graph.addNode(manifest.id, {
      dependsOn: extractDependencies(manifest)
    });

    // 7. Store
    this.plugins.set(manifest.id, plugin);
    this.eventBus.emit('registered', plugin);

    return plugin;
  }

  private detectConflicts(manifest: PluginManifest): Conflict[] {
    const conflicts: Conflict[] = [];

    // Check for conflicting exporter IDs
    const exporters = (manifest.contributes?.exporters || []) as any[];
    for (const exporter of exporters) {
      for (const other of this.plugins.values()) {
        const otherExporters = (other.manifest.contributes?.exporters || []) as any[];
        if (otherExporters.find(e => e.id === exporter.id)) {
          conflicts.push({
            type: 'capability',
            message: `Exporter ${exporter.id} already provided by ${other.manifest.id}`,
            relatedPlugin: other.manifest.id,
            severity: 'error'
          });
        }
      }
    }

    return conflicts;
  }
}
