## 4. Lifecycle Management

Plugins have a strict state machine lifecycle with well-defined hooks.

### 4.1 Lifecycle States and Transitions

```
┌────────────┐
│ registered │ (manifest loaded, not running)
└──────┬─────┘
       │ activate()
       ▼
┌──────────────┐
│ activating   │ (running activation code)
└──────┬───────┘
       │
   ┌───┴──────────────┐
   │                  │
   ▼                  ▼
┌────────┐      ┌───────┐
│ active │      │ failed │
└──┬─────┘      └───────┘
   │ deactivate()
   ▼
┌─────────────┐
│ deactivating│ (cleanup hooks)
└──────┬──────┘
       │
       ▼
┌────────┐
│inactive│
└────────┘
```

### 4.2 Lifecycle Hooks

```typescript
interface PluginExports {
  // Initialization hook: runs when plugin is activated
  activate?(context: PluginContext): Promise<void>;

  // Cleanup hook: runs when plugin is deactivated
  deactivate?(): Promise<void>;

  // Migration hook: runs when upgrading plugin version
  migrate?(from: string, to: string): Promise<void>;
}

interface PluginContext {
  // API version this plugin is running against
  apiVersion: string;

  // Services provided by host
  commands: CommandService;
  storage: StorageService;
  logger: LoggerService;
  events: EventService;

  // Plugin introspection
  pluginId: string;
  pluginVersion: string;
  manifest: PluginManifest;

  // Configuration
  getConfig(key: string): unknown;
  onDidChangeConfiguration: Event<ConfigurationChangeEvent>;
}

// Activation flow
class PluginActivationManager {
  async activate(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (!plugin) throw new PluginNotFoundError(pluginId);
    if (plugin.state === 'active') return;

    plugin.state = 'activating';

    try {
      // 1. Activate dependencies first
      for (const dep of plugin.dependencies.dependsOn) {
        if (!this.registry.isEnabled(dep)) {
          throw new DependencyNotAvailableError(dep);
        }
        await this.activate(dep);
      }

      // 2. Load module (lazy)
      const module = await loadPluginModule(plugin.manifest);

      // 3. Call activate hook with context
      if (module.activate) {
        const timeout = ms(plugin.manifest.sandbox?.capabilities?.resources?.timeoutSeconds ?? 30);
        await withTimeout(
          module.activate(createContext(plugin)),
          timeout,
          new ActivationTimeoutError(pluginId)
        );
      }

      // 4. Mark as loaded
      plugin.state = 'active';
      plugin.loadedAt = new Date();
      plugin.exports = module;

      this.eventBus.emit('activated', pluginId);

    } catch (error) {
      plugin.state = 'failed';
      plugin.error = {
        code: error.code || 'ACTIVATION_FAILED',
        message: error.message,
        stack: error.stack,
        timestamp: new Date()
      };
      this.eventBus.emit('failed', pluginId);
      throw error;
    }
  }

  async deactivate(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (!plugin || plugin.state !== 'active') return;

    plugin.state = 'deactivating';

    try {
      // 1. Deactivate dependents first
      for (const dependent of plugin.dependencies.dependedOnBy) {
        await this.deactivate(dependent);
      }

      // 2. Call deactivate hook
      if (plugin.exports.deactivate) {
        const timeout = ms('10s');
        await withTimeout(
          plugin.exports.deactivate(),
          timeout,
          new DeactivationTimeoutError(pluginId)
        );
      }

      // 3. Clean up resources
      await this.resourceManager.cleanup(pluginId);

      plugin.state = 'inactive';
      plugin.exports = {};
      this.eventBus.emit('deactivated', pluginId);

    } catch (error) {
      logger.error(`Deactivation failed for ${pluginId}:`, error);
      plugin.state = 'inactive';
      plugin.error = {
        code: 'DEACTIVATION_FAILED',
        message: error.message,
        timestamp: new Date()
      };
    }
  }

  async reload(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (!plugin) throw new PluginNotFoundError(pluginId);

    const oldVersion = plugin.manifest.version;

    try {
      // 1. Deactivate
      await this.deactivate(pluginId);

      // 2. Load new manifest and validate
      const newManifest = await loadManifest(plugin.manifest.id);

      // 3. Run migration hook if version changed
      if (oldVersion !== newManifest.version && plugin.exports.migrate) {
        await plugin.exports.migrate(oldVersion, newManifest.version);
      }

      // 4. Re-register with new manifest
      this.registry.unregister(pluginId);
      await this.registry.register(newManifest);

      // 5. Re-activate
      await this.activate(pluginId);

      this.eventBus.emit('reloaded', pluginId);

    } catch (error) {
      logger.error(`Reload failed for ${pluginId}:`, error);

      // Attempt rollback
      try {
        await this.activate(pluginId);
      } catch {}

      throw error;
    }
  }
}
```

### 4.3 Activation Events

Plugins declare when they should auto-activate via `activationEvents`:

```typescript
type ActivationEvent =
  | 'onStartup'
  | `onCommand:${string}`              // e.g., "onCommand:custom-exporter.export"
  | `onView:${string}`                 // e.g., "onView:report-sidebar"
  | `onLanguage:${string}`             // e.g., "onLanguage:json"
  | `onFileExists:${glob}`             // e.g., "onFileExists:**/plugin-config.json"
  | `onWorkspaceContains:${glob}`;     // e.g., "onWorkspaceContains:**/package.json"

// Activation rules:
// - 'onStartup' activates immediately after plugin registry initializes
// - Command activation defers until user invokes that command
// - View activation waits until user opens that view
// - Only 1 plugin per command ID is allowed
// - Activation is lazy: plugins don't load until needed
// - If plugin fails to activate on demand, command/view fails gracefully
```

