## 5. Sandboxed Execution Boundary

Plugins run in isolated Node.js worker threads with restricted access and resource limits.

### 5.1 Sandbox Architecture

```typescript
interface SandboxConfig {
  capabilities: {
    filesystem: {
      read?: string[];          // Glob patterns allowed for read
      write?: string[];         // Glob patterns allowed for write
      allowedPaths?: string[];  // Absolute paths bypassing pattern matching
    };
    network: {
      allowedHosts?: string[];  // Glob patterns for hostnames
      allowedProtocols?: string[]; // ['http', 'https', 'ws', 'wss']
    };
    ipc: {
      allowedCommands?: string[]; // Command ID patterns plugin can invoke
      canAccessStorage?: boolean; // Can use persistent storage APIs
    };
    resources: {
      maxMemoryMB?: number;     // Default: 512
      maxCpuPercent?: number;   // Default: 50
      timeoutSeconds?: number;  // Default: 30
    };
  };
}

// Execution model:
// - Each plugin runs in a dedicated Node.js Worker
// - Main thread ←→ Worker communication via message passing
// - Filesystem access is intercepted and validated
// - Network calls checked against allowlist
// - Resource usage monitored, plugin killed if exceeded
// - No access to host process internals (require, process, etc.)
```

### 5.2 Sandbox Implementation

```typescript
class PluginSandbox {
  private worker: Worker;
  private messageHandlers = new Map<string, (data: any) => void>();
  private resourceMonitor: ResourceMonitor;

  constructor(
    pluginId: string,
    modulePath: string,
    sandboxConfig: SandboxConfig,
    context: PluginContext
  ) {
    // 1. Create isolated worker
    this.worker = new Worker(SANDBOX_BOOTSTRAP_PATH, {
      env: {
        PLUGIN_ID: pluginId,
        PLUGIN_PATH: modulePath,
        API_VERSION: API_VERSION
      }
    });

    // 2. Set up resource limits
    this.resourceMonitor = new ResourceMonitor(
      pluginId,
      sandboxConfig.capabilities.resources
    );

    // 3. Set up message handler
    this.worker.on('message', (msg) => this.handleMessage(msg));
    this.worker.on('error', (err) => this.handleError(err));
    this.worker.on('exit', (code) => this.handleExit(code));

    // 4. Initialize sandbox capabilities
    this.worker.postMessage({
      type: 'init',
      sandboxConfig,
      context: {
        pluginId,
        apiVersion: API_VERSION,
        manifest: context.manifest
      }
    });
  }

  private handleMessage(msg: WorkerMessage): void {
    if (msg.type === 'fs.read') {
      // Validate path against read permissions
      if (!this.isPathAllowed('read', msg.path)) {
        this.worker.postMessage({
          id: msg.id,
          error: 'Permission denied'
        });
        return;
      }
      // Perform actual read
      fs.readFile(msg.path, (err, data) => {
        this.worker.postMessage({
          id: msg.id,
          error: err?.message,
          data: err ? null : data.toString()
        });
      });
    } else if (msg.type === 'command.invoke') {
      // Validate command against allowed list
      if (!this.isCommandAllowed(msg.command)) {
        this.worker.postMessage({
          id: msg.id,
          error: 'Command not allowed'
        });
        return;
      }
      // Invoke command in main context
      commandService.invoke(msg.command, msg.args).then(
        result => this.worker.postMessage({ id: msg.id, result }),
        error => this.worker.postMessage({ id: msg.id, error: error.message })
      );
    }
    // ... handle other message types
  }

  private isPathAllowed(mode: 'read' | 'write', path: string): boolean {
    const allowedPatterns = this.sandboxConfig.capabilities.filesystem[mode] || [];
    const allowedPaths = this.sandboxConfig.capabilities.filesystem.allowedPaths || [];

    // Check absolute path allowlist
    if (allowedPaths.includes(path)) return true;

    // Check glob patterns
    return allowedPatterns.some(pattern => minimatch(path, pattern));
  }

  private isCommandAllowed(command: string): boolean {
    const allowedCommands = this.sandboxConfig.capabilities.ipc.allowedCommands || [];
    return allowedCommands.some(pattern => minimatch(command, pattern));
  }

  async invoke(fnName: string, args: unknown[]): Promise<unknown> {
    return new Promise((resolve, reject) => {
      const msgId = uuid();
      const timeout = setTimeout(() => {
        this.messageHandlers.delete(msgId);
        reject(new PluginTimeoutError());
      }, 30000);

      this.messageHandlers.set(msgId, (result) => {
        clearTimeout(timeout);
        this.messageHandlers.delete(msgId);
        if (result.error) reject(new Error(result.error));
        else resolve(result.data);
      });

      this.worker.postMessage({
        type: 'invoke',
        id: msgId,
        function: fnName,
        arguments: args
      });
    });
  }

  terminate(): void {
    this.resourceMonitor.stop();
    this.worker.terminate();
  }
}

// Worker bootstrap script (runs inside worker)
import Module from 'module';

const sandboxConfig = await waitForInit();
const pluginModule = require(process.env.PLUGIN_PATH);

// Intercept require() to block dangerous modules
const originalRequire = Module.prototype.require;
Module.prototype.require = function(id: string) {
  const blockedModules = ['child_process', 'cluster', 'worker_threads'];
  if (blockedModules.includes(id)) {
    throw new Error(`Module "${id}" is not allowed in plugins`);
  }
  return originalRequire.call(this, id);
};

// Provide limited APIs
global.sandboxAPI = {
  fs: new RestrictedFileSystem(sandboxConfig),
  http: new RestrictedHTTP(sandboxConfig),
  commands: new RestrictedCommandService(sandboxConfig)
};

// Handle messages from main
process.on('message', async (msg) => {
  if (msg.type === 'invoke') {
    try {
      const fn = pluginModule[msg.function];
      const result = await fn(...msg.arguments);
      process.send({ id: msg.id, data: result });
    } catch (error) {
      process.send({ id: msg.id, error: error.message });
    }
  }
});

// Report readiness
process.send({ type: 'ready' });
```

