## 6. Versioned API Contract

The reporting tool exposes a stable, versioned API that plugins depend on.

### 6.1 API Versioning Strategy

```typescript
// Semantic versioning: MAJOR.MINOR.PATCH
// - MAJOR: Breaking changes (requires plugin update)
// - MINOR: New features (plugins can opt-in, backwards compatible)
// - PATCH: Bug fixes (transparent)

const API_VERSION = '3.0.0';

// Compatibility rules:
// - Plugins declare minimum required API version in engines.reportingTool
// - ^3.0.0 = accept 3.0.0 through <4.0.0 (breaking changes not allowed)
// - ~3.5.0 = accept 3.5.0 through <3.6.0 (only patch updates)
// - 3.x = accept any 3.x version (most permissive)
// - Tool REJECTS plugins requiring newer API version than available

// Deprecation path for breaking changes:
// 1. Announce in release notes 2 major versions ahead
// 2. In MAJOR-1 release: mark feature as deprecated, keep functional
// 3. In MAJOR release: remove deprecated feature, bump major version
// 4. Plugins using removed features fail to activate with clear error
```

### 6.2 Public API Surface

```typescript
// Main API namespace exported to all plugins

namespace ReportingToolAPI {
  // Commands subsystem
  export namespace commands {
    export function register(id: string, handler: CommandHandler): Disposable;
    export function execute(id: string, args?: unknown[]): Promise<unknown>;
  }

  // Event system
  export namespace events {
    export function on<T>(event: string, handler: (data: T) => void): Disposable;
    export function emit(event: string, data: unknown): void;
    export function once<T>(event: string): Promise<T>;
  }

  // Report management
  export namespace reports {
    export function create(config: ReportConfig): Promise<Report>;
    export function get(id: string): Promise<Report | null>;
    export function list(query?: ReportQuery): Promise<Report[]>;
    export function export(id: string, format: string, options?: unknown): Promise<Uint8Array>;
  }

  // Export formats
  export namespace exporters {
    export function register(format: ExporterDefinition): Disposable;
    export function get(format: string): Exporter | null;
  }

  // Data access with permissions
  export namespace data {
    export function query(sql: string, params?: Record<string, unknown>): Promise<unknown[]>;
    export function subscribe(query: string, onChange: (rows: unknown[]) => void): Disposable;
  }

  // Configuration
  export namespace config {
    export function get<T>(key: string, defaultValue?: T): T;
    export function update(key: string, value: unknown): Promise<void>;
    export function onDidChange(key: string, handler: () => void): Disposable;
  }

  // Storage
  export namespace storage {
    export function get(key: string): Promise<unknown>;
    export function set(key: string, value: unknown): Promise<void>;
    export function delete(key: string): Promise<void>;
  }

  // UI/Views
  export namespace ui {
    export function registerView(view: ViewDefinition): Disposable;
    export function showMessage(message: string, level?: 'info' | 'warn' | 'error'): Promise<void>;
  }

  // Logging
  export namespace logger {
    export function debug(message: string, data?: unknown): void;
    export function info(message: string, data?: unknown): void;
    export function warn(message: string, error?: Error): void;
    export function error(message: string, error?: Error): void;
  }
}

// Strict contract: each API version is immutable
// - API 3.0 exports contain ONLY what's in this schema
// - Removing APIs requires major version bump
// - New APIs go into MINOR releases
// - Experimental APIs marked as @unstable, subject to breaking change
```

### 6.3 API Stability Guarantees

```typescript
interface APIStabilityContract {
  // These functions will NOT change signature in 3.x
  stable: {
    'commands.register': {
      parameters: ['id: string', 'handler: CommandHandler'],
      returns: 'Disposable',
      minVersion: '3.0.0'
    },
    'reports.export': {
      parameters: ['id: string', 'format: string', 'options?: unknown'],
      returns: 'Promise<Uint8Array>',
      minVersion: '3.0.0'
    }
    // ... all documented APIs
  };

  // These are experimental, may change in 3.x
  unstable: {
    'data.subscribe': {
      reason: 'Real-time subscriptions implementation may change',
      minVersion: '3.1.0'
    }
  };

  // These are deprecated, removed in 4.0.0
  deprecated: {
    'reports.render': {
      removedInVersion: '4.0.0',
      alternative: 'Use reports.export instead',
      deprecatedSince: '3.5.0'
    }
  };
}

// Runtime API version checking
function getAPI(pluginManifest: PluginManifest): typeof ReportingToolAPI {
  const requiredVersion = pluginManifest.engines.reportingTool;

  if (!semver.satisfies(API_VERSION, requiredVersion)) {
    throw new IncompatibleAPIError(
      `Plugin requires API ${requiredVersion}, but ${API_VERSION} is available`
    );
  }

  // Return API with runtime guards
  return new Proxy(ReportingToolAPI, {
    get(target, prop) {
      const api = target[prop];

      // Warn on deprecated usage
      if (STABILITY_CONTRACT.deprecated[`${String(prop)}`]) {
        logger.warn(`API ${String(prop)} is deprecated, will be removed in next major version`);
      }

      return api;
    }
  });
}
