### 7.2 Dependency Resolution

```typescript
interface DependencyResolution {
  // Hard dependencies (required)
  dependencies: Record<string, string>;      // e.g., { "com.example.base": "^1.0.0" }

  // Soft dependencies (optional, enhances functionality)
  optionalDependencies: Record<string, string>;

  // API requirements
  requiredAPIs: Record<string, string>;      // e.g., { "reports.export": "^3.0.0" }
}

class DependencyResolver {
  async resolve(pluginId: string): Promise<ResolutionResult> {
    const manifest = this.registry.get(pluginId)?.manifest;
    const deps = manifest.dependencies || {};
    const resolved: string[] = [];
    const failed: { id: string; reason: string }[] = [];

    for (const [depId, versionRange] of Object.entries(deps)) {
      const depPlugin = this.registry.get(depId);

      if (!depPlugin) {
        failed.push({ id: depId, reason: 'Not installed' });
        continue;
      }

      if (!semver.satisfies(depPlugin.manifest.version, versionRange)) {
        failed.push({
          id: depId,
          reason: `Version mismatch: need ${versionRange}, have ${depPlugin.manifest.version}`
        });
        continue;
      }

      resolved.push(depId);
    }

    return { resolved, failed };
  }

  async validateBeforeActivation(pluginId: string): Promise<ValidationError[]> {
    const manifest = this.registry.get(pluginId)?.manifest;
    const errors: ValidationError[] = [];

    // Check hard dependencies
    const { failed } = await this.resolve(pluginId);
    if (failed.length > 0) {
      errors.push({
        code: 'MISSING_DEPENDENCY',
        message: `Missing dependencies: ${failed.map(f => f.id).join(', ')}`
      });
    }

    // Check optional dependencies are available but activation should not fail
    for (const [optId, versionRange] of Object.entries(manifest.optionalDependencies || {})) {
      const optPlugin = this.registry.get(optId);
      if (optPlugin && !semver.satisfies(optPlugin.manifest.version, versionRange)) {
        logger.warn(`Optional dependency ${optId} has incompatible version`);
      }
    }

    return errors;
  }
}

// Activation order respects dependency graph:
// [A → B → C] means: activate C first, then B, then A
```

