## 8. Error Handling & Recovery

### 8.1 Error Classification

```typescript
enum PluginErrorSeverity {
  INFO = 'info',
  WARNING = 'warning',
  ERROR = 'error',
  FATAL = 'fatal'
}

interface PluginErrorCatalog {
  'MANIFEST_INVALID': {
    severity: 'ERROR',
    message: 'Plugin manifest does not conform to schema',
    userMessage: 'This plugin cannot be installed because it is not properly configured.'
  },
  'ENGINE_INCOMPATIBLE': {
    severity: 'ERROR',
    message: 'Plugin requires incompatible reporting tool version',
    userMessage: 'This plugin requires a newer version of the reporting tool.'
  },
  'ACTIVATION_FAILED': {
    severity: 'ERROR',
    message: 'Plugin crashed during initialization',
    userMessage: 'The plugin failed to start. Check the logs.'
  },
  'ACTIVATION_TIMEOUT': {
    severity: 'WARNING',
    message: 'Plugin activation took too long',
    userMessage: 'The plugin is slow to start.'
  },
  'DEPENDENCY_MISSING': {
    severity: 'ERROR',
    message: 'Required dependency plugin not installed',
    userMessage: 'This plugin depends on another plugin that is not installed.'
  },
  'RESOURCE_EXCEEDED': {
    severity: 'FATAL',
    message: 'Plugin exceeded resource limits',
    userMessage: 'The plugin is using too many resources and has been stopped.'
  },
  'SANDBOX_VIOLATION': {
    severity: 'WARNING',
    message: 'Plugin attempted unauthorized access',
    userMessage: 'The plugin attempted an action it is not allowed to perform.'
  }
}

// Error handling in activation:
try {
  await activationManager.activate(pluginId);
} catch (error) {
  const errorEntry = PLUGIN_ERROR_CATALOG[error.code];

  if (errorEntry.severity === 'FATAL') {
    // Disable plugin permanently or temporarily
    await registry.disable(pluginId);
    ui.showMessage(errorEntry.userMessage, 'error');
  } else if (errorEntry.severity === 'ERROR') {
    // Activation failed, plugin remains registered but inactive
    logger.error(errorEntry.message, error);
    ui.showMessage(errorEntry.userMessage, 'error');
  } else {
    // Warning level, plugin may still be usable
    logger.warn(errorEntry.message, error);
  }
}
```

### 8.2 Recovery Strategies

```typescript
interface PluginRecoveryStrategy {
  // Retry with exponential backoff (for transient failures)
  retryWithBackoff: {
    maxAttempts: number;          // default: 3
    initialDelayMs: number;       // default: 1000
    backoffFactor: number;        // default: 2
    applicableTo: PluginErrorCode[];
  };

  // Deferred activation (try again on next startup)
  deferredActivation: {
    applicableTo: PluginErrorCode[];
  };

  // Graceful degradation (partial functionality)
  gracefulDegradation: {
    disableFeatures: string[];    // Feature IDs to disable
    applicableTo: PluginErrorCode[];
  };

  // Quarantine (disable until user manually re-enables)
  quarantine: {
    applicableTo: PluginErrorCode[];
  };
}

class RecoveryManager {
  async attemptRecovery(pluginId: string, error: PluginError): Promise<RecoveryOutcome> {
    const plugin = this.registry.get(pluginId);
    const strategy = this.getRecoveryStrategy(error.code);

    if (strategy.retryWithBackoff?.applicableTo.includes(error.code)) {
      return this.retryWithBackoff(pluginId, strategy.retryWithBackoff);
    }

    if (strategy.gracefulDegradation?.applicableTo.includes(error.code)) {
      return this.disableSpecificFeatures(pluginId, strategy.gracefulDegradation.disableFeatures);
    }

    if (strategy.quarantine?.applicableTo.includes(error.code)) {
      return this.quarantinePlugin(pluginId);
    }

    return { outcome: 'unrecoverable', error };
  }

  private async retryWithBackoff(
    pluginId: string,
    config: RetryConfig
  ): Promise<RecoveryOutcome> {
    for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
      const delay = config.initialDelayMs * Math.pow(config.backoffFactor, attempt - 1);
      await sleep(delay);

      try {
        await this.activationManager.activate(pluginId);
        return { outcome: 'recovered', attempt };
      } catch (error) {
        if (attempt === config.maxAttempts) {
          return { outcome: 'failed_all_retries', error, attempts: attempt };
        }
        logger.warn(`Activation attempt ${attempt} failed, retrying in ${delay}ms`);
      }
    }
  }
}
