### 10.2 Installation Flow

```typescript
class PluginInstaller {
  async install(source: string): Promise<InstallResult> {
    // 1. Fetch or validate source
    const packagePath = await this.obtainPackage(source);

    // 2. Extract and validate manifest
    const manifest = await this.validateManifest(packagePath);

    // 3. Check engine compatibility
    if (!semver.satisfies(TOOL_VERSION, manifest.engines.reportingTool)) {
      throw new IncompatibleEngineError(manifest.id);
    }

    // 4. Verify dependencies
    await this.verifyDependencies(packagePath);

    // 5. Scan for security issues
    const securityReport = await this.securityScanner.scan(packagePath);
    if (securityReport.critical > 0) {
      throw new SecurityViolationError(securityReport);
    }

    // 6. Copy to plugins directory
    const targetPath = path.join(PLUGINS_DIR, manifest.id);
    await fs.copy(packagePath, targetPath);

    // 7. Register in registry
    await this.registry.register(manifest);

    return {
      pluginId: manifest.id,
      version: manifest.version,
      installed: true
    };
  }

  async upgrade(pluginId: string, newVersion: string): Promise<UpgradeResult> {
    const currentPlugin = this.registry.get(pluginId);

    // 1. Validate new version
    const manifest = await this.validateVersion(pluginId, newVersion);

    // 2. Check for breaking changes
    const breakingChanges = this.detectBreakingChanges(
      currentPlugin.manifest.version,
      newVersion
    );

    // 3. Create backup of current version
    await this.createBackup(pluginId);

    // 4. Install new version
    await this.install(manifest);

    // 5. Reload plugin
    await this.activationManager.reload(pluginId);

    return { upgraded: true, breakingChanges };
  }

  async uninstall(pluginId: string): Promise<void> {
    // 1. Deactivate plugin
    await this.activationManager.deactivate(pluginId);

    // 2. Check for dependents
    const plugin = this.registry.get(pluginId);
    if (plugin.dependencies.dependedOnBy.length > 0) {
      throw new DependentPluginsError(plugin.dependencies.dependedOnBy);
    }

    // 3. Remove from filesystem
    const pluginPath = path.join(PLUGINS_DIR, pluginId);
    await fs.remove(pluginPath);

    // 4. Unregister
    this.registry.unregister(pluginId);
  }
}
```

