### 2. Plugin Registry

**Purpose:** Central record of all available plugins, versions, and metadata.

```typescript
interface PluginDescriptor {
  id: string;                          // unique identifier (org.reporting.plugin-name)
  name: string;
  version: string;                     // semver
  apiVersion: string;                  // required host API version range (^1.0.0)
  location: string;                    // path or URL to plugin
  enabled: boolean;
  loadOrder: number;                   // for dependency-aware loading
  manifest: PluginManifest;
  state: 'unloaded' | 'loading' | 'loaded' | 'active' | 'error';
  error?: string;
  loadedAt?: timestamp;
  instanceId?: string;                 // unique runtime instance
}

class PluginRegistry {
  private registry: Map<string, PluginDescriptor> = new Map();

  register(descriptor: PluginDescriptor): void;
  deregister(pluginId: string): void;
  get(pluginId: string): PluginDescriptor | null;
  list(filter?: { enabled?: boolean; state?: string }): PluginDescriptor[];

  // Dependency resolution
  resolveLoadOrder(plugins: PluginDescriptor[]): PluginDescriptor[];

  // Querying
  findByCapability(capability: string): PluginDescriptor[];
  findCompatible(apiVersion: string): PluginDescriptor[];
}
```

