### 4. Lifecycle Hooks

**Design Pattern:** Event-driven with guaranteed ordering.

```typescript
type LifecyclePhase = 'discovering' | 'manifest' | 'validating' | 
                      'loading' | 'initializing' | 'active' | 
                      'reloading' | 'unloading' | 'unloaded' | 'error';

type HookName = 'onDiscovered' | 'onManifestLoaded' | 'onValidated' |
                'onBeforeLoad' | 'onAfterLoad' | 'onInitialize' | 
                'onActivate' | 'onBeforeReload' | 'onReload' |
                'onBeforeUnload' | 'onUnload' | 'onError' | 'onDisabled';

interface PluginHooks {
  // System hooks (called by host)
  onDiscovered?(manifest: PluginManifest): void | Promise<void>;
  onManifestLoaded?(manifest: PluginManifest): void | Promise<void>;
  onValidated?(manifest: PluginManifest): void | Promise<void>;
  onBeforeLoad?(context: PluginLoadContext): void | Promise<void>;
  onAfterLoad?(plugin: PluginInstance): void | Promise<void>;
  onInitialize?(config: PluginConfiguration): void | Promise<void>;
  onActivate?(): void | Promise<void>;

  onBeforeReload?(context: PluginReloadContext): void | Promise<void>;
  onReload?(context: PluginReloadContext): void | Promise<void>;

  onBeforeUnload?(): void | Promise<void>;
  onUnload?(): void | Promise<void>;

  onError?(error: PluginError, phase: LifecyclePhase): void | Promise<void>;
  onDisabled?(reason: string): void | Promise<void>;
}

class PluginLifecycleManager {
  private phase: LifecyclePhase = 'discovering';
  private hooks: Map<string, Hook[]> = new Map();

  async discover(strategies: DiscoveryStrategy[]): Promise<void>;

  async load(pluginId: string, config?: PluginConfiguration): Promise<PluginInstance>;

  async reload(pluginId: string, config?: PluginConfiguration): Promise<void> {
    // 1. Call onBeforeReload hooks
    // 2. Capture current state
    // 3. Call onBeforeUnload
    // 4. Unload from sandbox
    // 5. Load new version
    // 6. Call onReload with state
    // 7. Call onActivate
  }

  async unload(pluginId: string, graceful: boolean = true): Promise<void> {
    // 1. Call onBeforeUnload
    // 2. Wait for in-flight operations (if graceful)
    // 3. Call onUnload
    // 4. Clean up resources
    // 5. Remove from registry
  }

  on(hookName: HookName, handler: Hook): void;
  off(hookName: HookName, handler: Hook): void;

  private async executeHook(hookName: HookName, ...args: any[]): Promise<void>;
}

// Hook execution guarantees
interface HookExecution {
  ordering: 'sequential' | 'parallel';  // usually sequential for lifecycle
  timeout: number;                       // ms, default 30000
  errorHandling: 'continue' | 'abort';   // if one hook fails
}
```

**Lifecycle Flow Diagram:**

```
┌─────────────┐
│  Discovered │
└──────┬──────┘
       │ onDiscovered
       ▼
┌──────────────────┐
│ Manifest Loaded  │
└────────┬─────────┘
         │ onManifestLoaded
         ▼
┌─────────────────┐
│   Validating    │
└────────┬────────┘
         │ onValidated
         ▼
┌──────────────────┐
