### 5. Sandboxed Execution Boundary

**Multi-layer isolation strategy:**

```typescript
interface SandboxConfig {
  // Process/resource isolation
  memoryLimit?: number;           // MB
  cpuLimit?: number;              // percentage
  executionTimeout?: number;      // ms per operation

  // Filesystem isolation
  allowedPaths: string[];         // whitelisted directories
  readonlyPaths?: string[];

  // Network isolation
  allowedDomains?: string[];      // null = no network access
  blockDomains?: string[];

  // Capability isolation
  capabilities: string[];         // plugin declares, host grants

  // Error containment
  catchUncaughtExceptions: boolean;
  catchUnhandledRejections: boolean;
}

// Layer 1: Process Isolation (for Node.js)
class WorkerThreadSandbox {
  private worker: Worker;
  private messagePort: MessagePort;

  async initialize(pluginCode: string, config: SandboxConfig): Promise<void>;
  async execute(method: string, ...args: any[]): Promise<any>;
  async terminate(): Promise<void>;
}

// Layer 2: API Boundary (all environments)
class PluginAPIBoundary {
  private exposedAPI: VersionedAPI;
  private interceptors: APIInterceptor[] = [];

  // Only specific methods are accessible to plugin
  private createProxy(plugin: PluginInstance): any {
    return new Proxy(this.exposedAPI, {
      get: (target, prop) => {
        // Validate capability
        if (!plugin.hasCapability(prop as string)) {
          throw new PermissionError(`Not permitted: ${String(prop)}`);
        }

        // Check quota
        if (this.isOverQuota(plugin, prop as string)) {
          throw new QuotaExceeded();
        }

        return async (...args: any[]) => {
          try {
            // Pre-call hooks
            for (const interceptor of this.interceptors) {
              await interceptor.beforeCall({
                plugin, method: prop, args
              });
            }

            const result = await target[prop as string](...args);

            // Post-call hooks
            for (const interceptor of this.interceptors) {
              await interceptor.afterCall({
                plugin, method: prop, args, result
              });
            }

            return result;
          } catch (error) {
            // Error isolation - don't leak host internals
            if (error instanceof SystemError) {
              throw new PluginError(error.message);
            }
            throw error;
          }
        };
      }
    });
  }
}

// Layer 3: Data Validation
class DataValidator {
  validateInput(method: string, args: any[], schema: JSONSchema): boolean;
  validateOutput(method: string, result: any, schema: JSONSchema): boolean;
}

interface PluginSandbox {
  config: SandboxConfig;
  api: VersionedPluginAPI;

  // Execution
  execute(method: string, ...args: any[]): Promise<any>;

  // Resource management
  getResourceUsage(): ResourceUsage;
  enforceResourceLimits(): void;

  // Cleanup
  dispose(): Promise<void>;
}

class SandboxFactory {
  createSandbox(
    plugin: PluginDescriptor,
    config: SandboxConfig
  ): PluginSandbox {
    // Choose isolation strategy based on plugin needs and runtime
    if (config.capabilities.includes('system:high-isolation')) {
      return new ProcessIsolatedSandbox(plugin, config);
    } else if (config.capabilities.includes('system:moderate-isolation')) {
      return new WorkerThreadSandbox(plugin, config);
    } else {
      return new InProcessSandbox(plugin, config);
    }
  }
}
```

