```typescript
interface Permission {
  action: string;        // fs:read, fs:write, network:http, etc.
  resource?: string;     // /reports/*, api.example.com, etc.
  conditions?: {
    quotaPerMinute?: number;
    quotaPerHour?: number;
    rateLimit?: number;  // ops/second
