### 6. Versioned API Contract

**Version Strategy: Semantic Versioning with backward compatibility guarantees**

```typescript
type APIVersion = `${number}.${number}.${number}`;

interface VersionedPluginAPI {
  version: APIVersion;

  // Core reporting operations
  reports: ReportingAPI;

  // Data access
  data: DataAPI;

  // Rendering/output
  output: OutputAPI;

  // System integration
  system: SystemAPI;

  // Logging
  logger: LoggerAPI;
}

// Version 1.0.0
namespace API_v1 {
  interface ReportingAPI {
    getReport(id: string): Promise<Report>;
    createReport(definition: ReportDefinition): Promise<Report>;
    updateReport(id: string, changes: Partial<ReportDefinition>): Promise<Report>;
    deleteReport(id: string): Promise<void>;
    listReports(filter?: ReportFilter): Promise<Report[]>;
    executeReport(id: string, params: Record<string, any>): Promise<ReportResult>;
  }

  interface DataAPI {
    query(sql: string, params?: Record<string, any>): Promise<Dataset>;
    transform(data: Dataset, transformer: DataTransformer): Promise<Dataset>;
    cache(key: string, data: Dataset, ttl?: number): Promise<void>;
    getCached(key: string): Promise<Dataset | null>;
  }

  interface OutputAPI {
    render(type: 'html' | 'pdf' | 'json', report: Report): Promise<Buffer>;
    format(data: any, options: FormatOptions): string;
  }

  interface SystemAPI {
    getConfig(key: string): any;
    setConfig(key: string, value: any): void;
    onEvent(event: string, handler: Function): void;
    emitEvent(event: string, data?: any): void;
  }

  interface LoggerAPI {
    debug(message: string, context?: any): void;
    info(message: string, context?: any): void;
    warn(message: string, context?: any): void;
    error(message: string, error?: Error): void;
  }
}

// Version 2.0.0 - with new capabilities
namespace API_v2 {
  interface ReportingAPI extends API_v1.ReportingAPI {
    // New methods (backward compatible)
    scheduleReport(id: string, schedule: CronExpression): Promise<void>;
    unscheduleReport(id: string): Promise<void>;

    // Deprecated (still work, but marked for removal in v3)
    executeReport(id: string, params: Record<string, any>): Promise<ReportResult>; // moved to ExecutionAPI
  }

  interface ExecutionAPI {
    execute(reportId: string, params: Record<string, any>): Promise<Execution>;
    getExecution(id: string): Promise<Execution>;
    cancelExecution(id: string): Promise<void>;
    onExecutionProgress(handler: ProgressHandler): void;
  }
}

// API Adapter handles version mismatch
class APIAdapter {
  private apis: Map<APIVersion, VersionedPluginAPI> = new Map();
  private deprecationWarnings: Map<string, string> = new Map();

  getAPI(requestedVersion: string): VersionedPluginAPI {
    // 1. Check exact match
    const exact = this.apis.get(requestedVersion as APIVersion);
    if (exact) return exact;

    // 2. Check compatible version (using semver)
    const compatible = this.findCompatibleVersion(requestedVersion);
    if (compatible) {
      console.warn(`API version mismatch: requested ${requestedVersion}, using ${compatible}`);
      return this.apis.get(compatible)!;
    }

    // 3. Fail with clear error
    throw new APIVersionUnsupported(
      `No compatible API found for version ${requestedVersion}. ` +
      `Supported versions: ${Array.from(this.apis.keys()).join(', ')}`
    );
  }

  private findCompatibleVersion(requested: string): APIVersion | null {
    // Implement semver comparison
    // Example: ^1.0.0 matches 1.x.x
  }
}

// Plugin must declare which API version it uses
interface PluginInstance {
  id: string;
  manifest: PluginManifest;
  api: VersionedPluginAPI;           // Bound to specific version
  exports: Record<string, any>;      // Plugin's exports

  callMethod(method: string, ...args: any[]): Promise<any>;
}
```

**Versioning Rules (contract):**

```
MAJOR version increments:
  - Breaking API removals
  - Incompatible parameter changes
  - Behavior changes affecting plugin contracts

MINOR version increments:
  - New API methods (backward compatible)
  - New optional parameters
  - Deprecated methods still work

PATCH version increments:
  - Bug fixes
  - Performance improvements
  - Security patches

Deprecation policy:
  - Mark for 2 minor versions
  - Show warnings (with migration guide)
  - Remove in next major version
```

