## 3. Lifecycle Hooks

### 3.1 Hook Contract

All hooks are **optional** but if declared must be exported by the entrypoint module. Each hook receives a `PluginContext` and must return a Promise.

```typescript
type PluginHookResult = {
  success: boolean;
  error?: string;
  data?: unknown;
};

interface PluginHandlers {
  // Called after plugin code loads but before it becomes available to host
  onLoad?(context: PluginContext): Promise<PluginHookResult>;

  // Called before plugin is removed from registry (e.g., uninstall, disable)
  onUnload?(context: PluginContext): Promise<PluginHookResult>;

  // Called when plugin is reloaded (e.g., after an update)
  onReload?(context: PluginContext): Promise<PluginHookResult>;

  // Called when any lifecycle hook fails
  onError?(context: PluginContext, error: PluginError): Promise<void>;

  // Exported capabilities (e.g., transform handlers, datasources)
  [key: string]: unknown;
}

interface PluginContext {
  // Identity
  pluginId: string;
  version: string;

  // Host API (versioned, stable)
  api: PluginAPI;

  // Configuration (from manifest + user overrides)
  config: Record<string, unknown>;

  // Filesystem access (sandboxed to plugin directory)
  fs: SandboxedFileSystem;

  // Logging
  logger: Logger;

  // State persistence (per plugin, survives reload)
  storage: KeyValueStore;

  // Other loaded plugins (read-only access to public APIs)
  plugins: PluginRegistry;
}
```

