### 3.3 Hook Execution Guarantees

| Hook | Called When | Timeout | Rollback Behavior |
|------|-------------|---------|-------------------|
| `onLoad` | Plugin finishes loading | `config.timeoutSeconds` | Plugin stays unloaded; `onError` fired |
| `onUnload` | Host calls `unload()` or plugin disabled | `config.timeoutSeconds` | Plugin forced to unloaded; `onError` fired |
| `onReload` | Plugin updated; called after `onUnload` succeeds | `config.timeoutSeconds` | Reload aborted; plugin reverts to prior version if one exists |
| `onError` | Any hook fails or plugin crashes during execution | `5000ms` (fixed) | Non-blocking; if error handler fails, logged to debug, not escalated |

### 3.4 Example Lifecycle Implementation

```typescript
// pdf-export-plugin/src/handlers.ts
import { PluginContext, PluginHookResult } from '@reporting/plugin-api';

export async function onLoad(context: PluginContext): Promise<PluginHookResult> {
  try {
    // Validate configuration
    const { apiKey, cachingEnabled } = context.config;
    if (!apiKey) {
      return { success: false, error: 'apiKey required in configuration' };
    }

    // Initialize external service connection
    context.logger.info('Initializing PDF rendering service...');
    const renderService = new PDFRenderService({
      apiKey,
      timeout: 30000
    });

    // Test connectivity
    await renderService.healthCheck();

    // Set up storage for caching
    if (cachingEnabled) {
      await context.storage.set('cache-version', '1.0');
      context.logger.info('Caching enabled');
    }

    // Store for later use (accessible to exported transforms)
    context.api.setPluginData(context.pluginId, {
      renderService,
      cacheEnabled: cachingEnabled
    });

    return { success: true, data: { version: context.version } };
  } catch (error) {
    return {
      success: false,
      error: `Failed to initialize: ${error.message}`
    };
  }
}

export async function onUnload(context: PluginContext): Promise<PluginHookResult> {
  try {
    context.logger.info('Cleaning up PDF rendering service...');
    const data = context.api.getPluginData(context.pluginId);
    if (data?.renderService) {
      await data.renderService.shutdown();
    }
    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: `Failed to clean up: ${error.message}`
    };
  }
}

export async function onReload(context: PluginContext): Promise<PluginHookResult> {
  // Reload updates configuration from disk, reinitializes services
  // Orchestrated by registry: calls onUnload → reloads code → calls onLoad
  // Plugin author typically doesn't implement onReload; registry handles it
  return { success: true };
}

export async function onError(
  context: PluginContext,
  error: PluginError
): Promise<void> {
  // Non-blocking error handler
  // Send to monitoring service, clean up partial state, notify user
  context.logger.error(`PDF plugin error: ${error.message} (${error.code})`);

  // Example: alert monitoring system
  await fetch('https://monitoring.internal/error', {
    method: 'POST',
    body: JSON.stringify({
      plugin: context.pluginId,
      version: context.version,
      error: error.message
    })
  }).catch(() => {}); // Don't escalate network failures
}
```

