### 6.4 Handlers (handlers.ts)

```typescript
import { PluginContext, PluginHookResult, PluginError } from '@reporting/plugin-api';
import { createPool, Pool } from 'pg';

let connectionPool: Pool;

export async function onLoad(context: PluginContext): Promise<PluginHookResult> {
  try {
    const config = context.config as {
      host: string;
      port: number;
      database: string;
      user: string;
      password: string;
      connectionPoolSize: number;
      queryTimeoutSeconds: number;
    };

    context.logger.info(
      `Initializing PostgreSQL connection pool: ${config.host}:${config.port}/${config.database}`
    );

    connectionPool = createPool({
      host: config.host,
      port: config.port,
      database: config.database,
      user: config.user,
      password: config.password,
      max: config.connectionPoolSize,
      statement_timeout: config.queryTimeoutSeconds * 1000,
      query_timeout: config.queryTimeoutSeconds * 1000
    });

    // Test connection
    await connectionPool.query('SELECT 1');
    context.logger.info('PostgreSQL connection successful');

    // Store pool for datasource handler
    context.api.setPluginData(context.pluginId, { connectionPool });

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: `PostgreSQL initialization failed: ${error.message}`
    };
  }
}

export async function onUnload(context: PluginContext): Promise<PluginHookResult> {
  try {
    context.logger.info('Closing PostgreSQL connection pool');
    if (connectionPool) {
      await connectionPool.end();
    }
    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: `Failed to close PostgreSQL pool: ${error.message}`
    };
  }
}

export async function onError(context: PluginContext, error: PluginError) {
  context.logger.error(`PostgreSQL plugin error: ${error.message}`);
  // Could alert on pool exhaustion, connection timeouts, etc.
}
```

### 6.5 Datasource (datasource.ts)

```typescript
import { PluginContext } from '@reporting/plugin-api';

export class PostgresDataSource {
  constructor(private context: PluginContext) {}

  async execute(query: string, params: unknown[] = []): Promise<any[]> {
    const data = this.context.api.getPluginData(this.context.pluginId);
    if (!data?.connectionPool) {
      throw new Error('PostgreSQL not initialized');
    }

    try {
      const result = await data.connectionPool.query(query, params);
      return result.rows;
    } catch (error) {
      this.context.logger.error(`Query failed: ${error.message}`);
      throw error;
    }
  }

  async validateConnection(): Promise<boolean> {
    try {
      await this.execute('SELECT 1');
      return true;
    } catch {
      return false;
    }
  }
}
```

