## 8. Implementation Guide

### 8.1 Plugin Registry Implementation

```typescript
class PluginRegistry implements IPluginRegistry {
  private plugins = new Map<string, PluginMetadata>();
  private runtime = new Map<string, PluginRuntime>();
  private discoveryPaths: string[];

  constructor(discoveryPaths: string[]) {
    this.discoveryPaths = discoveryPaths;
  }

  async discover(): Promise<void> {
    for (const path of this.discoveryPaths) {
      const dirs = await fs.readdir(path);
      for (const dir of dirs) {
        const manifest = await this.loadManifest(join(path, dir));
        if (manifest) {
          this.plugins.set(manifest.id, manifest);
          this.runtime.set(manifest.id, {
            pluginId: manifest.id,
            status: "idle",
            instance: null,
            resourceUsage: { memoryMb: 0, cpuMs: 0, activeRequests: 0 },
            hooks: [],
          });
        }
      }
    }
  }

  async load(pluginId: string): Promise<PluginInstance> {
    const meta = this.plugins.get(pluginId);
    if (!meta) throw new Error(`Plugin ${pluginId} not found`);

    const rt = this.runtime.get(pluginId);
    if (rt.status === "active") return rt.instance;

    rt.status = "loading";
    try {
      const instance = await this.instantiate(meta);

      // Call onLoad hook
      if (instance.lifecycle?.onLoad) {
        await this.withTimeout(
          instance.lifecycle.onLoad({
            version: meta.version,
            environment: process.env.NODE_ENV as any,
            config: meta.settings,
            logger: new PluginLogger(pluginId),
            permissions: meta.capabilities.permissions,
            apiVersion: getCurrentAPIVersion(),
          }),
          10000
        );
      }

      rt.status = "active";
      rt.instance = instance;
      rt.loadedAt = new Date().toISOString();
      return instance;
    } catch (err) {
      rt.status = "failed";
      rt.lastError = err as PluginError;
      throw err;
    }
  }

  async unload(pluginId: string): Promise<void> {
    const rt = this.runtime.get(pluginId);
    if (rt.status !== "active") return;

    rt.status = "unloading";
    const instance = rt.instance;

    try {
      if (instance?.lifecycle?.onUnload) {
        await this.withTimeout(
          instance.lifecycle.onUnload({
            reason: "uninstall",
            force: false,
            logger: new PluginLogger(pluginId),
          }),
          5000
        );
      }
    } catch (err) {
      console.error(`Failed to unload ${pluginId}:`, err);
    } finally {
      rt.status = "idle";
      rt.instance = null;
      rt.unloadedAt = new Date().toISOString();
    }
  }

  private async withTimeout<T>(
    promise: Promise<T>,
    timeoutMs: number
  ): Promise<T> {
    return Promise.race([
      promise,
      new Promise((_, reject) =>
        setTimeout(() => reject(new Timeout("Lifecycle operation timeout", timeoutMs)), timeoutMs)
      ),
    ]);
  }

  private async instantiate(meta: PluginMetadata): Promise<PluginInstance> {
    const mod = require(meta.installationPath + "/" + meta.entry.main);
    return new PluginInstance(meta.id, mod.default || mod);
  }

  private async loadManifest(dir: string): Promise<PluginMetadata | null> {
    try {
      const content = await fs.readFile(join(dir, "plugin.json"), "utf-8");
      const manifest = JSON.parse(content);

      // Validate against schema
      await validateManifest(manifest);

      return {
        ...manifest,
        installationPath: dir,
        installedAt: new Date().toISOString(),
        checksum: await hashDirectory(dir),
      };
    } catch (err) {
      console.error(`Invalid manifest in ${dir}:`, err);
      return null;
    }
  }
}
```

### 8.2 Permission Interceptor

```typescript
class CapabilityInterceptor {
  constructor(private permissions: Permission[]) {}

  interceptEnv(key: string): string | undefined {
    const perm = this.permissions.find(
      p => p.type === "env" && p.variable === key
    ) as EnvVarPermission;

    if (!perm) {
      throw new PermissionDenied(`Access to env var ${key} denied`);
    }

    return process.env[key];
  }

  interceptFetch(url: string, options?: RequestInit): Promise<Response> {
    const urlObj = new URL(url);
    const perm = this.permissions.find(
      p => p.type === "network" && this.matchesHost(urlObj.host, p.hosts)
    ) as NetworkPermission;

    if (!perm || !perm.protocols.includes(urlObj.protocol.slice(0, -1) as any)) {
      throw new PermissionDenied(
        `Network access to ${url} denied; not in allowed hosts`
      );
    }

    return fetch(url, options);
  }

  interceptFileRead(path: string): Buffer {
    const perm = this.permissions.find(
      p =>
        p.type === "filesystem" &&
        p.access.includes("read") &&
        this.isUnderPath(path, p.path)
    ) as FilesystemPermission;

    if (!perm) {
      throw new PermissionDenied(`Read access to ${path} denied`);
    }

    return fs.readFileSync(path);
  }

  private matchesHost(actual: string, allowed: string[]): boolean {
    return allowed.some(a =>
      a.startsWith("*")
        ? actual.endsWith(a.slice(1))
        : actual === a
    );
  }

  private isUnderPath(file: string, dir: string): boolean {
    return resolve(file).startsWith(resolve(dir));
  }
}
```

### 8.3 Plugin Wrapper (Lifecycle + API Binding)

```typescript
class PluginInstance {
  instance: any;
  lifecycle: PluginLifecycle;
  api: ReportingAPI;

  constructor(id: string, module: any, apiVersion: string) {
    this.instance = module;
    this.lifecycle = module.lifecycle || {};

    // Bind API to version
    this.api = getAPIVersion(apiVersion);

    // Wrap API calls with permission checks
    this.api = new PermissionCheckingProxy(this.api, permissions);

    // Track resource usage
    this.api = new ResourceTrackingProxy(this.api, resourceLimits);
  }
}

class PermissionCheckingProxy implements ReportingAPI {
  constructor(private api: ReportingAPI, private interceptor: CapabilityInterceptor) {}

  async query(spec: QuerySpec): Promise<Dataset> {
    // Interceptor wraps all internal I/O
    return this.api.query(spec);
  }
  // ... other methods
}

class ResourceTrackingProxy implements ReportingAPI {
  constructor(private api: ReportingAPI, private limits: ResourceLimits) {}

  async query(spec: QuerySpec): Promise<Dataset> {
    const timer = startTimer();
    const memBefore = process.memoryUsage().heapUsed;

    try {
      const result = await this.api.query(spec);

      const memAfter = process.memoryUsage().heapUsed;
      const elapsed = timer.ms();

      if (memAfter - memBefore > this.limits.memoryMb * 1024 * 1024) {
        throw new OutOfMemory(`Exceeded memory limit`);
      }
      if (elapsed > this.limits.wallclockTimeMs) {
        throw new Timeout(`Exceeded wallclock timeout`);
      }

      return result;
    } catch (err) {
      throw err;
    }
  }
  // ... other methods
}
```

