## 10. Extension Points & Hooks

### 10.1 DataSource Plugin Example

```typescript
// my-datasource-plugin/src/index.ts
import { ReportingAPI, DataSource } from "@reporting-tool/api-v7";

export class MyDataSource implements DataSource {
  private api: ReportingAPI;
  private connection: DatabaseConnection;

  constructor(api: ReportingAPI) {
    this.api = api;
  }

  async query(spec: QuerySpec): Promise<Dataset> {
    const stmt = this.buildSQL(spec);
    const rows = await this.connection.query(stmt);
    return {
      schema: this.inferSchema(rows),
      rows,
      metadata: {
        sourceId: "my-datasource",
        rowCount: rows.length,
        fetchedAt: new Date().toISOString(),
      },
    };
  }

  private buildSQL(spec: QuerySpec): string {
    // Convert QuerySpec to SQL
    let sql = "SELECT * FROM table";
    if (spec.filters?.length) {
      sql += " WHERE " + spec.filters.map(f => f.toSQL()).join(" AND ");
    }
    return sql;
  }

  private inferSchema(rows: any[]): ColumnSchema[] {
    // Infer types from first row
    return Object.entries(rows[0]).map(([name, value]) => ({
      name,
      type: typeof value,
    }));
  }
}

export const lifecycle = {
  async onLoad(ctx) {
    ctx.logger.info("Loading MyDataSource plugin");

    // Access environment (if permitted)
    const connStr = ctx.config.connectionString;

    // Initialize connection
    this.connection = new DatabaseConnection(connStr);
    await this.connection.verify();
  },

  async onUnload(ctx) {
    ctx.logger.info("Unloading MyDataSource plugin");
    await this.connection.close();
  },
};

export default MyDataSource;
```

### 10.2 Transformer Plugin Example

```typescript
// my-transformer-plugin/src/index.ts
import { Transformer, Dataset, AggregationSpec } from "@reporting-tool/api-v7";

export class MyTransformer implements Transformer {
  async transform(
    data: Dataset,
    spec: AggregationSpec
  ): Promise<Dataset> {
    const grouped = this.groupBy(data, spec.groupBy);
    const aggregated = this.aggregate(grouped, spec.aggregations);

    return {
      schema: this.buildOutputSchema(spec),
      rows: aggregated,
      metadata: {
        ...data.metadata,
        transformedBy: "my-transformer",
        groupCount: aggregated.length,
      },
    };
  }

  private groupBy(data: Dataset, keys: string[]): Map<string, any[]> {
    const groups = new Map<string, any[]>();
    for (const row of data.rows) {
      const key = keys.map(k => row[k]).join("|");
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(row);
    }
    return groups;
  }

  private aggregate(
    groups: Map<string, any[]>,
    aggregations: AggregationFunc[]
  ): any[] {
    return Array.from(groups.values()).map(group =>
      aggregations.reduce((acc, agg) => {
        acc[agg.outputName] = agg.compute(group);
        return acc;
      }, {})
    );
  }
}

export const lifecycle = {
  async onLoad(ctx) {
    ctx.logger.info("Transformer ready");
  },
};

export default MyTransformer;
```

