```typescript
async validatePlugin(manifestPath: string): Promise<ValidationResult> {
  const manifest = await loadManifest(manifestPath);

  const checks = {
    schemaValid: await validateManifestSchema(manifest),
    idUnique: !registry.has(manifest.id),
    apiCompatible: isAPIVersionSupported(manifest.minApiVersion),
    entryExists: await fileExists(manifest.entry.main),
    dependenciesResolvable: await canResolveDependencies(manifest.dependencies),
    permissionsReasonable: await checkPermissionsPolicy(manifest.capabilities.permissions),
  };

  return {
    valid: Object.values(checks).every(v => v),
    checks,
    errors: Object.entries(checks)
      .filter(([_, result]) => !result)
      .map(([check, _]) => `Failed: ${check}`),
  };
}
