// Every 5 minutes (configurable), host calls onHealthCheck
async runHealthChecks(): Promise<void> {
  for (const [pluginId, runtime] of this.runtime) {
    if (runtime.status !== "active") continue;

    try {
      const health = await this.withTimeout(
        runtime.instance.lifecycle.onHealthCheck?.({
          logger: new PluginLogger(pluginId),
          apiVersion: getCurrentAPIVersion(),
        }),
        5000
      );

      // Record metrics
      emit("plugin:health", {
        pluginId,
        status: health?.status || "healthy",
        details: health?.details,
      });
    } catch (err) {
      emit("plugin:health:error", {
        pluginId,
        error: err.message,
      });
    }
  }
}
