### 2.4 Discovery & Resolution Algorithm

```typescript
class PluginRegistry {
  async resolve(spec: DependencySpec): Promise<PluginMetadata> {
    // 1. Look up plugin by ID
    const candidates = await this.list({ pluginId: spec.pluginId });

    // 2. Filter by version constraint (semver)
    const compatible = candidates.filter(p => 
      semver.satisfies(p.version, spec.versionConstraint)
    );

    if (compatible.length === 0) {
      throw new UnresolvedDependencyError(spec);
    }

    // 3. Return latest matching version (prefer stable)
    return compatible.sort((a, b) => 
      semver.compare(b.version, a.version)
    )[0];
  }
}
```

