## 4. Lifecycle Hooks & State Machine

### 4.1 Plugin State Machine

```
┌─────────────────────────────────────────────────────────────┐
│                                                             │
│  REGISTERED ──→ LOADING ──→ LOADED ──→ ACTIVATING ──→ ACTIVE
│                    ↑          ↓         ↓          ↓        │
│                    │        ERROR     FAILED     RELOADING  │
│                    │          ↓         ↓          ↓        │
│                    │      UNLOADING  SUSPENDED  (retry)     │
│                    │          ↓         ↓          ↓        │
│                    └──────────UNLOADED←─────────→ INACTIVE  │
│                                                             │
└─────────────────────────────────────────────────────────────┘

State Descriptions:
- REGISTERED: Manifest parsed, not yet instantiated
- LOADING: Entry point module being loaded
- LOADED: Module loaded, awaiting initialization
- ACTIVATING: Lifecycle hooks being invoked
- ACTIVE: Fully operational, serving requests
- RELOADING: Hot-reload in progress
- SUSPENDED: Temporarily disabled (manual or error)
- UNLOADING: Cleanup in progress
- UNLOADED: Removed from memory
- ERROR: Unrecoverable failure
```

### 4.2 Lifecycle Hooks

Every plugin exports a lifecycle handler that implements this interface:

```typescript
interface PluginLifecycle {
  // Called once after module load, before serving requests
  onLoad(context: PluginContext): Promise<void>;

  // Called before unloading (graceful shutdown)
  onUnload(): Promise<void>;

  // Called during hot-reload (optional, supports true reloading)
  onReload?(): Promise<void>;

  // Called on catastrophic error
  onError(error: PluginError): Promise<void>;

  // Health check (periodic, ~30s interval)
  onHealthCheck?(): Promise<HealthStatus>;
}

interface PluginContext {
  pluginId: string;
  version: string;
  config: Record<string, unknown>;
  logger: Logger;
  api: TtakHostAPI;
  cache: CacheProvider;
  fs: FileSystemProvider;
  permissions: PermissionManager;
}

interface HealthStatus {
  status: 'healthy' | 'degraded' | 'unhealthy';
  details?: Record<string, unknown>;
  nextCheckIn?: number; // milliseconds
}
```

### 4.3 Hook Implementation Example

```typescript
// plugin/src/index.ts
export class CustomReportsPlugin {
  private cache: CacheProvider;
  private api: TtakHostAPI;
  private client?: ApiClient;

  async onLoad(context: PluginContext) {
    this.cache = context.cache;
    this.api = context.api;

    // Initialize external client with scoped permissions
    const perms = context.permissions.check('network.outbound');
    if (!perms.granted) {
      throw new PermissionError('network.outbound permission not granted');
    }

    this.client = new ApiClient(context.config.apiKey);

    // Warm up caches
    await this.client.validateConnection();
    context.logger.info('Custom Reports plugin initialized');
  }

  async onUnload() {
    await this.client?.disconnect();
    await this.cache.flush();
  }

  async onReload() {
    // Preserve running requests, reload configuration
    await this.cache.clear();
    this.client = new ApiClient(this.api.config.get('apiKey'));
  }

  async onHealthCheck(): Promise<HealthStatus> {
    try {
      const ping = await this.client?.ping();
      return {
        status: ping ? 'healthy' : 'degraded',
        details: { apiLatency: ping }
      };
    } catch (err) {
      return {
        status: 'unhealthy',
        details: { error: err.message }
      };
    }
  }

  // Plugin interface (exported)
  generateReport(spec: ReportSpec) { /*...*/ }
  fetchData(query: DataQuery) { /*...*/ }
}

export const lifecycle: PluginLifecycle = {
  onLoad: (ctx) => new CustomReportsPlugin().onLoad(ctx),
  onUnload: () => new CustomReportsPlugin().onUnload(),
  onReload: () => new CustomReportsPlugin().onReload(),
  onHealthCheck: () => new CustomReportsPlugin().onHealthCheck(),
};
```

### 4.4 Lifecycle Manager

```typescript
class PluginLifecycleManager {
  async load(pluginId: string): Promise<void> {
    const meta = await this.registry.get(pluginId);
    this.registry.setLoadState(pluginId, 'loading');

    try {
      // 1. Load module
      const module = await this.moduleLoader.load(meta.entryPoint);

      // 2. Create context
      const context = this.createContext(meta);

      // 3. Call onLoad hook with timeout
      await this.executeHook(
        module.lifecycle.onLoad,
        context,
        meta.lifecycle.maxInitTime
      );

      this.registry.setLoadState(pluginId, 'active');
    } catch (err) {
      this.registry.setLoadState(pluginId, 'error');
      this.logger.error(`Failed to load plugin ${pluginId}:`, err);
      throw new PluginLoadError(pluginId, err);
    }
  }

  async reload(pluginId: string): Promise<void> {
    const meta = await this.registry.get(pluginId);
    if (!meta.lifecycle.supportsReload) {
      throw new Error(`Plugin ${pluginId} does not support reloading`);
    }

    this.registry.setLoadState(pluginId, 'reloading');
    try {
      const module = await this.moduleLoader.getLoaded(pluginId);
      await this.executeHook(
        module.lifecycle.onReload,
        this.createContext(meta),
        meta.lifecycle.maxInitTime
      );
      this.registry.setLoadState(pluginId, 'active');
    } catch (err) {
      await this.unload(pluginId);
      throw new PluginReloadError(pluginId, err);
    }
  }

  async unload(pluginId: string): Promise<void> {
    this.registry.setLoadState(pluginId, 'unloading');
    try {
      const module = await this.moduleLoader.getLoaded(pluginId);
      const meta = await this.registry.get(pluginId);

      await this.executeHook(
        module.lifecycle.onUnload,
        null,
        meta.lifecycle.maxShutdownTime
      );

      this.moduleLoader.unload(pluginId);
      this.registry.setLoadState(pluginId, 'unloaded');
    } catch (err) {
      this.registry.setLoadState(pluginId, 'suspended');
      throw new PluginUnloadError(pluginId, err);
    }
  }

  private async executeHook(
    hook: Function,
    context: PluginContext | null,
    timeout: number
  ): Promise<void> {
    return Promise.race([
      hook(context),
      new Promise((_, reject) =>
        setTimeout(() => reject(new TimeoutError()), timeout)
      )
    ]);
  }
}
```

