## 5. Sandboxed Execution Boundary

### 5.1 Sandbox Architecture

Plugins run in **V8 isolates** (Node.js vm module) with strict memory limits and no access to host globals.

```
┌─────────────────────────────────────────────────────────┐
│ HOST PROCESS                                            │
│  ├─ TTAK Core API (restricted view)                     │
│  └─ Permission Manager                                  │
│                                                         │
│  ┌─────────────────────────────────────────────┐       │
│  │ V8 ISOLATE (Plugin Sandbox)                 │       │
│  │  ├─ Plugin Module                           │       │
│  │  ├─ Plugin Runtime (~50MB memory limit)     │       │
│  │  ├─ Filtered require() whitelist            │       │
│  │  └─ No access to: fs, process, child_proc  │       │
│  │                                              │       │
│  │  ┌────────────────────────────────────────┐ │       │
│  │  │ Capability-Based Access Control        │ │       │
│  │  │ - data.read (filtered by scope)        │ │       │
│  │  │ - network.outbound (URL whitelist)     │ │       │
│  │  │ - file.read (path whitelist)           │ │       │
│  │  │ - file.write (path: plugin storage)    │ │       │
│  │  └────────────────────────────────────────┘ │       │
│  │                                              │       │
│  └─────────────────────────────────────────────┘       │
│                                                         │
└─────────────────────────────────────────────────────────┘
```

### 5.2 Sandbox Policy & Limits

```typescript
interface SandboxPolicy {
  // Memory constraints
  memoryLimitMB: number;              // 50-200 MB per plugin
  heapSnapshotEnabled: boolean;       // For debugging OOM

  // CPU constraints
  cpuQuotaMs?: number;                // Optional throttling

  // Module whitelist (only these can be require'd)
  allowedModules: string[];           // ['lodash', 'axios', '@ttak/api']
  blockedModules: string[];           // ['child_process', 'fs', 'net']

  // File system access (scoped to plugin storage)
  fileSystemRoot: string;             // /var/lib/ttak/plugins/{pluginId}/data
  allowedPaths: GlobPattern[];

  // Network access (whitelist URLs)
  networkWhitelist: UrlPattern[];
  dnsEnabled: boolean;

  // Timing (detect infinite loops)
  executionTimeoutMs: number;         // 30s for sync, per-async-call for async

  // Capabilities (explicit allow-list)
  capabilities: Capability[];
}

class SandboxRuntime {
  private isolate: vm.Isolate;
  private context: vm.Context;
  private monitoring: RuntimeMonitor;

  constructor(policy: SandboxPolicy, pluginId: string) {
    this.isolate = new vm.Isolate({ memoryLimit: policy.memoryLimitMB });
    this.context = this.isolate.createContextSync();

    // Install filtered globals
    this.installGlobals(policy);

    // Install capability-gated API
    this.installCapabilityAPI(policy);

    // Monitor resource usage
    this.monitoring = new RuntimeMonitor(pluginId, policy);
  }

  private installGlobals(policy: SandboxPolicy) {
    const globals = {
      // Standard globals
      console: console,
      setTimeout: global.setTimeout,
      setInterval: global.setInterval,
      Promise: Promise,
      JSON: JSON,
      // Blocked from plugin context:
      // process, require, __dirname, __filename, eval, Function
    };

    Object.assign(this.context, globals);
  }

  private installCapabilityAPI(policy: SandboxPolicy) {
    this.context.api = {
      // Only methods matching declared capabilities
      data: {
        read: async (spec) => this.checkPermission('data.read', spec.scope),
        // ... more data methods
      },
      network: {
        fetch: (url) => this.checkPermission('network.outbound', url),
        // ... more network methods
      },
      file: {
        read: (path) => this.checkPermission('file.read', path),
        write: (path) => this.checkPermission('file.write', path),
      },
      cache: {
        get: (key) => { /*...*/ },
        set: (key, value) => { /*...*/ },
      }
    };
  }

  private checkPermission(resource: string, scope: string): Promise<any> {
    if (!this.policy.capabilities.some(c => c.name === resource)) {
      throw new PermissionError(`${resource} not declared in manifest`);
    }
    // Check scoped access (regex matching)
    if (!this.isScopeAllowed(resource, scope)) {
      throw new PermissionError(`Access to ${scope} denied by policy`);
    }
    // Delegate to host API
    return this.hostAPI.execute(resource, scope);
  }
}
```

### 5.3 Isolation Testing & Verification

```typescript
class SandboxVerifier {
  // Unit test: verify no breakout to host
  async testIsolation(pluginId: string): Promise<VerificationResult> {
    const tests = [
      () => this.testGlobalAccess(),      // process, require, eval
      () => this.testFileSystemAccess(),  // Out-of-bounds paths
      () => this.testNetworkAccess(),     // Unwhitelisted hosts
      () => this.testMemoryLimit(),       // Allocating >limit
      () => this.testTimeoutEnforcement(), // Infinite loops
    ];

    return Promise.all(tests.map(t => t()));
  }

  private testGlobalAccess(): Promise<VerificationResult> {
    const maliciousCode = `
      try { require('child_process').exec('id'); } catch (e) { return 'BLOCKED'; }
      try { process.exit(1); } catch (e) { return 'BLOCKED'; }
      try { eval('1+1'); } catch (e) { return 'BLOCKED'; }
    `;
    // Should throw, not execute
    return this.runInSandbox(maliciousCode);
  }
}
```

