### 6.3 API Backward Compatibility Layer

```typescript
class HostAPIAdapter {
  static createForPlugin(
    pluginVersion: string,
    hostVersion: string
  ): TtakHostAPI {
    // Plugin targets v1.0 API, host provides v1.2
    // Adapter fills in the gap

    const base = this.getCoreAPI();

    if (semver.lt(pluginVersion, '2.0.0')) {
      // Plugin is v1.x, might use deprecated methods
      base.reports.legacyGenerate = this.legacyReportAdapter();
    }

    if (semver.gt(hostVersion, pluginVersion)) {
      // Host is newer, add compatibility layer
      base.$compat = {
        warnings: this.getDeprecationWarnings(pluginVersion, hostVersion),
      };
    }

    return base;
  }
}
```

