### 7.2 Plugin Discovery & Composition

```typescript
class PluginComposer {
  // Find all plugins implementing a capability
  async findByCapability(
    capability: string,
    version?: string
  ): Promise<PluginMetadata[]> {
    return this.registry.list({
      capabilities: capability,
      minVersion: version
    });
  }

  // Compose a report pipeline from plugins
  async composeReportPipeline(spec: ReportSpec): Promise<ReportPipeline> {
    // 1. Find data source plugin
    const dataSources = await this.findByCapability('data.source');
    const chosenSource = this.selectBestMatch(dataSources, spec.sourceType);

    // 2. Find middleware plugins (in order)
    const middleware = await this.findByCapability('middleware.processor');
    const sortedMiddleware = middleware.sort((a, b) => 
      (a.order || 0) - (b.order || 0)
    );

    // 3. Find renderer
    const renderers = await this.findByCapability('visualization.renderer');
    const chosenRenderer = this.selectBestMatch(renderers, spec.chartType);

    // 4. Find exporter
    const exporters = await this.findByCapability('export.target');
    const chosenExporter = this.selectBestMatch(exporters, spec.destination);

    return {
      dataSource: chosenSource,
      middleware: sortedMiddleware,
      renderer: chosenRenderer,
      exporter: chosenExporter,
    };
  }

  async executePipeline(pipeline: ReportPipeline, spec: ReportSpec): Promise<void> {
    // 1. Fetch data
    let data = await pipeline.dataSource.query(spec.sourceParams);

    // 2. Process through middleware
    for (const processor of pipeline.middleware) {
      data = await processor.process(data, spec.processingConfig);
    }

    // 3. Render visualization
    const visualization = await pipeline.renderer.render(data, spec.renderConfig);

    // 4. Export
    await pipeline.exporter.export(visualization, spec.destination);
  }
}
```

