## 8. Security & Permission Model

### 8.1 Capability-Based Permissions

Plugins declare required permissions in the manifest; platform grants or denies at load time.

```typescript
interface Permission {
  resource: string;           // 'data.read', 'network.outbound', etc.
  scope: string;              // Glob pattern: 'reports:*', 'https://api.*.com/*'
  rationale: string;          // Why plugin needs this
  sensitive?: boolean;        // Requires admin approval
}

enum PermissionLevel {
  ALWAYS_GRANT = 'always_grant',      // Public data access
  ADMIN_APPROVAL = 'admin_approval',  // Sensitive APIs
  INTERACTIVE = 'interactive',        // Ask user at load time
}

class PermissionManager {
  async grantPermissions(
    pluginId: string,
    permissions: Permission[]
  ): Promise<PermissionGrant[]> {
    return permissions.map(perm => {
      const level = this.determineLevel(perm);

      switch (level) {
        case PermissionLevel.ALWAYS_GRANT:
          return { granted: true, resource: perm.resource };

        case PermissionLevel.ADMIN_APPROVAL:
          return this.auditLog({
            action: 'permission_request',
            plugin: pluginId,
            permission: perm,
            requiresApproval: true,
          });

        case PermissionLevel.INTERACTIVE:
          return { granted: false, requiresUserAction: true };
      }
    });
  }

  checkPermission(
    context: PluginContext,
    resource: string,
    scope: string
  ): boolean {
    const grants = context.permissions;
    return grants.some(g =>
      g.resource === resource && this.scopeMatches(g.scope, scope)
    );
  }

  private scopeMatches(scopePattern: string, requestedScope: string): boolean {
    // 'reports:*' matches 'reports:123'
    // 'https://api.example.com/*' matches 'https://api.example.com/v1/data'
    const regex = new RegExp(`^${scopePattern.replace('*', '.*')}$`);
    return regex.test(requestedScope);
  }
}
```

### 8.2 Audit Logging

```typescript
interface AuditLog {
  timestamp: ISO8601;
  event: AuditEvent;
  plugin: {
    id: string;
    version: string;
  };
  action: string;              // 'load', 'unload', 'permission_grant', 'permission_deny'
  resource?: string;
  result: 'success' | 'failure';
  details?: Record<string, any>;
  principal: string;           // User or service that initiated action
}

class AuditLogger {
  async log(entry: AuditLog): Promise<void> {
    // 1. Write to durable audit log
    await this.auditStore.append(entry);

    // 2. Alert on sensitive actions
    if (entry.action === 'permission_grant' && entry.details?.sensitive) {
      await this.alerting.notifyAdmins(entry);
    }

    // 3. Index for compliance reporting
    await this.searchIndex.index(entry);
  }

  async getPluginAuditTrail(
    pluginId: string,
    since?: ISO8601
  ): Promise<AuditLog[]> {
    return this.auditStore.query({
      'plugin.id': pluginId,
      timestamp: { $gte: since }
    });
  }
}
```

### 8.3 Security Best Practices for Plugin Developers

Plugins must:
1. Declare all required permissions in manifest
2. Use only allowed modules (no dynamic requires)
3. Validate all user inputs
4. Never log sensitive data (API keys, auth tokens)
5. Handle errors gracefully; don't expose stack traces
6. Implement rate limiting for external API calls
7. Clean up resources in onUnload

