### 9.2 Runtime Environment

```typescript
interface PluginRuntimeEnvironment {
  // Plugin metadata
  pluginId: string;
  version: string;

  // Configuration (validated against schema)
  config: Record<string, unknown>;

  // File system root (plugin can only access this directory)
  dataDir: string;

  // Sandbox policy
  policy: SandboxPolicy;

  // Resource limits at startup
  cpuLimit?: number;
  memoryLimit: number;

  // Telemetry
  telemetry: TelemetryCollector;

  // Logging
  logger: Logger;
}

class PluginExecutor {
  async executeInSandbox<T>(
    pluginId: string,
    fn: (api: TtakHostAPI) => Promise<T>,
    timeout: number = 30000
  ): Promise<T> {
    const runtime = this.runtimes.get(pluginId);
    if (!runtime) throw new Error(`Plugin ${pluginId} not loaded`);

    // Run function in isolate context with timeout
    return Promise.race([
      runtime.execute(fn),
      new Promise((_, reject) =>
        setTimeout(() => reject(new TimeoutError()), timeout)
      )
    ]);
  }
}
```

