### 10.2 Installation Workflow

```typescript
class PluginInstaller {
  async install(
    packagePath: string,
    opts?: InstallOptions
  ): Promise<PluginMetadata> {
    // 1. Extract and validate
    const manifest = await this.validate(packagePath);

    // 2. Check compatibility
    const compatible = await this.checkCompatibility(manifest);
    if (!compatible) {
      throw new IncompatibilityError(manifest);
    }

    // 3. Scan for security issues
    const scan = await this.securityScanner.scan(packagePath);
    if (scan.critical.length > 0) {
      throw new SecurityError(scan.critical);
    }

    // 4. Register in registry
    const token = await this.registry.register(manifest);

    // 5. Copy to plugin storage
    await this.fileSystem.install(manifest.id, packagePath);

    // 6. Audit log
    await this.auditLog.log({
      action: 'install',
      plugin: manifest.id,
      version: manifest.version,
      principal: opts?.user || 'system',
    });

    return manifest;
  }
}
```

### 10.3 Health Monitoring & Alerting

```typescript
class PluginHealthMonitor {
  private checks = new Map<string, HealthCheckSchedule>();

  startMonitoring(pluginId: string): void {
    // Run health checks every 30 seconds
    this.checks.set(pluginId, setInterval(async () => {
      const status = await this.executeHealthCheck(pluginId);

      switch (status.status) {
        case 'healthy':
          // No action
          break;
        case 'degraded':
          // Log warning, continue
          this.logger.warn(`Plugin ${pluginId} degraded`, status.details);
          break;
        case 'unhealthy':
          // Attempt recovery: reload
          try {
            await this.lifecycleManager.reload(pluginId);
          } catch {
            // Failed recovery: suspend and alert
            await this.registry.setLoadState(pluginId, 'suspended');
            await this.alerting.sendAlert({
              severity: 'high',
              message: `Plugin ${pluginId} is unhealthy and could not be recovered`,
              details: status.details,
            });
          }
      }
    }, 30000));
  }

  stopMonitoring(pluginId: string): void {
    clearInterval(this.checks.get(pluginId));
    this.checks.delete(pluginId);
  }

  private async executeHealthCheck(pluginId: string): Promise<HealthStatus> {
    const module = await this.moduleLoader.getLoaded(pluginId);
    if (!module.lifecycle.onHealthCheck) {
      return { status: 'healthy' };
    }

    try {
      return await module.lifecycle.onHealthCheck();
    } catch (err) {
      return {
        status: 'unhealthy',
        details: { error: err.message }
      };
    }
  }
}
```

