  dependencies: Record<string, string>;
  config: ConfigSchema;
  resources: ResourceRequirements;
  events: EventDefinition[];
}

export enum PluginState {
  UNINITIALIZED = "uninitialized",
  LOADING = "loading",
  LOADED = "loaded",
  ACTIVE = "active",
  INACTIVE = "inactive",
  UNLOADING = "unloading",
  ERROR = "error",
  OUTDATED = "outdated"
}

// ============ PLUGIN CONTEXT ============

export interface PluginContext {
