## 3. Plugin Registry

The registry manages the complete lifecycle of plugins.

```typescript
// registry/PluginRegistry.ts

export class PluginRegistry {
  private plugins: Map<string, PluginInstance> = new Map();
  private hooks: Map<string, Hook[]> = new Map();
  private sandboxes: Map<string, PluginSandbox> = new Map();
  private logger: ILogger;
  private eventBus: IEventBus;
  private storage: IPluginStorage;

  constructor(
    private engine: IReportingEngine,
    logger: ILogger,
    eventBus: IEventBus,
    storage: IPluginStorage
  ) {
    this.logger = logger;
    this.eventBus = eventBus;
    this.storage = storage;
  }

  // ============ PLUGIN DISCOVERY & LOADING ============

  /**
   * Discover plugins from a directory or registry
   */
  async discoverPlugins(source: PluginSource): Promise<PluginMetadata[]> {
    const manifests = await this.storage.discover(source);

    for (const manifest of manifests) {
      this.validateManifest(manifest);
      await this.checkCompatibility(manifest);
    }

    return manifests;
  }

  /**
   * Load a plugin by ID
   */
  async loadPlugin(
    pluginId: string,
    options: LoadOptions = {}
  ): Promise<IPlugin> {
    try {
      this.logger.info(`Loading plugin: ${pluginId}`);

      // 1. Check if already loaded
      if (this.plugins.has(pluginId)) {
        if (!options.force) {
          throw new PluginError(
            ErrorCode.INVALID_CONFIG,
            pluginId,
            "Plugin already loaded"
          );
        }
        await this.unloadPlugin(pluginId);
      }

      // 2. Load manifest
      const manifest = await this.storage.loadManifest(pluginId);
      this.validateManifest(manifest);

      // 3. Check compatibility
      const compatibility = await this.checkCompatibility(manifest);
      if (!compatibility.compatible) {
        throw new PluginError(
          ErrorCode.INCOMPATIBLE_ENGINE,
          pluginId,
          `Engine version ${this.engine.version} not compatible. ` +
          `Required: ${manifest.minEngineVersion}-${manifest.maxEngineVersion}`
        );
      }

      // 4. Create sandbox
      const sandbox = new PluginSandbox(
        pluginId,
        manifest,
        this.engine,
        this.logger
      );
      this.sandboxes.set(pluginId, sandbox);

      // 5. Load plugin code
      const pluginModule = await sandbox.load(manifest.entrypoint.main);
      const plugin = pluginModule.default || pluginModule;

      // 6. Create context
      const context = this.createContext(manifest);

      // 7. Initialize plugin state
      const instance: PluginInstance = {
        id: pluginId,
        manifest,
        plugin,
        context,
        sandbox,
        state: PluginState.LOADING,
        loadedAt: new Date(),
        hooks: []
      };

      // 8. Call onLoad hook
      await this.withTimeout(
        plugin.onLoad(context),
        manifest.resources.timeout.init,
        pluginId
      );

      instance.state = PluginState.LOADED;
      this.plugins.set(pluginId, instance);

      // 9. Emit event
      this.eventBus.emit("plugin.loaded", {
        pluginId,
        version: manifest.version,
        timestamp: new Date()
      });

      this.logger.info(`Plugin loaded: ${pluginId}@${manifest.version}`);
      return plugin;

    } catch (error) {
      await this.handleLoadError(pluginId, error);
      throw error;
    }
  }

  /**
   * Unload a plugin
   */
  async unloadPlugin(pluginId: string): Promise<void> {
    try {
      const instance = this.plugins.get(pluginId);
      if (!instance) return;

      instance.state = PluginState.UNLOADING;
      this.logger.info(`Unloading plugin: ${pluginId}`);

      // 1. Unregister hooks
      this.unregisterPluginHooks(pluginId);

      // 2. Call onUnload
      await this.withTimeout(
        instance.plugin.onUnload(),
        instance.manifest.resources.timeout.shutdown,
        pluginId
      );

      // 3. Cleanup sandbox
      const sandbox = this.sandboxes.get(pluginId);
      if (sandbox) {
        await sandbox.cleanup();
        this.sandboxes.delete(pluginId);
      }

      // 4. Update state
      instance.state = PluginState.INACTIVE;
      this.plugins.delete(pluginId);

      this.eventBus.emit("plugin.unloaded", {
        pluginId,
        timestamp: new Date()
      });

      this.logger.info(`Plugin unloaded: ${pluginId}`);

    } catch (error) {
      this.logger.error(`Error unloading plugin ${pluginId}:`, error);
      const instance = this.plugins.get(pluginId);
      if (instance) {
        instance.state = PluginState.ERROR;
      }
      throw error;
    }
  }

  /**
   * Reload a plugin (unload + load)
   */
  async reloadPlugin(pluginId: string): Promise<IPlugin> {
    this.logger.info(`Reloading plugin: ${pluginId}`);

    const instance = this.plugins.get(pluginId);
    if (!instance) {
      throw new PluginError(
        ErrorCode.INVALID_CONFIG,
        pluginId,
        "Plugin not loaded"
      );
    }

    try {
      instance.state = PluginState.LOADING;

      // Get config before unload
      const config = instance.context.config;

      await this.unloadPlugin(pluginId);
      const plugin = await this.loadPlugin(pluginId);

      // Restore config
      await plugin.onConfigChange(config);

      this.eventBus.emit("plugin.reloaded", {
        pluginId,
        timestamp: new Date()
      });

      return plugin;
    } catch (error) {
      this.logger.error(`Error reloading plugin ${pluginId}:`, error);
      const instance = this.plugins.get(pluginId);
      if (instance) {
        instance.state = PluginState.ERROR;
      }
      throw error;
    }
  }

  // ============ HOOK MANAGEMENT ============

  registerHook(
    event: string,
    pluginId: string,
    handler: HookHandler,
    priority: number = 0
  ): string {
    const hookId = `${pluginId}-${event}-${Date.now()}`;

    const hook: Hook = {
      id: hookId,
      event,
      pluginId,
      handler,
      priority,
      enabled: true
    };

    if (!this.hooks.has(event)) {
      this.hooks.set(event, []);
    }

    this.hooks.get(event)!.push(hook);
    this.hooks.get(event)!.sort((a, b) => b.priority - a.priority);

    this.logger.debug(`Hook registered: ${event} by ${pluginId}`);
    return hookId;
  }

  unregisterHook(event: string, hookId: string): void {
    const hooks = this.hooks.get(event);
    if (!hooks) return;

    const index = hooks.findIndex(h => h.id === hookId);
    if (index >= 0) {
      hooks.splice(index, 1);
      this.logger.debug(`Hook unregistered: ${hookId}`);
    }
  }

  /**
   * Execute hooks for an event in priority order
   */
  async executeHooks(event: string, payload: unknown): Promise<unknown> {
    const hooks = this.hooks.get(event) || [];
    let result = payload;

    for (const hook of hooks) {
      if (!hook.enabled) continue;

      try {
        const instance = this.plugins.get(hook.pluginId);
        if (!instance) continue;

        result = await this.withTimeout(
          hook.handler(result),
          instance.manifest.resources.timeout.hook,
          hook.pluginId
        );

      } catch (error) {
        this.logger.error(`Hook failed: ${hook.id}`, error);
        this.eventBus.emit("hook.failed", {
          hookId: hook.id,
          event,
          pluginId: hook.pluginId,
          error: (error as Error).message
        });
      }
    }

    return result;
  }

  // ============ PLUGIN QUERIES ============

  getPlugin(pluginId: string): IPlugin | undefined {
    return this.plugins.get(pluginId)?.plugin;
  }

  listPlugins(filter?: PluginFilter): PluginInfo[] {
    const plugins = Array.from(this.plugins.values());

    let filtered = plugins;
    if (filter?.state) {
      filtered = filtered.filter(p => p.state === filter.state);
    }
    if (filter?.capability) {
      filtered = filtered.filter(p =>
        Object.values(p.manifest.capabilities).flat().includes(filter.capability!)
      );
    }

    return filtered.map(p => ({
      id: p.id,
      name: p.manifest.name,
      version: p.manifest.version,
      state: p.state,
      loadedAt: p.loadedAt,
      health: p.health
    }));
  }

  // ============ CONFIGURATION ============

  async updatePluginConfig(
    pluginId: string,
    config: Record<string, unknown>
  ): Promise<void> {
    const instance = this.plugins.get(pluginId);
    if (!instance) {
      throw new PluginError(
        ErrorCode.INVALID_CONFIG,
        pluginId,
        "Plugin not loaded"
      );
    }

    // Validate against schema
    const validation = this.validateConfig(instance.manifest.config, config);
    if (!validation.valid) {
      throw new PluginError(
        ErrorCode.INVALID_CONFIG,
        pluginId,
        `Invalid config: ${validation.errors.join(", ")}`
      );
    }

    // Update context config
    instance.context.config = config;

    // Notify plugin
    await this.withTimeout(
      instance.plugin.onConfigChange(config),
      5000,
      pluginId
    );

    this.eventBus.emit("plugin.config.changed", {
      pluginId,
      timestamp: new Date()
    });
  }

  // ============ PRIVATE HELPERS ============

  private createContext(manifest: PluginManifest): PluginContext {
    return {
      engine: this.engine,
      logger: this.logger.child({ plugin: manifest.id }),
      eventBus: this.eventBus,
      cache: new PluginCache(manifest.id),
      config: manifest.config?.default || {},
      env: {
        pluginId: manifest.id,
        pluginVersion: manifest.version,
        engineVersion: this.engine.version,
        isDevelopment: process.env.NODE_ENV === "development",
        sandboxId: `sandbox-${manifest.id}-${Date.now()}`,
        tempDir: `/tmp/plugins/${manifest.id}`
      }
    };
  }

  private validateManifest(manifest: PluginManifest): void {
    if (!manifest.id || !manifest.version) {
      throw new Error("Invalid manifest: missing id or version");
    }
  }

  private async checkCompatibility(manifest: PluginManifest) {
    const engineVersion = this.engine.version;
    const minOk = this.compareVersions(engineVersion, manifest.minEngineVersion) >= 0;
    const maxOk = this.compareVersions(engineVersion, manifest.maxEngineVersion) <= 0;

    return {
      compatible: minOk && maxOk,
      reason: !minOk ? "Engine too old" : !maxOk ? "Engine too new" : undefined
    };
  }

  private unregisterPluginHooks(pluginId: string): void {
    for (const hooks of this.hooks.values()) {
      const indices = hooks
        .map((h, i) => h.pluginId === pluginId ? i : -1)
        .filter(i => i >= 0)
        .reverse();

      for (const i of indices) {
        hooks.splice(i, 1);
      }
    }
  }

  private async withTimeout<T>(
    promise: Promise<T>,
    timeoutMs: number,
    pluginId: string
  ): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) =>
        setTimeout(() => reject(new PluginError(
          ErrorCode.TIMEOUT,
          pluginId,
          `Operation timed out after ${timeoutMs}ms`
        )), timeoutMs)
      )
    ]);
  }

  private async handleLoadError(pluginId: string, error: Error): Promise<void> {
    const instance = this.plugins.get(pluginId);
    if (instance) {
      instance.state = PluginState.ERROR;
    }

    this.eventBus.emit("plugin.error", {
      pluginId,
      error: error.message,
      timestamp: new Date()
    });
  }

  private compareVersions(v1: string, v2: string): number {
    // Semantic version comparison
    // Returns: -1 if v1 < v2, 0 if equal, 1 if v1 > v2
    const [major1, minor1, patch1] = v1.split(".").map(Number);
    const [major2, minor2, patch2] = v2.split(".").map(Number);

    if (major1 !== major2) return major1 - major2;
    if (minor1 !== minor2) return minor1 - minor2;
    return patch1 - patch2;
  }

  private validateConfig(schema: ConfigSchema, config: Record<string, unknown>) {
    // Use JSON Schema validator
    const valid = true; // Simplified
