## 4. Sandboxed Execution

Plugins run in isolated V8 contexts with controlled resource limits and capability restrictions.

```typescript
// sandbox/PluginSandbox.ts

import { VM } from "vm2"; // Or custom sandbox implementation

export class PluginSandbox {
  private vm?: VM;
  private resources: ResourceMonitor;
  private capabilities: Set<string>;
  private logger: ILogger;

  constructor(
    private pluginId: string,
    private manifest: PluginManifest,
    private engine: IReportingEngine,
    logger: ILogger
  ) {
    this.logger = logger.child({ sandbox: pluginId });
    this.resources = new ResourceMonitor(manifest.resources);
    this.capabilities = new Set(manifest.entrypoint.permissions);
  }

  async load(entrypoint: string): Promise<any> {
    if (!this.manifest.entrypoint.sandbox) {
      // Load in main process (trusted plugins only)
      return import(entrypoint);
    }

    // Create isolated VM context
    this.vm = new VM({
      timeout: this.manifest.resources.timeout.init,
      sandbox: this.createSandbox()
    });

    try {
      const code = await this.loadPluginCode(entrypoint);
      const module = this.vm.run(code);
      return module;
    } catch (error) {
      throw new PluginError(
        ErrorCode.SANDBOX_VIOLATION,
        this.pluginId,
        `Failed to load plugin in sandbox: ${(error as Error).message}`
      );
    }
  }

  private createSandbox(): Record<string, any> {
    return {
      console: this.createSafeConsole(),
      require: this.createSafeRequire(),
      process: this.createSafeProcess(),
      global: this.createSafeGlobal(),

      // Plugin API access
      api: this.createCapabilityGatedAPI(),

      // Event system
      on: (event: string, handler: Function) => {
        this.checkCapability("events:subscribe");
        return this.subscribeEvent(event, handler);
      },

      emit: (event: string, data: any) => {
        this.checkCapability("events:emit");
        return this.emitEvent(event, data);
      }
    };
  }

  private createSafeConsole() {
    return {
      log: (...args: any[]) => this.logger.info(args),
      warn: (...args: any[]) => this.logger.warn(args),
      error: (...args: any[]) => this.logger.error(args),
      debug: (...args: any[]) => this.logger.debug(args)
    };
  }

  private createSafeRequire() {
    return (moduleId: string) => {
      // Only allow whitelisted dependencies from manifest
      if (!this.manifest.dependencies[moduleId]) {
        throw new PluginError(
          ErrorCode.PERMISSION_DENIED,
          this.pluginId,
          `Cannot require ${moduleId}: not in dependencies`
        );
      }

      // Return safe wrapped version of module
      return require(moduleId);
    };
  }

  private createSafeProcess() {
    return {
      env: {
        NODE_ENV: process.env.NODE_ENV,
        PLUGIN_ID: this.pluginId
      },
      version: process.version
      // No access to: exit, kill, chdir, etc.
    };
  }

  private createSafeGlobal() {
    return {
      // Standard globals
      setTimeout: global.setTimeout,
      setInterval: global.setInterval,
      clearTimeout: global.clearTimeout,
      clearInterval: global.clearInterval,
      Promise: global.Promise,
      Error: global.Error,

      // No access to: eval, Function constructor, etc.
    };
  }

  private createCapabilityGatedAPI() {
    return {
      reports: {
        create: (config: any) => {
          this.checkCapability("api:reports:create");
          return this.engine.createReport(config);
        },
        query: (query: any) => {
          this.checkCapability("data:read");
          return this.engine.queryData(query);
        }
      },

      users: {
        query: (params: any) => {
          this.checkCapability("api:users:query");
          return this.engine.query("users", params);
        }
      },

      datasources: {
        register: (adapter: any) => {
          this.checkCapability("api:datasources:register");
          return this.engine.registerDatasource(adapter);
        }
      },

      files: {
        write: (path: string, content: any) => {
          this.checkCapability("file:temp:write");
          this.resources.checkDiskQuota(content.length);
          return this.writeFile(path, content);
        },
        read: (path: string) => {
          this.checkCapability("file:temp:read");
          return this.readFile(path);
        }
      },

      network: {
        fetch: (url: string, options?: any) => {
          this.checkCapability("network:http");
          this.resources.checkNetworkQuota(url);
          return this.safeFetch(url, options);
        }
      }
    };
  }

  private checkCapability(permission: string): void {
    if (!this.capabilities.has(permission)) {
      throw new PluginError(
        ErrorCode.PERMISSION_DENIED,
        this.pluginId,
        `Permission denied: ${permission}`
      );
    }
  }

  async cleanup(): Promise<void> {
    this.resources.cleanup();
    this.logger.info("Sandbox cleaned up");
  }

  private async loadPluginCode(entrypoint: string): Promise<string> {
    // Load and possibly transpile plugin code
    const fs = require("fs");
    return fs.readFileSync(entrypoint, "utf-8");
  }

  private subscribeEvent(event: string, handler: Function): string {
    // Return subscription ID
    return `sub-${Date.now()}`;
  }

  private emitEvent(event: string, data: any): void {
    // Emit event to plugin context
  }

  private async writeFile(path: string, content: any): Promise<void> {
    // Write to sandboxed temp directory only
  }

  private async readFile(path: string): Promise<Buffer> {
    // Read from sandboxed temp directory only
    return Buffer.from("");
  }

  private async safeFetch(url: string, options?: any): Promise<Response> {
    // Fetch with URL validation and request/response size limits
    return fetch(url, options);
  }
}

class ResourceMonitor {
  private memoryUsage = 0;
  private diskUsage = 0;
  private networkUsage = 0;
  private startTime = Date.now();

  constructor(private limits: ResourceRequirements) {}

  checkMemoryQuota(bytes: number): void {
    const maxBytes = this.parseSize(this.limits.memory.max);
    if (this.memoryUsage + bytes > maxBytes) {
      throw new PluginError(
        ErrorCode.RESOURCE_EXHAUSTED,
        "",
        "Memory quota exceeded"
      );
    }
    this.memoryUsage += bytes;
  }

  checkDiskQuota(bytes: number): void {
    const maxBytes = parseSize(this.limits.memory.max) * 2; // 2x memory
    if (this.diskUsage + bytes > maxBytes) {
      throw new PluginError(
        ErrorCode.RESOURCE_EXHAUSTED,
        "",
        "Disk quota exceeded"
      );
    }
    this.diskUsage += bytes;
  }

  checkNetworkQuota(url: string): void {
    // Prevent SSRF attacks, rate limiting
    if (url.includes("localhost") || url.includes("127.0.0.1")) {
      throw new PluginError(
        ErrorCode.PERMISSION_DENIED,
        "",
        "Cannot access localhost"
      );
    }
  }

  cleanup(): void {
    this.memoryUsage = 0;
    this.diskUsage = 0;
  }

  private parseSize(size: string): number {
    const match = size.match(/^(\d+)(MB|GB|KB)$/);
    if (!match) return 0;
    const [, num, unit] = match;
    const multipliers: Record<string, number> = { KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 };
    return parseInt(num) * (multipliers[unit] || 1);
  }
}

interface ResourceRequirements {
  memory: { min: string; recommended: string; max: string };
  timeout: { init: number; hook: number; shutdown: number };
}
