## 5. Security Model

### Permission System

```typescript
// security/PermissionManager.ts

export enum Permission {
  // Data access
  DATA_READ = "data:read",
  DATA_WRITE = "data:write",
  DATA_DELETE = "data:delete",

  // API access
  API_REPORTS_CREATE = "api:reports:create",
  API_REPORTS_READ = "api:reports:read",
  API_REPORTS_DELETE = "api:reports:delete",
  API_USERS_QUERY = "api:users:query",
  API_DATASOURCES_REGISTER = "api:datasources:register",

  // File system
  FILE_TEMP_READ = "file:temp:read",
  FILE_TEMP_WRITE = "file:temp:write",

  // Network
  NETWORK_HTTP = "network:http",
  NETWORK_HTTPS = "network:https",

  // Events
  EVENTS_SUBSCRIBE = "events:subscribe",
  EVENTS_EMIT = "events:emit"
}

export class PermissionManager {
  private permissions: Map<string, Set<Permission>> = new Map();
  private auditLog: AuditLogEntry[] = [];

  grantPermissions(pluginId: string, permissions: Permission[]): void {
    this.permissions.set(pluginId, new Set(permissions));
  }

  revokePermission(pluginId: string, permission: Permission): void {
    this.permissions.get(pluginId)?.delete(permission);
  }

  hasPermission(pluginId: string, permission: Permission): boolean {
    return this.permissions.get(pluginId)?.has(permission) ?? false;
  }

  checkPermission(pluginId: string, permission: Permission): void {
    if (!this.hasPermission(pluginId, permission)) {
      this.logDeniedAccess(pluginId, permission);
      throw new PluginError(
        ErrorCode.PERMISSION_DENIED,
        pluginId,
        `Permission denied: ${permission}`
      );
    }
    this.logPermissionUsage(pluginId, permission);
  }

  private logPermissionUsage(pluginId: string, permission: Permission): void {
    this.auditLog.push({
      timestamp: new Date(),
      pluginId,
      permission,
      granted: true
    });
  }

  private logDeniedAccess(pluginId: string, permission: Permission): void {
    this.auditLog.push({
      timestamp: new Date(),
      pluginId,
      permission,
      granted: false
    });
  }

  getAuditLog(filter?: AuditFilter): AuditLogEntry[] {
    let entries = this.auditLog;

    if (filter?.pluginId) {
      entries = entries.filter(e => e.pluginId === filter.pluginId);
    }
    if (filter?.granted !== undefined) {
      entries = entries.filter(e => e.granted === filter.granted);
    }

    return entries;
  }
}

interface AuditLogEntry {
  timestamp: Date;
  pluginId: string;
  permission: Permission;
  granted: boolean;
}

interface AuditFilter {
  pluginId?: string;
  granted?: boolean;
}
```

### Content Isolation

```typescript
// security/ContentIsolation.ts

export interface ContentPolicy {
  allowedOrigins: string[];
  allowedDomains: string[];
  cspHeader: string;
  maxRequestSize: number;
  maxResponseSize: number;
}

export class ContentIsolationManager {
  private policies: Map<string, ContentPolicy> = new Map();

  registerPolicy(pluginId: string, policy: ContentPolicy): void {
    this.policies.set(pluginId, policy);
  }

  validateRequest(pluginId: string, url: string): boolean {
    const policy = this.policies.get(pluginId);
    if (!policy) return false;

    const origin = new URL(url).origin;
    return policy.allowedOrigins.includes(origin);
  }

  validateResponse(pluginId: string, size: number): boolean {
    const policy = this.policies.get(pluginId);
    return (policy?.maxResponseSize ?? Infinity) >= size;
  }

  getCSPHeader(pluginId: string): string {
    return this.policies.get(pluginId)?.cspHeader ?? "default-src 'none'";
  }
}
