## 4. Plugin Registry

Central manager for lifecycle, discovery, hook coordination:

```typescript
export class PluginRegistry {
  // Discover plugins from storage
  async discoverPlugins(source: PluginSource): Promise<PluginMetadata[]>;

  // Load plugin with version check and sandbox setup
  async loadPlugin(
    pluginId: string,
    options?: { force?: boolean; config?: Record<string, unknown> }
  ): Promise<IPlugin>;

  // Unload plugin: cleanup, unregister hooks, destroy sandbox
  async unloadPlugin(pluginId: string): Promise<void>;

  // Reload plugin: unload + load (preserves config)
  async reloadPlugin(pluginId: string): Promise<IPlugin>;

  // Hook management
  registerHook(event: string, pluginId: string, handler: HookHandler, priority?: number): string;
  unregisterHook(event: string, hookId: string): void;
  async executeHooks(event: string, payload: unknown): Promise<unknown>;

  // Query loaded plugins
  getPlugin(pluginId: string): IPlugin | undefined;
  listPlugins(filter?: { state?: PluginState; capability?: string }): PluginInfo[];

  // Configuration
  async updatePluginConfig(pluginId: string, config: Record<string, unknown>): Promise<void>;
}

interface PluginInfo {
  id: string;
  name: string;
  version: string;
  state: PluginState;
  loadedAt: Date;
  health?: HealthStatus;
}
```

