### **8. Example Plugin Implementation**

```typescript
import type {
  IPlugin, PluginContext, PluginState, Report, ReportConfig, HealthStatus
} from "@reporting/plugin-api@2.3.0";

export default class SalesReportPlugin implements IPlugin {
  id = "com.example.sales-report";
  version = "1.2.3";
  state: PluginState = PluginState.UNINITIALIZED;

  private context!: PluginContext;
  private hookIds: string[] = [];

  async onLoad(context: PluginContext): Promise<void> {
    this.context = context;
    this.context.logger.info("Loading Sales Report plugin");

    // Register hooks (priority: higher = earlier)
    const hookId = this.context.engine.registerHook(
      "report.generate",
      (config: ReportConfig) => this.handleReportGenerate(config)
    );
    this.hookIds.push(hookId);

    // Warmup: cache reference data
    const rates = await fetch("https://api.example.com/rates").then(r => r.json());
    await this.context.cache.set("exchange_rates", rates);

    this.state = PluginState.ACTIVE;
  }

  async onUnload(): Promise<void> {
    // Unregister all hooks
    this.hookIds.forEach(id => {
      this.context.engine.unregisterHook("report.generate", id);
    });

    // Cleanup
    await this.context.cache.clear();
    this.state = PluginState.INACTIVE;
  }

  async onReload(context: PluginContext): Promise<void> {
    const prevConfig = this.context.config;
    await this.onUnload();
    await this.onLoad(context);
    await this.onConfigChange(prevConfig);
  }

  async onConfigChange(config: Record<string, unknown>): Promise<void> {
    this.context.config = config;
    // Reinit if needed
  }

  async getHealth(): Promise<HealthStatus> {
    return {
      status: "healthy",
      uptime: Date.now(),
      memory: {
        used: process.memoryUsage().heapUsed,
        limit: 256 * 1024 * 1024,
        percentage: 10
      },
      hooks: [
        {
          event: "report.generate",
          successRate: 0.98,
          avgDuration: 150
        }
      ]
    };
  }

  private async handleReportGenerate(config: ReportConfig): Promise<ReportConfig> {
    // Fetch data via engine API (permission checked by sandbox)
    const data = await this.context.engine.queryData({
      source: "salesforce",
      filters: { dateRange: config.dateRange }
    });

    // Cache result
    await this.context.cache.set(`report-${config.id}`, data);

    return config; // Pass to next hook
  }
}
```

