### **9. Integration: Minimal Startup Code**

```typescript
import { PluginRegistry } from "./registry/PluginRegistry";

const engine: IReportingEngine = {
  version: "2.3.0",
  createReport: async (config) => { /* ... */ },
  queryData: async (query) => { /* ... */ },
  registerHook: (event, handler) => { /* ... */ },
  // ...
};

const registry = new PluginRegistry(engine, logger, eventBus, storage);

// Load plugins at startup
async function startupPlugins() {
  const available = await registry.discoverPlugins({
    type: "directory",
    path: "./plugins"
  });

  for (const plugin of available) {
    try {
      await registry.loadPlugin(plugin.id);
      logger.info(`✓ ${plugin.id}@${plugin.version}`);
    } catch (error) {
      logger.error(`✗ ${plugin.id}:`, error);
    }
  }
}

// Use hooks in report flow
async function generateReport(config: ReportConfig): Promise<Report> {
  // 1. Validation: run report.validate hooks
  const validated = await registry.executeHooks("report.validate", config);

  // 2. Generate
  const report = await engine.createReport(validated);

  // 3. Transform: run export.transform hooks
  const transformed = await registry.executeHooks("export.transform", report);

  return transformed;
}
```

