## 4. Lifecycle Hooks

### 4.1 Hook Signatures

```typescript
interface LifecycleHooks {
  // Called when plugin is first registered and sandbox initialized
  // Perform schema setup, cache initialization, connection pooling
  load(): Promise<void>

  // Called during graceful shutdown or explicit unregister
  // Clean up resources, close connections, persist state
  unload?(): Promise<void>

  // Called to reload plugin without stopping active handlers
  // Preserve request-scoped state; reinitialize module state
  reload?(): Promise<void>

  // Called before handler invocation; can inspect/modify context
  beforeInvoke?(capability: string, args: unknown): Promise<void>

  // Called after successful handler invocation
  afterInvoke?(capability: string, result: unknown): Promise<void>

  // Called on handler error
  onInvokeError?(capability: string, error: Error): Promise<void>
}
```

### 4.2 Initialization Example

```typescript
// plugin/src/lifecycle.ts
import { PluginContext } from "@reporting/plugin-api@2.1"

let cache: Map<string, unknown>
let db: ConnectionPool

export async function onLoad(ctx: PluginContext) {
  // Initialize caches
  cache = new Map()

  // Connect to resources
  db = new ConnectionPool({
    host: ctx.getConfig("DB_HOST"),
    maxConnections: 10,
    timeout: 5000
  })

  await db.warmup()

  // Register event listeners
  ctx.on("report.render", async (event) => {
    cache.set(`render/${event.reportId}`, event)
  })
}

export async function onUnload(ctx: PluginContext) {
  // Flush pending writes
  await cache.flush()

  // Close connections gracefully
  await db.drain()
}

export async function onReload(ctx: PluginContext) {
  // Preserve ongoing requests; reinitialize module cache
  cache.clear()

  // Optionally reconnect to update configs
  if (ctx.getConfig("DB_HOST") !== db.host) {
    await db.reconnect()
  }
}
```

### 4.3 Handler with Hooks

```typescript
// plugin/src/exporters.ts
import { ExportContext } from "@reporting/plugin-api@2.1"

export async function exportExcel(
  data: ReportData,
  options: ExcelOptions,
  ctx: ExportContext
) {
  // Hooks are called transparently by the registry:
  // 1. beforeInvoke("exporters/excel", { data, options })
  // 2. handler execution
  // 3. afterInvoke("exporters/excel", result) or onInvokeError(...)

  const workbook = new ExcelWorkbook()

  for (const row of data.rows) {
    workbook.addRow(row)
  }

  const buffer = await workbook.toBuffer()
  return {
    buffer: buffer.toString("base64"),
    mimeType: "application/vnd.ms-excel"
  }
}
```

