## 6. Versioned API Contract

### 6.1 API Versioning Strategy

Plugins target a major.minor API version. Breaking changes introduce new major versions; old versions remain available.

```
API v1.0 (Deprecated 2026-12-31)
  ├─ report.render(data) → Report
  ├─ report.validate(data) → ValidationResult

API v2.0 (Current)
  ├─ report.render(data, options) → Report
  ├─ report.validate(data, options) → ValidationResult
  ├─ report.schedule(definition) → ScheduledReport  [NEW]

API v2.1 (Latest)
  ├─ report.render(data, options, context) → Report  [CHANGED]
  ├─ report.validate(data, options) → ValidationResult
  ├─ report.schedule(definition, triggers) → ScheduledReport  [CHANGED]
  ├─ report.export(format, data) → ExportResult  [NEW]
```

### 6.2 API Definition

```typescript
// @reporting/plugin-api@2.1/types.ts

export interface ReportData {
  id: string
  title: string
  rows: Record<string, unknown>[]
  columns: Column[]
  metadata?: Metadata
}

export interface ReportRenderOptions {
  format?: "html" | "json"
  breakpoints?: boolean
  includeMetadata?: boolean
}

export interface Report {
  id: string
  html: string
  metadata?: Metadata
  renderedAt: Date
}

export interface ReportContext {
  userId: string
  role: string
  permissions: string[]
  requestId: string
  timeout: number
}

// Core APIs available to all plugins
export const apis = {
  async render(
    data: ReportData,
    options?: ReportRenderOptions,
    ctx?: ReportContext
  ): Promise<Report>,

  async validate(
    data: ReportData,
    options?: ReportRenderOptions
  ): Promise<ValidationResult>,

  async schedule(
    definition: ScheduleDefinition,
    triggers?: ScheduleTrigger[]
  ): Promise<ScheduledReport>,

  async export(
    format: string,
    data: ReportData
  ): Promise<ExportResult>,

  on(event: string, handler: (data: unknown) => void): void,
  emit(event: string, data: unknown): void,
}
```

### 6.3 API Registration

```typescript
// core/api-registry.ts

class ApiRegistry {
  registerVersion(
    name: string,
    version: string,
    impl: Record<string, Function>
  ) {
    // v2.1
    this.apis.set("report.render@2.1", reportRenderV21)
    this.apis.set("report.validate@2.1", reportValidateV21)

    // v2.0 (backwards compatibility)
    this.apis.set("report.render@2.0", reportRenderV20)
    this.apis.set("report.validate@2.0", reportValidateV20)
  }

  resolve(pluginId: string, apiName: string): Function {
    const plugin = registry.get(pluginId)
    const targetVersion = plugin.manifest.apiVersion

    const impl = this.apis.get(`${apiName}@${targetVersion}`)
    if (!impl) {
      throw new PluginError({
        code: "DEPENDENCY_NOT_FOUND",
        message: `API ${apiName}@${targetVersion} not found`
      })
    }

    return impl
  }
}
```

