## 8. Implementation Patterns

### 8.1 Plugin Loading (Core)

```typescript
async function loadPlugin(req: RegistrationRequest): Promise<Plugin> {
  const { manifest, code, permissions } = req

  // Step 1: Validate manifest structure
  const validation = manifestValidator.validate(manifest)
  if (!validation.valid) {
    throw new PluginError({
      code: "LOAD_FAILED",
      cause: validation.errors
    })
  }

  // Step 2: Resolve dependencies
  const dependencies = resolveDependencies(manifest.dependencies)
  if (!dependencies.resolved) {
    throw new PluginError({
      code: "DEPENDENCY_NOT_FOUND",
      message: `Missing: ${dependencies.missing.join(", ")}`
    })
  }

  // Step 3: Create sandbox
  const sandbox = new PluginSandbox(manifest, {
    env: permissions?.env || {},
    permissions: permissions?.permissions || [],
    storageDir: `/tmp/plugins/${manifest.id}`
  })

  // Step 4: Initialize plugin
  const plugin = new Plugin(manifest, sandbox, code)

  // Step 5: Call load hook
  try {
    await plugin.invoke("load")
  } catch (err) {
    throw new PluginError({
      code: "LOAD_FAILED",
      cause: err
    })
  }

  // Step 6: Register and return
  registry.set(manifest.id, plugin)
  registry.emit("pluginLoaded", plugin)
  return plugin
}
```

### 8.2 Capability Registration

```typescript
// In plugin manifest, register capability
{
  "capabilities": [
    {
      "name": "exporters/pdf",
      "version": "1.0.0",
      "handler": "src/pdf.ts::exportPdf",
      "input": { ... },
      "output": { ... }
    }
  ]
}

// In registry, make capability discoverable
class CapabilityRegistry {
  register(plugin: Plugin) {
    for (const cap of plugin.manifest.capabilities) {
      const key = `${cap.name}@${cap.version}`
      this.capabilities.set(key, {
        plugin,
        handler: cap.handler,
        inputSchema: cap.input,
        outputSchema: cap.output
      })
    }
  }

  invoke<T>(
    name: string,
    version: string = "latest",
    args: unknown
  ): Promise<T> {
    const impl = this.capabilities.get(`${name}@${version}`)
    return invokeCapability(impl.plugin, name, args)
  }
}
```

### 8.3 Hot Reload

```typescript
async function reloadPlugin(pluginId: string) {
  const plugin = registry.get(pluginId)
  if (!plugin) throw Error(`Plugin ${pluginId} not found`)

  // Step 1: Call custom reload handler if defined
  if (plugin.manifest.lifecycle.reload) {
    await plugin.invoke("reload")
  }

  // Step 2: Reinitialize module state (but preserve request context)
  plugin.resetModuleState()

  // Step 3: Notify listeners
  registry.emit("pluginReloaded", plugin)
}

// Plugin can intercept reload to preserve state:
export async function onReload() {
  // Close and reopen connections
  await db.reconnect()

  // Clear in-memory caches
  templateCache.clear()

  // Re-read config files if changed
  const newConfig = await loadConfig()
  updateConfig(newConfig)
}
```

### 8.4 Error Recovery

```typescript
class PluginErrorRecovery {
  async invokeWithFallback<T>(
    capability: string,
    args: unknown,
    fallback: T
  ): Promise<T> {
    try {
      return await registry.invoke(capability, args)
    } catch (err) {
      if (err instanceof PluginError) {
        if (err.code === "CRASH") {
          // Plugin crashed; log and return fallback
          logger.error(`Plugin crashed: ${err.pluginId}`, err.cause)
          return fallback
        } else if (err.code === "TIMEOUT") {
          // Plugin took too long; cancel and return fallback
          logger.warn(`Plugin timeout: ${err.pluginId}`)
          return fallback
        } else if (err.code === "PERMISSION_DENIED") {
          // Plugin lacks permission; log security event and return fallback
          audit.log({ event: "PERMISSION_DENIED", plugin: err.pluginId })
          return fallback
        }
      }
      throw err
    }
  }
}
```

