## 9. Integration Points

### 9.1 Report Rendering Pipeline

```typescript
interface ReportRenderPipeline {
  // 1. User submits report definition

  // 2. Registry invokes validation plugins
  const validation = await registry.invoke("validators/*", reportData)
  if (!validation.passed) return { error: validation.issues }

  // 3. Registry invokes pre-render hooks
  await registry.emit("render.pre", { reportId, data })

  // 4. Core engine renders report
  const report = await renderReport(reportData)

  // 5. Registry invokes render plugins (charts, formatting, etc.)
  for (const enhancement of registry.find("enhancements/*")) {
    await enhancement.invoke("enhance", { report })
  }

  // 6. Registry invokes post-render hooks
  await registry.emit("render.post", { reportId, report })

  // 7. Return rendered report
  return report
}
```

### 9.2 Export Pipeline

```typescript
interface ExportRequest {
  reportId: string
  format: string  // "pdf", "xlsx", "csv", etc.
  options?: Record<string, unknown>
}

async function exportReport(req: ExportRequest): Promise<ExportResult> {
  // 1. Find exporter plugin for format
  const exporters = registry.find(`exporters/${req.format}`)
  if (exporters.length === 0) {
    throw Error(`No exporter found for ${req.format}`)
  }

  // Use first registered exporter (or configurable priority)
  const exporter = exporters[0]

  // 2. Invoke exporter
  const result = await registry.invoke("exporters/" + req.format, {
    reportId: req.reportId,
    options: req.options
  })

  // 3. Return result
  return result
}
```

### 9.3 Scheduled Report Trigger

```typescript
interface ScheduledReportTrigger {
  onTrigger: (schedule: ScheduleDefinition) => Promise<void>
}

// When a scheduled report fires:
async function triggerScheduledReport(schedule: ScheduleDefinition) {
  // 1. Load report definition
  const report = await loadReport(schedule.reportId)

  // 2. Invoke any pre-execute plugins
  await registry.emit("schedule.pre", { scheduleId: schedule.id })

  // 3. Render report
  const rendered = await renderReport(report)

  // 4. Invoke exporters if configured
  if (schedule.exports) {
    for (const exp of schedule.exports) {
      const exported = await registry.invoke("exporters/" + exp.format, {
        data: rendered,
        options: exp.options
      })

      // 5. Invoke delivery plugins (email, webhook, storage)
      await registry.invoke("delivery/" + exp.delivery, {
        data: exported,
        recipients: exp.recipients
      })
    }
  }

  // 6. Invoke post-execute hooks
  await registry.emit("schedule.post", { scheduleId: schedule.id })
}
```

