import { PluginContext } from "@reporting/plugin-api@2.1"

export async function onLoad(ctx: PluginContext) {
  console.log("Markdown exporter loaded")
}

export async function onUnload(ctx: PluginContext) {
  console.log("Markdown exporter unloading")
}

// src/exporter.ts
import { ReportData } from "@reporting/plugin-api@2.1"

interface ExportOptions {
  includeMetadata?: boolean
  includeTableOfContents?: boolean
}

export async function exportMarkdown(
  data: ReportData,
  options: ExportOptions = {}
): Promise<{ buffer: string; mimeType: string }> {
  let markdown = `# ${data.title}\n\n`

  if (options.includeMetadata && data.metadata) {
    markdown += `_Generated: ${new Date().toISOString()}_\n\n`
  }

  if (options.includeTableOfContents) {
    markdown += generateTableOfContents(data)
  }

  markdown += generateContent(data)

  const buffer = Buffer.from(markdown, "utf8").toString("base64")
  return {
    buffer,
    mimeType: "text/markdown"
  }
}

function generateContent(data: ReportData): string {
  let md = ""

  // Render table
  md += "| " + data.columns.map(c => c.name).join(" | ") + " |\n"
  md += "| " + data.columns.map(() => "---").join(" | ") + " |\n"

  for (const row of data.rows) {
    md += "| " + data.columns.map(c => row[c.key] || "").join(" | ") + " |\n"
  }

  return md
}
