// core/api-registry.ts

class ApiRegistry {
  registerVersion(
    name: string,
    version: string,
    impl: Record<string, Function>
  ) {
    // v2.1
    this.apis.set("report.render@2.1", reportRenderV21)
    this.apis.set("report.validate@2.1", reportValidateV21)

    // v2.0 (backwards compatibility)
    this.apis.set("report.render@2.0", reportRenderV20)
    this.apis.set("report.validate@2.0", reportValidateV20)
  }

  resolve(pluginId: string, apiName: string): Function {
    const plugin = registry.get(pluginId)
    const targetVersion = plugin.manifest.apiVersion

    const impl = this.apis.get(`${apiName}@${targetVersion}`)
    if (!impl) {
      throw new PluginError({
        code: "DEPENDENCY_NOT_FOUND",
        message: `API ${apiName}@${targetVersion} not found`
      })
    }

    return impl
  }
}
