## Versioned API Contract

### Core API v2.1

Plugins interact with the host through a versioned API exposed in a sandbox context.

```typescript
// types/plugin-api.ts

/**
 * Global context available to all plugins at runtime.
 * Version: 2.1.0
 */
declare global {
  namespace PluginAPI {
    // === PLUGIN IDENTITY ===

    interface PluginContext {
      /** Plugin metadata from manifest */
      metadata: PluginMetadata;
      /** Plugin configuration (validated against schema) */
      config: Record<string, unknown>;
      /** Granted capabilities for this plugin */
      capabilities: Capability[];
      /** Plugin version as registered */
      version: string;
      /** Host API version being used */
      apiVersion: string;
    }

    interface PluginMetadata {
      id: string;
      name: string;
      version: string;
      author: string;
    }

    type Capability = 
      | "datasource:read"
      | "datasource:write"
      | "report:read"
      | "report:write"
      | "schedule:create"
      | "schedule:delete"
      | "network:http"
      | "storage:plugin-local"
      | "storage:shared"
      | "secrets:read";

    // === DATA SOURCE API ===

    interface DataSource {
      id: string;
      name: string;
      type: "sql" | "rest" | "graphql" | "file";
      createdAt: Date;
    }

    interface QueryOptions {
      timeout?: number;       // ms
      cache?: {
        ttl: number;         // seconds
        key: string;         // cache key override
      };
    }

    interface QueryResult {
      rows: Record<string, unknown>[];
      rowCount: number;
      executionTimeMs: number;
      isCached: boolean;
      schema: ColumnSchema[];
    }

    interface ColumnSchema {
      name: string;
      type: "string" | "number" | "boolean" | "date" | "json";
      nullable: boolean;
    }

    interface DataSourceAPI {
      /**
       * List available data sources.
       * Requires: datasource:read
       */
      list(): Promise<DataSource[]>;

      /**
       * Execute query against a data source.
       * Requires: datasource:read
       */
      query(
        sourceId: string,
        sql: string,
        options?: QueryOptions
      ): Promise<QueryResult>;

      /**
       * Get metadata for a data source.
       * Requires: datasource:read
       */
      getSchema(sourceId: string): Promise<ColumnSchema[]>;
    }

    // === REPORT API ===

    type ReportFormat = "json" | "html" | "pdf" | "csv" | "xlsx";

    interface ReportDefinition {
      id: string;
      name: string;
      format: ReportFormat;
      createdBy: string;
      createdAt: Date;
      updatedAt: Date;
    }

    interface ReportGenerationInput {
      format: ReportFormat;
      title: string;
      description?: string;
      parameters?: Record<string, unknown>;
      scheduling?: {
        frequency: "once" | "hourly" | "daily" | "weekly" | "monthly";
        recipients?: string[];
        timezone?: string;
      };
    }

    interface ReportOutput {
      id: string;
      content: Buffer | string;
      format: ReportFormat;
      generatedAt: Date;
      generatedBy: string;
    }

    interface ReportAPI {
      /**
       * Generate a report.
       * Requires: report:write
       */
      generate(
        input: ReportGenerationInput
      ): Promise<ReportOutput>;

      /**
       * List reports (created by this plugin or accessible to it).
       * Requires: report:read
       */
      list(filters?: {
        createdBy?: string;
        format?: ReportFormat;
      }): Promise<ReportDefinition[]>;

      /**
       * Get a report by ID.
       * Requires: report:read
       */
      get(reportId: string): Promise<ReportDefinition>;

      /**
       * Delete a report.
       * Requires: report:write
       */
      delete(reportId: string): Promise<void>;
    }

    // === SCHEDULING API ===

    interface ScheduleDefinition {
      id: string;
      expression: string;        // cron expression
      pluginId: string;
      handler: string;           // exported handler name
      parameters: Record<string, unknown>;
      enabled: boolean;
      createdAt: Date;
    }

    interface ScheduleAPI {
      /**
       * Create a scheduled job.
       * Requires: schedule:create
       * 
       * The specified handler must be exported from the plugin.
       */
      create(
        expression: string,
        handler: string,
        parameters?: Record<string, unknown>
      ): Promise<ScheduleDefinition>;

      /**
       * List scheduled jobs for this plugin.
       * Requires: schedule:create
       */
      list(): Promise<ScheduleDefinition[]>;

      /**
       * Delete a scheduled job.
       * Requires: schedule:create
       */
      delete(scheduleId: string): Promise<void>;
    }

    // === NETWORK API ===

    interface HttpRequestOptions {
      method?: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
      headers?: Record<string, string>;
      body?: string | Buffer;
      timeout?: number;        // ms, max 30000
      allowInsecure?: boolean; // Allow self-signed certs
    }

    interface HttpResponse {
      status: number;
      headers: Record<string, string>;
      body: string;
      bodyBuffer: Buffer;
    }

    interface NetworkAPI {
      /**
       * Make HTTP request.
       * Requires: network:http
       * 
       * Requests to private IPs are blocked unless allowlist configured.
       */
      http(
        url: string,
        options?: HttpRequestOptions
      ): Promise<HttpResponse>;
    }

    // === STORAGE API ===

    interface StorageAPI {
      /**
       * Read from plugin-local storage.
       * Requires: storage:plugin-local
       */
      read(key: string): Promise<string | null>;

      /**
       * Write to plugin-local storage.
       * Requires: storage:plugin-local
       */
      write(key: string, value: string): Promise<void>;

      /**
       * Delete from plugin-local storage.
       * Requires: storage:plugin-local
       */
      delete(key: string): Promise<void>;

      /**
       * List all keys in plugin-local storage.
       * Requires: storage:plugin-local
       */
      keys(): Promise<string[]>;
    }

    // === SECRETS API ===

    interface SecretsAPI {
      /**
       * Get a secret value.
       * Requires: secrets:read
       * 
       * Only secrets declared in plugin manifest are accessible.
       */
      get(key: string): Promise<string | null>;
    }

    // === LOGGING API ===

    interface LoggerAPI {
      debug(message: string, metadata?: Record<string, unknown>): void;
      info(message: string, metadata?: Record<string, unknown>): void;
      warn(message: string, metadata?: Record<string, unknown>): void;
      error(message: string, error?: Error, metadata?: Record<string, unknown>): void;
    }

    // === UNIFIED PLUGIN API ===

    interface PluginAPI {
      context: PluginContext;
      data: DataSourceAPI;
      reports: ReportAPI;
      schedules: ScheduleAPI;
      network: NetworkAPI;
      storage: StorageAPI;
      secrets: SecretsAPI;
      logger: LoggerAPI;
    }
  }
}

// Global variable injected by host into plugin sandbox
declare const plugin: PluginAPI.PluginAPI;
```

