## Plugin Lifecycle Hooks

Plugins can export lifecycle handlers:

```typescript
// hooks.ts - Optional handlers exported by plugins

/**
 * Called when plugin is first loaded into memory.
 * Use for: initialization, database migrations, dependency setup
 * 
 * If this rejects, plugin load fails and plugin is not registered.
 */
export async function onLoad(
  api: PluginAPI.PluginAPI,
  previousState?: Record<string, unknown>
): Promise<void> {
  // Initialize connections, validate configuration
  console.log(`Loading ${api.context.metadata.name}`);
  // previousState contains state from last reload if applicable
}

/**
 * Called when plugin is about to be unloaded.
 * Use for: cleanup, persisting state, closing connections
 * 
 * Must complete within timeout (default 5s).
 * If rejected, plugin still unloads but errors are logged.
 */
export async function onUnload(
  api: PluginAPI.PluginAPI
): Promise<Record<string, unknown>> {
  // Cleanup and optionally return state to preserve
  console.log(`Unloading ${api.context.metadata.name}`);
  return { lastSyncTime: Date.now() };
}

/**
 * Called when plugin is being reloaded (new version or config change).
 * Default: system calls onUnload() then onLoad().
 * 
 * Use custom reload for atomic updates without downtime.
 */
export async function onReload(
  api: PluginAPI.PluginAPI,
  previousState?: Record<string, unknown>
): Promise<void> {
  // Reload configuration without full restart
  console.log(`Reloading ${api.context.metadata.name}`);
}
```

