## Plugin Registry

The registry is the source of truth for installed plugins.

```typescript
// registry.ts

interface RegisteredPlugin {
  id: string;
  version: string;
  manifest: PluginManifest;
  status: "loaded" | "unloaded" | "error" | "disabled";
  loadedAt?: Date;
  error?: string;
  config: Record<string, unknown>;
}

interface PluginRegistry {
  /**
   * Register a plugin from manifest + package.
   */
  register(
    manifestPath: string,
    packagePath: string
  ): Promise<RegisteredPlugin>;

  /**
   * Unregister a plugin.
   */
  unregister(id: string, version?: string): Promise<void>;

  /**
   * Get plugin by ID (latest version if not specified).
   */
  get(id: string, version?: string): RegisteredPlugin | undefined;

  /**
   * List all registered plugins.
   */
  list(): RegisteredPlugin[];

  /**
   * Find plugins by capability.
   */
  findByCapability(capability: Capability): RegisteredPlugin[];

  /**
   * Resolve version (supports semver ranges).
   */
  resolveVersion(id: string, versionRange: string): string | undefined;

  /**
   * Update plugin configuration.
   */
  updateConfig(id: string, config: Record<string, unknown>): Promise<void>;

  /**
   * Disable/enable plugin without unloading.
   */
  setEnabled(id: string, enabled: boolean): void;
}
```

