## Version Management & Compatibility

### Multi-Version Support

```typescript
// version-resolver.ts

interface ApiVersionInfo {
  major: number;
  minor: number;
  patch: number;
  stable: boolean;
  deprecatedIn?: string;   // e.g., "2.1"
  removedIn?: string;      // e.g., "3.0"
}

class VersionResolver {
  /**
   * Get API version for a plugin.
   * 
   * - Plugin declares compatible versions in manifest
   * - Host picks best compatible version
   * - Fallback to v1 for old plugins
   */
  resolveApiVersion(
    manifest: PluginManifest,
    hostVersion: string
  ): string {
    const compatible = manifest.spec.compatibleApiVersions;
    // Return highest compatible version
  }

  /**
   * Check if plugin is compatible with host.
   */
  isCompatible(
    manifest: PluginManifest,
    hostVersion: string
  ): boolean {
    return semverSatisfies(
      hostVersion,
      manifest.spec.minHostVersion
    );
  }
}

// Upgrade path: Host v3.0 removes v1 API but provides v2
// Plugins using v1 fail to load with helpful message
// Plugin author updates manifest: compatibleApiVersions: ["2.0", "2.1", "3.0"]
