## Security Model

### Capability-Based Access Control

```typescript
// security.ts

/**
 * Permission enforcement before API calls.
 * 
 * Each API method checks required capability.
 * If plugin lacks capability, raises PermissionDenied.
 */

class CapabilityChecker {
  check(
    pluginCapabilities: Capability[],
    requiredCapability: Capability
  ): void {
    if (!pluginCapabilities.includes(requiredCapability)) {
      throw new PermissionDeniedError(
        `Plugin does not have capability: ${requiredCapability}`
      );
    }
  }
}

/**
 * API isolation:
 * - Plugins cannot directly call each other (must use host routing)
 * - Plugins cannot access other plugins' storage
 * - Plugins cannot modify other plugins' schedules
 * - Secrets are redacted from logs and error messages
 */

/**
 * Code verification:
 * - Manifests validated against JSON Schema
 * - Plugin code scanned for forbidden patterns
 * - Signed manifests supported (future)
 */

// Audit logging
interface AuditLog {
  timestamp: Date;
  pluginId: string;
  action: string;
  capability?: Capability;
  result: "allowed" | "denied";
  metadata?: Record<string, unknown>;
}
```

