## Plugin Manifest Schema

Manifests define what a plugin is and what it needs.

```yaml
# plugin-manifest.yml - REQUIRED
apiVersion: "plugins/v1"
kind: "Plugin"
metadata:
  id: "com.acme.sales-forecast"      # Reverse DNS, globally unique
  name: "Sales Forecast Reporter"
  version: "2.1.0"                    # Semantic versioning
  author:
    name: "ACME Analytics"
    email: "contact@acme.example.com"
  description: "Generates sales forecasts using ML models"
  repository: "https://github.com/acme/forecast-plugin"
  license: "Apache-2.0"

# Plugin lifecycle and configuration
spec:
  # API contract version(s) this plugin supports
  compatibleApiVersions: ["2.0", "2.1"]

  # Minimum host version required
  minHostVersion: "5.0.0"

  # Entry point (ES module or CommonJS)
  main: "./dist/index.js"

  # Entry point for browser/UI context
  uiMain: "./dist/ui.js"

  # Dependencies on other plugins
  dependencies:
    - id: "com.reporting.datasources"
      version: "^1.0.0"

  # Plugin capabilities and required permissions
  capabilities:
    - "datasource:read"        # Read data from data sources
    - "report:write"           # Create/modify reports
    - "schedule:create"        # Create scheduled jobs
    - "network:http"           # Make HTTP requests
    - "storage:plugin-local"   # Local plugin storage

  # Lifecycle hooks
  hooks:
    onLoad: true               # Plugin has onLoad hook
    onUnload: true             # Plugin has onUnload hook
    onReload: true             # Plugin has onReload hook (default: unload+load)

  # Resource constraints
  resources:
    memory: "512Mi"            # Max memory
    timeout: "30s"             # Max execution time per call
    diskQuota: "100Mi"         # Local storage quota

  # Configuration schema for users
  config:
    schema:
      type: "object"
      properties:
        apiKey:
          type: "string"
          description: "Third-party service API key"
          secret: true
        refreshInterval:
          type: "integer"
          default: 3600
          description: "Data refresh interval in seconds"
    required: ["apiKey"]

  # Export capabilities (what this plugin provides to other plugins)
  exports:
    - name: "ForecastModel"
      version: "1.0.0"
      type: "class"

# Plugin metadata visibility and distribution
distribution:
  registry: true               # Discoverable in plugin registry
  tags: ["forecasting", "ml", "sales"]
  categories: ["reporting", "analytics"]

  # Where to fetch the plugin
  packages:
    - os: "linux"
      arch: "x64"
      url: "https://releases.acme.com/forecast-v2.1.0-linux.tar.gz"
      sha256: "abc123def456..."
    - os: "macos"
      arch: "arm64"
      url: "https://releases.acme.com/forecast-v2.1.0-darwin-arm64.tar.gz"
      sha256: "ghi789jkl012..."
```

