/**
 * Main report handler - called by host or scheduled jobs.
 */
export async function generateForecast(
  api: PluginAPI.PluginAPI,
  params: {
    datasourceId: string;
    forecastMonths: number;
    region?: string;
  }
): Promise<Record<string, unknown>> {
  api.logger.info("Generating forecast", params);

  // 1. Query historical data
  const schema = await api.data.getSchema(params.datasourceId);
  api.logger.debug("Data schema", { columns: schema.length });

  const query = `
    SELECT date, sales, region FROM sales_data
    WHERE date >= CURRENT_DATE - INTERVAL '24 months'
    ${params.region ? "AND region = ?" : ""}
  `;

  const result = await api.data.query(
    params.datasourceId,
    query,
    { timeout: 30000 }
  );

  api.logger.info("Retrieved forecast data", { rowCount: result.rowCount });

  // 2. Call external ML service
  const apiKey = await api.secrets.get("forecast_api_key");
  const mlResponse = await api.network.http(
    "https://ml.acme.example.com/api/forecast",
    {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        data: result.rows,
        months: params.forecastMonths
      })
    }
  );

  if (mlResponse.status !== 200) {
    throw new Error(`ML service error: ${mlResponse.status}`);
  }

  const forecast = JSON.parse(mlResponse.body);

  // 3. Generate report
  const report = await api.reports.generate({
    format: "html",
    title: `Sales Forecast - ${params.region || "All Regions"}`,
    description: `${params.forecastMonths}-month forecast`,
    parameters: params
  });

  // 4. Store metadata locally
  await api.storage.write(
    `forecast_${Date.now()}`,
    JSON.stringify({
      forecastId: report.id,
      params,
      generatedAt: new Date().toISOString()
    })
  );

  // 5. Create scheduled job for monthly updates
  if (!params.region) {
    await api.schedules.create(
      "0 0 1 * *",  // First day of month
      "updateForecast",
      { forecastMonths: params.forecastMonths }
    );
  }

  api.logger.info("Forecast generated", { reportId: report.id });

  return {
    reportId: report.id,
    forecast,
    generatedAt: report.generatedAt
  };
}

export async function updateForecast(
  api: PluginAPI.PluginAPI,
  params: { forecastMonths: number }
): Promise<void> {
  api.logger.info("Updating forecast via schedule");
  // Similar to generateForecast
}
