## **2. Versioned API Contract** (TypeScript)

Injected globally as `plugin` in each plugin's sandbox:

```typescript
declare global {
  namespace PluginAPI {
    // Identity & context
    interface PluginContext {
      metadata: PluginMetadata;
      config: Record<string, unknown>;
      capabilities: Capability[];
      version: string;
      apiVersion: string;
    }

    type Capability = 
      | "datasource:read" | "datasource:write"
      | "report:read" | "report:write"
      | "schedule:create" | "schedule:delete"
      | "network:http"
      | "storage:plugin-local" | "storage:shared"
      | "secrets:read";

    // Data source queries
    interface DataSourceAPI {
      list(): Promise<DataSource[]>;
      query(sourceId: string, sql: string, options?: QueryOptions): Promise<QueryResult>;
      getSchema(sourceId: string): Promise<ColumnSchema[]>;
    }

    // Report generation
    interface ReportAPI {
      generate(input: ReportGenerationInput): Promise<ReportOutput>;
      list(filters?: ReportFilters): Promise<ReportDefinition[]>;
      get(reportId: string): Promise<ReportDefinition>;
      delete(reportId: string): Promise<void>;
    }

    // Scheduled job creation
    interface ScheduleAPI {
      create(expression: string, handler: string, parameters?: Record<string, unknown>): Promise<ScheduleDefinition>;
      list(): Promise<ScheduleDefinition[]>;
      delete(scheduleId: string): Promise<void>;
    }

    // Outbound HTTP with limits
    interface NetworkAPI {
      http(url: string, options?: HttpRequestOptions): Promise<HttpResponse>;
      // Private IPs blocked unless allowlisted
    }

    // Plugin-local key/value store
    interface StorageAPI {
      read(key: string): Promise<string | null>;
      write(key: string, value: string): Promise<void>;
      delete(key: string): Promise<void>;
      keys(): Promise<string[]>;
    }

    // Secrets (read-only)
    interface SecretsAPI {
      get(key: string): Promise<string | null>;  // Only declared secrets accessible
    }

    // Structured logging
    interface LoggerAPI {
      debug(message: string, metadata?: Record<string, unknown>): void;
      info(message: string, metadata?: Record<string, unknown>): void;
      warn(message: string, metadata?: Record<string, unknown>): void;
      error(message: string, error?: Error, metadata?: Record<string, unknown>): void;
    }

    // Unified API object
    interface PluginAPI {
      context: PluginContext;
      data: DataSourceAPI;
      reports: ReportAPI;
      schedules: ScheduleAPI;
      network: NetworkAPI;
      storage: StorageAPI;
      secrets: SecretsAPI;
      logger: LoggerAPI;
    }
  }
}

declare const plugin: PluginAPI.PluginAPI;
```

