## 6. Versioned API Contract

The plugin API is versioned independently of the reporting tool version. This allows:
- Old plugins to work with new tool versions
- New APIs to be added without breaking old plugins
- Graceful deprecation with migration period

### 6.1 API Versioning Strategy

```typescript
// API versions follow semantic versioning
// MAJOR.MINOR.PATCH

// v1.0.0: Initial release
// v1.1.0: Add new chart types, backward compatible
// v1.2.0: Add data transform hooks, backward compatible
// v2.0.0: Remove deprecated APIs, breaking changes

interface ReportingAPIvX_Y {
  // Stable: present in all versions
  readonly version: string;
  readonly toolVersion: string;
  readonly context: PluginContext;

  // Features gated by API version
  charts?: ChartAPIv1_0;
  exporters?: ExporterAPIv1_0;
  dataProcessing?: DataProcessingAPIv1_1;

  // Deprecated (warning on use, planned removal)
  legacyCharts?: LegacyChartAPIv0_9 & {
    readonly deprecated: {
      message: string;
      removedIn: string;
      migration: string;
    };
  };
}

// Concrete implementations
interface ReportingAPIv1_0 {
  // Charts
  charts: {
    register(id: string, renderer: ChartRenderer): void;
    get(id: string): ChartRenderer | undefined;
    list(): ChartRegistry[];
  };
  // Exporters
  exporters: {
    register(id: string, exporter: Exporter): void;
    get(id: string): Exporter | undefined;
  };
  // Utilities
  utils: {
    parseData(csv: string): DataTable;
    formatNumber(n: number, format: string): string;
  };
}

interface ReportingAPIv1_1 extends ReportingAPIv1_0 {
  // New in v1.1: Data transform hooks
  dataTransforms: {
    register(name: string, fn: DataTransformFn): void;
    apply(name: string, data: DataTable): DataTable;
  };
}

interface ReportingAPIv1_2 extends ReportingAPIv1_1 {
  // New in v1.2: Plugin config hooks
  config: {
    get<T>(key: string): T;
    set<T>(key: string, value: T): void;
    onChange(key: string, callback: (newValue: any) => void): void;
  };
}
```

### 6.2 API Adapter Pattern

```typescript
class APIAdapter {
  static create(
    requestedVersion: string,
    toolVersion: string,
    context: PluginContext
  ): ReportingAPIvX_Y {
    const [major, minor, patch] = requestedVersion.split('.').map(Number);

    // Requested version newer than tool supports
    if (major > CURRENT_API_MAJOR) {
      throw new Error(
        `Plugin requests API v${requestedVersion} ` +
        `but tool only supports up to v${CURRENT_API_VERSION}`
      );
    }

    // Create base API with all features
    const api = this.createLatestAPI(context);

    // Shim deprecated APIs for backward compatibility
    if (major < CURRENT_API_MAJOR) {
      api.legacyCharts = this.createLegacyCharts(context);
    }

    return api;
  }

  private static createLatestAPI(context: PluginContext): ReportingAPIv1_2 {
    return {
      version: '1.2.0',
      toolVersion: TOOL_VERSION,
      context,
      charts: new ChartRegistry(),
      exporters: new ExporterRegistry(),
      dataTransforms: new DataTransformRegistry(),
      config: new ConfigManager(context),
      utils: new UtilityLibrary(),
    };
  }
}
```

