## 9. Security Model

### 9.1 Permission System

Plugins declare required permissions in their manifest. Administrators review and approve before loading.

```typescript
enum PluginPermission {
  // Data access
  'data.read' = 'data.read',           // Access report data
  'data.modify' = 'data.modify',       // Modify data

  // Filesystem
  'filesystem.read' = 'filesystem.read',
  'filesystem.write' = 'filesystem.write',

  // Network
  'network.http' = 'network.http',
  'network.https' = 'network.https',

  // System
  'worker.spawn' = 'worker.spawn',
  'process.spawn' = 'process.spawn',

  // Plugins
  'plugin.access' = 'plugin.access',
  'plugin.modify' = 'plugin.modify',
}

interface PermissionPolicy {
  // Global: required by all plugins
  required: Set<PluginPermission>;

  // Whitelist: plugins can request these
  allowed: Set<PluginPermission>;

  // Blacklist: plugins cannot request these
  denied: Set<PluginPermission>;

  // Per-plugin overrides
  pluginOverrides: Map<string, {
    grant: Set<PluginPermission>;
    deny: Set<PluginPermission>;
  }>;
}
