}

export async function unload(context: PluginContext): Promise<void> {
  context.logger.info('Advanced Charts plugin unloading');
  // Cleanup D3 instances
  // Cancel pending renders
}

export async function onPreReport(
  context: PluginContext,
  report: ReportDefinition
): Promise<void> {
  // Validate that data has required columns for sunburst
  if (report.charts.some(c => c.type === 'sunburst')) {
