export interface ReportsApiV3_0 extends ReportsApiBase {
  createReport(report: ReportDefinition): Promise<Report>;
  updateReport(reportId: string, updates: Partial<Report>): Promise<Report>;
  deleteReport(reportId: string): Promise<void>;
  streamReportData(reportId: string): AsyncIterable<DataChunk>;
}

// v3.2 - Additive
export interface ReportsApiV3_2 extends ReportsApiV3_0 {
  batchGetReports(ids: string[]): Promise<Report[]>;
  batchExecute(requests: ExecutionRequest[]): AsyncIterable<ExecutionResult>;
  registerWebhook(trigger: WebhookTrigger, url: string): Promise<Webhook>;
  unregisterWebhook(webhookId: string): Promise<void>;
}

// v3.5 - Further additions
export interface ReportsApiV3_5 extends ReportsApiV3_2 {
  scheduleReport(report: ReportDefinition, schedule: CronSchedule): Promise<ScheduledReport>;
  getAuditLog(filter: AuditFilter): Promise<AuditEntry[]>;
}

// v4.0 - BREAKING (incompatible with v3)
export interface ReportsApiV4_0 {
