  // ... completely new interface
}

// Compatibility resolver
export class CompatibilityResolver {
  canLoad(manifest: PluginManifest, hostApiVersion: string): { compatible: boolean; reason?: string } {
    const pluginMin = manifest.apiVersion;
    const pluginMax = manifest.apiMaxVersion || null;

    const [hostMajor, hostMinor] = hostApiVersion.split('.').map(Number);
    const [pluginMinMajor, pluginMinMinor] = pluginMin.split('.').map(Number);

    if (hostMajor < pluginMinMajor || 
        (hostMajor === pluginMinMajor && hostMinor < pluginMinMinor)) {
      return { compatible: false, reason: `Host API ${hostApiVersion} < required ${pluginMin}` };
    }

    if (pluginMax) {
      const [maxMajor, maxMinor] = pluginMax.split('.').map(Number);
      if (hostMajor > maxMajor) {
        return { compatible: false, reason: `Host API major ${hostMajor} > max ${maxMajor}` };
      }
    }

    return { compatible: true };
  }
}

// Get correct API version for plugin
export function getHostApi(version: string): ReportsApiBase {
  if (version.startsWith('3.')) return new ReportsApiV3_5();
  if (version.startsWith('4.')) return new ReportsApiV4_0();
  throw new Error(`Unsupported API version: ${version}`);
}
