```typescript
export interface PluginRegistry {
  // Discovery & Loading
  discover(paths: string[]): Promise<PluginManifest[]>;
  register(manifest: PluginManifest): Promise<PluginDescriptor>;
  load(pluginId: string, config?: any): Promise<PluginInstance>;
  unload(pluginId: string, reason?: string): Promise<void>;
  reload(pluginId: string, config?: any): Promise<PluginInstance>;

  // Query
  get(pluginId: string): PluginDescriptor | undefined;
  getByCapability(capability: string): PluginDescriptor[];
  getByTag(tag: string): PluginDescriptor[];
  list(filter?: { state?: PluginState; tags?: string[] }): PluginDescriptor[];

  // Dependencies
  resolveDependencies(pluginId: string): Promise<ResolvedDependencies>;
  checkConflicts(pluginId: string): ConflictReport;

  // Events
  onStateChange(pluginId: string, cb: (event: PluginEvent) => void): () => void;
  onError(pluginId: string, cb: (error: PluginError) => void): () => void;
  onEvent(type: PluginEventType, cb: (event: PluginEvent) => void): () => void;

  // Persistence
  save(): Promise<void>;
  exportState(): RegistrySnapshot;
  importState(snapshot: RegistrySnapshot): Promise<void>;
}

// Load sequence - key state machine
export async function loadPluginSequence(
  registry: PluginRegistry,
  pluginId: string,
  config?: Record<string, any>
): Promise<PluginInstance> {
  const descriptor = registry.get(pluginId);
  if (!descriptor) throw new Error(`Plugin ${pluginId} not found`);
  if (descriptor.state === 'LOADED') return descriptor.instance!;

  descriptor.state = 'LOADING';

  try {
    // 1. Resolve dependencies
    const deps = await registry.resolveDependencies(pluginId);
    if (deps.missing.length > 0) {
      throw new PluginLoadError(pluginId, 'dependency-resolution', 
        new Error(`Missing: ${deps.missing.join(', ')}`));
    }

    // 2. Check conflicts
    const conflicts = registry.checkConflicts(pluginId);
    if (!conflicts.resolvable) {
      throw new PluginLoadError(pluginId, 'validation', 
        new Error(`Conflicts: ${conflicts.conflicts.map(c => c.conflictingPlugin).join(', ')}`));
    }

    // 3. Validate config
    if (descriptor.manifest.config?.configurable && config) {
      validateConfig(config, descriptor.manifest.config.configSchema);
    }

    // 4. Load module
    const module = await loadModule(descriptor.manifest.entry);
    validateModuleExports(module);

    // 5. Create context
    const context = createPluginContext(pluginId, module, config);

    // 6. Execute onLoad hook with timeout
    const timeout = descriptor.manifest.hooks?.onLoad?.timeout || 5000;
    await executeWithTimeout(module.onLoad(context), timeout);

    // 7. Register capabilities
    const capabilities = module.getCapabilities();
    registerCapabilities(pluginId, capabilities);

    // Mark LOADED
    descriptor.state = 'LOADED';
    descriptor.loadedAt = new Date();

    return descriptor.instance!;

  } catch (error) {
    descriptor.state = 'FAILED';
    descriptor.errors.push(error as PluginError);

    // Try best-effort cleanup
    try {
      if (descriptor.instance?.module.onUnload) {
        await executeWithTimeout(descriptor.instance.module.onUnload(context), 3000);
      }
    } catch (e) {
      // Log but don't throw
    }

    throw error;
  }
}

// Unload sequence - best-effort cleanup
export async function unloadPluginSequence(
  registry: PluginRegistry,
  pluginId: string,
  reason: string = 'manual'
): Promise<void> {
  const descriptor = registry.get(pluginId);
  if (!descriptor || !descriptor.instance) return;

  descriptor.state = 'UNLOADING';

  try {
    // 1. Drain active requests
    await drainActiveRequests(pluginId, 5000);

    // 2. Call onUnload (best-effort)
    if (descriptor.instance.module.onUnload) {
      const timeout = descriptor.manifest.hooks?.onUnload?.timeout || 3000;
      await executeWithTimeout(
        descriptor.instance.module.onUnload(context), 
        timeout
      ).catch(e => logger.warn(`onUnload error for ${pluginId}`, e));
    }

    // 3. Force cleanup
    forceCleanupResources(pluginId);
    unregisterCapabilities(pluginId);

    // 4. Update state
    descriptor.state = 'REGISTERED';
    descriptor.instance = null;
    descriptor.loadedAt = null;

  } catch (e) {
    // Best-effort - continue anyway
    logger.error(`Error unloading ${pluginId}`, e);
  }
}
