```typescript
export class CapabilityProxy implements ReportsApi {
  constructor(
    private realApi: ReportsApi,
    private permissions: SandboxPermissions,
    private pluginId: string,
    private logger: Logger,
    private metrics: MetricsCollector
  ) {}

  async getReports(filter?: ReportFilter): Promise<Report[]> {
    this.checkCapability('data:read');
    this.checkResourceLimit('apiCall');

    // Apply workspace restrictions
    if (this.permissions.dataAccess?.workspaceIds) {
      filter = { ...filter, workspaceId: this.permissions.dataAccess.workspaceIds };
    }

    const start = Date.now();
    try {
      const result = await this.realApi.getReports(filter);
      this.metrics.recordApiCall(Date.now() - start, true, 'getReports');
      return result;
    } catch (error) {
      this.metrics.recordApiCall(Date.now() - start, false, 'getReports');
      throw error;
    }
  }

  async executeReport(reportId: string, params: Record<string, any>): Promise<ExecutionResult> {
    this.checkCapability('data:read');

    // Check report access
    if (this.permissions.dataAccess?.reportIds?.length) {
      if (!this.permissions.dataAccess.reportIds.includes(reportId)) {
        throw new PluginPermissionError(this.pluginId, 'data:read', reportId);
      }
    }

    return this.realApi.executeReport(reportId, params);
  }

  private checkCapability(capability: string): void {
    const allowed = this.permissions.dataAccess?.includes(capability);
    if (!allowed) {
      this.logger.warn(`Denied ${capability}`, { plugin: this.pluginId });
      this.metrics.recordPermissionDenied(capability);
      throw new PluginPermissionError(this.pluginId, capability, 'unknown');
    }
  }

  private checkResourceLimit(type: string): void {
    const current = this.getResourceUsage(type);
    const limit = this.permissions.system?.[`max${capitalize(type)}`];
    if (limit && current >= limit) {
      throw new PluginResourceExhaustedError(this.pluginId, type, limit);
    }
  }

  private getResourceUsage(type: string): number {
    // Actual resource measurement would happen here
    return 0;
  }
}

// Filesystem access control
export class SandboxedFileSystem {
  constructor(
    private allowedPaths: string[],
    private pluginId: string
  ) {}

  async read(path: string): Promise<Buffer> {
    const resolved = Path.resolve(path);

    if (!this.isAllowed(resolved)) {
      throw new PluginPermissionError(this.pluginId, 'filesystem:read', path);
    }

    const realPath = await fs.realpath(resolved);
    if (!this.isAllowed(realPath)) {
      throw new PluginPermissionError(this.pluginId, 'filesystem:read', path);
    }

    return fs.readFile(realPath);
  }

  async write(path: string, data: Buffer): Promise<void> {
    const resolved = Path.resolve(path);
    if (!this.isAllowed(resolved)) {
      throw new PluginPermissionError(this.pluginId, 'filesystem:write', path);
    }
    return fs.writeFile(resolved, data);
  }

  private isAllowed(path: string): boolean {
    return this.allowedPaths.some(allowed => minimatch(path, allowed));
  }
}

// Network interception
export class NetworkProxy {
  private rateLimits = new Map<string, RateLimit>();

  interceptFetch(pluginId: string, permissions: SandboxPermissions) {
    const originalFetch = globalThis.fetch;

    globalThis.fetch = async (url: string | URL, options?: RequestInit) => {
      const domain = new URL(url).hostname;

      if (!this.isAllowed(domain, permissions)) {
        throw new PluginPermissionError(pluginId, 'network', domain);
      }

      await this.checkRateLimit(domain, permissions);
      return originalFetch(url, options);
    };
  }

  private isAllowed(domain: string, permissions: SandboxPermissions): boolean {
    const allowed = permissions.network?.allowed || [];
    if (allowed.length === 0) return false;
    return allowed.some(pattern => minimatch(domain, pattern));
  }

  private async checkRateLimit(domain: string, permissions: SandboxPermissions): Promise<void> {
    const limit = permissions.network?.rateLimit;
    if (!limit) return;

    const key = domain;
    const current = this.rateLimits.get(key) || { count: 0, resetAt: Date.now() };

    if (current.count >= limit.requestsPerSecond && Date.now() < current.resetAt + 1000) {
      throw new Error(`Rate limit exceeded for ${domain}`);
    }

    current.count++;
    this.rateLimits.set(key, current);
  }
}

// Memory limiter
export class ResourceLimiter {
  private timers: Set<any> = new Set();
  private connections: Set<any> = new Set();

  constructor(
    private heapLimit: number,
    private cpuTimeout: number
  ) {
    setInterval(() => this.checkMemory(), 1000);
  }

  private checkMemory(): void {
    const usage = process.memoryUsage();
    if (usage.heapUsed > this.heapLimit * 1024 * 1024) {
      if (global.gc) global.gc();

      if (usage.heapUsed > this.heapLimit * 1024 * 1024) {
        throw new PluginResourceExhaustedError('plugin', 'memory', this.heapLimit);
      }
    }
  }

  async runWithTimeout<T>(fn: () => Promise<T>): Promise<T> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error('Plugin operation timeout'));
      }, this.cpuTimeout);

      fn()
        .finally(() => clearTimeout(timeout))
        .then(resolve)
        .catch(reject);
    });
  }
}
