### Registry Implementation Strategy

```typescript
class PluginRegistryImpl implements PluginRegistry {
  private plugins = new Map<string, PluginInfo>();
  private workers = new Map<string, WorkerHandle>();
  private listeners: RegistryListener[] = [];
  private stateMachine: StateMachine<string, PluginState>;

  constructor(
    private resourceLimit: ResourceLimits = DEFAULT_LIMITS,
    private manifestValidator: ManifestValidator,
    private dependencyResolver: DependencyResolver
  ) {
    this.stateMachine = new StateMachine<string, PluginState>();
  }

  async load(manifest: PluginManifest): Promise<PluginHandle> {
    // 1. Validate manifest
    const validation = await this.manifestValidator.validate(manifest);
    if (!validation.valid) throw new ManifestError(validation.errors);

    // 2. Check compatibility
    const compatibility = await this.checkCompatibility(manifest);
    if (!compatibility.compatible) throw new IncompatibilityError(compatibility.issues);

    // 3. Resolve and load dependencies
    const deps = this.resolveDependencies(manifest.id);
    if (!deps.every(d => d.health.status !== "failed")) {
      throw new DependencyError("Required dependencies failed to load");
    }

    // 4. Create plugin info
    const info: PluginInfo = {
      id: manifest.id,
      version: manifest.version,
      name: manifest.name,
      description: manifest.description,
      author: manifest.author,
      capabilities: manifest.capabilities,
      dependencies: manifest.dependencies || [],
      apiVersion: manifest.apiVersion,
      entrypoint: manifest.entrypoint,
      config: manifest.config,
      health: { status: "initializing", lastCheck: new Date() },
    };

    // 5. Spawn isolated worker
    const worker = await this.createWorker(manifest);
    const handle = new PluginHandle(manifest.id, worker);

    // 6. Initialize plugin (call setup hook)
    try {
      await handle.invoke("__setup__", { manifest });
      info.health = { status: "healthy", lastCheck: new Date() };
      info.handle = handle;
    } catch (error) {
      info.health = { 
        status: "failed", 
        lastCheck: new Date(), 
        error: error.message 
      };
      await worker.terminate();
      throw new PluginInitError(manifest.id, error);
    }

    // 7. Register and emit event
    this.plugins.set(manifest.id, info);
    this.stateMachine.transition(manifest.id, "loaded");
    this.emit("onPluginLoaded", info);

    return handle;
  }

  async unload(id: string): Promise<void> {
    const info = this.plugins.get(id);
    if (!info) throw new PluginNotFoundError(id);

    this.stateMachine.transition(id, "unloading");

    try {
      // Call teardown hook
      if (info.handle) {
        await info.handle.invoke("__teardown__", {});
        await info.handle.close();
      }

      this.plugins.delete(id);
      this.workers.delete(id);
      this.stateMachine.transition(id, "unloaded");
      this.emit("onPluginUnloaded", id);
    } catch (error) {
      this.stateMachine.transition(id, "failed");
      this.emit("onPluginFailed", id, error);
      throw new PluginUnloadError(id, error);
    }
  }

  async reload(id: string): Promise<void> {
    const info = this.plugins.get(id);
    if (!info) throw new PluginNotFoundError(id);

    const manifest = /* reconstruct from info */;
    await this.unload(id);
    await this.load(manifest);
  }

  private async createWorker(manifest: PluginManifest): Promise<WorkerHandle> {
    const workerPath = resolve(manifest.entrypoint);
    const worker = new WorkerImpl(workerPath, {
      memoryLimit: this.resourceLimit.memoryPerPlugin,
      timeout: this.resourceLimit.callTimeout,
    });

    this.workers.set(manifest.id, worker);
    return worker;
  }

  private emit(event: keyof RegistryListener, ...args: any[]) {
    for (const listener of this.listeners) {
      const handler = listener[event];
      if (handler) handler.apply(listener, args);
    }
  }
}
