### Validation & Tools

```typescript
// Manifest validator
class ManifestValidator {
  private schemaValidator: AjvValidator;

  async validate(manifest: PluginManifest): Promise<ValidationResult> {
    const errors: ValidationError[] = [];

    // 1. Schema validation
    if (!this.schemaValidator.validate(manifest)) {
      errors.push(...this.schemaValidator.errors.map(e => ({
        path: e.instancePath,
        message: e.message,
        severity: "error" as const
      })));
    }

    // 2. Semantic validation
    if (!/^[a-z0-9.-]+$/.test(manifest.id)) {
      errors.push({
        path: "/id",
        message: "Plugin ID must be lowercase alphanumeric with dots/hyphens",
        severity: "error"
      });
    }

    if (!isValidSemver(manifest.version)) {
      errors.push({
        path: "/version",
        message: "Version must follow semver (e.g., 1.2.0)",
        severity: "error"
      });
    }

    if (!isValidSemver(manifest.apiVersion)) {
      errors.push({
        path: "/apiVersion",
        message: "API version must follow semver",
        severity: "error"
      });
    }

    // 3. Export validation
    for (const method of manifest.exports.methods) {
      if (!method.name.match(/^[a-zA-Z_][a-zA-Z0-9_]*$/)) {
        errors.push({
          path: `/exports/methods/${method.name}`,
          message: "Method name must be valid identifier",
          severity: "error"
        });
      }
    }

    return {
      valid: errors.filter(e => e.severity === "error").length === 0,
      errors,
      warnings: errors.filter(e => e.severity === "warning")
    };
  }
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationError[];
}

interface ValidationError {
  path: string;
  message: string;
  severity: "error" | "warning";
}
