## Lifecycle Management

Plugins follow a strict state machine with well-defined hooks.

### State Machine

```
┌─────────┐     load()    ┌─────────────────┐    __setup__()  ┌────────┐
│ UNLOADED├────────────→ │  INITIALIZING  ├────────────────→ │HEALTHY │
└─────────┘               └─────────────────┘                 └────┬───┘
                                  ↓ error                          │
                            ┌───────────┐                         │
                            │ LOAD_FAIL │                         │
                            └───────────┘                         │
                                                                   │
                             ┌──────────────────────────────────┘
                             │
                             ├─── reload() ──→ INITIALIZING
                             │
                             └─── unload() ──→ UNLOADING
                                                   ↓ __teardown__()
                                            ┌──────────────┐
                                            │   UNLOADED   │
                                            └──────────────┘
```

### Lifecycle Hooks

Plugins must implement these lifecycle methods as exports.

```typescript
// Hooks that the host calls on plugins
interface PluginLifecycleHooks {
  /**
   * Called when plugin is first loaded.
   * Must complete within 10 seconds.
   * 
   * @param config - Configuration from manifest merged with runtime overrides
   * @param context - Access to host API, logger, storage
   */
  __setup__(config: unknown, context: PluginContext): Promise<void>;

  /**
   * Called periodically to check plugin health.
   * Should return quickly (< 1 second).
   * 
   * @returns Health status
   */
  __health__(): Promise<HealthCheckResult>;

  /**
   * Called before plugin is unloaded or reloaded.
   * Must complete within 5 seconds.
   * All resources must be cleaned up here.
   * 
   * @param reason - Why teardown is happening ("unload", "reload", "shutdown")
   */
  __teardown__(reason: "unload" | "reload" | "shutdown"): Promise<void>;

  /**
   * Called when configuration is updated at runtime.
   * Must complete within 5 seconds.
   * 
   * @param oldConfig - Previous configuration
   * @param newConfig - New configuration
   * @returns true to apply changes, false to reject
   */
  __configUpdated__(oldConfig: unknown, newConfig: unknown): Promise<boolean>;
}

interface PluginContext {
  // Logging
  logger: Logger;

  // Configuration storage
  config: ConfigStore;

  // Host API access (versioned)
  hostApi: HostAPI;

  // Plugin-to-plugin messaging
  messaging: PluginMessaging;

  // Storage for plugin state (isolated, per-plugin)
  storage: PluginStorage;
}

interface HealthCheckResult {
  healthy: boolean;
  issues?: string[];
  metrics?: {
    memory?: number;
    uptime?: number;
    lastError?: { message: string; timestamp: Date };
  };
}

// Example plugin implementation
class MyReportPlugin {
  private config: MyConfig;
  private resources: Resource[] = [];

  async __setup__(config: unknown, context: PluginContext): Promise<void> {
    this.config = validateConfig(config);
    context.logger.info("Plugin initializing", { version: "1.0" });

    // Initialize resources
    this.resources.push(
      await context.hostApi.connect("database", this.config.dbUrl)
    );

    context.logger.info("Plugin ready");
  }

  async __health__(): Promise<HealthCheckResult> {
    try {
      for (const resource of this.resources) {
        if (!await resource.isHealthy()) {
          return { healthy: false, issues: ["Database connection lost"] };
        }
      }
      return { healthy: true };
    } catch (error) {
      return { 
        healthy: false, 
        issues: [error.message]
      };
    }
  }

  async __teardown__(reason: string): Promise<void> {
    for (const resource of this.resources) {
      await resource.close();
    }
    this.resources = [];
  }

  async __configUpdated__(
    oldConfig: unknown, 
    newConfig: unknown
  ): Promise<boolean> {
    const newParsed = validateConfig(newConfig);

    // Can we apply changes without restart?
    if (oldConfig.logLevel !== newParsed.logLevel) {
      this.config.logLevel = newParsed.logLevel;
      return true; // Apply
    }

    if (oldConfig.dbUrl !== newParsed.dbUrl) {
      return false; // Requires reload
    }

    return true;
  }

  // Plugin-specific methods exported to host
  async generateReport(params: ReportParams): Promise<Report> {
    // Implementation
  }
}
```

### Lifecycle Manager Implementation

```typescript
class PluginLifecycleManager {
  private stateMap = new Map<string, PluginState>();
  private timeouts = new Map<string, NodeJS.Timeout>();
  private hooks: LifecycleHook[] = [];

  async load(
    handle: PluginHandle,
    config: unknown,
    context: PluginContext
  ): Promise<void> {
    const id = handle.id;
    this.setState(id, "initializing");

    const setupTimeout = setTimeout(() => {
      throw new Error(`__setup__ timeout for plugin ${id}`);
    }, 10000);

    try {
      await handle.invoke("__setup__", [config, context]);
      clearTimeout(setupTimeout);
      this.setState(id, "loaded");
      this.emit({ type: "loaded", pluginId: id });
    } catch (error) {
      clearTimeout(setupTimeout);
      this.setState(id, "failed");
      this.emit({ type: "load-failed", pluginId: id, error });
      throw error;
    }
  }

  async unload(
    handle: PluginHandle,
    reason: "unload" | "reload" | "shutdown"
  ): Promise<void> {
    const id = handle.id;
    this.setState(id, "unloading");

    const teardownTimeout = setTimeout(() => {
      throw new Error(`__teardown__ timeout for plugin ${id}`);
    }, 5000);

    try {
      await handle.invoke("__teardown__", [reason]);
      clearTimeout(teardownTimeout);
      this.setState(id, "unloaded");
      this.emit({ type: "unloaded", pluginId: id });
    } catch (error) {
      clearTimeout(teardownTimeout);
      // Log but don't throw - plugin is going away anyway
      this.emit({ type: "teardown-failed", pluginId: id, error });
    }
  }

  async updateConfig(
    handle: PluginHandle,
    oldConfig: unknown,
    newConfig: unknown
  ): Promise<boolean> {
    const timeout = setTimeout(() => {
      throw new Error(`__configUpdated__ timeout for plugin ${handle.id}`);
    }, 5000);

    try {
      const accepted = await handle.invoke("__configUpdated__", [
        oldConfig,
        newConfig
      ]);
      clearTimeout(timeout);

      this.emit({
        type: "config-updated",
        pluginId: handle.id,
        accepted: !!accepted
      });

      return !!accepted;
    } catch (error) {
      clearTimeout(timeout);
      throw new ConfigUpdateError(handle.id, error);
    }
  }

  async healthCheck(handle: PluginHandle): Promise<HealthCheckResult> {
    const timeout = setTimeout(() => {
      return { healthy: false, issues: ["Health check timeout"] };
    }, 1000);

    try {
      const result = await handle.invoke("__health__", []);
      clearTimeout(timeout);
      return result;
    } catch (error) {
      clearTimeout(timeout);
      return { 
        healthy: false, 
        issues: [error.message]
      };
    }
  }

  private setState(id: string, state: PluginState) {
    this.stateMap.set(id, state);
  }

  private emit(event: LifecycleEvent) {
    for (const hook of this.hooks) {
      hook(event);
    }
  }
}

type PluginState = 
  | "unloaded" 
  | "initializing" 
  | "loaded" 
  | "unloading" 
  | "failed";

type LifecycleEvent = 
  | { type: "loaded"; pluginId: string }
  | { type: "load-failed"; pluginId: string; error: Error }
  | { type: "unloaded"; pluginId: string }
  | { type: "teardown-failed"; pluginId: string; error: Error }
  | { type: "config-updated"; pluginId: string; accepted: boolean };
```

