## Sandboxing & Execution

Plugins run in isolated worker processes with strict resource limits and permission boundaries.

### Worker Sandbox Architecture

```
┌───────────────────────────────────────────────────────────┐
│                    Host Process                            │
│  ┌─────────────────────────────────────────────────────┐  │
│  │ Plugin Registry / RPC Broker                        │  │
│  │ ┌───────────────────────────────────────────────┐   │  │
│  │ │ Resource Governor                             │   │  │
│  │ │ - Memory quota enforcement                    │   │  │
│  │ │ - CPU limits (via process groups / cgroups)  │   │  │
│  │ │ - Call timeout enforcement                    │   │  │
│  │ │ - Concurrency limiting                        │   │  │
│  │ └───────────────────────────────────────────────┘   │  │
│  └─────────────────────────────────────────────────────┘  │
│                      ↕ Message Queue                       │
└───────────────────────────────────────────────────────────┘
              ↓                    ↓                    ↓
    ┌──────────────────┐  ┌──────────────────┐  ┌──────────────────┐
    │ Worker 1         │  │ Worker 2         │  │ Worker 3         │
    │ (Plugin A)       │  │ (Plugin B)       │  │ (Plugin C)       │
    │ ┌──────────────┐ │  │ ┌──────────────┐ │  │ ┌──────────────┐ │
    │ │ Restricted   │ │  │ │ Restricted   │ │  │ │ Restricted   │ │
    │ │ Environment: │ │  │ │ Environment: │ │  │ │ Environment: │ │
    │ │ - Only Host  │ │  │ │ - Only Host  │ │  │ │ - Only Host  │ │
    │ │   API access │ │  │ │   API access │ │  │ │   API access │ │
    │ │ - No network │ │  │ │ - No network │ │  │ │ - No network │ │
    │ │ - No fs      │ │  │ │ - No fs      │ │  │ │ - No fs      │ │
    │ │ - Memory: 256M
    │ │ - Timeout: 30s
    │ └──────────────┘ │  │ └──────────────┘ │  │ └──────────────┘ │
    └──────────────────┘  └──────────────────┘  └──────────────────┘
```

### Execution Model

```typescript
// Plugin runs only in response to RPC calls from the host
// Communication is strictly request/response with versioning

interface WorkerHandle {
  id: string;

  // Invoke a plugin method with full isolation
  invoke(
    method: string,
    params: unknown,
    options?: InvokeOptions
  ): Promise<unknown>;

  // Subscribe to plugin events
  subscribe(
    event: string,
    listener: (data: unknown) => void
  ): Unsubscribe;

  // Terminate worker
  terminate(): Promise<void>;
}

interface InvokeOptions {
  timeout?: number;                  // Override default timeout
  cancelToken?: CancellationToken;   // Support cancellation
  priority?: "normal" | "high";      // Queue priority
}

// Implementation uses Worker threads (Node.js) or Web Workers (browser)
// Each plugin is isolated in its own worker with its own memory heap

class WorkerHandleImpl implements WorkerHandle {
  private worker: Worker;
  private pendingCalls = new Map<string, PendingCall>();
  private eventListeners = new Map<string, Set<EventListener>>();
  private callId = 0;

  constructor(
    scriptPath: string,
    private limits: ResourceLimits
  ) {
    this.worker = new Worker(scriptPath, {
      resourceLimits: {
        maxOldGenerationSizeMb: limits.memoryPerPlugin / 1024 / 1024,
      }
    });

    this.worker.on("message", (msg) => this.handleMessage(msg));
    this.worker.on("error", (error) => this.handleError(error));
    this.worker.on("exit", (code) => this.handleExit(code));
  }

  async invoke(
    method: string,
    params: unknown,
    options?: InvokeOptions
  ): Promise<unknown> {
    const id = String(this.callId++);
    const timeout = options?.timeout || this.limits.callTimeout;

    const call: PendingCall = {
      id,
      method,
      startTime: Date.now(),
      promise: new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          this.pendingCalls.delete(id);
          reject(new TimeoutError(`Call to ${method} exceeded ${timeout}ms`));
        }, timeout);

        call.resolve = (value) => {
          clearTimeout(timer);
          resolve(value);
        };

        call.reject = (error) => {
          clearTimeout(timer);
          reject(error);
        };
      })
    };

    this.pendingCalls.set(id, call);

    // Send message to worker
    this.worker.postMessage({
      type: "invoke",
      id,
      method,
      params
    });

    return call.promise;
  }

  private handleMessage(msg: any) {
    if (msg.type === "result") {
      const call = this.pendingCalls.get(msg.id);
      if (call) {
        this.pendingCalls.delete(msg.id);
        const duration = Date.now() - call.startTime;

        if (msg.error) {
          call.reject!(new PluginError(msg.error.message, msg.error.stack));
        } else {
          call.resolve!(msg.result);
        }

        // Record metrics
        this.recordMetrics(call.method, duration, !msg.error);
      }
    } else if (msg.type === "event") {
      const listeners = this.eventListeners.get(msg.event) || new Set();
      for (const listener of listeners) {
        listener(msg.data);
      }
    }
  }

  private handleError(error: Error) {
    // Reject all pending calls
    for (const [id, call] of this.pendingCalls) {
      call.reject!(new WorkerError(`Worker crashed: ${error.message}`));
    }
    this.pendingCalls.clear();
  }

  async terminate(): Promise<void> {
    await this.worker.terminate();
  }
}
```

