### Crash Isolation & Recovery

```typescript
// If a plugin crashes, it doesn't take down the host or other plugins

class CrashIsolationManager {
  async executeWithRecovery<T>(
    handle: PluginHandle,
    method: string,
    params: unknown
  ): Promise<T> {
    try {
      return await handle.invoke(method, params) as T;
    } catch (error) {
      if (error instanceof WorkerError && error.isCrash) {
        // Plugin worker crashed

        // 1. Log the crash with full context
        this.logger.error("Plugin worker crashed", {
          pluginId: handle.id,
          method,
          error: error.message,
          stack: error.stack
        });

        // 2. Update health status
        this.registry.getState(handle.id).health = {
          status: "failed",
          error: error.message
        };

        // 3. Try to restart worker
        try {
          await this.registry.reload(handle.id);
          this.logger.info("Plugin restarted after crash", { 
            pluginId: handle.id 
          });
        } catch (restartError) {
          this.logger.error("Plugin restart failed", {
            pluginId: handle.id,
            error: restartError.message
          });
          throw new PluginCrashError(handle.id, error);
        }

        // 4. Retry the call (once)
        try {
          return await handle.invoke(method, params) as T;
        } catch (retryError) {
          throw new PluginRecoveryFailedError(handle.id, retryError);
        }
      }

      throw error;
    }
  }
}
