## API Contract & Versioning

The plugin API is versioned to allow evolution without breaking existing plugins.

### API Versioning Strategy

```typescript
// Plugin declares which API version it targets
// Host can run multiple API versions simultaneously

interface PluginManifest {
  apiVersion: "1.0";      // Strictly semantic versioning
  // ...
}

// API versions follow these rules:
// - MAJOR: Breaking changes, old plugins cannot run
// - MINOR: Additive changes, old plugins still work
// - PATCH: Bug fixes, no behavioral changes

// Example evolution:
// 1.0.0 - Initial release
//   ├─ Core Host API
//   └─ Plugin lifecycle
//
// 1.1.0 - Add plugin messaging, backwards compatible
//   ├─ Core Host API (unchanged)
//   ├─ Plugin messaging (new)
//   └─ Plugin lifecycle (unchanged)
//
// 2.0.0 - Redesign Host API, NOT backwards compatible
//   ├─ New Host API structure
//   ├─ Old 1.x plugins cannot load
//   └─ Migration guide provided

type APIVersion = "1.0" | "1.1" | "2.0";

// Host maintains compatibility layer
class APIRouter {
  private handlers: Map<APIVersion, HostAPI> = new Map([
    ["1.0", new HostAPIv1_0()],
    ["1.1", new HostAPIv1_1()],
    ["2.0", new HostAPIv2_0()],
  ]);

  getAPI(version: string): HostAPI {
    const handler = this.handlers.get(version as APIVersion);
    if (!handler) {
      throw new Error(`Unsupported API version: ${version}`);
    }
    return handler;
  }
}
