### API v1.0 Contract (Stable)

```typescript
// This is what plugins build against
// Every plugin implementing this contract is guaranteed to work

namespace PluginAPI_v1_0 {
  export interface HostAPI {
    // ─── LIFECYCLE ──────────────────────────────────────
    version: "1.0";

    // ─── LOGGING ────────────────────────────────────────
    logger: {
      info(message: string, context?: Record<string, any>): void;
      warn(message: string, context?: Record<string, any>): void;
      error(message: string, context?: Record<string, any>): void;
      debug(message: string, context?: Record<string, any>): void;
    };

    // ─── CONFIGURATION ──────────────────────────────────
    config: {
      // Get config value
      get<T = unknown>(path: string, defaultValue?: T): T;

      // Subscribe to config changes
      onChange(
        path: string,
        listener: (newValue: unknown, oldValue: unknown) => void
      ): () => void;
    };

    // ─── STORAGE (plugin-specific, isolated) ──────────
    storage: {
      get<T = unknown>(key: string): Promise<T | null>;
      set<T = unknown>(key: string, value: T): Promise<void>;
      delete(key: string): Promise<void>;
      list(pattern?: string): Promise<string[]>;
      clear(): Promise<void>;
    };

    // ─── QUERYING & DATA ACCESS ────────────────────────
    data: {
      // Execute a query against configured data sources
      query(
        source: string,
        query: string,
        params?: Record<string, unknown>
      ): Promise<QueryResult>;

      // Write data to a data source
      write(
        source: string,
        table: string,
        rows: Record<string, unknown>[]
      ): Promise<{ rowsWritten: number }>;
    };

    // ─── REPORTING ──────────────────────────────────────
    reports: {
      // Render a report from a specification
      render(spec: ReportSpec): Promise<RenderedReport>;

      // Schedule a report for periodic execution
      schedule(
        reportId: string,
        spec: ReportSpec,
        schedule: CronExpression
      ): Promise<void>;
    };

    // ─── EVENTS & MESSAGING ─────────────────────────────
    // Plugins can only message other plugins that declared capability
    messaging: {
      send(
        targetPluginId: string,
        method: string,
        params: unknown
      ): Promise<unknown>;
    };
  }

  export interface QueryResult {
    rows: Record<string, unknown>[];
    columns: ColumnMetadata[];
    rowCount: number;
    executionTime: number;  // milliseconds
  }

  export interface ReportSpec {
    title: string;
    description?: string;
    sections: ReportSection[];
    parameters?: Parameter[];
  }

  export interface ReportSection {
    title: string;
    type: "table" | "chart" | "metric" | "text";
    dataSource?: string;
    query?: string;
    visualization?: VisualizationConfig;
  }

  export interface RenderedReport {
    id: string;
    title: string;
    generatedAt: Date;
    sections: RenderedSection[];
    metadata: Record<string, unknown>;
  }
}

// Plugins import and use this contract
import { HostAPI } from "reporting-tool-plugin-api/v1.0";

export class MyPlugin {
  async generateReport(
    hostApi: HostAPI,
    params: ReportParams
  ): Promise<Report> {
    hostApi.logger.info("Generating report", { params });

    const data = await hostApi.data.query(
      "analytics",
      "SELECT * FROM events WHERE date >= ?",
      [params.startDate]
    );

    return hostApi.reports.render({
      title: "Analytics Report",
      sections: [{
        type: "table",
        title: "Events",
        // data from query above
      }]
    });
  }
}
