### Minimal Plugin Example

```typescript
// src/index.ts
import { HostAPI } from "reporting-tool-plugin-api/v1.0";

let hostApi: HostAPI;
let config: MyConfig;

// ─── Lifecycle Hooks ────────────────────────────────────

export async function __setup__(
  cfg: unknown,
  api: HostAPI
): Promise<void> {
  config = validateConfig(cfg);
  hostApi = api;

  hostApi.logger.info("My Plugin loaded", { 
    version: "1.0.0" 
  });
}

export async function __teardown__(reason: string): Promise<void> {
  hostApi.logger.info("My Plugin unloading", { reason });
}

export async function __health__() {
  return { healthy: true };
}

// ─── Plugin Methods (exported to host) ──────────────────

export interface ReportParams {
  startDate: string;
  endDate: string;
}

export async function generateReport(
  params: ReportParams
): Promise<RenderedReport> {
  hostApi.logger.info("Generating report", { 
    startDate: params.startDate,
    endDate: params.endDate
  });

  // Query data via host API
  const result = await hostApi.data.query(
    "analytics",
    "SELECT count(*) as total FROM events WHERE date BETWEEN ? AND ?",
    [params.startDate, params.endDate]
  );

  // Render report via host API
  return hostApi.reports.render({
    title: "Analytics Report",
    description: "Report of events",
    sections: [
      {
        type: "metric",
        title: "Total Events",
        // Include data from result
      }
    ]
  });
}

// Configuration validation
interface MyConfig {
  logLevel: "debug" | "info" | "warn" | "error";
}

function validateConfig(cfg: unknown): MyConfig {
  if (typeof cfg !== "object" || cfg === null) {
    throw new Error("Invalid config");
  }

  const obj = cfg as Record<string, unknown>;
  if (!["debug", "info", "warn", "error"].includes(obj.logLevel as string)) {
    throw new Error("Invalid logLevel");
  }

  return cfg as MyConfig;
}
