## Error Handling & Observability

### Error Hierarchy

```typescript
// All errors inherit from base PluginError
abstract class PluginError extends Error {
  constructor(
    public pluginId: string,
    message: string,
    public code: string,
    public context?: Record<string, unknown>
  ) {
    super(message);
  }
}

// Lifecycle errors
class PluginInitError extends PluginError {
  constructor(pluginId: string, cause: Error) {
    super(pluginId, `Failed to initialize: ${cause.message}`, "INIT_FAILED", {
      cause: cause.message,
      stack: cause.stack,
    });
  }
}

class PluginLoadError extends PluginError {
  constructor(pluginId: string, cause: Error) {
    super(pluginId, `Failed to load: ${cause.message}`, "LOAD_FAILED");
  }
}

class PluginUnloadError extends PluginError {
  constructor(pluginId: string, cause: Error) {
    super(pluginId, `Failed to unload: ${cause.message}`, "UNLOAD_FAILED");
  }
}

// Execution errors
class PluginTimeoutError extends PluginError {
  constructor(
    pluginId: string,
    public method: string,
    public timeout: number
  ) {
    super(
      pluginId,
      `Method ${method} exceeded timeout of ${timeout}ms`,
      "TIMEOUT",
      { method, timeout }
    );
  }
}

class PluginCrashError extends PluginError {
  constructor(
    pluginId: string,
    public cause: Error
  ) {
    super(
      pluginId,
      `Plugin worker crashed: ${cause.message}`,
      "CRASH",
      { cause: cause.message }
    );
  }
}

// Resource errors
class ResourceLimitExceededError extends PluginError {
  constructor(
    pluginId: string,
    public resource: "memory" | "cpu" | "time",
    public limit: number,
    public used: number
  ) {
    super(
      pluginId,
      `${resource} limit exceeded: ${used} > ${limit}`,
      "RESOURCE_LIMIT",
      { resource, limit, used }
    );
  }
}

// Dependency errors
class MissingDependencyError extends PluginError {
  constructor(pluginId: string, missingPluginId: string, version: string) {
    super(
      pluginId,
      `Missing dependency: ${missingPluginId}@${version}`,
      "MISSING_DEPENDENCY",
      { missingPluginId, version }
    );
  }
}

// API errors
class APIVersionMismatchError extends PluginError {
  constructor(
    pluginId: string,
    public pluginApiVersion: string,
    public hostApiVersion: string
  ) {
    super(
      pluginId,
      `API mismatch: plugin wants ${pluginApiVersion}, host has ${hostApiVersion}`,
      "API_MISMATCH",
      { pluginApiVersion, hostApiVersion }
    );
  }
}
