// Metrics collection
interface PluginMetrics {
  callCount: number;
  errorCount: number;
  totalDuration: number;
  avgDuration: number;
  maxDuration: number;
  peakMemory: number;
  currentMemory: number;
  uptime: number;
  lastError?: { message: string; timestamp: Date };
}

class MetricsCollector {
  private metrics = new Map<string, PluginMetrics>();

  recordCall(
    pluginId: string,
    method: string,
    duration: number,
    success: boolean,
    error?: Error
  ) {
    let m = this.metrics.get(pluginId) || defaultMetrics();

    m.callCount++;
    m.totalDuration += duration;
    m.avgDuration = m.totalDuration / m.callCount;
    m.maxDuration = Math.max(m.maxDuration, duration);

    if (!success) {
      m.errorCount++;
      m.lastError = {
        message: error?.message || "Unknown error",
        timestamp: new Date(),
      };
    }

    this.metrics.set(pluginId, m);
  }

  recordMemory(pluginId: string, bytes: number) {
    const m = this.metrics.get(pluginId) || defaultMetrics();
    m.peakMemory = Math.max(m.peakMemory, bytes);
    m.currentMemory = bytes;
    this.metrics.set(pluginId, m);
  }
}

// Health checks
class HealthMonitor {
  private lastCheck = new Map<string, HealthCheckResult>();

  async checkAll(registry: PluginRegistry) {
    for (const info of registry.list()) {
      try {
        const result = await info.handle?.invoke("__health__", []);
        this.lastCheck.set(info.id, result);

        if (!result.healthy) {
          this.logger.warn("Plugin unhealthy", {
            pluginId: info.id,
            issues: result.issues,
          });
        }
      } catch (error) {
        this.logger.error("Health check failed", {
          pluginId: info.id,
          error: error.message,
        });
      }
    }
  }
}
