## Plugin Registry

The registry is the single source of truth for all active plugins and their state.

### Registry Interface

```typescript
// Core registry API exposed to the host
interface PluginRegistry {
  // Discovery & Metadata
  list(): PluginInfo[];
  get(id: string): PluginInfo | null;
  search(criteria: SearchCriteria): PluginInfo[];

  // Lifecycle
  load(manifest: PluginManifest): Promise<PluginHandle>;
  unload(id: string): Promise<void>;
  reload(id: string): Promise<void>;

  // State Management
  getState(id: string): PluginState;
  setState(id: string, state: PluginState): void;

  // Dependencies
  resolveDependencies(id: string): PluginInfo[];
  checkCompatibility(manifest: PluginManifest): CompatibilityReport;

  // Monitoring
  subscribe(listener: RegistryListener): Unsubscribe;
  getMetrics(id: string): PluginMetrics;
}

// Plugin metadata stored in registry
interface PluginInfo {
  id: string;
  version: string;
  name: string;
  description: string;
  author: string;
  capabilities: string[];          // e.g. ["data-source", "visualizer"]
  dependencies: PluginDependency[];
  apiVersion: string;               // e.g. "1.0", "1.1"
  entrypoint: string;               // path to worker module
  config: PluginConfigSchema;
  health: PluginHealth;
  loadedAt?: Date;
  handle?: PluginHandle;
}

interface PluginDependency {
  pluginId: string;
  version: string;                  // semver range: "^1.0.0"
  optional: boolean;
}

interface PluginHealth {
  status: "healthy" | "degraded" | "failed" | "initializing";
  lastCheck: Date;
  error?: string;
  workerUptime?: number;
}

interface PluginMetrics {
  callCount: number;
  errorCount: number;
  avgDuration: number;
  peakMemory: number;
  lastError?: { message: string; timestamp: Date };
}

interface PluginHandle {
  id: string;
  invoke(method: string, params: unknown): Promise<unknown>;
  close(): Promise<void>;
}

// Events emitted by registry
interface RegistryListener {
  onPluginLoaded?(info: PluginInfo): void;
  onPluginUnloaded?(id: string): void;
  onPluginFailed?(id: string, error: Error): void;
  onStateChanged?(id: string, state: PluginState): void;
}

interface SearchCriteria {
  capability?: string;
  author?: string;
  status?: PluginState;
}
