## Plugin Registry

### Registry Data Structure

```typescript
interface PluginMetadata {
  id: string;
  name: string;
  version: string;
  state: "unloaded" | "loaded" | "failed" | "disabled";
  manifest: PluginManifest;
  lastModified: number;
  loadedAt?: number;
  error?: PluginError;
  instance?: PluginInstance;
  dependencies: DependencyInfo[];
}

interface PluginRegistry {
  // Discovery
  discover(searchPaths: string[]): Promise<PluginMetadata[]>;

  // Lookup
  get(id: string): PluginMetadata | null;
  getByVersion(id: string, versionRange: string): PluginMetadata | null;
  getAll(): PluginMetadata[];
  find(predicate: (m: PluginMetadata) => boolean): PluginMetadata[];

  // Metadata operations
  register(metadata: PluginMetadata): void;
  update(id: string, updates: Partial<PluginMetadata>): void;
  remove(id: string): void;

  // State queries
  getLoaded(): PluginMetadata[];
  getFailed(): PluginMetadata[];
  getDisabled(): PluginMetadata[];

  // Dependency resolution
  resolveDependencies(id: string): PluginMetadata[];
  validateDependencies(id: string): ValidationResult;

  // Events
  on(event: RegistryEvent, handler: EventHandler): Unsubscribe;
  emit(event: RegistryEvent): void;
}

interface RegistryEvent {
  type: "plugin:discovered" | "plugin:loaded" | "plugin:failed" | 
         "plugin:unloaded" | "plugin:reloaded" | "registry:initialized";
  pluginId?: string;
  timestamp: number;
  metadata?: any;
}
```

### Registry Implementation

```typescript
class PluginRegistryImpl implements PluginRegistry {
  private plugins = new Map<string, PluginMetadata>();
  private versioned = new Map<string, PluginMetadata[]>(); // id -> [versions]
  private listeners = new Map<string, Set<EventHandler>>();
  private cache: RegistryCache;

  async discover(searchPaths: string[]): Promise<PluginMetadata[]> {
    const discovered: PluginMetadata[] = [];

    for (const path of searchPaths) {
      const manifests = await this.scanDirectory(path);
      for (const manifest of manifests) {
        try {
          this.validateManifest(manifest);
          const metadata: PluginMetadata = {
            id: manifest.id,
            name: manifest.name,
            version: manifest.version,
            state: "unloaded",
            manifest,
            lastModified: Date.now(),
            dependencies: await this.resolveDeps(manifest),
          };

          discovered.push(metadata);
          this.register(metadata);
          this.emit({
            type: "plugin:discovered",
            pluginId: manifest.id,
            timestamp: Date.now(),
            metadata,
          });
        } catch (error) {
          this.handleDiscoveryError(manifest, error);
        }
      }
    }

    return discovered;
  }

  register(metadata: PluginMetadata): void {
    this.plugins.set(metadata.id, metadata);

    if (!this.versioned.has(metadata.id)) {
      this.versioned.set(metadata.id, []);
    }
    this.versioned.get(metadata.id)!.push(metadata);

    // Keep versions sorted by semver
    this.versioned.get(metadata.id)!.sort((a, b) =>
      compareSemver(a.version, b.version)
    );

    this.cache.invalidate(metadata.id);
  }

  getByVersion(id: string, versionRange: string): PluginMetadata | null {
    const versions = this.versioned.get(id);
    if (!versions) return null;

    return versions.find(v =>
      semverSatisfies(v.version, versionRange)
    ) || null;
  }

  resolveDependencies(id: string): PluginMetadata[] {
    const metadata = this.get(id);
    if (!metadata) return [];

    const resolved: PluginMetadata[] = [];
    const visited = new Set<string>();

    const traverse = (depId: string) => {
      if (visited.has(depId)) return;
      visited.add(depId);

      const dep = this.get(depId);
      if (!dep) throw new Error(`Dependency not found: ${depId}`);

      resolved.push(dep);
      dep.dependencies.forEach(d => traverse(d.id));
    };

    metadata.dependencies.forEach(d => traverse(d.id));
    return resolved;
  }

  validateDependencies(id: string): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];
    const metadata = this.get(id);

    if (!metadata) {
      return { valid: false, errors: ["Plugin not found"], warnings: [] };
    }

    // Check all dependencies exist
    for (const dep of metadata.dependencies) {
      const depMeta = this.getByVersion(dep.id, dep.versionRange);
      if (!depMeta) {
        errors.push(
          `Dependency "${dep.id}@${dep.versionRange}" not satisfied`
        );
      } else if (depMeta.state === "failed") {
        errors.push(`Dependency "${dep.id}" is in failed state`);
      } else if (depMeta.state === "disabled") {
        warnings.push(`Dependency "${dep.id}" is disabled`);
      }
    }

    // Check for circular dependencies
    const visited = new Set<string>();
    const detectCycle = (id: string, path: string[]): string | null => {
      if (visited.has(id)) {
        return `${path.join(" -> ")} -> ${id}`;
      }
      visited.add(id);

      const meta = this.get(id);
      if (!meta) return null;

      for (const dep of meta.dependencies) {
        const cycle = detectCycle(dep.id, [...path, id]);
        if (cycle) return cycle;
      }

      return null;
    };

    const cycle = detectCycle(id, []);
    if (cycle) {
      errors.push(`Circular dependency detected: ${cycle}`);
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
    };
  }

  on(event: string, handler: EventHandler): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(handler);

    return () => {
      this.listeners.get(event)?.delete(handler);
    };
  }

  private emit(event: RegistryEvent): void {
    const handlers = this.listeners.get(event.type);
    if (handlers) {
      for (const handler of handlers) {
        try {
          handler(event);
        } catch (error) {
          console.error(`Error in registry event handler: ${error}`);
        }
      }
    }
  }
}
```

