## Lifecycle Management

### Lifecycle State Machine

```
    [Unloaded]
         ↓ load()
    [Loading] → [Loaded]
         ↓ error     ↓ reload()
    [Failed]    [Reloading] → [Loaded]
         ↓        ↓ error
    (error state) [Failed]
         ↓          ↓
      unload()  (error recovery)
         ↓          ↓
    [Unloaded]  [Unloaded]
```

### Lifecycle Manager Interface

```typescript
interface LifecycleHook {
  onLoad?(context: PluginContext): Promise<void>;
  onUnload?(context: PluginContext): Promise<void>;
  onReload?(context: PluginContext): Promise<void>;
  onError?(error: PluginError, context: PluginContext): Promise<void>;
  onConfigChange?(newConfig: any, context: PluginContext): Promise<void>;
}

interface PluginContext {
  pluginId: string;
  version: string;
  config: any;
  logger: Logger;
  hostAPI: HostAPI;
  state: Map<string, any>; // Plugin-scoped state
}

interface LifecycleManager {
  // Load/unload operations
  load(id: string, config?: any): Promise<PluginInstance>;
  unload(id: string): Promise<void>;
  reload(id: string, config?: any): Promise<PluginInstance>;

  // Batch operations
  loadMany(ids: string[]): Promise<LoadResult[]>;
  unloadMany(ids: string[]): Promise<void>;

  // State queries
  getState(id: string): PluginState;
  getContext(id: string): PluginContext | null;

  // Configuration
  updateConfig(id: string, config: any): Promise<void>;
  getConfig(id: string): any;

  // Hooks
  registerHook(id: string, hook: LifecycleHook): void;

  // Events
  on(event: LifecycleEvent, handler: EventHandler): Unsubscribe;

  // Diagnostics
  getDiagnostics(id: string): PluginDiagnostics;
  dump(): LifecycleState;
}

interface PluginInstance {
  id: string;
  version: string;
  exports: Record<string, any>;
  context: PluginContext;
  manifest: PluginManifest;
}

interface LifecycleEvent {
  type: "lifecycle:load" | "lifecycle:unload" | "lifecycle:reload" |
         "lifecycle:error" | "lifecycle:config-change" | "lifecycle:timeout";
  pluginId: string;
  timestamp: number;
  duration?: number;
  error?: PluginError;
  metadata?: any;
}
```

### Lifecycle Manager Implementation

```typescript
class LifecycleManagerImpl implements LifecycleManager {
  private instances = new Map<string, PluginInstance>();
  private states = new Map<string, PluginState>();
  private hooks = new Map<string, LifecycleHook>();
  private listeners = new Map<string, Set<EventHandler>>();
  private contexts = new Map<string, PluginContext>();
  private loader: PluginLoader;
  private sandbox: SandboxEnvironment;

  async load(id: string, config?: any): Promise<PluginInstance> {
    const metadata = this.registry.get(id);
    if (!metadata) throw new PluginError(`Plugin not found: ${id}`);

    if (this.states.get(id) === "loaded") {
      return this.instances.get(id)!;
    }

    this.setState(id, "loading");
    const startTime = Date.now();

    try {
      // Validate dependencies
      const depValidation = this.registry.validateDependencies(id);
      if (!depValidation.valid) {
        throw new DependencyError(depValidation.errors.join("; "));
      }

      // Load dependencies first
      const deps = this.registry.resolveDependencies(id);
      for (const dep of deps) {
        if (this.states.get(dep.id) !== "loaded") {
          await this.load(dep.id);
        }
      }

      // Merge configs
      const finalConfig = {
        ...metadata.manifest.config?.defaults,
        ...config,
      };

      // Validate config
      if (metadata.manifest.config?.schema) {
        validateSchema(finalConfig, metadata.manifest.config.schema);
      }

      // Create context
      const context: PluginContext = {
        pluginId: id,
        version: metadata.version,
        config: finalConfig,
        logger: this.createLogger(id),
        hostAPI: this.createHostAPI(id, metadata),
        state: new Map(),
      };

      this.contexts.set(id, context);

      // Load module
      const module = await this.loader.load(
        metadata.manifest.entryPoint,
        {
          apiVersion: metadata.manifest.apiVersion,
          capabilities: metadata.manifest.capabilities,
          sandboxLevel: metadata.manifest.permissions.sandboxLevel,
        }
      );

      // Create instance
      const instance: PluginInstance = {
        id,
        version: metadata.version,
        exports: module.exports,
        context,
        manifest: metadata.manifest,
      };

      this.instances.set(id, instance);

      // Call onLoad hook
      const hook = this.hooks.get(id);
      if (hook?.onLoad) {
        await this.executeWithTimeout(
          () => hook.onLoad!(context),
          metadata.manifest.permissions.timeoutMs
        );
      }

      this.setState(id, "loaded");
      this.emit({
        type: "lifecycle:load",
        pluginId: id,
        timestamp: Date.now(),
        duration: Date.now() - startTime,
      });

      return instance;
    } catch (error) {
      this.setState(id, "failed");
      this.emit({
        type: "lifecycle:error",
        pluginId: id,
        timestamp: Date.now(),
        error: this.wrapError(error),
      });
      throw error;
    }
  }

  async unload(id: string): Promise<void> {
    const instance = this.instances.get(id);
    if (!instance) return;

    this.setState(id, "unloading");
    const startTime = Date.now();

    try {
      // Call onUnload hook
      const hook = this.hooks.get(id);
      if (hook?.onUnload) {
        const context = this.contexts.get(id)!;
        await this.executeWithTimeout(
          () => hook.onUnload!(context),
          instance.manifest.permissions.timeoutMs
        );
      }

      // Clean up
      this.instances.delete(id);
      this.contexts.delete(id);

      this.setState(id, "unloaded");
      this.emit({
        type: "lifecycle:unload",
        pluginId: id,
        timestamp: Date.now(),
        duration: Date.now() - startTime,
      });
    } catch (error) {
      this.setState(id, "failed");
      throw error;
    }
  }

  async reload(id: string, config?: any): Promise<PluginInstance> {
    await this.unload(id);
    return this.load(id, config);
  }

  async updateConfig(id: string, config: any): Promise<void> {
    const context = this.contexts.get(id);
    if (!context) throw new Error(`Plugin not loaded: ${id}`);

    const metadata = this.registry.get(id);
    if (!metadata) throw new Error(`Plugin not found: ${id}`);

    // Validate new config
    if (metadata.manifest.config?.schema) {
      validateSchema(config, metadata.manifest.config.schema);
    }

    const oldConfig = context.config;
    context.config = config;

    try {
      const hook = this.hooks.get(id);
      if (hook?.onConfigChange) {
        await this.executeWithTimeout(
          () => hook.onConfigChange!(config, context),
          metadata.manifest.permissions.timeoutMs
        );
      }

      this.emit({
        type: "lifecycle:config-change",
        pluginId: id,
        timestamp: Date.now(),
        metadata: { oldConfig, newConfig: config },
      });
    } catch (error) {
      context.config = oldConfig; // Rollback
      throw error;
    }
  }

  getDiagnostics(id: string): PluginDiagnostics {
    const metadata = this.registry.get(id);
    const instance = this.instances.get(id);
    const context = this.contexts.get(id);

    return {
      id,
      state: this.states.get(id) || "unknown",
      version: metadata?.version,
      manifest: metadata?.manifest,
      loadedAt: instance ? Date.now() : null,
      uptime: instance ? Date.now() - (instance as any).loadedAt : 0,
      dependencies: metadata?.dependencies || [],
      config: context?.config,
      exportedNames: instance ? Object.keys(instance.exports) : [],
      errors: metadata?.error ? [metadata.error] : [],
    };
  }

  private setState(id: string, state: PluginState): void {
    this.states.set(id, state);
    if (state === "failed") {
      // Keep failed state until explicitly unloaded
    }
  }

  private async executeWithTimeout<T>(
    fn: () => Promise<T>,
    timeoutMs: number
  ): Promise<T> {
    return Promise.race([
      fn(),
      new Promise<T>((_, reject) =>
        setTimeout(
          () => reject(new TimeoutError(`Operation exceeded ${timeoutMs}ms`)),
          timeoutMs
        )
      ),
    ]);
  }

  private emit(event: LifecycleEvent): void {
    const handlers = this.listeners.get(event.type);
    if (handlers) {
      for (const handler of handlers) {
        try {
          handler(event);
        } catch (error) {
          console.error(`Error in lifecycle event handler: ${error}`);
        }
      }
    }
  }
}
```

