## Sandboxed Execution

### Sandbox Model

Plugins execute in isolated contexts with restricted capabilities:

```typescript
interface SandboxEnvironment {
  // Module isolation
  createModuleContext(pluginId: string, manifest: PluginManifest): ModuleContext;

  // Capability enforcement
  grantCapability(pluginId: string, capability: string): void;
  revokeCapability(pluginId: string, capability: string): void;
  hasCapability(pluginId: string, capability: string): boolean;

  // Resource limits
  setMemoryLimit(pluginId: string, limitMb: number): void;
  setTimeoutLimit(pluginId: string, timeoutMs: number): void;

  // Network control
  restrictNetwork(pluginId: string, allowlist: string[]): void;

  // Filesystem isolation
  isolateFilesystem(pluginId: string, allowedPaths: string[]): void;
}

interface ModuleContext {
  pluginId: string;
  // Minimal globals - no access to:
  // - require() (except whitelisted modules)
  // - import.meta
  // - process (except .env whitelisted vars)
  // - global object

  // Only accessible:
  // - hostAPI (restricted interface)
  // - console (logging, limited)
  // - standard globals (Math, JSON, etc.)
  // - setTimeout/setInterval (with limits)
}

enum SandboxLevel {
  STRICT = "strict",      // Minimal access, tight restrictions
  MODERATE = "moderate",  // Balanced, production default
  PERMISSIVE = "permissive" // Trusting plugins, internal use
}

interface CapabilityToken {
  capability: string;
  pluginId: string;
  grantedAt: number;
  expiresAt?: number; // TTL-based revocation
  metadata?: Record<string, any>;
}
```

### Sandbox Implementation Strategy

```typescript
class SandboxEnvironmentImpl implements SandboxEnvironment {
  private capabilities = new Map<string, Set<string>>(); // pluginId -> capabilities
  private tokenStore = new Map<string, CapabilityToken[]>();
  private resourceMonitor: ResourceMonitor;
  private sandboxLevels = new Map<string, SandboxLevel>();

  createModuleContext(
    pluginId: string,
    manifest: PluginManifest
  ): ModuleContext {
    const capabilities = new Set(manifest.capabilities);
    const sandboxLevel = manifest.permissions.sandboxLevel as SandboxLevel;

    this.capabilities.set(pluginId, capabilities);
    this.sandboxLevels.set(pluginId, sandboxLevel);

    // Create restricted global object
    const moduleGlobals = this.buildRestrictedGlobals(
      pluginId,
      capabilities,
      sandboxLevel
    );

    return {
      pluginId,
      ...moduleGlobals,
    };
  }

  private buildRestrictedGlobals(
    pluginId: string,
    capabilities: Set<string>,
    level: SandboxLevel
  ): Record<string, any> {
    // Base globals always available
    const globals = {
      console: this.createRestrictedConsole(pluginId),
      Math,
      JSON,
      Array,
      Object,
      String,
      Number,
      Boolean,
      Date,
      RegExp,
      Promise,
      Map,
      Set,
      WeakMap,
      WeakSet,
      Symbol,
      Error,
      TypeError,
      RangeError,
      setTimeout: this.createRestrictedTimeout(pluginId),
      setInterval: this.createRestrictedInterval(pluginId),
      clearTimeout,
      clearInterval,
    };

    // Conditionally add based on capabilities and sandbox level
    if (level !== SandboxLevel.STRICT) {
      if (capabilities.has("network:http")) {
        globals.fetch = this.createRestrictedFetch(pluginId, level);
      }
      if (capabilities.has("storage:temp")) {
        globals.tmpStorage = this.createTempStorage(pluginId);
      }
      if (capabilities.has("system:logging")) {
        globals.Logger = this.createLogger(pluginId);
      }
    }

    return globals;
  }

  private createRestrictedConsole(pluginId: string) {
    // Log with plugin context
    return {
      log: (...args: any[]) => console.log(`[${pluginId}]`, ...args),
      warn: (...args: any[]) => console.warn(`[${pluginId}]`, ...args),
      error: (...args: any[]) => console.error(`[${pluginId}]`, ...args),
      info: (...args: any[]) => console.info(`[${pluginId}]`, ...args),
      debug: (...args: any[]) => console.debug(`[${pluginId}]`, ...args),
      // Prevent access to other console methods
    };
  }

  private createRestrictedFetch(pluginId: string, level: SandboxLevel) {
    return async (url: string, options?: RequestInit) => {
      // Check capabilities
      if (!this.hasCapability(pluginId, "network:http")) {
        throw new Error("network:http capability required");
      }

      // Validate URL against allowlist
      const manifest = this.getManifest(pluginId);
      const allowlist = manifest.permissions.networkAllowlist || [];
      if (!this.urlMatchesAllowlist(url, allowlist)) {
        throw new Error(
          `URL ${url} not in network allowlist for ${pluginId}`
        );
      }

      // Monitor request
      this.resourceMonitor.trackNetworkRequest(pluginId, url);

      try {
        return await fetch(url, {
          ...options,
          // Force safe options
          mode: "cors",
          credentials: "omit", // No cookies
        });
      } catch (error) {
        this.resourceMonitor.trackNetworkError(pluginId, url, error);
        throw error;
      }
    };
  }

  private createRestrictedTimeout(pluginId: string) {
    return (callback: () => void, delay: number) => {
      const manifest = this.getManifest(pluginId);
      const maxDelay = manifest.permissions.timeoutMs;

      if (delay > maxDelay) {
        throw new Error(
          `Timeout ${delay}ms exceeds limit ${maxDelay}ms for ${pluginId}`
        );
      }

      return setTimeout(() => {
        this.resourceMonitor.trackExecutionTime(pluginId);
        try {
          callback();
        } catch (error) {
          console.error(`Error in ${pluginId} timeout callback:`, error);
        }
      }, delay);
    };
  }

  grantCapability(pluginId: string, capability: string): void {
    if (!this.capabilities.has(pluginId)) {
      this.capabilities.set(pluginId, new Set());
    }
    this.capabilities.get(pluginId)!.add(capability);

    // Create token
    const token: CapabilityToken = {
      capability,
      pluginId,
      grantedAt: Date.now(),
    };

    if (!this.tokenStore.has(pluginId)) {
      this.tokenStore.set(pluginId, []);
    }
    this.tokenStore.get(pluginId)!.push(token);
  }

  hasCapability(pluginId: string, capability: string): boolean {
    const caps = this.capabilities.get(pluginId);
    return !!caps?.has(capability);
  }
}

class ResourceMonitor {
  private resourceUsage = new Map<string, ResourceMetrics>();
  private limits: ResourceLimits;

  trackExecutionTime(pluginId: string): void {
    const metrics = this.getMetrics(pluginId);
    metrics.totalExecutionTime += Date.now() - metrics.lastCheckpoint;
    metrics.lastCheckpoint = Date.now();
  }

  trackNetworkRequest(pluginId: string, url: string): void {
    const metrics = this.getMetrics(pluginId);
    metrics.networkRequests++;
    metrics.lastNetworkUrl = url;
  }

  trackMemoryUsage(pluginId: string, bytes: number): void {
    const metrics = this.getMetrics(pluginId);
    metrics.memoryUsed = Math.max(metrics.memoryUsed, bytes);

    // Enforce limit
    const manifest = this.getManifest(pluginId);
    if (metrics.memoryUsed > manifest.permissions.memoryLimitMb * 1024 * 1024) {
      throw new OutOfMemoryError(
        `${pluginId} exceeded memory limit: ${metrics.memoryUsed} bytes`
      );
    }
  }

  private getMetrics(pluginId: string): ResourceMetrics {
    if (!this.resourceUsage.has(pluginId)) {
      this.resourceUsage.set(pluginId, {
        totalExecutionTime: 0,
        lastCheckpoint: Date.now(),
        networkRequests: 0,
        memoryUsed: 0,
        lastNetworkUrl: null,
      });
    }
    return this.resourceUsage.get(pluginId)!;
  }
}
