## API Versioning Contract

### Host API Versioning Strategy

Plugins declare required API versions in manifest. The host provides versioned APIs that guarantee:
- **Patch (1.0.x)**: Bug fixes, no breaking changes
- **Minor (1.x.0)**: New features, backwards compatible
- **Major (x.0.0)**: Breaking changes

```typescript
interface HostAPI {
  // Read-only query operations
  query: QueryAPI;

  // Report operations
  report: ReportAPI;

  // Rendering/formatting
  render: RenderAPI;

  // Authentication context
  auth: AuthAPI;

  // Logging
  logger: Logger;

  // Plugin-to-plugin communication
  hooks: HookAPI;
}

// v1.0 - Initial API
namespace APIv1 {
  interface QueryAPI {
    execute(sql: string): Promise<Row[]>;
    executePrepared(
      statement: string,
      params: any[]
    ): Promise<Row[]>;
  }

  interface ReportAPI {
    // Read-only operations
    getReport(id: string): Promise<Report | null>;
    listReports(filter?: ReportFilter): Promise<Report[]>;
    getReportMetadata(id: string): Promise<ReportMetadata | null>;
  }

  interface RenderAPI {
    render(
      template: string,
      data: any,
      format: "html" | "text"
    ): Promise<string>;
  }

  interface AuthAPI {
    getCurrentUser(): Promise<User | null>;
    getAuthContext(): Promise<AuthContext>;
  }
}

// v2.0 - New features, breaking changes
namespace APIv2 {
  interface QueryAPI extends APIv1.QueryAPI {
    // New cache parameter
    execute(
      sql: string,
      options?: { cache?: boolean; cacheTtl?: number }
    ): Promise<Row[]>;

    // New streaming API
    executeStream(
      sql: string,
      options?: StreamOptions
    ): AsyncIterable<Row>;
  }

  interface ReportAPI extends APIv1.ReportAPI {
    // New write operations
    createReport(spec: ReportSpec): Promise<Report>;
    updateReport(id: string, updates: Partial<Report>): Promise<Report>;
    deleteReport(id: string): Promise<void>;

    // New publishing API
    publishReport(id: string, options?: PublishOptions): Promise<PublishedReport>;
  }

  interface RenderAPI {
    // New async rendering with progress
    renderAsync(
      template: string,
      data: any,
      format: string,
      onProgress?: (progress: ProgressEvent) => void
    ): Promise<string>;

    // Custom renderers
    registerRenderer(
      format: string,
      renderer: (data: any) => Promise<string>
    ): void;
  }

  interface AuthAPI extends APIv1.AuthAPI {
    // New permission checking
    checkPermission(
      resource: string,
      action: string
    ): Promise<boolean>;
    hasRole(role: string): Promise<boolean>;
  }
}

// Version adapter pattern
class APIAdapter {
  static createAPI(
    pluginId: string,
    requestedVersion: string,
    currentVersion: string
  ): HostAPI {
    const [reqMajor, reqMinor] = requestedVersion.split(".").map(Number);
    const [curMajor, curMinor] = currentVersion.split(".").map(Number);

    if (reqMajor !== curMajor) {
      throw new IncompatibleAPIError(
        `${pluginId} requires API v${reqMajor} but host provides v${curMajor}`
      );
    }

    if (reqMinor > curMinor) {
      throw new IncompatibleAPIError(
        `${pluginId} requires API v${requestedVersion} but host only provides v${currentVersion}`
      );
    }

    // Return appropriate version implementation
    if (curMajor === 1) {
      return new APIv1Implementation();
    } else if (curMajor === 2) {
      return new APIv2Implementation();
    }

    throw new Error(`Unsupported API version: ${currentVersion}`);
  }
}

interface VersionContract {
  hostVersion: string;
  apiVersion: string; // e.g., "2.1"

  // Supported capabilities in this version
  capabilities: Record<string, CapabilityStatus>;

  // Deprecation warnings
  deprecations: Deprecation[];

  // Migration guide for upgrades
  migrationGuide?: string;
}

interface Deprecation {
  feature: string;
  since: string;
  willBeRemovedIn: string;
  alternative: string;
  severity: "low" | "medium" | "high";
}
```

### Version Declaration & Negotiation

```typescript
interface PluginManifest {
  // Exactly v1.0 or v2.0, never ranges
  apiVersion: "1.0" | "2.0" | "3.0";

  // Host version range (semver ranges allowed)
  hostVersionRange: string;
}

class VersionNegotiator {
  negotiateAPI(
    plugin: PluginManifest,
    hostVersion: string,
    hostAPIVersion: string
  ): VersionContract {
    // 1. Check host version compatibility
    if (!semverSatisfies(hostVersion, plugin.hostVersionRange)) {
      throw new HostVersionError(
        `Plugin requires host ${plugin.hostVersionRange} but got ${hostVersion}`
      );
    }

    // 2. Check API version support
    const [hostMajor, hostMinor] = hostAPIVersion.split(".").map(Number);
    const [pluginMajor, pluginMinor] = plugin.apiVersion.split(".").map(Number);

    if (pluginMajor > hostMajor) {
      throw new APIVersionError(
        `Plugin requires API v${plugin.apiVersion} but host only provides v${hostAPIVersion}`
      );
    }

    if (pluginMajor === hostMajor && pluginMinor > hostMinor) {
      throw new APIVersionError(
        `Plugin requires API v${plugin.apiVersion} but host only provides v${hostAPIVersion}`
      );
    }

    // 3. Return contract
    return {
      hostVersion,
      apiVersion: hostAPIVersion,
      capabilities: this.getCapabilities(plugin.apiVersion),
      deprecations: this.getDeprecations(plugin.apiVersion),
    };
  }

  private getCapabilities(apiVersion: string): Record<string, CapabilityStatus> {
    if (apiVersion.startsWith("1.")) {
      return {
        "query:execute": { available: true, since: "1.0" },
        "query:streaming": { available: false, since: "2.0" },
        "report:write": { available: false, since: "2.0" },
        "auth:permissions": { available: false, since: "2.0" },
      };
    } else if (apiVersion.startsWith("2.")) {
      return {
        "query:execute": { available: true, since: "1.0" },
        "query:streaming": { available: true, since: "2.0" },
        "report:write": { available: true, since: "2.0" },
        "auth:permissions": { available: true, since: "2.0" },
        "render:custom": { available: false, since: "3.0" },
      };
    }
    return {};
  }
}
```

