**Plugin Implementation (index.js):**
```typescript
import { parse } from "csv-parse/sync";

interface PluginContext {
  pluginId: string;
  config: any;
  logger: Logger;
  hostAPI: HostAPI;
}

interface PluginHooks {
  onLoad(context: PluginContext): Promise<void>;
  onUnload(context: PluginContext): Promise<void>;
}

let context: PluginContext;

export async function onLoad(ctx: PluginContext): Promise<void> {
  context = ctx;
  ctx.logger.log("CSV DataSource plugin loaded");

  // Validate config at load time
  if (!context.config.delimiter) {
    throw new Error("delimiter config required");
  }
}

export async function onUnload(ctx: PluginContext): Promise<void> {
  ctx.logger.log("CSV DataSource plugin unloading");
}

export class CSVDataSource {
  constructor(private hostAPI: HostAPI, private config: any) {}

  async read(filePath: string): Promise<any[]> {
    try {
      // File access validated by sandbox
      const fileContent = await this.hostAPI.storage.temp.read(filePath);

      const records = parse(fileContent, {
        delimiter: this.config.delimiter,
        encoding: this.config.encoding,
        columns: this.config.hasHeader,
      });

      context.logger.log(
        `Parsed ${records.length} records from ${filePath}`
      );

      return records;
    } catch (error) {
      context.logger.error(`Failed to read CSV: ${error.message}`);
      // Never expose file paths in errors
      throw new Error("Failed to parse CSV file");
    }
  }

  async getSchema(filePath: string): Promise<string[]> {
    const records = await this.read(filePath);
    if (records.length === 0) return [];

    return Object.keys(records[0]);
  }
}

// Export the class for use by host
export default CSVDataSource;
