### Manifest Schema Specification

```typescript
interface PluginManifest {
  // ========== IDENTITY ==========
  apiVersion: "1.0" | "1.1" | "2.0"
  id: string                    // kebab-case, globally unique, <64 chars
  version: string               // semver: MAJOR.MINOR.PATCH
  name: string                  // Human-readable, <128 chars
  description: string           // <512 chars, no HTML

  // ========== AUTHORSHIP & DISTRIBUTION ==========
  author: {
    name: string
    email?: string
    organization?: string
  }
  license: string               // SPDX identifier (MIT, Apache-2.0, etc.)
  repository?: string           // Git URL or web URL
  homepage?: string
  keywords?: string[]

  // ========== CAPABILITIES & METADATA ==========
  capabilities: Capability[]
  tags: string[]                // Searchable tags

  // ========== ENTRY POINT ==========
  entry: {
    type: "esm" | "commonjs" | "wasm" | "native"
    path: string                // Relative path from manifest location
    exports?: string[]          // For ESM: exported function names
  }

  // ========== DEPENDENCIES ==========
  dependencies?: {
    hostVersion: string         // semver range: ">=2.0.0 <3.0.0"
    hostCapabilities?: string[] // Required capabilities host must provide
    plugins?: {
      [pluginId: string]: {
        version: string         // semver range
        optional?: boolean      // default: false
        config?: Record<string, any>  // Config to pass to dependency
      }
    }
  }

  // ========== PERMISSIONS & SECURITY ==========
  permissions: {
    required: Permission[]
    optional: Permission[]
  }

  sandbox: {
    cpuLimit: number            // ms per execution
    memoryLimit: number         // MB (default: 256)
    timeLimit: number           // ms total (default: 30000)
    networkAccess: "none" | "internal" | "restricted" | "full"
    fileSystemAccess: "none" | "readonly" | "temp" | "full"
    isolationLevel?: 1 | 2 | 3  // default: 2
  }

  // ========== CONFIGURATION ==========
  configSchema?: JSONSchema     // User configuration validation
  defaultConfig?: Record<string, any>

  // ========== LIFECYCLE ==========
  lifecycle: {
    supportsHotReload: boolean
    gracefulShutdown: number    // ms to wait for cleanup
  }

  // ========== DEPRECATION & MIGRATION ==========
  deprecated?: {
    since: string               // Version deprecated
    until: string               // Version removed
    replacement?: string        // Suggested replacement plugin
    migrationGuide?: string     // URL to migration docs
  }

  // ========== RUNTIME METADATA ==========
  metadata?: {
    stability: "experimental" | "alpha" | "beta" | "stable"
    supportLevel: "community" | "supported" | "deprecated"
    lastUpdated: string         // ISO date
    conforms?: string[]         // Spec conformances
    documentation?: string      // URL to full docs
  }
}

interface Capability {
  name: string                  // e.g., "export:pdf"
  version: string               // semver
  description: string
  schema?: JSONSchema           // Output/behavior contract
}

interface Permission {
  resource: string              // Pattern: scope:target
  actions: ("read" | "write" | "delete" | "execute")[]
  constraints?: {
    rateLimit?: number
    maxSize?: number
    allowedDomains?: string[]
    timeWindow?: number
  }
}
```

### Manifest Validation

Manifests are validated on three levels:

1. **Schema Validation**: Against JSONSchema spec for API version
2. **Semantic Validation**: Version ranges, dependencies, permissions
3. **Deployment Validation**: Host version compatibility, permission approval

```typescript
interface ManifestValidationResult {
  valid: boolean
  errors: ValidationError[]    // Schema/semantic errors
  warnings: ValidationWarning[] // Deprecation, missing fields
  analysis: {
    complexity: "simple" | "moderate" | "complex"
    requiredApprovals: string[] // e.g., ["security", "platform"]
    estimatedResources: {
      peakMemory: number
      avgCPU: number
      diskSpace: number
    }
  }
}

// Tool: manifest-validator
function validateManifest(
  manifest: PluginManifest,
  hostVersion: string
): ManifestValidationResult {
  // 1. Validate against schema for apiVersion
  const schemaValid = validateSchema(manifest, getSchema(manifest.apiVersion))

  // 2. Validate semver ranges
  const depsValid = validateDependencies(manifest.dependencies, hostVersion)

  // 3. Validate capability names are unique
  const capsValid = manifest.capabilities.length === 
    new Set(manifest.capabilities.map(c => c.name)).size

  // 4. Check for circular dependencies
  const noCycles = !hasCircularDependencies(manifest.dependencies?.plugins)

  return {
    valid: schemaValid && depsValid && capsValid && noCycles,
    errors: [...],
    warnings: [...],
    analysis: {...}
  }
}
```

