### Capability Registry (Secondary Index)

Plugins provide capabilities; other plugins consume them.

```typescript
interface Capability {
  name: string                  // "export:pdf", "transform:data"
  version: string               // semver
  providers: {
    pluginId: string
    version: string
    priority: number            // Higher = preferred
  }[]
}

class CapabilityRegistry {
  private capabilities: Map<string, Capability>

  // Resolve a capability request to a plugin
  resolve(
    capabilityName: string,
    versionRange: string
  ): { pluginId: string; version: string } | null {
    const capability = this.capabilities.get(capabilityName)
    if (!capability) return null

    // Find best matching provider
    const candidates = capability.providers
      .filter(p => semverInRange(p.version, versionRange))
      .sort((a, b) => b.priority - a.priority)

    return candidates[0] || null
  }

  getImplementations(capabilityName: string): PluginEntry[] {
    // Get all plugins implementing this capability
  }
}
