### Dependency Resolution Algorithm

The registry uses topological sorting to determine load order and detect cycles.

```typescript
class DependencyResolver {
  resolve(
    plugins: Map<string, PluginManifest>,
    hostVersion: string
  ): {
    order: string[]           // Load order (topologically sorted)
    conflicts: Conflict[]
    satisfied: boolean
  } {
    // 1. Build dependency graph
    const graph = new DirectedGraph<string>()
    const conflicts: Conflict[] = []

    for (const [id, manifest] of plugins) {
      // Check host version compatibility
      if (!this.satisfiesHostVersion(manifest, hostVersion)) {
        conflicts.push({
          type: "version-mismatch",
          plugin: id,
          required: manifest.dependencies?.hostVersion,
          actual: hostVersion
        })
      }

      // Check plugin dependencies
      for (const [depId, depSpec] of Object.entries(manifest.dependencies?.plugins || {})) {
        graph.addEdge(id, depId)

        const depManifest = plugins.get(depId)
        if (!depManifest && !depSpec.optional) {
          conflicts.push({
            type: "missing-dependency",
            plugin: id,
            dependency: depId
          })
        }

        if (depManifest && !this.satisfiesVersion(depManifest.version, depSpec.version)) {
          conflicts.push({
            type: "version-incompatible",
            plugin: id,
            dependency: depId,
            required: depSpec.version,
            available: depManifest.version
          })
        }
      }
    }

    // 2. Detect cycles
    const cycles = graph.findCycles()
    if (cycles.length > 0) {
      conflicts.push({
        type: "circular-dependency",
        cycles
      })
    }

    // 3. Topological sort
    const order = graph.topologicalSort()

    return {
      order,
      conflicts,
      satisfied: conflicts.length === 0
    }
  }
}
```

