## Lifecycle Management

Plugins go through a strict lifecycle from discovery to unload. Each phase has defined hooks and error handling.

### Lifecycle Phases

```
┌─────────────┐
│ DISCOVERING │  Manifest file found on disk
└──────┬──────┘
       │ validate()
       ▼
┌─────────────┐
│ VALIDATING  │  JSONSchema validation
└──────┬──────┘
       │ resolve()
       ▼
┌─────────────┐
│  RESOLVED   │  Dependencies satisfied
└──────┬──────┘
       │ load()
       ▼
┌─────────────┐
│  LOADING    │  Code loaded into memory
└──────┬──────┘
       │ init()
       ▼
┌──────────────┐
│ INITIALIZING │  init() hook running
└──────┬───────┘
       │
       ├─ success ──┐
       │            ▼
       │      ┌─────────┐
       │      │ LOADED  │  Ready to activate
       │      └──┬──────┘
       │         │ activate()
       │         ▼
       │    ┌───────────┐
       │    │ ACTIVATING│  Prepare for use
       │    └──┬────────┘
       │       │
       │       ▼
       │    ┌──────┐
       │    │ACTIVE│  Serving requests
       │    └──┬───┘
       │       │ deactivate()
       │       ▼
       │  ┌──────────────┐
       │  │ DEACTIVATING │  Graceful shutdown
       │  └──┬───────────┘
       │     │ cleanup()
       │     ▼
       │  ┌──────────┐
       │  │UNLOADING │  cleanup() hook
       │  └──┬───────┘
       │     ▼
       └──>┌──────────┐
           │ UNLOADED │  Memory released
           └──────────┘

Error paths from any state → ERROR → (retry/disable/unload)
```

### Plugin Hooks API

```typescript
interface PluginHooks {
  // ========== REQUIRED HOOKS ==========

  // Called once when plugin is loaded
  // Plugins initialize state, register handlers, etc.
  init(context: PluginContext): Promise<void>

  // Called when plugin is unloaded
  // Must cleanup: close connections, flush state, release locks
  cleanup(): Promise<void>

  // ========== OPTIONAL HOOKS ==========

  // Called when plugin becomes active (serving requests)
  activate?(): Promise<void>

  // Called when plugin becomes inactive
  deactivate?(): Promise<void>

  // Called when configuration changes
  onConfigChange?(config: Record<string, any>): Promise<void>

  // Called when a dependency is loaded
  onDependencyReady?(pluginId: string, api: any): Promise<void>

  // Called before a dependency unloads
  onDependencyUnloading?(pluginId: string): Promise<void>

  // Called on unhandled errors
  onError?(error: Error, context: ErrorContext): Promise<void>

  // Called periodically for health checks
  healthCheck?(): Promise<HealthStatus>
}

interface PluginContext {
  // Plugin identity
  id: string
  version: string

  // Configuration
