### Lifecycle Manager Implementation

```typescript
class LifecycleManager {
  async load(manifest: PluginManifest, path: string): Promise<PluginInstance> {
    try {
      // 1. Validate manifest
      const validation = validateManifest(manifest)
      if (!validation.valid) {
        throw new ManifestError(validation.errors)
      }

      // 2. Resolve dependencies
      const deps = await this.dependencyResolver.resolve(manifest.dependencies)
      if (!deps.satisfied) {
        throw new DependencyError(deps.conflicts)
      }

      // 3. Load code
      const code = await this.loadCode(manifest.entry)

      // 4. Create sandbox
      const sandbox = await this.sandboxManager.create(manifest.sandbox)

      // 5. Initialize context
      const context = new PluginContext({
        id: manifest.id,
        version: manifest.version,
        config: manifest.defaultConfig || {},
        hostAPI: this.apiRouter.selectAPI(manifest.dependencies?.hostVersion),
        logger: this.createLogger(manifest.id),
        storage: this.createStorage(manifest.id),
        eventBus: this.eventBus,
        dependencies: new DependencyLoader(deps.resolved)
      })

      // 6. Call init() hook
      const initTimeout = manifest.lifecycle.gracefulShutdown || 30000
      await this.executeWithTimeout(
        () => code.init(context),
        initTimeout,
        `Plugin ${manifest.id} init() hook exceeded ${initTimeout}ms`
      )

      // 7. Register in registry
      const entry = this.registry.register(manifest, path)
      entry.instance = { code, context, sandbox }
      this.registry.setState(manifest.id, PluginState.LOADED)

      // 8. Emit event
      this.eventBus.emit("plugin:loaded", { pluginId: manifest.id })

      return entry.instance
    } catch (error) {
      this.registry.setState(manifest.id, PluginState.ERROR)
      this.registry.addError(manifest.id, {
        phase: PluginState.LOADING,
        severity: "fatal",
        message: error.message,
        stack: error.stack
      })
      throw error
    }
  }

  async activate(pluginId: string): Promise<void> {
    const entry = this.registry.get(pluginId)
    if (!entry.instance) throw new Error(`Plugin ${pluginId} not loaded`)

    const { code, context } = entry.instance
    const gracefulShutdown = entry.manifest.lifecycle.gracefulShutdown || 5000

    try {
      this.registry.setState(pluginId, PluginState.ACTIVATING)

      if (code.activate) {
        await this.executeWithTimeout(
          () => code.activate(),
          gracefulShutdown
        )
      }

      this.registry.setState(pluginId, PluginState.ACTIVE)
      this.eventBus.emit("plugin:activated", { pluginId })
    } catch (error) {
      this.registry.addError(pluginId, {
        phase: PluginState.ACTIVATING,
        severity: "error",
        message: error.message
      })
      throw error
    }
  }

  async deactivate(pluginId: string): Promise<void> {
    const entry = this.registry.get(pluginId)
    if (!entry.instance) return

    const { code } = entry.instance
    const gracefulShutdown = entry.manifest.lifecycle.gracefulShutdown || 5000

    try {
      this.registry.setState(pluginId, PluginState.DEACTIVATING)

      // Drain in-flight requests
      await this.drainInflightRequests(pluginId, gracefulShutdown / 2)

      if (code.deactivate) {
        await this.executeWithTimeout(
          () => code.deactivate(),
          gracefulShutdown / 2
        )
      }

      this.registry.setState(pluginId, PluginState.LOADED)
      this.eventBus.emit("plugin:deactivated", { pluginId })
    } catch (error) {
      this.registry.addError(pluginId, {
        phase: PluginState.DEACTIVATING,
        severity: "warning",
        message: error.message
      })
      // Don't throw; allow unload to proceed
    }
  }

  async unload(pluginId: string): Promise<void> {
    const entry = this.registry.get(pluginId)
    if (!entry.instance) return

    const { code, sandbox } = entry.instance
    const gracefulShutdown = entry.manifest.lifecycle.gracefulShutdown || 5000

    try {
      // Deactivate first if active
      if (entry.state === PluginState.ACTIVE) {
        await this.deactivate(pluginId)
      }

      this.registry.setState(pluginId, PluginState.UNLOADING)

      // Call cleanup() hook
      if (code.cleanup) {
        await this.executeWithTimeout(
          () => code.cleanup(),
          gracefulShutdown
        )
      }

      // Release sandbox resources
      await sandbox.terminate()

      this.registry.setState(pluginId, PluginState.UNLOADED)
      this.eventBus.emit("plugin:unloaded", { pluginId })
    } catch (error) {
      this.registry.addError(pluginId, {
        phase: PluginState.UNLOADING,
        severity: "warning",
        message: error.message
      })
      // Force cleanup anyway
      await sandbox.terminate().catch(() => {})
      this.registry.setState(pluginId, PluginState.UNLOADED)
    }
  }

  async hotReload(pluginId: string): Promise<void> {
    const entry = this.registry.get(pluginId)
    const manifest = entry.manifest

    if (!manifest.lifecycle.supportsHotReload) {
      throw new Error(`Plugin ${pluginId} does not support hot reload`)
    }

    const wasActive = entry.state === PluginState.ACTIVE

    // Phase 1: Pause
    await this.pausePlugin(pluginId)

    // Phase 2: Unload
    await this.unload(pluginId)

    // Phase 3: Reload
    await this.load(manifest, entry.resolvedPath)

    // Phase 4: Resume
    if (wasActive) {
      await this.activate(pluginId)
    }

    this.eventBus.emit("plugin:reloaded", { pluginId })
  }

  private executeWithTimeout(
    fn: () => Promise<void>,
    timeoutMs: number,
    message?: string
  ): Promise<void> {
    return Promise.race([
      fn(),
      new Promise((_, reject) =>
        setTimeout(
          () => reject(new Error(message || `Operation exceeded ${timeoutMs}ms`)),
          timeoutMs
        )
      )
    ])
  }

  private async pausePlugin(pluginId: string): Promise<void> {
    // Stop accepting new requests
    this.registry.setState(pluginId, PluginState.DEACTIVATING)
    // Drain in-flight requests with timeout
    await this.drainInflightRequests(pluginId, 5000)
  }
}
```

