## Sandboxed Execution

Plugins are untrusted code. The sandbox isolates them from the host and other plugins, enforces resource limits, and mediates API access.

### Isolation Tiers

```
Tier 1: Process Isolation (Strongest Security)
  • Separate worker process / thread
  • OS-level resource limits (cgroups, job objects)
  • Complete memory isolation
  • Use: Untrusted plugins, resource-heavy plugins, third-party

Tier 2: VM Context Isolation (Recommended)
  • Shared process, separate V8/JavaScript contexts
  • Proxy-based API access (can revoke instantly)
  • Memory limits via GC pressure
  • CPU limits via execution time tracking
  • Use: Trusted partner plugins, typical scenario

Tier 3: In-Process (Minimal Overhead)
  • Shared context, direct API access
  • No resource isolation
  • Use: Internal/built-in plugins only
```

### Sandbox Configuration

```typescript
interface SandboxConfig {
  // ========== ISOLATION ==========

  isolationLevel: 1 | 2 | 3        // default: 2

  // ========== RESOURCE LIMITS ==========

  // CPU throttling
  cpuLimit: number                 // ms CPU per window
  cpuWindow: number                // time window (e.g., 1000ms)

  // Single execution timeout
  executionTimeout: number         // max ms per call (e.g., 30000)

  // Memory ceiling
  memoryLimit: number              // MB (e.g., 512)
  memoryWarningThreshold: number   // % (e.g., 80)

  // ========== FILE SYSTEM ==========

  fileSystemAccess: {
    mode: "none" | "readonly" | "temp" | "full"
    sandbox: string                // Isolated temp directory
    maxFileSize: number            // bytes per file
    maxTotalSize: number           // bytes total
  }

  // ========== NETWORK ==========

  networkAccess: {
    mode: "none" | "internal" | "restricted" | "full"
    whitelist?: string[]           // Allowed domain patterns
    blacklist?: string[]
    timeout: number                // connection timeout
    rateLimit: number              // requests per second
  }

  // ========== API ACCESS ==========

  apiAccess: {
    whitelist: string[]            // Allowed API methods
    rateLimits: Record<string, number>  // method -> calls/sec
  }

  // ========== PROCESS CAPABILITIES (Linux) ==========

  capabilities?: string[]          // CAP_NET_BIND_SERVICE, etc.
}
```

### Sandboxing Strategies by Runtime

#### Node.js Worker Threads (Tier 2 Default)

```typescript
class WorkerThreadSandbox implements ISandbox {
  private worker: Worker
  private metrics: ResourceMetrics
  private constraints: SandboxConfig
  private requestQueue: Map<string, PendingRequest>

  async create(
    code: PluginCode,
    constraints: SandboxConfig,
    context: PluginContext
  ): Promise<SandboxInstance> {
    // 1. Create worker thread with memory limit
    const memoryLimitMb = constraints.memoryLimit
    this.worker = new Worker("./sandbox-worker.js", {
      resourceLimits: {
        maxOldSpaceSize: memoryLimitMb
      },
      isolatedContext: true
    })

    // 2. Set up message channel
    this.worker.on("message", (msg: SandboxMessage) => {
      this.handleWorkerMessage(msg)
    })

    // 3. Communicate constraints
    this.worker.postMessage({
      type: "init",
      code,
      context,
      constraints
    })

    return {
      execute: (fn: string, args: any[]) => this.execute(fn, args),
      getMetrics: () => this.getResourceUsage(),
      terminate: () => this.terminate()
    }
  }

  async execute(
    functionName: string,
    args: any[],
    timeout?: number
  ): Promise<any> {
    timeout = timeout || this.constraints.executionTimeout

    // 1. Check rate limits
    const rate = this.getRateLimit(functionName)
    if (rate.exceeded) {
      throw new RateLimitError(`Rate limit exceeded for ${functionName}`)
    }

    // 2. Check memory
    const usage = this.getResourceUsage()
    if (usage.memory > this.constraints.memoryLimit) {
      throw new ResourceExhaustedError("Memory limit exceeded")
    }

    // 3. Execute with timeout
    const requestId = crypto.randomUUID()
    const request = new PendingRequest(requestId, timeout)
    this.requestQueue.set(requestId, request)

    try {
      this.worker.postMessage({
        type: "execute",
        requestId,
        functionName,
        args
      })

      return await Promise.race([
        request.promise,
        this.createTimeoutPromise(timeout)
      ])
    } finally {
      this.requestQueue.delete(requestId)
    }
  }

  private handleWorkerMessage(msg: SandboxMessage): void {
    if (msg.type === "result") {
      const request = this.requestQueue.get(msg.requestId)
      if (request) request.resolve(msg.result)
    } else if (msg.type === "error") {
      const request = this.requestQueue.get(msg.requestId)
      if (request) request.reject(new Error(msg.error))
    } else if (msg.type === "metrics") {
      this.metrics = msg.metrics
    }
  }

  getResourceUsage(): ResourceUsage {
    return this.metrics
  }

  async terminate(): Promise<void> {
    // Reject all pending requests
    for (const request of this.requestQueue.values()) {
      request.reject(new Error("Worker terminated"))
    }
    this.requestQueue.clear()

    // Terminate worker
    await this.worker.terminate()
  }
}
```

#### Process Isolation (Tier 1 - High Security)

```typescript
class ProcessSandbox implements ISandbox {
  private process: ChildProcess
  private constraints: SandboxConfig
  private resourceWatcher: ResourceWatcher

  async create(...): Promise<SandboxInstance> {
    // 1. Set OS-level resource limits
    const limits = {
      cpu: this.constraints.cpuLimit,
      memory: this.constraints.memoryLimit * 1024 * 1024,  // convert to bytes
      processes: 1
    }

    // 2. Spawn subprocess with limits
    this.process = fork("./plugin-process.js", [], {
      stdio: ["ignore", "pipe", "pipe", "ipc"],
      env: {
        // Pass only required env vars
        PLUGIN_ID: context.id,
        PLUGIN_CONFIG: JSON.stringify(context.config)
      }
      // Cgroups configuration (Linux)
      ...(process.platform === "linux" && {
        cgroup: this.createCgroup(limits)
      })
    })

    // 3. Watch resource usage
    this.resourceWatcher = new ResourceWatcher(this.process.pid)
    this.resourceWatcher.on("threshold-exceeded", (metric, value) => {
      if (metric === "memory") {
        this.process.kill()
      }
    })

    return {
      execute: (fn, args) => this.execute(fn, args),
      getMetrics: () => this.resourceWatcher.getMetrics(),
      terminate: () => this.terminate()
    }
  }

  private createCgroup(limits: any): string {
    // Linux cgroups v2 configuration
    const cgroupPath = `/sys/fs/cgroup/plugin-${this.processId}`

    fs.writeFileSync(`${cgroupPath}/memory.max`, limits.memory)
    fs.writeFileSync(`${cgroupPath}/cpu.max`, `${limits.cpu} 1000000`)
    fs.writeFileSync(`${cgroupPath}/pids.max`, limits.processes)

    return cgroupPath
  }
}
```

#### In-Process Sandbox (Tier 3 - Trust Boundary)

```typescript
class InProcessSandbox implements ISandbox {
  private plugin: PluginCode
  private constraints: SandboxConfig
  private metrics: ResourceMetrics

  async create(
    code: PluginCode,
    constraints: SandboxConfig,
    context: PluginContext
  ): Promise<SandboxInstance> {
    this.plugin = code
    this.constraints = constraints

    // Wrap each API call with proxy to enforce permissions
    const apiProxy = this.createAPIProxy(context.hostAPI)
    context.hostAPI = apiProxy

    return {
      execute: (fn, args) => this.executeWithMetrics(fn, args),
      getMetrics: () => this.metrics,
      terminate: () => Promise.resolve()
    }
  }

  private createAPIProxy(hostAPI: any): any {
    const constraints = this.constraints
    const startTime = Date.now()

    return new Proxy(hostAPI, {
      get: (target, methodName: string) => {
        return async (...args: any[]) => {
          // 1. Check timeout
          if (Date.now() - startTime > constraints.executionTimeout) {
            throw new TimeoutError("Execution exceeded timeout")
          }

          // 2. Check permissions
          if (!constraints.apiAccess.whitelist.includes(methodName)) {
            throw new PermissionError(`API method '${methodName}' not permitted`)
          }

          // 3. Check rate limit
          const rate = this.getRateLimit(methodName)
          if (rate.exceeded) {
            throw new RateLimitError(`Rate limit exceeded for '${methodName}'`)
          }

          // 4. Execute with measurement
          const callStart = Date.now()
          try {
            const result = await target[methodName](...args)
            this.metrics.calls.push({
              method: methodName,
              duration: Date.now() - callStart,
              success: true
            })
            return result
          } catch (error) {
            this.metrics.calls.push({
              method: methodName,
              duration: Date.now() - callStart,
              success: false
            })
            throw error
          }
        }
      }
    })
  }
}
```

### Permission Enforcement

```typescript
interface PermissionContext {
  resource: string          // e.g., "api:reports", "storage:plugin-data"
  action: string            // "read", "write", "delete"
  actor: string             // Plugin ID
  target: any               // What's being accessed
  constraints?: any
}

class PermissionEnforcer {
  async check(context: PermissionContext): Promise<void> {
    const entry = this.registry.get(context.actor)
    if (!entry) throw new Error(`Unknown plugin: ${context.actor}`)

    const permission = entry.permissions.find(
      p => p.resource === context.resource && p.actions.includes(context.action)
    )

    if (!permission) {
      this.auditLog.record({
        event: "permission_denied",
        pluginId: context.actor,
        resource: context.resource,
        action: context.action,
        reason: "No matching permission"
      })
      throw new PermissionDeniedError(
        `Plugin ${context.actor} not permitted to ${context.action} ${context.resource}`
      )
    }

    // Check constraints (rate limits, data sizes, etc.)
    if (permission.constraints) {
      this.checkConstraints(permission.constraints, context)
    }
  }
}
