# 4. Plugin is automatically reloaded on file changes
# 5. Test against host running on localhost:5000

# 6. Run tests
$ npm test                          # Unit tests
$ npm run test:integration          # Against real host APIs

# 7. Build for deployment
$ npm run build
# Creates: dist/plugin.tar.gz with manifest, code, signature

# 8. Submit to registry (optional)
$ npm run publish
# Uploads to @reporting/registry, signs with your key
