### Resource Limit Enforcement

Plugins are constrained to prevent abuse:

```typescript
interface ResourceConstraints {
  cpu: {
    limit: number               // ms per time window
    window: number              // e.g., 1000ms
  }
  memory: {
    limit: number               // MB
    warning: number             // % of limit
  }
  network: {
    rateLimit: number           // req/sec
    timeout: number             // ms per request
  }
  storage: {
    maxFileSize: number         // bytes
    maxTotalSize: number        // bytes
  }
}

class ResourceLimiter {
  async enforceConstraints(
    pluginId: string,
    constraints: ResourceConstraints
  ): Promise<void> {
    const usage = this.getResourceUsage(pluginId)

    if (usage.cpu > constraints.cpu.limit) {
      this.sandboxManager.throttle(pluginId)
      this.auditLog.record({
        eventType: "resource_limit_exceeded",
        pluginId,
        details: { resource: "cpu", usage: usage.cpu, limit: constraints.cpu.limit }
      })
    }

    if (usage.memory > constraints.memory.limit) {
      this.sandboxManager.kill(pluginId)
      throw new Error(`Plugin ${pluginId} exceeded memory limit`)
    }
  }
}
```

