## Operational Concerns

Running plugins in production.

### Monitoring & Observability

```typescript
interface PluginMetrics {
  // Lifecycle
  loadTime: number                  // Time to init
  unloadTime: number

  // Execution
  executionTimes: Histogram         // Distribution of call durations
  callCount: Counter
  errorCount: Counter

  // Resources
  memoryPeak: Gauge
  memoryCurrent: Gauge
  cpuTime: Counter
  networkBytesOut: Counter
  networkBytesIn: Counter

  // API Usage
  apiCallsByMethod: Record<string, number>
  apiErrorsByMethod: Record<string, number>
}

class MetricsCollector {
  private metrics: Map<string, PluginMetrics>

  recordExecution(
    pluginId: string,
    method: string,
    duration: number,
    success: boolean
  ): void {
    const m = this.metrics.get(pluginId)!
    m.executionTimes.observe(duration)
    m.callCount.inc()
    if (!success) m.errorCount.inc()

    // Export to Prometheus
    this.prometheus.recordExecution({
      plugin: pluginId,
      method,
      duration,
      status: success ? "ok" : "error"
    })
  }

  getMetrics(pluginId?: string): PluginMetrics | PluginMetrics[] {
    if (pluginId) {
      return this.metrics.get(pluginId)!
    }
    return Array.from(this.metrics.values())
  }
}

// Prometheus metrics format
plugin_load_duration_ms{plugin="my-plugin", version="1.2.3"} 234.5
plugin_execution_time_ms{plugin="my-plugin", method="exportPDF"} 1234.56
plugin_errors_total{plugin="my-plugin"} 5
plugin_memory_bytes{plugin="my-plugin"} 52428800
