### Health Checks

```typescript
interface PluginHealth {
  pluginId: string
  status: "healthy" | "degraded" | "unhealthy"
  lastCheck: Date

  state: PluginState
  uptime: number                    // seconds

  errors: {
    recent: PluginError[]
    trend: "improving" | "stable" | "worsening"
  }

  resources: {
    memory: { current: number; limit: number }
    cpu: { usage: number; limit: number }
  }

  api: {
    successRate: number             // 0-1
    errorRate: number               // 0-1
    avgLatency: number              // ms
  }
}

class HealthChecker {
  async check(pluginId: string): Promise<PluginHealth> {
    const entry = this.registry.get(pluginId)

    const health: PluginHealth = {
      pluginId,
      status: this.computeStatus(entry),
      lastCheck: new Date(),
      state: entry.state,
      uptime: Date.now() - entry.loadedAt,
      errors: {
        recent: entry.errors.slice(-10),
        trend: this.computeErrorTrend(entry)
      },
      resources: this.sandbox.getResourceUsage(pluginId),
      api: this.metrics.getMetrics(pluginId).getAPIStats()
    }

    return health
  }

  async systemHealth(): Promise<{
    status: "healthy" | "degraded" | "unhealthy"
    plugins: PluginHealth[]
    summary: { healthy: number; degraded: number; unhealthy: number }
  }> {
    const plugins = await Promise.all(
      this.registry.getAll().map(e => this.check(e.id))
    )

    return {
      status: this.computeSystemStatus(plugins),
      plugins,
      summary: {
        healthy: plugins.filter(p => p.status === "healthy").length,
        degraded: plugins.filter(p => p.status === "degraded").length,
        unhealthy: plugins.filter(p => p.status === "unhealthy").length
      }
    }
  }
}
```

