### Configuration Management

```typescript
interface PluginConfiguration {
  [pluginId: string]: {
    enabled: boolean
    version?: string              // Pin to specific version
    config: Record<string, any>  // Plugin-specific config
    sandbox?: Partial<SandboxConfig>  // Override sandbox
    permissions?: Partial<PermissionModel>  // Override permissions
    timeout?: number              // Override execution timeout
  }
}

// Config is versioned and can be rolled back
interface ConfigVersion {
  version: number
  timestamp: Date
  author: string
  config: PluginConfiguration
  changelog: string
}

class ConfigurationManager {
  async updateConfig(
    pluginId: string,
    config: Record<string, any>
  ): Promise<void> {
    // 1. Validate against manifest schema
    const validation = validatePluginConfig(
      this.registry.get(pluginId).manifest,
      config
    )
    if (!validation.valid) {
      throw new ValidationError(validation.errors)
    }

    // 2. Apply config (reload plugin if necessary)
    await this.registry.get(pluginId).instance?.context.onConfigChange(config)

    // 3. Record change
    this.configHistory.record({
      pluginId,
      config,
      author: getCurrentUser(),
      timestamp: Date.now()
    })
  }

  rollbackConfig(pluginId: string, toVersion: number): Promise<void> {
    // Restore previous configuration version
  }
}
