## Plugin Manifest Schema

The manifest is the contract between plugin authors and the platform.

### Example Manifest

```json
{
  "apiVersion": "2.0",
  "id": "custom-export-handler",
  "version": "1.2.3",
  "name": "Custom Export Handler",
  "description": "Adds PDF and Excel export capabilities",

  "author": {
    "name": "Report Team A",
    "email": "team-a@company.com"
  },
  "license": "MIT",

  "capabilities": [
    {
      "name": "export:format",
      "version": "1.0",
      "description": "PDF and Excel export formats"
    }
  ],

  "entry": {
    "type": "esm",
    "path": "dist/index.js"
  },

  "dependencies": {
    "hostVersion": ">=2.0.0 <4.0.0",
    "plugins": {
      "data-formatter": {
        "version": ">=1.0.0"
      }
    }
  },

  "permissions": {
    "required": [
      {
        "resource": "api:reports",
        "actions": ["read"],
        "constraints": { "rateLimit": 100 }
      }
    ]
  },

  "sandbox": {
    "cpuLimit": 5000,
    "memoryLimit": 512,
    "timeLimit": 30000,
    "networkAccess": "restricted",
    "fileSystemAccess": "temp"
  },

  "lifecycle": {
    "supportsHotReload": true,
    "gracefulShutdown": 5000
  },

  "metadata": {
    "stability": "stable",
    "supportLevel": "supported"
  }
}
```

### Manifest Specification

```typescript
interface PluginManifest {
  // Required identity
  apiVersion: "1.0" | "1.1" | "2.0"
  id: string                       // kebab-case, globally unique
  version: string                  // semver: MAJOR.MINOR.PATCH
  name: string                     // Display name
  description: string              // <512 chars

  author: {
    name: string
    email?: string
    organization?: string
  }
  license: string                  // SPDX identifier

  // What this plugin provides
  capabilities: Capability[]       // Capabilities exported
  tags?: string[]                  // Searchable tags

  // Code location
  entry: {
    type: "esm" | "commonjs" | "wasm" | "native"
    path: string                   // Relative to manifest
    exports?: string[]             // Named exports for ESM
  }

  // Dependencies
  dependencies?: {
    hostVersion: string            // semver range
    hostCapabilities?: string[]    // Required host capabilities
    plugins?: {
      [pluginId: string]: {
        version: string
        optional?: boolean
        config?: Record<string, any>
      }
    }
  }

  // Security
  permissions: {
    required: Permission[]
    optional?: Permission[]
  }

  sandbox: {
    cpuLimit: number               // ms per window
    memoryLimit: number            // MB
    timeLimit: number              // max execution ms
    networkAccess: "none" | "internal" | "restricted" | "full"
    fileSystemAccess: "none" | "readonly" | "temp" | "full"
    isolationLevel?: 1 | 2 | 3     // default: 2
  }

  // User configuration
  configSchema?: JSONSchema
  defaultConfig?: Record<string, any>

  // Lifecycle
  lifecycle: {
    supportsHotReload: boolean
    gracefulShutdown: number       // ms to wait for cleanup
  }

  // Deprecation
  deprecated?: {
    since: string
    until: string
    replacement?: string
    migrationGuide?: string
  }

  // Metadata
  metadata?: {
    stability: "experimental" | "alpha" | "beta" | "stable"
    supportLevel: "community" | "supported" | "deprecated"
    lastUpdated?: string
    conforms?: string[]
    documentation?: string
  }
}

interface Capability {
  name: string                     // e.g., "export:pdf"
  version: string                  // semver
  description: string
  schema?: JSONSchema              // Output/behavior contract
}

interface Permission {
  resource: string                 // Pattern: "scope:target"
  actions: ("read" | "write" | "delete" | "execute")[]
  constraints?: {
    rateLimit?: number
    maxSize?: number
    allowedDomains?: string[]
  }
}
```

