## Plugin Registry

Central source of truth for plugin metadata, state, dependencies, and capabilities.

### Registry Operations

```typescript
class PluginRegistry {
  // Register a new plugin
  register(
    manifest: PluginManifest,
    path: string,
    permissions?: Permission[]
  ): PluginEntry

  // Remove a plugin
  unregister(pluginId: string): void

  // Query plugins
  get(pluginId: string): PluginEntry | null
  query(filters: PluginQuery): PluginEntry[]
  findByCapability(capabilityName: string): PluginEntry[]

  // Dependency management
  getDependencies(pluginId: string): PluginEntry[]
  getDependents(pluginId: string): PluginEntry[]
  resolveDependencies(pluginId: string): {
    resolved: PluginEntry[]
    conflicts: DependencyConflict[]
    satisfiable: boolean
  }

  // State tracking
  setState(pluginId: string, state: PluginState): void
  addError(pluginId: string, error: PluginError): void

  // Version compatibility
  checkCompatibility(manifest: PluginManifest, hostVersion: string): CompatibilityResult
  getCompatiblePlugins(hostVersion: string, capability?: string): PluginEntry[]

  // Aggregation
  getAll(): PluginEntry[]
  getStats(): RegistryStats
}

enum PluginState {
  DISCOVERING = "discovering",
  VALIDATING = "validating",
  RESOLVED = "resolved",
  LOADING = "loading",
  INITIALIZING = "initializing",
  LOADED = "loaded",
  ACTIVATING = "activating",
  ACTIVE = "active",
  DEACTIVATING = "deactivating",
  UNLOADING = "unloading",
  UNLOADED = "unloaded",
  ERROR = "error",
  DISABLED = "disabled"
}

interface PluginEntry {
  id: string
  manifest: PluginManifest
  state: PluginState
  instance: PluginInstance | null
  loadedAt: number | null
  resolvedPath: string
  errors: PluginError[]
  dependencies: Set<string>
  dependents: Set<string>
  permissions: Permission[]
  constraints: SandboxConstraints
}
```

### Dependency Resolution

Uses topological sorting to determine load order and detect cycles:

```typescript
class DependencyResolver {
  resolve(
    plugins: Map<string, PluginManifest>,
    hostVersion: string
  ): {
    order: string[]                    // Load order
    conflicts: Conflict[]              // Unresolvable conflicts
    satisfied: boolean
  }
}

// Example resolution:
// Input: pluginA → pluginB → pluginC
// Output: [pluginC, pluginB, pluginA]  (load from leaves to root)
```

