import {
  Plugin,
  Context,
  Hook,
  Capability
} from "@reporting/plugin-sdk"

@Capability("export:pdf")
@Capability("export:xlsx")
export default class CustomExportPlugin extends Plugin {
  async init(context: Context): Promise<void> {
    this.logger = context.logger
    this.api = context.hostAPI        // Fully typed
