### 1.2 Manifest Validation Rules

```typescript
// Validation constraints enforced at load time
interface ManifestValidation {
  // ID uniqueness across registry
  idFormat: /^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)*$/;
  idMaxLength: 128;

  // Version must be semantic
  versionFormat: /^\d+\.\d+\.\d+(-[a-z0-9]+)?(\+[a-z0-9]+)?$/;

  // API version must match host
  apiVersionCompatible: boolean; // host checks this

  // Capabilities must be declared
  capabilityWhitelist: Set<string>;

  // Resources must be reasonable
  maxMemoryMB: [1, 4096]; // min, max allowed
  maxStorageMB: [1, 102400];
  requestTimeoutMs: [1000, 600000];

  // Entry points must exist and be readable
  entrypointMustExist: boolean;

  // Cyclic dependency check
  noCyclicDependencies: boolean;
}
```

