## 2. Plugin Registry

### 2.1 Registry Architecture

```typescript
// Main registry: in-memory store with file-based discovery

interface PluginRegistry {
  // Store: ID → metadata + runtime state
  plugins: Map<string, RegisteredPlugin>;

  // Index: capability → [plugin IDs]
  capabilities: Map<string, Set<string>>;

  // Version index: namespace → [versions]
  versions: Map<string, SemanticVersion[]>;

  // Dependency graph for conflict detection
  dependencyGraph: DependencyGraph;

  // Hooks for lifecycle events
  listeners: RegistryEventListener[];
}

interface RegisteredPlugin {
  // Static metadata from manifest
  manifest: PluginManifest;

  // Runtime state
  state: "unloaded" | "loading" | "loaded" | "error" | "unloading";
  loadedAt: number | null;
  instance: PluginInstance | null;

  // Error tracking
  lastError: PluginError | null;
  errorCount: number;
  consecutiveFailures: number;

  // Dependencies resolved at load time
  resolvedDependencies: Map<string, RegisteredPlugin>;
  dependents: Set<string>; // plugins that depend on this

  // Configuration
  activeConfig: PluginConfig;
  configSchema: JSONSchema;

  // Version metadata
  supportsAPIVersions: string[]; // e.g., ["2.0", "2.1"]

  // Resource usage
  resources: ResourceUsage;
  lastHealthCheck: HealthCheckResult | null;
}

interface RegistryEventListener {
  on(event: RegistryEvent, handler: (data: any) => void): void;
  off(event: RegistryEvent): void;
}

type RegistryEvent = 
  | "plugin:discovered"
  | "plugin:registered"
  | "plugin:load-started"
  | "plugin:loaded"
  | "plugin:load-failed"
  | "plugin:unloaded"
  | "plugin:reloaded"
  | "plugin:error"
  | "dependency:resolved"
  | "dependency:conflict";
```

### 2.2 Discovery & Registration Flow

```typescript
class PluginDiscoveryService {
  async discoverPlugins(pluginsDirs: string[]): Promise<PluginManifest[]> {
    const manifests: PluginManifest[] = [];

    for (const dir of pluginsDirs) {
      const entries = await fs.readdir(dir);

      for (const entry of entries) {
        try {
          const manifestPath = path.join(dir, entry, "plugin.json");
          const manifest = await this.loadAndValidateManifest(manifestPath);

          // Check semantic version compatibility
          if (!this.isCompatibleWithHost(manifest.engines.reportingTool)) {
            this.logger.warn(`Plugin ${manifest.id} requires incompatible host version`);
            continue;
          }

          manifests.push(manifest);
        } catch (err) {
          this.logger.error(`Failed to discover plugin in ${entry}:`, err);
          // Continue with other plugins
        }
      }
    }

    return manifests;
  }

  private async loadAndValidateManifest(path: string): Promise<PluginManifest> {
    const content = await fs.readFile(path, "utf-8");
    const manifest = JSON.parse(content);

    // Validate against JSON schema
    const validator = this.getValidator("plugin-manifest/v1.json");
    const valid = validator.validate(manifest);

    if (!valid.valid) {
      throw new ManifestValidationError(valid.errors);
    }

    return manifest;
  }

  private isCompatibleWithHost(engineConstraint: string): boolean {
    const hostVersion = getHostVersion();
    return satisfies(hostVersion, engineConstraint);
  }
}
```

### 2.3 Registry Operations

```typescript
class PluginRegistry {
  // Register a plugin (after discovery)
  async register(manifest: PluginManifest): Promise<void> {
    // Check ID uniqueness
    if (this.plugins.has(manifest.id)) {
      throw new PluginAlreadyRegisteredError(manifest.id);
    }

    // Check for conflicts (same namespace, different version range requirements)
    this.detectConflicts(manifest);

    // Resolve dependencies
    const resolved = await this.resolveDependencies(manifest);

    const registered: RegisteredPlugin = {
      manifest,
      state: "unloaded",
      loadedAt: null,
      instance: null,
      lastError: null,
      errorCount: 0,
      consecutiveFailures: 0,
      resolvedDependencies: resolved,
      dependents: new Set(),
      activeConfig: {},
      supportsAPIVersions: this.inferAPIVersions(manifest),
      resources: createEmptyResourceUsage(),
      lastHealthCheck: null,
    };

    this.plugins.set(manifest.id, registered);

    // Update capability index
    for (const cap of manifest.capabilities) {
      if (!this.capabilities.has(cap)) {
        this.capabilities.set(cap, new Set());
      }
      this.capabilities.get(cap)!.add(manifest.id);
    }

    // Update version index
    const namespace = manifest.namespace;
    if (!this.versions.has(namespace)) {
      this.versions.set(namespace, []);
    }
    this.versions.get(namespace)!.push(new SemanticVersion(manifest.version));

    this.emit("plugin:registered", { id: manifest.id });
  }

  // Resolve a plugin's dependencies
  private async resolveDependencies(
    manifest: PluginManifest
  ): Promise<Map<string, RegisteredPlugin>> {
    const resolved = new Map<string, RegisteredPlugin>();

    for (const [depId, depVersionRange] of Object.entries(manifest.dependencies || {})) {
      const candidates = this.plugins.get(depId);
      if (!candidates) {
        throw new DependencyNotFoundError(depId);
      }

      const compatible = this.findCompatibleVersion(depId, depVersionRange);
      if (!compatible) {
        throw new DependencyVersionConflictError(depId, depVersionRange);
      }

      resolved.set(depId, compatible);
    }

    return resolved;
  }

  // Detect version conflicts
  private detectConflicts(manifest: PluginManifest): void {
    const namespace = manifest.namespace;
    const versions = this.versions.get(namespace) || [];

    for (const existingVersion of versions) {
      // Check if this plugin's version overlaps with requirements
      if (versionsIncompatible(manifest.version, existingVersion)) {
        this.emit("dependency:conflict", {
          namespace,
          newVersion: manifest.version,
          existingVersion: existingVersion.toString(),
        });
      }
    }
  }

  // Query operations
  getPlugin(id: string): RegisteredPlugin | undefined {
    return this.plugins.get(id);
  }

  getPluginsByCapability(capability: string): RegisteredPlugin[] {
    const ids = this.capabilities.get(capability) || new Set();
    return Array.from(ids)
      .map(id => this.plugins.get(id)!)
      .filter(p => p.state === "loaded");
  }

  getPluginsInNamespace(namespace: string): RegisteredPlugin[] {
    return Array.from(this.plugins.values()).filter(
      p => p.manifest.namespace === namespace
    );
  }
}
