## 3. Plugin Lifecycle Hooks

### 3.1 Hook Definitions

```typescript
// Each hook is async; errors are caught and tracked

interface PluginLifecycleHooks {
  onLoad?(api: PluginAPI): Promise<void>;
  onUnload?(): Promise<void>;
  onReload?(api: PluginAPI): Promise<void>;
  onConfigChange?(newConfig: PluginConfig): Promise<void>;
  onHealthCheck?(): Promise<HealthCheckResult>;
  onPermissionsDenied?(deniedCapabilities: string[]): Promise<void>;
  onError?(error: PluginError): Promise<void>;
}

interface HealthCheckResult {
  status: "healthy" | "degraded" | "unhealthy";
  uptime: number;
  timestamp: number;
  details?: Record<string, unknown>;
  message?: string;
}

type PluginError = 
  | LoadError
  | UnloadError
  | RuntimeError
  | TimeoutError
  | PermissionError
  | ResourceExhaustionError;
```

### 3.2 Hook Execution Flow

```typescript
class PluginLifecycleManager {
  async loadPlugin(pluginId: string, config?: PluginConfig): Promise<void> {
    const registered = this.registry.getPlugin(pluginId);
    if (!registered) {
      throw new PluginNotFoundError(pluginId);
    }

    if (registered.state !== "unloaded") {
      throw new InvalidStateTransitionError(
        `Cannot load plugin in state: ${registered.state}`
      );
    }

    try {
      registered.state = "loading";
      this.emit("plugin:load-started", { id: pluginId });

      // 1. Load module
      const module = await this.loadPluginModule(registered);

      // 2. Validate entry point
      if (typeof module.default !== "object") {
        throw new InvalidEntryPointError("Plugin must export default object");
      }

      // 3. Initialize config
      const activeConfig = config || (await this.loadPluginConfig(registered));
      registered.activeConfig = activeConfig;

      // 4. Create API sandbox
      const api = this.createSandboxedAPI(registered);

      // 5. Start resource monitoring
      this.startResourceMonitoring(registered);

      // 6. Call onLoad hook
      if (module.default.onLoad) {
        const promise = module.default.onLoad(api);
        const result = await this.withTimeout(promise, registered.manifest.resources.requestTimeoutMs);

        if (result instanceof Error) {
          throw result;
        }
      }

      // 7. Mark as loaded
      registered.instance = {
        module,
        api,
        startedAt: Date.now(),
        config: activeConfig,
      };
      registered.state = "loaded";
      registered.loadedAt = Date.now();
      registered.errorCount = 0;
      registered.consecutiveFailures = 0;

      this.emit("plugin:loaded", { id: pluginId });

      // 8. Start health checks if enabled
      if (registered.manifest.healthCheck?.enabled) {
        this.startHealthCheckInterval(registered);
      }

    } catch (err) {
      registered.state = "error";
      registered.lastError = err as PluginError;
      registered.errorCount++;
      registered.consecutiveFailures++;

      this.logger.error(`Failed to load plugin ${pluginId}:`, err);
      this.emit("plugin:load-failed", { id: pluginId, error: err });

      throw err;
    }
  }

  async reloadPlugin(pluginId: string): Promise<void> {
    const registered = this.registry.getPlugin(pluginId);
    if (!registered) {
      throw new PluginNotFoundError(pluginId);
    }

    if (registered.state !== "loaded") {
      throw new InvalidStateTransitionError(
        `Cannot reload plugin in state: ${registered.state}`
      );
    }

    try {
      // Preserve config during reload
      const config = registered.activeConfig;

      // Call onReload hook before unloading (for cleanup)
      if (registered.instance?.module.onReload) {
        const promise = registered.instance.module.onReload(registered.instance.api);
        await this.withTimeout(promise, registered.manifest.resources.requestTimeoutMs);
      }

      // Unload current instance
      await this.unloadPlugin(pluginId, { isReload: true });

      // Reload with same config
      await this.loadPlugin(pluginId, config);

      this.emit("plugin:reloaded", { id: pluginId });

    } catch (err) {
      this.logger.error(`Failed to reload plugin ${pluginId}:`, err);
      throw err;
    }
  }

  async unloadPlugin(pluginId: string, options?: { isReload?: boolean }): Promise<void> {
    const registered = this.registry.getPlugin(pluginId);
    if (!registered || registered.state === "unloaded") {
      return;
    }

    try {
      registered.state = "unloading";

      // Stop health checks
      this.stopHealthCheckInterval(pluginId);

      // Stop resource monitoring
      this.stopResourceMonitoring(pluginId);

      // Call onUnload hook
      if (registered.instance?.module.onUnload) {
        const promise = registered.instance.module.onUnload();
        await this.withTimeout(promise, 5000);
      }

      // Clear instance
      registered.instance = null;
      registered.state = "unloaded";

      if (!options?.isReload) {
        this.emit("plugin:unloaded", { id: pluginId });
      }

    } catch (err) {
      this.logger.error(`Error during plugin unload: ${pluginId}`, err);
      // Mark as unloaded anyway to avoid getting stuck
      registered.state = "unloaded";
      registered.instance = null;
    }
  }

  private async withTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
    return Promise.race([
      promise,
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new TimeoutError(`Plugin operation timed out after ${timeoutMs}ms`)), timeoutMs)
      ),
    ]);
  }

  private emit(event: string, data: any): void {
    this.listeners.forEach(listener => listener(event, data));
  }
}
