## 4. Sandboxed Execution Boundary

### 4.1 API Surface & Isolation Model

```typescript
// Plugins ONLY access this API; they cannot access host internals

interface PluginAPI {
  version: string; // e.g., "2.1"

  // Data access: read-only + filtered
  data: {
    getReport(reportId: string): Promise<Report>;
    queryDatasources(filter: DatasourceFilter): Promise<Datasource[]>;
    getDatasourceData(id: string, params: QueryParams): Promise<QueryResult>;
    getCachedData(key: string): Promise<unknown | null>;
    setCachedData(key: string, value: unknown, ttlMs?: number): Promise<void>;
  };

  // Configuration: typed, schema-validated
  config: {
    get<T = any>(key: string): T | undefined;
    set<T = any>(key: string, value: T): Promise<void>;
    getSchema(): JSONSchema;
    validate(config: unknown): ValidationResult;
  };

  // Execution: async only, with timeouts
  execute: {
    query(sql: string, params?: any[]): Promise<QueryResult>;
    transform(data: unknown, transformFn: string): Promise<unknown>;
    schedule(jobName: string, cronExpression: string, handler: () => Promise<void>): Promise<JobHandle>;
  };

  // Events: pub/sub within plugin scope
  events: {
    on(eventName: string, handler: (data: any) => void): void;
    off(eventName: string): void;
    emit(eventName: string, data: any): void;
  };

  // Network: restricted by manifest permissions
  network: {
    fetch(url: string, options?: RequestInit): Promise<Response>;
    openWebSocket(url: string): Promise<WebSocketHandle>;
  };

  // Storage: namespaced, quota-enforced
  storage: {
    get(key: string): Promise<unknown>;
    set(key: string, value: unknown): Promise<void>;
    delete(key: string): Promise<void>;
    list(pattern: string): Promise<string[]>;
    getQuota(): Promise<{ used: number; limit: number }>;
  };

  // Secrets: read-only, declared in manifest
  secrets: {
    get(name: string): Promise<string | undefined>;
  };

  // Logging: captured + indexed
  logger: {
    debug(msg: string, data?: any): void;
    info(msg: string, data?: any): void;
    warn(msg: string, data?: any): void;
    error(msg: string, data?: any): void;
  };

  // Metrics: push to host
  metrics: {
    counter(name: string, value: number, tags?: Record<string, string>): void;
    gauge(name: string, value: number, tags?: Record<string, string>): void;
    histogram(name: string, value: number, tags?: Record<string, string>): void;
  };

  // Plugin metadata
  self: {
    id: string;
    version: string;
    manifest: PluginManifest;
    config: PluginConfig;
  };
}
