### 4.2 Sandbox Implementation

```typescript
class SandboxedAPIFactory {
  createSandboxedAPI(plugin: RegisteredPlugin): PluginAPI {
    const manifest = plugin.manifest;
    const apiVersion = this.selectAPIVersion(plugin);

    return {
      version: apiVersion,

      data: {
        getReport: async (reportId: string) => {
          // Verify capability
          this.assertCapability(plugin, "datasource.read");

          // Call internal report service
          return this.reportService.getReport(reportId);
        },

        queryDatasources: async (filter: DatasourceFilter) => {
          this.assertCapability(plugin, "datasource.read");
          return this.datasourceService.query(filter);
        },

        getDatasourceData: async (id: string, params: QueryParams) => {
          this.assertCapability(plugin, "datasource.read");

          // Check network permission
          const datasource = await this.datasourceService.get(id);
          this.assertNetworkAllowed(plugin, datasource.endpoint);

          return this.datasourceService.queryData(id, params);
        },

        getCachedData: async (key: string) => {
          this.assertCapability(plugin, "cache.read");
          return this.cacheService.get(this.namespaceKey(plugin, key));
        },

        setCachedData: async (key: string, value: unknown, ttlMs?: number) => {
          this.assertCapability(plugin, "cache.write");
          return this.cacheService.set(
            this.namespaceKey(plugin, key),
            value,
            ttlMs
          );
        },
      },

      config: {
        get: (key: string) => plugin.activeConfig[key],

        set: async (key: string, value: any) => {
          // Validate against schema
          const schema = plugin.manifest.configSchema || {};
          this.validateAgainstSchema({ [key]: value }, schema);

          plugin.activeConfig[key] = value;

          // Notify plugin of change
          if (plugin.instance?.module.onConfigChange) {
            try {
              await plugin.instance.module.onConfigChange(plugin.activeConfig);
            } catch (err) {
              this.logger.error(`Config change hook failed for ${plugin.manifest.id}:`, err);
            }
          }
        },

        getSchema: () => plugin.manifest.configSchema || {},

        validate: (config: unknown) => {
          return this.validateAgainstSchema(config, plugin.manifest.configSchema || {});
        },
      },

      execute: {
        query: async (sql: string, params?: any[]) => {
          this.assertCapability(plugin, "query.execute");
          this.assertQueryPermissions(plugin, sql);

          return this.queryEngine.execute(sql, params, {
            timeout: manifest.resources.requestTimeoutMs,
            maxRows: 10000,
          });
        },

        transform: async (data: unknown, transformFn: string) => {
          // Only allow whitelisted transformations
          this.assertTransformAllowed(plugin, transformFn);
          return this.transformService.apply(data, transformFn);
        },

        schedule: async (jobName: string, cronExpression: string, handler: () => Promise<void>) => {
          this.assertCapability(plugin, "scheduler.write");

          const jobId = `${plugin.manifest.id}:${jobName}`;
          return this.schedulerService.schedule(jobId, cronExpression, handler, {
            timeout: manifest.resources.requestTimeoutMs,
          });
        },
      },

      events: {
        on: (eventName: string, handler: (data: any) => void) => {
          // Events are namespaced per plugin
          const namespacedEvent = `${plugin.manifest.id}:${eventName}`;
          this.eventBus.on(namespacedEvent, handler);
        },

        off: (eventName: string) => {
          const namespacedEvent = `${plugin.manifest.id}:${eventName}`;
          this.eventBus.off(namespacedEvent);
        },

        emit: (eventName: string, data: any) => {
          const namespacedEvent = `${plugin.manifest.id}:${eventName}`;
          this.eventBus.emit(namespacedEvent, data);
        },
      },

      network: {
        fetch: async (url: string, options?: RequestInit) => {
          this.assertNetworkAllowed(plugin, url);

          return fetch(url, {
            ...options,
            timeout: manifest.resources.requestTimeoutMs,
            // Headers can be intercepted to add authentication, tracing, etc.
            headers: {
              ...(options?.headers || {}),
              "X-Plugin-Id": plugin.manifest.id,
              "X-Plugin-Version": plugin.manifest.version,
            },
          });
        },

        openWebSocket: async (url: string) => {
          this.assertNetworkAllowed(plugin, url);

          const ws = new WebSocket(url);
          const handle = this.createWebSocketHandle(ws, plugin.manifest.id);

          // Enforce connection limit
          this.enforceConnectionLimit(plugin);

          return handle;
        },
      },

      storage: {
        get: async (key: string) => {
          const nsKey = this.namespaceKey(plugin, key);
          return this.storageService.get(nsKey);
        },

        set: async (key: string, value: unknown) => {
          const nsKey = this.namespaceKey(plugin, key);
          this.enforceStorageQuota(plugin, key, value);
          return this.storageService.set(nsKey, value);
        },

        delete: async (key: string) => {
          const nsKey = this.namespaceKey(plugin, key);
          return this.storageService.delete(nsKey);
        },

        list: async (pattern: string) => {
          const nsPattern = this.namespaceKey(plugin, pattern);
          return this.storageService.list(nsPattern);
        },

        getQuota: async () => {
          return this.storageService.getQuotaForPlugin(plugin.manifest.id);
        },
      },

      secrets: {
        get: async (name: string) => {
          // Check if plugin declared this secret
          const declaredSecrets = manifest.permissions?.secrets?.names || [];
          if (!declaredSecrets.includes(name)) {
            throw new PermissionError(
              `Plugin did not declare access to secret: ${name}`
            );
          }

          return this.secretsService.get(name);
        },
      },

      logger: {
        debug: (msg: string, data?: any) => {
          this.logService.log(plugin.manifest.id, "debug", msg, data);
        },
        info: (msg: string, data?: any) => {
          this.logService.log(plugin.manifest.id, "info", msg, data);
        },
        warn: (msg: string, data?: any) => {
          this.logService.log(plugin.manifest.id, "warn", msg, data);
        },
        error: (msg: string, data?: any) => {
          this.logService.log(plugin.manifest.id, "error", msg, data);
        },
      },

      metrics: {
        counter: (name: string, value: number, tags?: Record<string, string>) => {
          this.metricsService.counter(
            `plugin.${plugin.manifest.id}.${name}`,
            value,
            tags
          );
        },
        gauge: (name: string, value: number, tags?: Record<string, string>) => {
          this.metricsService.gauge(
            `plugin.${plugin.manifest.id}.${name}`,
            value,
            tags
          );
        },
        histogram: (name: string, value: number, tags?: Record<string, string>) => {
          this.metricsService.histogram(
            `plugin.${plugin.manifest.id}.${name}`,
            value,
            tags
          );
        },
      },

      self: {
        id: plugin.manifest.id,
        version: plugin.manifest.version,
        manifest: plugin.manifest,
        config: plugin.activeConfig,
      },
    };
  }

  private assertCapability(plugin: RegisteredPlugin, capability: string): void {
    if (!plugin.manifest.capabilities.includes(capability)) {
      throw new PermissionError(
        `Plugin ${plugin.manifest.id} does not have capability: ${capability}`
      );
    }
  }

  private assertNetworkAllowed(plugin: RegisteredPlugin, url: string): void {
    const permissions = plugin.manifest.permissions;
    if (!permissions?.network) {
      throw new PermissionError("Plugin does not have network permission");
    }

    const allowedDomains = permissions.network.allowedDomains || [];
    const urlDomain = new URL(url).hostname;

    const isAllowed = allowedDomains.some(domain => {
      if (domain.startsWith("*.")) {
        const pattern = new RegExp(`\\.${domain.slice(2)}$`);
        return pattern.test(urlDomain);
      }
      return domain === urlDomain;
    });

    if (!isAllowed) {
      throw new PermissionError(
        `Plugin not allowed to access domain: ${urlDomain}`
      );
    }
  }

  private namespaceKey(plugin: RegisteredPlugin, key: string): string {
    return `plugin:${plugin.manifest.id}:${key}`;
  }

  private selectAPIVersion(plugin: RegisteredPlugin): string {
    // Return highest compatible API version
    const hostAPI = this.getHostAPIVersion();
    const supportedVersions = plugin.manifest.supportsAPIVersions || [];

    return supportedVersions
      .filter(v => isCompatibleAPI(v, hostAPI))
      .sort(compareSemanticVersions)
      .reverse()[0] || "1.0";
  }
}
