### 4.3 Resource Isolation

```typescript
class ResourceMonitor {
  // Per-plugin resource tracking and enforcement

  private limits: Map<string, ResourceLimits>;
  private usage: Map<string, ResourceUsage>;

  startMonitoring(plugin: RegisteredPlugin): void {
    const manifest = plugin.manifest;

    this.limits.set(plugin.manifest.id, {
      memoryMB: manifest.resources.maxMemoryMB,
      storageMB: manifest.resources.maxStorageMB,
      cpuPercent: manifest.resources.maxCPUPercent,
      networkConnections: manifest.resources.maxNetworkConnections,
    });

    this.usage.set(plugin.manifest.id, {
      memoryMB: 0,
      storageMB: 0,
      cpuPercent: 0,
      networkConnections: 0,
      startTime: Date.now(),
    });

    // Start periodic sampling
    this.startResourceSampling(plugin.manifest.id);
  }

  private startResourceSampling(pluginId: string): void {
    const interval = setInterval(() => {
      try {
        const usage = this.sampleResources(pluginId);
        const limits = this.limits.get(pluginId)!;

        // Check limits and trigger warnings/enforcement
        if (usage.memoryMB > limits.memoryMB * 0.9) {
          this.logger.warn(
            `Plugin ${pluginId} approaching memory limit: ${usage.memoryMB}MB / ${limits.memoryMB}MB`
          );
        }

        if (usage.memoryMB > limits.memoryMB) {
          this.enforceMemoryLimit(pluginId);
        }

        this.usage.set(pluginId, usage);
      } catch (err) {
        this.logger.error(`Resource sampling failed for ${pluginId}:`, err);
      }
    }, 5000); // Sample every 5 seconds

    // Cleanup on unload
    const cleanup = () => clearInterval(interval);
    this.cleanupHandlers.set(pluginId, cleanup);
  }

  private enforceMemoryLimit(pluginId: string): void {
    // Trigger garbage collection
    if (global.gc) {
      global.gc();
    }

    // If still over limit, unload plugin
    const usage = this.usage.get(pluginId)!;
    const limits = this.limits.get(pluginId)!;

    if (usage.memoryMB > limits.memoryMB) {
      this.logger.error(
        `Unloading plugin ${pluginId} due to memory exhaustion`
      );
      this.lifecycleManager.unloadPlugin(pluginId);
    }
  }
}
