## 5. Versioned API Contract

### 5.1 API Versioning Strategy

```typescript
// Semantic versioning for both plugins and the host API

interface APIVersion {
  major: number; // Breaking changes
  minor: number; // New features, backward compatible
  patch: number; // Bug fixes
  prerelease?: string; // "alpha", "beta", "rc"
}

// Compatibility matrix:
// Plugin v2.x → API v2.y (any minor version, same major)
// Plugin v2.x → API v1.y (NOT compatible, major version differs)
// Plugin v2.0-beta → API v2.0+ (prerelease compatible with stable)

const COMPATIBILITY_RULES = {
  // Same major version = compatible
  allowMajorDowngrade: false,
  allowMinorDowngrade: false, // Plugins only use features from their declared version

  // Feature matrix per version
  features: {
    "1.0": ["data", "config", "logger"],
    "2.0": ["data", "config", "logger", "execute.query", "storage"],
    "2.1": ["data", "config", "logger", "execute.query", "storage", "metrics", "events"],
    "3.0": ["*"], // All future features
  },
};

// Host must support at least min API version
interface HostAPISupport {
  min: string; // e.g., "1.0"
  max: string; // e.g., "3.5"
  current: string; // e.g., "2.1"
}
