### 5.2 API Evolution & Deprecation

```typescript
// Planned deprecations announced in advance

type DeprecationLevel = "notice" | "warning" | "error";

interface DeprecationPolicy {
  // Minor version: notice (log but don't break)
  notice: {
    level: "info",
    versions: 2, // Two minor versions of notice
  },

  // Next major version: warning (log warnings)
  warning: {
    level: "warn",
    versions: 1, // One major version of warnings
  },

  // Following major: error (break)
  error: {
    level: "error",
    versions: 0, // No grace period, breaks immediately
  },
};

// Example: Deprecating a method
class APIv2_1Adapter implements PluginAPI {
  // New preferred method
  data: {
    getDatasourceData(id: string, params: QueryParams): Promise<QueryResult> {
      return this.datasourceService.queryData(id, params);
    }
  };

  // Deprecated method (marked for removal in v4.0)
  async legacyGetDatasource(id: string): Promise<Datasource> {
    this.logger.warn(
      `legacyGetDatasource is deprecated as of v2.1. Use getDatasourceData instead. ` +
      `Will be removed in v4.0.`
    );
    return this.datasourceService.get(id);
  }
}

// Host provides wrapper to adapt old plugins to new API
class APIAdapter {
  constructor(sourceVersion: string, targetVersion: string) {
    this.sourceVersion = sourceVersion;
    this.targetVersion = targetVersion;
    this.adaptations = this.loadAdaptations(sourceVersion, targetVersion);
  }

  adapt(api: PluginAPI): PluginAPI {
    // Apply transformations for version differences
    for (const adaptation of this.adaptations) {
      api = adaptation.apply(api);
    }
    return api;
  }

  private loadAdaptations(source: string, target: string): Adaptation[] {
    // Adaptations are bidirectional
    // e.g., v1.0 → v2.0 includes wrapping old methods, adding new features

    if (source === "1.0" && target === "2.0") {
      return [
        new LegacyDataAccessAdaptation(),
        new StorageAPIAdaptation(),
        new ExecuteAPIAdaptation(),
      ];
    }

    return [];
  }
}
