export const MyPlugin = PluginSDK.createPlugin({ apiVersion: "2.1", name: "My Plugin" })
  .withCapability("datasource.read")
  .withCapability("cache.write")
  .withHook("onLoad", async (api) => {
    console.log(`Plugin loaded, API version: ${api.version}`);
  })
  .build();
