### 6.3 Error Recovery & Resilience

```typescript
class PluginErrorRecovery {
  // Circuit breaker: stop calling broken plugins
  private circuitBreakers: Map<string, CircuitBreaker>;

  async callPlugin(pluginId: string, method: string, ...args: any[]): Promise<any> {
    const breaker = this.getCircuitBreaker(pluginId);

    try {
      return await breaker.call(async () => {
        const plugin = this.registry.getPlugin(pluginId);
        return plugin.instance!.module[method](...args);
      });
    } catch (err) {
      // Log error, increment counter
      this.handleError(pluginId, err);

      // Decide: retry, degrade, or propagate
      if (this.isRetryable(err)) {
        return this.retry(() => this.callPlugin(pluginId, method, ...args));
      }

      throw err;
    }
  }

  private handleError(pluginId: string, error: Error): void {
    const plugin = this.registry.getPlugin(pluginId)!;

    plugin.errorCount++;
    plugin.consecutiveFailures++;
    plugin.lastError = error;

    // After 5 consecutive failures, unload plugin
    if (plugin.consecutiveFailures >= 5) {
      this.logger.error(
        `Plugin ${pluginId} has failed 5 times consecutively. Unloading.`
      );
      this.lifecycleManager.unloadPlugin(pluginId);
    }

    // Call plugin's error hook
    if (plugin.instance?.module.onError) {
      try {
        plugin.instance.module.onError(error);
      } catch (err) {
        this.logger.error(`Error hook failed for ${pluginId}:`, err);
      }
    }
  }
}
```

