```typescript
// plugin.json
{
  "id": "com.example.postgres",
  "name": "PostgreSQL",
  "version": "2.0.0",
  "apiVersion": "2.1",
  "capabilities": ["datasource.read", "config.encrypted.read"],
  "permissions": {
    "network": { "allowedDomains": ["*.db.example.com"] },
    "secrets": { "names": ["postgres_password"] }
  },
  "resources": { "maxMemoryMB": 512, "requestTimeoutMs": 30000 }
}

// dist/index.js
export default {
  async onLoad(api) {
    const host = api.config.get('host');
    const password = await api.secrets.get('postgres_password');
    this.pool = new Pool({ host, password });
    api.logger.info('Pool initialized', { host });
  },

  async onUnload() {
    await this.pool.end();
  },

  async query(sql, params) {
    try {
      const result = await this.pool.query(sql, params);
      api.metrics.counter('queries', 1, { status: 'ok' });
      return result.rows;
    } catch (err) {
      api.logger.error('Query failed', { sql, error: err.message });
      throw err;
    }
  }
};
```

