 * Plugin Registry - manages plugin discovery, registration, and metadata
 */

import { PluginManifest, PluginInstance, PluginState, DiscoveryCriteria } from '../types.js';
import { v4 as uuidv4 } from 'uuid';

export interface DiscoveryCriteria {
  type?: string;
  tags?: string[];
  state?: PluginState;
  hasCapability?: string;
}

export class PluginRegistry {
  private plugins: Map<string, PluginInstance> = new Map();
  private manifestsByPath: Map<string, PluginManifest> = new Map();

  /**
   * Register a plugin with manifest and location
   */
  registerPlugin(manifest: PluginManifest, location: string): PluginInstance {
    if (this.plugins.has(manifest.id)) {
      throw new Error(`Plugin already registered: ${manifest.id}`);
    }

    const instance: PluginInstance = {
      id: manifest.id,
      manifest,
      state: 'discovered',
      lastStateChange: new Date(),
      activeConfig: {
        id: manifest.id,
        version: manifest.version,
        enabled: false,
        userSettings: manifest.configDefaults || {},
        grantedPermissions: [],
        deniedPermissions: [],
        environment: 'production',
        logLevel: 'info',
      },
      userConfig: {},
      resolvedDependencies: new Map(),
      dependents: new Set(),
      metrics: {
        executionCount: 0,
        totalExecutionTime: 0,
        averageExecutionTime: 0,
        maxExecutionTime: 0,
        memoryUsage: {
          heapUsed: 0,
          heapTotal: 0,
          external: 0,
        },
        permissionRequestCount: 0,
        permissionDeniedCount: 0,
        errorCount: 0,
      },
      errorCount: 0,
      consecutiveErrors: 0,
      isolationLevel: 'worker',
      registeredHooks: new Map(),
    };

    this.plugins.set(manifest.id, instance);
    this.manifestsByPath.set(location, manifest);
    return instance;
  }

  /**
   * Unregister a plugin
   */
  unregisterPlugin(pluginId: string): void {
    this.plugins.delete(pluginId);
  }

  /**
   * Get a registered plugin by ID
   */
  getPlugin(pluginId: string): PluginInstance | undefined {
    return this.plugins.get(pluginId);
  }

  /**
   * Get all registered plugins
   */
  getAllPlugins(): PluginInstance[] {
    return Array.from(this.plugins.values());
  }

  /**
   * Find plugins matching criteria
   */
  find(criteria: DiscoveryCriteria): PluginInstance[] {
    return this.getAllPlugins().filter((plugin) => {
      if (criteria.type && plugin.manifest.type !== criteria.type) return false;
      if (criteria.state && plugin.state !== criteria.state) return false;
      if (criteria.tags && !criteria.tags.some((t) => plugin.manifest.tags.includes(t))) return false;
      if (
        criteria.hasCapability &&
        !plugin.manifest.capabilities.some((c) => c.name === criteria.hasCapability)
      )
        return false;
      return true;
    });
  }

  /**
   * Find plugins by type
   */
  findByType(type: string): PluginInstance[] {
    return this.find({ type });
  }

  /**
   * Find plugins by capability
   */
  findByCapability(capability: string): PluginInstance[] {
    return this.find({ hasCapability: capability });
  }

  /**
   * Update plugin state
   */
  updatePluginState(pluginId: string, newState: PluginState): void {
    const plugin = this.plugins.get(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    plugin.state = newState;
    plugin.lastStateChange = new Date();
  }

  /**
   * Add dependent plugin tracking
   */
  addDependent(parentId: string, dependentId: string): void {
    const parent = this.plugins.get(parentId);
    if (parent) {
      parent.dependents.add(dependentId);
    }
  }

  /**
   * Remove dependent plugin tracking
   */
  removeDependent(parentId: string, dependentId: string): void {
    const parent = this.plugins.get(parentId);
    if (parent) {
      parent.dependents.delete(dependentId);
    }
  }

  /**
   * Clear all plugins (for testing)
   */
  clear(): void {
    this.plugins.clear();
    this.manifestsByPath.clear();
  }

  /**
   * Get registry statistics
   */
  getStats() {
    const states = new Map<PluginState, number>();
    for (const plugin of this.plugins.values()) {
      states.set(plugin.state, (states.get(plugin.state) || 0) + 1);
    }

    return {
      totalPlugins: this.plugins.size,
      byState: Object.fromEntries(states),
      totalCapabilities: Array.from(this.plugins.values()).reduce(
        (sum, p) => sum + p.manifest.capabilities.length,
        0
      ),
    };
  }
}
