 * Plugin Lifecycle Manager - handles load/unload/enable/disable state transitions
 */

import {
  PluginInstance,
  PluginState,
  PluginError,
  PluginModuleExports,
  PluginConfig,
  DependencyResolution,
} from '../types.js';
import { EventEmitter } from 'events';
import { PluginRegistry } from './registry.js';
import { DependencyResolver } from './dependency-resolver.js';

export class PluginLifecycleManager extends EventEmitter {
  private registry: PluginRegistry;
  private dependencyResolver: DependencyResolver;
  private healthMonitors: Map<string, NodeJS.Timer> = new Map();

  private readonly stateTransitions: Map<PluginState, PluginState[]> = new Map([
    ['discovered', ['validating', 'error', 'quarantined']],
    ['validating', ['dependency-check', 'error']],
    ['dependency-check', ['loading', 'error']],
    ['loading', ['loaded', 'error']],
    ['loaded', ['enabling', 'unloading', 'error']],
    ['enabling', ['enabled', 'error']],
    ['enabled', ['disabling', 'error']],
    ['disabling', ['disabled', 'error']],
    ['disabled', ['enabling', 'unloading', 'error']],
    ['error', ['validating', 'quarantined', 'unloading']],
    ['quarantined', ['unloading']],
    ['unloading', ['unloaded', 'error']],
    ['unloaded', []],
  ]);

  constructor(registry: PluginRegistry, dependencyResolver: DependencyResolver) {
    super();
    this.registry = registry;
    this.dependencyResolver = dependencyResolver;
  }

  /**
   * Load a plugin and its dependencies
   */
  async loadPlugin(pluginId: string, config?: Partial<PluginConfig>): Promise<PluginInstance> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    // State: discovered → validating
    await this.transitionState(plugin, 'validating');

    try {
      // Resolve dependencies
      await this.transitionState(plugin, 'dependency-check');
      const deps = await this.dependencyResolver.resolve(plugin.manifest);
      plugin.resolvedDependencies = deps.resolved;

      // Load dependencies first (recursively)
      for (const [depId] of deps.resolved) {
        const depPlugin = this.registry.getPlugin(depId);
        if (depPlugin && depPlugin.state === 'discovered') {
          await this.loadPlugin(depId, config);
        }
      }

      // State: dependency-check → loading
      await this.transitionState(plugin, 'loading');

      // Load module dynamically
      const modulePath = this.resolveModulePath(plugin);
      plugin.loadedModule = await this.loadModuleFromPath(modulePath);
      plugin.moduleInstance = plugin.loadedModule as PluginModuleExports;

      // Validate module exports
      this.validateModuleExports(plugin);

      // Apply config
      if (config) {
        Object.assign(plugin.activeConfig, config);
      }

      // State: loading → loaded
      await this.transitionState(plugin, 'loaded');
      plugin.loadedAt = new Date();

      this.emit('plugin:loaded', { pluginId, manifest: plugin.manifest });
      return plugin;
    } catch (error) {
      await this.handleLoadError(plugin, error as Error);
      throw error;
    }
  }

  /**
   * Enable a loaded plugin
   */
  async enablePlugin(pluginId: string): Promise<void> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);
    if (plugin.state !== 'loaded') {
      throw new Error(`Cannot enable plugin in state ${plugin.state}`);
    }

    await this.transitionState(plugin, 'enabling');

    try {
      // Run onEnable hook
      if (plugin.moduleInstance?.hooks?.onEnable) {
        await this.runHookWithTimeout(plugin.moduleInstance.hooks.onEnable, 30000);
      }

      // Start health monitoring
      this.startHealthMonitoring(plugin);

      // State: enabling → enabled
      await this.transitionState(plugin, 'enabled');
      plugin.enabledAt = new Date();

      this.emit('plugin:enabled', { pluginId });
    } catch (error) {
      await this.transitionState(plugin, 'error');
      throw new Error(`Failed to enable plugin: ${error}`);
    }
  }

  /**
   * Disable an enabled plugin
   */
  async disablePlugin(pluginId: string, reason?: string): Promise<void> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);
    if (plugin.state !== 'enabled') {
      throw new Error(`Cannot disable plugin in state ${plugin.state}`);
    }

    await this.transitionState(plugin, 'disabling');

    try {
      // Stop health monitoring
      this.stopHealthMonitoring(plugin);

      // Run onDisable hook
      if (plugin.moduleInstance?.hooks?.onDisable) {
        await this.runHookWithTimeout(plugin.moduleInstance.hooks.onDisable, 10000);
      }

      // State: disabling → disabled
      await this.transitionState(plugin, 'disabled');

      this.emit('plugin:disabled', { pluginId, reason });
    } catch (error) {
      await this.transitionState(plugin, 'error');
      throw new Error(`Failed to disable plugin: ${error}`);
    }
  }

  /**
   * Reload a plugin (disable → unload → load → enable)
   */
  async reloadPlugin(pluginId: string): Promise<PluginInstance> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    const wasEnabled = plugin.state === 'enabled';

    try {
      if (wasEnabled) {
        await this.disablePlugin(pluginId);
      }

      await this.unloadPlugin(pluginId);

      const config = { ...plugin.activeConfig };
      const loaded = await this.loadPlugin(pluginId, config);

      if (wasEnabled) {
        await this.enablePlugin(pluginId);
      }

      this.emit('plugin:reloaded', { pluginId });
      return loaded;
    } catch (error) {
      this.emit('plugin:reload-failed', { pluginId, error });
      throw error;
    }
  }

  /**
   * Unload a plugin
   */
  async unloadPlugin(pluginId: string): Promise<void> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    // Check for dependents
    if (plugin.dependents.size > 0) {
      throw new Error(`Plugin has dependents: ${Array.from(plugin.dependents).join(', ')}`);
    }

    await this.transitionState(plugin, 'unloading');

    try {
      // Run onUnload hook
      if (plugin.moduleInstance?.hooks?.onUnload) {
        await this.runHookWithTimeout(plugin.moduleInstance.hooks.onUnload, 10000);
      }

      // Clear module
      plugin.moduleInstance = undefined;
      plugin.loadedModule = undefined;

      await this.transitionState(plugin, 'unloaded');

      this.emit('plugin:unloaded', { pluginId });
    } catch (error) {
      await this.transitionState(plugin, 'error');
      throw new Error(`Failed to unload plugin: ${error}`);
    }
  }

  /**
   * Update plugin configuration
   */
  async updatePluginConfig(pluginId: string, config: Partial<PluginConfig>): Promise<void> {
    const plugin = this.registry.getPlugin(pluginId);
    if (!plugin) throw new Error(`Plugin not found: ${pluginId}`);

    const oldConfig = { ...plugin.activeConfig };
    Object.assign(plugin.activeConfig, config);

    try {
      // Run onConfigChange hook
      if (plugin.moduleInstance?.hooks?.onConfigChange) {
        await this.runHookWithTimeout(
          () => plugin.moduleInstance!.hooks!.onConfigChange!(plugin.activeConfig.userSettings),
          10000
        );
      }

      this.emit('plugin:config-changed', { pluginId, oldConfig, newConfig: plugin.activeConfig });
    } catch (error) {
      Object.assign(plugin.activeConfig, oldConfig);
      throw error;
    }
  }

  /**
   * Transition plugin to new state with validation
   */
  private async transitionState(plugin: PluginInstance, newState: PluginState): Promise<void> {
    const allowed = this.stateTransitions.get(plugin.state) || [];

    if (!allowed.includes(newState)) {
      throw new Error(`Invalid state transition: ${plugin.state} → ${newState}`);
    }

    const oldState = plugin.state;
    this.registry.updatePluginState(plugin.id, newState);

    this.emit('plugin:state-changed', {
      pluginId: plugin.id,
      from: oldState,
      to: newState,
      timestamp: new Date(),
    });
  }

  /**
   * Start health monitoring for a plugin
   */
  private startHealthMonitoring(plugin: PluginInstance): void {
    const interval = setInterval(() => {
      // Monitor memory, check if plugin is responsive
      if (plugin.metrics.memoryUsage.heapUsed > 100 * 1024 * 1024) {
        // 100MB limit
        this.handlePluginCrash(plugin, 'Memory exceeded');
      }
    }, 5000);

    this.healthMonitors.set(plugin.id, interval);
  }

  /**
   * Stop health monitoring for a plugin
   */
  private stopHealthMonitoring(plugin: PluginInstance): void {
    const interval = this.healthMonitors.get(plugin.id);
    if (interval) {
      clearInterval(interval);
      this.healthMonitors.delete(plugin.id);
    }
  }

  /**
   * Handle plugin crash
   */
  private async handlePluginCrash(plugin: PluginInstance, reason: string): Promise<void> {
    plugin.lastError = {
      code: 'PLUGIN_CRASH',
      message: `Plugin crashed: ${reason}`,
      timestamp: new Date(),
      severity: 'high',
      recoverable: false,
    };

    plugin.consecutiveErrors++;
    plugin.crashedAt = new Date();
    this.stopHealthMonitoring(plugin);

    // Disable if enabled
    if (plugin.state === 'enabled') {
      await this.disablePlugin(plugin.id, 'crash');
    }

    // Quarantine if too many errors
    if (plugin.consecutiveErrors >= 3) {
      await this.transitionState(plugin, 'quarantined');
      this.emit('plugin:quarantined', {
        pluginId: plugin.id,
        reason: 'Too many consecutive errors',
      });
    }

    this.emit('plugin:crashed', {
      pluginId: plugin.id,
      reason,
      consecutiveErrors: plugin.consecutiveErrors,
    });
  }

  /**
   * Handle load error
   */
  private async handleLoadError(plugin: PluginInstance, error: Error): Promise<void> {
    plugin.lastError = {
      code: error.name,
      message: error.message,
      stack: error.stack,
      timestamp: new Date(),
      severity: 'high',
      recoverable: true,
    };

    plugin.errorCount++;
    plugin.consecutiveErrors++;

    await this.transitionState(plugin, 'error');

    this.emit('plugin:load-error', {
      pluginId: plugin.id,
      error: error.message,
    });
  }

  /**
   * Validate module exports match manifest
   */
  private validateModuleExports(plugin: PluginInstance): void {
    if (!plugin.moduleInstance) throw new Error('Module not loaded');

    for (const [_type, config] of Object.entries(plugin.manifest.entryPoints)) {
      if (!config) continue;

      for (const exportName of config.exports) {
        if (!(exportName in plugin.moduleInstance)) {
          throw new Error(`Required export '${exportName}' not found in module`);
        }
      }
    }
  }

  /**
   * Run a hook with timeout
   */
  private async runHookWithTimeout(hook: Function, timeoutMs: number): Promise<void> {
    return Promise.race([
      Promise.resolve(hook()),
      new Promise<void>((_, reject) => setTimeout(() => reject(new Error('Hook timeout')), timeoutMs)),
    ]);
  }

  /**
   * Resolve module path from manifest
   */
  private resolveModulePath(plugin: PluginInstance): string {
    const entryPoint = Object.values(plugin.manifest.entryPoints)[0];
    if (!entryPoint) throw new Error('No entry points defined');
    return entryPoint.module;
  }

  /**
   * Load module from path (stub implementation)
   */
  private async loadModuleFromPath(path: string): Promise<unknown> {
    // In real implementation, would dynamically require/import the module
    // For now, return a stub
    return {};
  }
