 * Dependency Resolver - resolves plugin dependencies with conflict detection
 */

import { PluginManifest, PluginInstance, DependencyResolution, UnresolvedDependency, DependencyConflict } from '../types.js';
import { satisfies } from 'semver';
import { PluginRegistry } from './registry.js';

export class DependencyResolver {
  private registry: PluginRegistry;

  constructor(registry: PluginRegistry) {
    this.registry = registry;
  }

  /**
   * Resolve all dependencies for a plugin
   */
  async resolve(manifest: PluginManifest): Promise<DependencyResolution> {
    const resolved = new Map<string, PluginInstance>();
    const unresolved: UnresolvedDependency[] = [];
    const conflicts: DependencyConflict[] = [];

    // Resolve required dependencies
    for (const [depId, depVersion] of Object.entries(manifest.dependencies || {})) {
      this.resolveDependency(depId, depVersion, resolved, unresolved);
    }

    // Resolve peer dependencies
    for (const [depId, depVersion] of Object.entries(manifest.peerDependencies || {})) {
      this.resolveDependency(depId, depVersion, resolved, unresolved);
    }

    // Resolve optional dependencies (don't fail if not found)
    for (const [depId, depVersion] of Object.entries(manifest.optionalDependencies || {})) {
      try {
        this.resolveDependency(depId, depVersion, resolved, unresolved);
      } catch {
        // Optional dependencies are allowed to fail
      }
    }

    // Detect conflicts
    this.detectConflicts(Array.from(resolved.values()), conflicts);

    // Compute load order (topological sort)
    const loadOrder = this.computeLoadOrder(manifest.id, resolved);

    return {
      resolved,
      unresolved,
      conflicts,
      loadOrder,
    };
  }

  /**
   * Resolve a single dependency
   */
  private resolveDependency(
    depId: string,
    depVersion: string,
    resolved: Map<string, PluginInstance>,
    unresolved: UnresolvedDependency[]
  ): PluginInstance {
    const depPlugin = this.registry.getPlugin(depId);

    if (!depPlugin) {
      unresolved.push({
        pluginId: depId,
        dependency: depId,
        requestedVersion: depVersion,
        reason: 'not-found',
      });
      throw new Error(`Dependency not found: ${depId}`);
    }

    if (!satisfies(depPlugin.manifest.version, depVersion)) {
      unresolved.push({
        pluginId: depId,
        dependency: depId,
        requestedVersion: depVersion,
        reason: 'version-mismatch',
      });
      throw new Error(`Version mismatch: ${depId} requires ${depVersion}, found ${depPlugin.manifest.version}`);
    }

    resolved.set(depId, depPlugin);
    return depPlugin;
  }

  /**
   * Detect dependency conflicts
   */
  private detectConflicts(plugins: PluginInstance[], conflicts: DependencyConflict[]): void {
    // Check for conflicting plugin types or capabilities
    const byType = new Map<string, string[]>();

    for (const plugin of plugins) {
      const type = plugin.manifest.type;
      if (!byType.has(type)) byType.set(type, []);
      byType.get(type)!.push(plugin.id);
    }

    // Detect conflicting datasources, reporters, etc.
    for (const [type, pluginIds] of byType) {
      if (type === 'datasource' && pluginIds.length > 1) {
        // Warn about multiple datasources
        for (let i = 0; i < pluginIds.length - 1; i++) {
          conflicts.push({
            pluginA: pluginIds[i],
            pluginB: pluginIds[i + 1],
            reason: `Multiple ${type} plugins may conflict`,
          });
        }
      }
    }
  }

  /**
   * Compute topological sort for load order
   */
  private computeLoadOrder(rootId: string, resolved: Map<string, PluginInstance>): string[] {
    const visited = new Set<string>();
    const order: string[] = [];

    const visit = (id: string) => {
      if (visited.has(id)) return;
      visited.add(id);

      const plugin = resolved.get(id);
      if (!plugin) return;

      // Visit dependencies first
      for (const [depId] of plugin.resolvedDependencies) {
        visit(depId);
      }

      order.push(id);
    };

    visit(rootId);
    return order;
  }
}
