 * API Version Manager - handles semantic versioning and backward compatibility
 */

import { APIContract, APICompatibility, CompatibilityAdapter, DeprecationNotice } from '../types.js';
import { major, minor, satisfies } from 'semver';

export class APIVersionManager {
  private contracts: Map<string, APIContract> = new Map();

  /**
   * Register API contract for a version
   */
  registerContract(version: string, contract: APIContract): void {
    this.contracts.set(version, contract);
  }

  /**
   * Validate plugin API version compatibility
   */
  validateAPIVersion(pluginApiVersion: string, hostApiVersion: string): APICompatibility {
    const [pluginMajor, pluginMinor] = pluginApiVersion.split('.').map(Number);
    const [hostMajor, hostMinor] = hostApiVersion.split('.').map(Number);

    // Major version mismatch = incompatible
    if (pluginMajor !== hostMajor) {
      return {
        compatible: false,
        reason: `Major version mismatch: plugin requires ${pluginMajor}.x, host provides ${hostMajor}.x`,
        adaptersAvailable: false,
      };
    }

    // Minor version lower than required = incompatible
    if (pluginMinor > hostMinor) {
      return {
        compatible: false,
        reason: `Plugin requires API ${pluginApiVersion}, but host only provides ${hostApiVersion}`,
        adaptersAvailable: false,
      };
    }

    // Minor version compatible
    const requiredAdapters = this.getRequiredAdapters(pluginMajor, pluginMinor, hostMinor);

    return {
      compatible: true,
      reason: 'Compatible',
      requiredAdapters: requiredAdapters.length > 0 ? requiredAdapters : undefined,
    };
  }

  /**
   * Generate compatibility adapter for version bridging
   */
  generateCompatibilityAdapter(
    pluginApiVersion: string,
    hostApiVersion: string
  ): CompatibilityAdapter {
    const deprecations = this.getDeprecationPath(pluginApiVersion, hostApiVersion);

    const adapter: CompatibilityAdapter = {
      version: hostApiVersion,
      originalVersion: pluginApiVersion,
      wrappers: deprecations.map((dep) => ({
        oldApi: dep.api,
        newApi: dep.replacement || dep.api,
        wrapper: this.createAPIWrapper(dep.api, dep.replacement || dep.api),
      })),
      warnings: deprecations.map((dep) => ({
        api: dep.api,
        message: dep.message,
        removedIn: dep.removedIn,
      })),
    };

    return adapter;
  }

  /**
   * Create wrapper function for deprecated API
   */
  private createAPIWrapper(oldApi: string, newApi: string): Function {
    return function (...args: any[]) {
      console.warn(`[DEPRECATION] API '${oldApi}' is deprecated, use '${newApi}' instead`);

      if (typeof this[newApi] === 'function') {
        return this[newApi].apply(this, args);
      }

      throw new Error(`Adapter failed: ${newApi} not found`);
    };
  }

  /**
   * Get required adapters between versions
   */
  private getRequiredAdapters(major: number, minorRequired: number, minorHost: number): string[] {
    const adapters: string[] = [];

    for (let minor = minorRequired; minor < minorHost; minor++) {
      const version = `${major}.${minor}.0`;
      const contract = this.contracts.get(version);

      if (contract?.deprecatedApis) {
        adapters.push(...contract.deprecatedApis.map((d) => d.api));
      }
    }

    return Array.from(new Set(adapters)); // Remove duplicates
  }

  /**
   * Get deprecation path between versions
   */
  private getDeprecationPath(fromVersion: string, toVersion: string): DeprecationNotice[] {
    const deprecations: DeprecationNotice[] = [];
    const [fromMinor] = fromVersion.split('.').map(Number);
    const [toMinor] = toVersion.split('.').map(Number);

    for (let minor = fromMinor; minor < toMinor; minor++) {
      const version = `1.${minor}.0`; // Assuming major version 1
      const contract = this.contracts.get(version);

      if (contract?.deprecatedApis) {
        deprecations.push(...contract.deprecatedApis);
      }
    }

    return deprecations;
  }

  /**
   * Get all APIs available in a version
   */
  getAvailableAPIs(version: string): string[] {
    const contract = this.contracts.get(version);
    if (!contract) return [];

    const apis: string[] = [];

    if (contract.newApis) {
      apis.push(...contract.newApis.map((a) => a.name));
    }

    if (contract.deprecatedApis) {
      apis.push(...contract.deprecatedApis.map((d) => d.api));
    }

    return apis;
  }

  /**
   * Check if API is deprecated in version
   */
  isDeprecated(apiName: string, version: string): boolean {
    const contract = this.contracts.get(version);
    if (!contract?.deprecatedApis) return false;

    return contract.deprecatedApis.some((d) => d.api === apiName);
  }

  /**
   * Get deprecation details
   */
  getDeprecationDetails(apiName: string, version: string): DeprecationNotice | undefined {
    const contract = this.contracts.get(version);
    if (!contract?.deprecatedApis) return undefined;

    return contract.deprecatedApis.find((d) => d.api === apiName);
  }
}

/**
 * Pre-defined API contracts for version 1.x
 */
export function createDefaultAPIContracts(): Map<string, APIContract> {
  const contracts = new Map<string, APIContract>();

  // API v1.0.0
  contracts.set('1.0.0', {
    major: 1,
    minor: 0,
    patch: 0,
    stable: true,
    newApis: [
      {
        name: 'Reporter.generate',
        signature: 'async generate(config: GenerateConfig): Promise<Report>',
        since: '1.0.0',
      },
      {
        name: 'DataSource.query',
        signature: 'async query(sql: string, params?: Record<string, any>): Promise<Row[]>',
        since: '1.0.0',
      },
    ],
  });

  // API v1.1.0 - Add streaming
  contracts.set('1.1.0', {
    major: 1,
    minor: 1,
    patch: 0,
    stable: true,
    newApis: [
      {
        name: 'Reporter.generateStream',
        signature: 'generateStream(config: GenerateConfig): AsyncIterable<Chunk>',
        since: '1.1.0',
      },
    ],
  });

  // API v1.2.0 - Deprecate old query
  contracts.set('1.2.0', {
    major: 1,
    minor: 2,
    patch: 0,
    stable: true,
    deprecatedApis: [
      {
        api: 'DataSource.query',
        since: '1.2.0',
        removedIn: '2.0.0',
        replacement: 'DataSource.execute',
        message: 'Use execute() for better streaming support',
      },
    ],
    newApis: [
      {
        name: 'DataSource.execute',
        signature: 'execute(sql: string, params?: Record<string, any>): QueryResult',
        since: '1.2.0',
      },
    ],
  });

  return contracts;
}
