 * Plugin Validator - multi-stage validation pipeline
 */

import { PluginManifest, ValidationResult, StageResult, ValidationError, ValidationWarning } from '../types.js';
import Ajv from 'ajv';
import { PLUGIN_MANIFEST_SCHEMA } from '../core/manifest-schema.js';

export interface ValidatorStage {
  name: string;
  optional?: boolean;
  validate(manifest: PluginManifest, moduleSource?: string): Promise<StageResult>;
}

export class PluginValidator {
  private validators: ValidatorStage[];

  constructor() {
    this.validators = [
      new ManifestStructureValidator(),
      new ManifestSchemaValidator(),
      new DependencyValidator(),
      new SecurityValidator(),
    ];
  }

  /**
   * Run complete validation pipeline
   */
  async validate(manifest: PluginManifest, moduleSource?: string): Promise<ValidationResult> {
    const results: StageResult[] = [];

    for (const validator of this.validators) {
      const result = await validator.validate(manifest, moduleSource);
      results.push(result);

      // Fail fast on critical errors
      if (result.severity === 'critical' && result.errors.length > 0) {
        return {
          valid: false,
          stages: results,
          firstError: result.errors[0],
        };
      }
    }

    const hasErrors = results.some((r) => r.errors.length > 0);
    const hasWarnings = results.some((r) => r.warnings.length > 0);

    return {
      valid: !hasErrors,
      stages: results,
      warnings: results.flatMap((r) => r.warnings),
      errors: results.flatMap((r) => r.errors),
      hasWarnings,
    };
  }
}

/**
 * Stage 1: Manifest structure validation
 */
class ManifestStructureValidator implements ValidatorStage {
  name = 'structure';

  async validate(manifest: PluginManifest): Promise<StageResult> {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Check required fields
    const requiredFields = ['id', 'name', 'version', 'type', 'author', 'entryPoints'];
    for (const field of requiredFields) {
      if (!manifest[field as keyof PluginManifest]) {
        errors.push({
          field,
          message: `Required field '${field}' is missing`,
          severity: 'critical',
        });
      }
    }

    // Validate ID format (reverse DNS)
    if (manifest.id && !manifest.id.match(/^@?[a-z0-9-]+\/[a-z0-9-]+$/)) {
      errors.push({
        field: 'id',
        message: "Plugin ID must follow format '@vendor/name' or 'vendor/name'",
        severity: 'critical',
      });
    }

    // Validate version format (semver)
    if (manifest.version && !manifest.version.match(/^\d+\.\d+\.\d+(-[a-z0-9.]+)?(\+[a-z0-9.]+)?$/i)) {
      errors.push({
        field: 'version',
        message: 'Version must follow semantic versioning: MAJOR.MINOR.PATCH',
        severity: 'critical',
      });
    }

    return {
      stage: 'structure',
      severity: 'critical',
      errors,
      warnings,
    };
  }
}

/**
 * Stage 2: JSON Schema validation
 */
class ManifestSchemaValidator implements ValidatorStage {
  name = 'schema';
  private ajv = new Ajv();

  async validate(manifest: PluginManifest): Promise<StageResult> {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    const validate = this.ajv.compile(PLUGIN_MANIFEST_SCHEMA);
    const valid = validate(manifest as any);

    if (!valid && validate.errors) {
      for (const error of validate.errors) {
        errors.push({
          field: error.instancePath || '/',
          message: error.message || 'Schema validation failed',
          severity: 'critical',
        });
      }
    }

    return {
      stage: 'schema',
      severity: 'critical',
      errors,
      warnings,
    };
  }
}

/**
 * Stage 3: Dependency validation
 */
class DependencyValidator implements ValidatorStage {
  name = 'dependencies';

  async validate(manifest: PluginManifest): Promise<StageResult> {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Validate dependency version format
    for (const [depId, depVersion] of Object.entries(manifest.dependencies || {})) {
      if (!this.isValidSemverRange(depVersion)) {
        errors.push({
          field: `dependencies.${depId}`,
          message: `Invalid version range: ${depVersion}`,
          severity: 'high',
        });
      }
    }

    // Warn about many dependencies
    const depCount = Object.keys(manifest.dependencies || {}).length;
    if (depCount > 10) {
      warnings.push({
        field: 'dependencies',
        message: `Plugin has many dependencies (${depCount}), consider reducing`,
        severity: 'medium',
      });
    }

    return {
      stage: 'dependencies',
      severity: 'high',
      errors,
      warnings,
    };
  }

  private isValidSemverRange(range: string): boolean {
    // Simple validation - just check if it looks like a version range
    return /^[~^>=<\d.]/.test(range);
  }
}

/**
 * Stage 4: Security analysis
 */
class SecurityValidator implements ValidatorStage {
  name = 'security';

  async validate(manifest: PluginManifest, moduleSource?: string): Promise<StageResult> {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Check capability levels
    for (const cap of manifest.capabilities) {
      if (cap.level === 'critical' && !cap.justification) {
        warnings.push({
          field: 'capabilities',
          message: `Critical capability '${cap.name}' should have a detailed justification`,
          severity: 'high',
        });
      }
    }

    // Check for excessive permissions
    const permCount = manifest.requiredPermissions.length;
    if (permCount > 15) {
      warnings.push({
        field: 'requiredPermissions',
        message: `Plugin requests many permissions (${permCount}), consider principle of least privilege`,
        severity: 'medium',
      });
    }

    // Check for dangerous patterns in module source
    if (moduleSource) {
      if (moduleSource.includes('eval(') && !manifest.requiredPermissions.some((p) => p.id === 'eval')) {
        warnings.push({
          field: 'module',
          message: 'Module uses eval() - declare permission for dynamic code execution',
          severity: 'high',
        });
      }
    }

    return {
      stage: 'security',
      severity: 'high',
      errors,
      warnings,
    };
  }
}
