    return sandboxId;
  }

  async destroySandbox(sandboxId: string): Promise<void> {
    const worker = this.workers.get(sandboxId);
    if (worker) {
      worker.terminate?.();
      this.workers.delete(sandboxId);
      this.limits.delete(sandboxId);
