}

/**
 * VM Context Sandbox - lightweight V8 context isolation
 */
export class VMContextSandbox extends SandboxManager {
  private contexts: Map<string, any> = new Map();
  private limits: Map<string, ResourceLimits> = new Map();

  async createSandbox(plugin: PluginInstance, limits: ResourceLimits): Promise<string> {
    const { v4: uuidv4 } = await import('uuid');
    const vm = await import('vm');

    const sandboxId = `vm-${uuidv4()}`;

    // Create restricted context
    const context = vm.createContext({
      console,
      Buffer,
      Math,
      Date,
      JSON,
      __pluginId: plugin.id,
      __sandboxId: sandboxId,
    });

    this.contexts.set(sandboxId, context);
    this.limits.set(sandboxId, limits);

    return sandboxId;
  }

  async destroySandbox(sandboxId: string): Promise<void> {
    this.contexts.delete(sandboxId);
    this.limits.delete(sandboxId);
  }

  async executeInSandbox<T>(
    sandboxId: string,
    code: string,
    _context?: Record<string, unknown>
  ): Promise<T> {
    const vmContext = this.contexts.get(sandboxId);
    if (!vmContext) throw new Error(`Sandbox not found: ${sandboxId}`);

    const limits = this.limits.get(sandboxId);
    const timeout = limits?.timeout || 30000;

    const vm = await import('vm');
    const script = new vm.Script(code);

    return new Promise((resolve, reject) => {
      try {
        const result = script.runInContext(vmContext, { timeout });
        resolve(result as T);
      } catch (error) {
        reject(error);
      }
    });
  }

  checkHealth(sandboxId: string): SandboxHealth {
    const context = this.contexts.get(sandboxId);

    return {
      alive: !!context,
      crashed: false,
      memoryUsage: 0,
      memoryExceeded: false,
      cpuUsage: 0,
      responseTimeout: false,
    };
  }

  async enforceResourceLimits(sandboxId: string, limits: ResourceLimits): Promise<void> {
    if (this.contexts.has(sandboxId)) {
      this.limits.set(sandboxId, limits);
    }
  }
}

/**
 * Permission Enforcer - gates sandbox operations
 */
export class PermissionEnforcer {
  private permissionGrants: Map<string, Set<string>> = new Map();
  private denials: Map<string, number> = new Map(); // Track denials for audit

  checkPermission(
    sandboxId: string,
    resource: string,
    action: string,
    scope?: string
  ): boolean {
    const key = `${resource}:${action}`;
    const granted = this.permissionGrants.get(key)?.has(sandboxId) || false;

    if (!granted) {
      const denyKey = `${sandboxId}:${key}`;
      this.denials.set(denyKey, (this.denials.get(denyKey) || 0) + 1);
    }

    return granted;
  }

  grantPermission(sandboxId: string, resource: string, action: string): void {
    const key = `${resource}:${action}`;
    if (!this.permissionGrants.has(key)) {
      this.permissionGrants.set(key, new Set());
    }
    this.permissionGrants.get(key)!.add(sandboxId);
  }

  denyPermission(sandboxId: string, resource: string, action: string): void {
    const key = `${resource}:${action}`;
    const granted = this.permissionGrants.get(key);
    if (granted) {
      granted.delete(sandboxId);
    }
  }

  /**
   * Get denial audit log
   */
  getDenialLog(sandboxId: string): Array<[string, number]> {
    const log: Array<[string, number]> = [];
    for (const [key, count] of this.denials) {
      if (key.startsWith(sandboxId)) {
        const permission = key.substring(sandboxId.length + 1);
        log.push([permission, count]);
      }
    }
    return log;
  }
}
