import { PluginInstance, PluginLogEntry } from '../types.js';

export class PluginMetricsCollector {
  private metrics: Map<string, number> = new Map();
  private gauges: Map<string, number> = new Map();

  /**
   * Record plugin execution
   */
  recordExecution(pluginId: string, operation: string, durationMs: number, success: boolean): void {
    const key = `exec_time:${pluginId}:${operation}`;
    const count = (this.metrics.get(`exec_count:${pluginId}`) || 0) + 1;

    this.metrics.set(`exec_count:${pluginId}`, count);
    this.metrics.set(`exec_time_total:${pluginId}`, (this.metrics.get(`exec_time_total:${pluginId}`) || 0) + durationMs);

    if (durationMs > (this.metrics.get(`exec_time_max:${pluginId}`) || 0)) {
      this.metrics.set(`exec_time_max:${pluginId}`, durationMs);
    }

    if (!success) {
      this.metrics.set(`exec_errors:${pluginId}`, (this.metrics.get(`exec_errors:${pluginId}`) || 0) + 1);
    }
  }

  /**
   * Record permission denial
   */
  recordPermissionDenial(pluginId: string, resource: string, action: string): void {
    const key = `perm_denied:${pluginId}:${resource}:${action}`;
    this.metrics.set(key, (this.metrics.get(key) || 0) + 1);
  }

  /**
   * Record state change
   */
  recordStateChange(pluginId: string, fromState: string, toState: string): void {
    const key = `state_change:${pluginId}:${fromState}->${toState}`;
    this.metrics.set(key, (this.metrics.get(key) || 0) + 1);
  }

  /**
   * Record memory usage
   */
  recordMemory(pluginId: string, bytes: number): void {
    this.gauges.set(`memory:${pluginId}`, bytes);
  }

  /**
   * Get metric value
   */
  getMetric(key: string): number {
    return this.metrics.get(key) || 0;
  }

  /**
   * Get gauge value
   */
  getGauge(key: string): number {
    return this.gauges.get(key) || 0;
  }

  /**
   * Get all metrics
   */
  getAllMetrics(): Record<string, number> {
    return Object.fromEntries(this.metrics);
  }

  /**
   * Get all gauges
   */
  getAllGauges(): Record<string, number> {
    return Object.fromEntries(this.gauges);
  }

  /**
   * Export metrics in Prometheus format
   */
  exportPrometheus(): string {
    const lines: string[] = [];

    for (const [key, value] of this.metrics) {
      lines.push(`plugin_${key} ${value}`);
    }

    for (const [key, value] of this.gauges) {
      lines.push(`plugin_${key} ${value}`);
    }

    return lines.join('\n');
  }

  /**
   * Clear all metrics (for testing)
   */
  clear(): void {
    this.metrics.clear();
    this.gauges.clear();
  }
}

/**
 * Plugin Logger - structured logging
 */
export class PluginLogger {
  private logs: PluginLogEntry[] = [];
  private maxLogs: number = 10000;

  /**
   * Log an entry
   */
  log(entry: PluginLogEntry): void {
    this.logs.push({
      ...entry,
      timestamp: new Date().toISOString() as any,
    });

    // Keep logs bounded
    if (this.logs.length > this.maxLogs) {
      this.logs.shift();
    }

    // Console output
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] [${entry.level.toUpperCase()}] [${entry.pluginId}] ${entry.message}`);
  }

  /**
   * Get logs
   */
  getLogs(pluginId?: string, level?: string, limit?: number): PluginLogEntry[] {
    let filtered = this.logs;

    if (pluginId) {
      filtered = filtered.filter((l) => l.pluginId === pluginId);
    }

    if (level) {
      filtered = filtered.filter((l) => l.level === level);
    }

    if (limit) {
      filtered = filtered.slice(-limit);
    }

    return filtered;
  }

  /**
   * Clear logs (for testing)
   */
  clear(): void {
    this.logs = [];
  }
}

/**
 * Health check provider
 */
export class PluginSystemHealth {
  constructor(
    private pluginInstances: Map<string, PluginInstance>,
    private metricsCollector: PluginMetricsCollector,
    private logger: PluginLogger
  ) {}

  /**
   * Get system health status
   */
  getHealth() {
    const plugins = Array.from(this.pluginInstances.values());
    const states = new Map<string, number>();

    for (const plugin of plugins) {
      states.set(plugin.state, (states.get(plugin.state) || 0) + 1);
    }

    const errorCount = plugins.filter((p) => p.state === 'error').length;
    const quarantinedCount = plugins.filter((p) => p.state === 'quarantined').length;

    return {
      status:
        quarantinedCount > 0 || errorCount > 3
          ? 'degraded'
          : errorCount > 0
            ? 'degraded'
            : 'healthy',
      timestamp: new Date().toISOString(),
      plugins: {
        total: plugins.length,
        loaded: (states.get('loaded') || 0) + (states.get('enabled') || 0),
        enabled: states.get('enabled') || 0,
        errors: errorCount,
        quarantined: quarantinedCount,
        byState: Object.fromEntries(states),
      },
      system: {
        uptime: process.uptime(),
      },
      recentErrors: plugins
        .filter((p) => p.lastError)
        .map((p) => p.lastError!)
        .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime())
        .slice(0, 10),
    };
  }
}
