 * PluginSystem - Main orchestrator for the plugin architecture
 */

import { EventEmitter } from 'events';
import {
  PluginManifest,
  PluginInstance,
  PluginState,
  PluginConfig,
  HealthStatus,
  ResourceLimits,
} from './types.js';
import { PluginRegistry } from './core/registry.js';
import { PluginLifecycleManager } from './core/lifecycle-manager.js';
import { DependencyResolver } from './core/dependency-resolver.js';
import { APIVersionManager, createDefaultAPIContracts } from './api/version-manager.js';
import { PluginValidator } from './validation/validator.js';
import { WorkerThreadSandbox, SandboxManager, PermissionEnforcer } from './sandbox/sandbox-manager.js';
import { PluginMetricsCollector, PluginLogger, PluginSystemHealth } from './observability/metrics.js';

export interface PluginSystemConfig {
  apiVersion: string;
  hostVersion: string;
  sandbox: {
    type: 'worker' | 'vm' | 'process';
    resourceLimits: ResourceLimits;
  };
  validation: {
    requireSignatures: boolean;
    validateAll: boolean;
  };
  monitoring: {
    enabled: boolean;
    metricsPort?: number;
  };
}

export class PluginSystem extends EventEmitter {
  private registry: PluginRegistry;
  private lifecycleManager: PluginLifecycleManager;
  private dependencyResolver: DependencyResolver;
  private validator: PluginValidator;
  private apiVersionManager: APIVersionManager;
  private sandboxManager: SandboxManager;
  private permissionEnforcer: PermissionEnforcer;
  private metricsCollector: PluginMetricsCollector;
  private logger: PluginLogger;
  private healthCheck: PluginSystemHealth;
  private config: PluginSystemConfig;

  constructor(config: Partial<PluginSystemConfig> = {}) {
    super();

    this.config = {
      apiVersion: config.apiVersion || '1.0',
      hostVersion: config.hostVersion || '1.0.0',
      sandbox: config.sandbox || {
        type: 'worker',
        resourceLimits: {
          maxMemoryMb: 512,
          maxCpuPercent: 50,
          maxFileDescriptors: 1000,
          maxNetworkConnections: 10,
          timeout: 30000,
        },
      },
      validation: config.validation || {
        requireSignatures: false,
        validateAll: false,
      },
      monitoring: config.monitoring || {
        enabled: true,
      },
    };

    // Initialize components
    this.registry = new PluginRegistry();
    this.dependencyResolver = new DependencyResolver(this.registry);
    this.lifecycleManager = new PluginLifecycleManager(this.registry, this.dependencyResolver);
    this.validator = new PluginValidator();
    this.apiVersionManager = new APIVersionManager();

    // Initialize API contracts
    const contracts = createDefaultAPIContracts();
    for (const [version, contract] of contracts) {
      this.apiVersionManager.registerContract(version, contract);
    }

    // Initialize sandbox
    this.sandboxManager = new WorkerThreadSandbox();
    this.permissionEnforcer = new PermissionEnforcer();

    // Initialize monitoring
    this.metricsCollector = new PluginMetricsCollector();
    this.logger = new PluginLogger();
    this.healthCheck = new PluginSystemHealth(this.registry['plugins'], this.metricsCollector, this.logger);

    // Wire up events
    this.wireUpEvents();
  }

  /**
   * Register a plugin from manifest
   */
  async registerPlugin(manifest: PluginManifest, location: string): Promise<PluginInstance> {
    // Validate manifest
    const validation = await this.validator.validate(manifest);
    if (!validation.valid) {
      throw new Error(`Plugin validation failed: ${validation.errors?.[0]?.message}`);
    }

    // Check API version compatibility
    const compatibility = this.apiVersionManager.validateAPIVersion(
      manifest.apiVersion,
      this.config.apiVersion
    );
    if (!compatibility.compatible) {
      throw new Error(`API incompatible: ${compatibility.reason}`);
    }

    // Register in registry
    const instance = this.registry.registerPlugin(manifest, location);

    this.emit('plugin:registered', { pluginId: instance.id });
    this.logger.log({
      level: 'info',
      pluginId: instance.id,
      event: 'registered',
      message: `Plugin registered: ${manifest.name}`,
    });

    return instance;
  }

  /**
   * Load a plugin
   */
  async loadPlugin(pluginId: string, config?: Partial<PluginConfig>): Promise<PluginInstance> {
    const startTime = Date.now();

    try {
      const instance = await this.lifecycleManager.loadPlugin(pluginId, config);

      const duration = Date.now() - startTime;
      this.metricsCollector.recordExecution(pluginId, 'load', duration, true);

      this.logger.log({
        level: 'info',
        pluginId,
        event: 'loaded',
        message: `Plugin loaded in ${duration}ms`,
      });

      return instance;
    } catch (error) {
      const duration = Date.now() - startTime;
      this.metricsCollector.recordExecution(pluginId, 'load', duration, false);

      this.logger.log({
        level: 'error',
        pluginId,
        event: 'load-failed',
        message: `Failed to load: ${error}`,
      });

      throw error;
    }
  }

  /**
   * Enable a plugin
   */
  async enablePlugin(pluginId: string): Promise<void> {
    try {
      await this.lifecycleManager.enablePlugin(pluginId);

      this.logger.log({
        level: 'info',
        pluginId,
        event: 'enabled',
        message: 'Plugin enabled',
      });
    } catch (error) {
      this.logger.log({
        level: 'error',
        pluginId,
        event: 'enable-failed',
        message: `Failed to enable: ${error}`,
      });

      throw error;
    }
  }

  /**
   * Disable a plugin
   */
  async disablePlugin(pluginId: string, reason?: string): Promise<void> {
    await this.lifecycleManager.disablePlugin(pluginId, reason);
  }

  /**
   * Reload a plugin
   */
  async reloadPlugin(pluginId: string): Promise<PluginInstance> {
    return this.lifecycleManager.reloadPlugin(pluginId);
  }

  /**
   * Unload a plugin
   */
  async unloadPlugin(pluginId: string): Promise<void> {
    await this.lifecycleManager.unloadPlugin(pluginId);
  }

  /**
   * Get a plugin
   */
  getPlugin(pluginId: string): PluginInstance | undefined {
    return this.registry.getPlugin(pluginId);
  }

  /**
   * List all plugins
   */
  listPlugins(filter?: { state?: PluginState; type?: string }): PluginInstance[] {
    if (!filter) {
      return this.registry.getAllPlugins();
    }

    return this.registry.find(filter);
  }

  /**
   * Get system health
   */
  getHealth(): HealthStatus {
    return this.healthCheck.getHealth();
  }

  /**
   * Get metrics
   */
  getMetrics() {
    return {
      counters: this.metricsCollector.getAllMetrics(),
      gauges: this.metricsCollector.getAllGauges(),
    };
  }

  /**
   * Get logs
   */
  getLogs(pluginId?: string, limit?: number) {
    return this.logger.getLogs(pluginId, undefined, limit);
  }

  /**
   * Wire up event listeners for internal components
   */
  private wireUpEvents(): void {
    this.lifecycleManager.on('plugin:state-changed', (event) => {
      this.metricsCollector.recordStateChange(event.pluginId, event.from, event.to);
      this.emit('plugin:state-changed', event);
    });

    this.lifecycleManager.on('plugin:loaded', (event) => {
      this.emit('plugin:loaded', event);
    });

    this.lifecycleManager.on('plugin:enabled', (event) => {
      this.emit('plugin:enabled', event);
    });

    this.lifecycleManager.on('plugin:disabled', (event) => {
      this.emit('plugin:disabled', event);
    });

    this.lifecycleManager.on('plugin:crashed', (event) => {
      this.emit('plugin:crashed', event);
    });
  }
}
