## Creating a Plugin

### Step 1: Define Manifest

Create `plugin.manifest.yaml`:

```yaml
id: "@mycompany/my-reporter"
name: "My Reporter"
version: "1.0.0"
type: "reporter"
apiVersion: "1.2"
hostVersionRange: ">=1.0.0 <2.0.0"

author:
  name: "Your Name"
  email: "you@company.com"

description: "My custom reporter plugin"

entryPoints:
  reporter:
    module: "./dist/reporter.js"
    exports: ["MyReporter"]
    class: "MyReporter"

capabilities:
  - name: "database.read"
    level: "medium"
    justification: "Read report data"

requiredPermissions:
  - id: "db"
    resource: "database"
    action: "read"
    scope: "/reports/**"
    reason: "Access report database"
```

### Step 2: Implement Plugin Class

Create `src/reporter.ts`:

```typescript
import { PluginModuleExports } from '@company/reporting-plugin-system';

interface GenerateConfig {
  template: string;
  dateRange: string;
  format: 'pdf' | 'xlsx' | 'html';
}

interface Report {
  id: string;
  content: Buffer;
  format: string;
}

export class MyReporter implements PluginModuleExports {
  version = "1.0.0";
  apiVersion = "1.2";

  capabilities = [
    {
      name: "database.read",
      level: "medium",
      justification: "Read report data",
    },
  ];

  async generate(config: GenerateConfig): Promise<Report> {
    // Fetch data, generate report
    const content = Buffer.from("Report content");

    return {
      id: `report-${Date.now()}`,
      content,
      format: config.format,
    };
  }

  async generateStream(config: GenerateConfig) {
    // Streaming implementation for large reports
    async function* generateChunks() {
      yield { data: "Header" };
      yield { data: "Body" };
      yield { data: "Footer" };
    }

    return generateChunks();
  }

  hooks = {
    async onLoad() {
      console.log("MyReporter plugin loaded");
      // Initialize resources
    },

    async onEnable() {
      console.log("MyReporter plugin enabled");
      // Start services, connect to DB, etc.
    },

    async onDisable() {
      console.log("MyReporter plugin disabled");
      // Cleanup
    },

    async onConfigChange(newConfig: Record<string, unknown>) {
      console.log("Config changed:", newConfig);
      // Apply new configuration
    },

    async onUnload() {
      console.log("MyReporter plugin unloading");
      // Final cleanup
    },
  };
}
```

### Step 3: Create Entry Point

Create `src/index.ts`:

```typescript
export { MyReporter } from './reporter.js';
```

### Step 4: Build and Package

```bash
npm run build

# Create tarball for distribution
npm pack
```

