```typescript
import { PluginSystem } from '@company/reporting-plugin-system';

export class MyReporter {
  constructor(private pluginSystem: PluginSystem) {}

  async onLoad() {
    // Access dependency plugin
    const datasource = this.pluginSystem.getPlugin('@company/datasource-sales');

    if (datasource?.state === 'enabled') {
      // Use the dependency
      console.log('Datasource is available');
    }
  }

  async generate(config: GenerateConfig) {
    const datasource = this.pluginSystem.getPlugin('@company/datasource-sales');

    if (!datasource || datasource.state !== 'enabled') {
      throw new Error('Required datasource plugin not available');
    }

    // Call dependency's exported functions
    const data = await datasource.moduleInstance.query({
      sql: 'SELECT * FROM sales'
    });

    // Generate report from data
    return this.generateReportFromData(data);
  }
}
```

