export class MyReporter implements PluginModuleExports {
  private config: any;

  async onConfigChange(newConfig: Record<string, unknown>) {
    // Validate configuration
    const valid = validateConfig(newConfig);
    if (!valid) {
      throw new Error('Invalid configuration');
    }

    // Apply configuration
    this.config = newConfig;
  }

  async generate(config: GenerateConfig) {
    // Use plugin configuration
    const format = this.config.outputFormat || 'pdf';
