 * API versioning and contract management.
 * Handles semantic versioning, deprecations, and compatibility checks.
 */

import { APIVersion, APIContract, CompatibilityRange, DeprecationInfo } from './plugin-types';

export class APIContractManager {
  private currentVersion: APIVersion = { major: 1, minor: 0, patch: 0 };
  private deprecations: Map<string, DeprecationInfo> = new Map();
  private compatibility: CompatibilityRange = { min: '0.1.0' };

  constructor() {
    this.initializeDeprecations();
  }

  private initializeDeprecations(): void {
    // Examples of deprecation tracking
    this.deprecations.set('api.reports.getLegacy', {
      feature: 'api.reports.getLegacy',
      removedInVersion: '2.0.0',
      alternative: 'api.reports.get',
      message: 'getLegacy is deprecated. Use get() instead with the same parameters.',
    });
  }

  /**
   * Check if a plugin's required API version is compatible with current version
   */
  isApiVersionCompatible(requiredVersion: string): boolean {
    const required = this.parseVersion(requiredVersion);
    const current = this.currentVersion;

    // Major mismatch always fails
    if (required.major > current.major) {
      return false;
    }

    // Same major: minor/patch must not exceed current
    if (required.major === current.major) {
      if (required.minor > current.minor) {
        return false;
      }
      if (required.minor === current.minor && required.patch > current.patch) {
        return false;
      }
    }

    return true;
  }

  /**
   * Check if a plugin version satisfies a semver range
   */
  satisfiesSemverRange(version: string, range: string): boolean {
    // Simplified semver range matching (^, >=, etc.)
    if (range.startsWith('^')) {
      const rangeVer = this.parseVersion(range.slice(1));
      const ver = this.parseVersion(version);
      return (
        ver.major === rangeVer.major &&
        (ver.minor > rangeVer.minor ||
          (ver.minor === rangeVer.minor && ver.patch >= rangeVer.patch))
      );
    }

    if (range.startsWith('>=')) {
      const rangeVer = this.parseVersion(range.slice(2));
      const ver = this.parseVersion(version);
      return this.compareVersions(ver, rangeVer) >= 0;
    }

    if (range.startsWith('~')) {
      const rangeVer = this.parseVersion(range.slice(1));
      const ver = this.parseVersion(version);
      return (
        ver.major === rangeVer.major &&
        ver.minor === rangeVer.minor &&
        ver.patch >= rangeVer.patch
      );
    }

    // Exact match
    return version === range;
  }

  /**
   * Get deprecation info for a feature
   */
  getDeprecation(feature: string): DeprecationInfo | undefined {
    return this.deprecations.get(feature);
  }

  /**
   * Get current API contract information
   */
  getContract(): APIContract {
    return {
      version: this.currentVersion,
      deprecations: Array.from(this.deprecations.values()),
      compatibility: this.compatibility,
    };
  }

  /**
   * Register a new deprecation
   */
  deprecate(feature: string, info: DeprecationInfo): void {
    this.deprecations.set(feature, info);
  }

  private parseVersion(versionStr: string): APIVersion {
    const match = versionStr.match(/(\d+)\.(\d+)(?:\.(\d+))?/);
    if (!match) {
      throw new Error(`Invalid version format: ${versionStr}`);
    }
    return {
      major: parseInt(match[1], 10),
      minor: parseInt(match[2], 10),
      patch: parseInt(match[3] || '0', 10),
    };
  }

  private compareVersions(a: APIVersion, b: APIVersion): number {
    if (a.major !== b.major) return a.major - b.major;
    if (a.minor !== b.minor) return a.minor - b.minor;
    return a.patch - b.patch;
  }
}

export const apiContractManager = new APIContractManager();
