 * Plugin registry: stores and retrieves plugin metadata and state.
 * Serves as the single source of truth for plugin information.
 */

import { PluginManifest, PluginState, PluginError } from './plugin-types';

export class PluginRegistry {
  private plugins: Map<string, PluginState> = new Map();
  private manifestMap: Map<string, PluginManifest> = new Map();
  private listeners: Set<(event: RegistryEvent) => void> = new Set();

  /**
   * Register a plugin's manifest in the registry
   */
  register(manifest: PluginManifest): void {
    if (this.plugins.has(manifest.id)) {
      throw new PluginError(
        `Plugin ${manifest.id} is already registered`,
        'MANIFEST_INVALID',
        manifest.id,
      );
    }

    const state: PluginState = {
      id: manifest.id,
      manifest,
      state: 'unloaded',
      dependencies: (manifest.dependencies || []).map((dep) => {
        if (typeof dep === 'string') {
          return { id: dep, requiredVersion: '*', resolved: false };
        }
        return { ...dep, resolved: false };
      }),
    };

    this.plugins.set(manifest.id, state);
    this.manifestMap.set(manifest.id, manifest);
    this.emit('registered', { pluginId: manifest.id, manifest });
  }

  /**
   * Unregister a plugin
   */
  unregister(pluginId: string): void {
    this.plugins.delete(pluginId);
    this.manifestMap.delete(pluginId);
    this.emit('unregistered', { pluginId });
  }

  /**
   * Get a plugin's state
   */
  getPluginState(pluginId: string): PluginState | undefined {
    return this.plugins.get(pluginId);
  }

  /**
   * Update a plugin's state
   */
  updatePluginState(
    pluginId: string,
    updates: Partial<PluginState>,
  ): void {
    const state = this.plugins.get(pluginId);
    if (!state) {
      throw new PluginError(
        `Plugin ${pluginId} not found in registry`,
        'LOAD_FAILED',
        pluginId,
      );
    }

    Object.assign(state, updates);

    if (updates.state) {
      this.emit('stateChanged', {
        pluginId,
        oldState: state.state,
        newState: updates.state,
      });
    }
  }

  /**
   * Get manifest for a plugin
   */
  getManifest(pluginId: string): PluginManifest | undefined {
    return this.manifestMap.get(pluginId);
  }

  /**
   * List all registered plugins
   */
  listPlugins(filter?: (state: PluginState) => boolean): PluginState[] {
    const plugins = Array.from(this.plugins.values());
    return filter ? plugins.filter(filter) : plugins;
  }

  /**
   * List loaded plugins
   */
  listLoadedPlugins(): PluginState[] {
    return this.listPlugins((p) => p.state === 'loaded');
  }

  /**
   * Check if a plugin is loaded
   */
  isLoaded(pluginId: string): boolean {
    const state = this.plugins.get(pluginId);
    return state?.state === 'loaded';
  }

  /**
   * Get plugins in dependency order (topological sort)
   */
  getDependencyOrder(): string[] {
    const visited = new Set<string>();
    const result: string[] = [];
    const visiting = new Set<string>();

    const visit = (id: string) => {
      if (visited.has(id)) return;
      if (visiting.has(id)) {
        throw new PluginError(
          `Circular dependency detected involving ${id}`,
          'DEPENDENCY_UNMET',
          id,
        );
      }

      visiting.add(id);
      const state = this.plugins.get(id);

      if (state) {
        for (const dep of state.dependencies) {
          if (!dep.resolved) continue;
          visit(dep.id);
        }
      }

      visiting.delete(id);
      visited.add(id);
      result.push(id);
    };

    for (const pluginId of this.plugins.keys()) {
      visit(pluginId);
    }

    return result;
  }

  /**
   * Resolve dependencies: mark which dependencies are available
   */
  resolveDependencies(): void {
    for (const state of this.plugins.values()) {
      for (const dep of state.dependencies) {
        dep.resolved = this.manifestMap.has(dep.id);
        if (dep.resolved) {
          dep.resolvedId = dep.id;
        }
      }
    }
  }

  /**
   * Check all dependencies for a plugin are available and met
   */
  validateDependencies(pluginId: string): { valid: boolean; missing: string[] } {
    const state = this.plugins.get(pluginId);
    if (!state) {
      return { valid: false, missing: [pluginId] };
    }

    const missing: string[] = [];

    for (const dep of state.dependencies) {
      const depManifest = this.manifestMap.get(dep.id);
      if (!depManifest) {
        missing.push(dep.id);
        continue;
      }

      // Simple version check (would use semver library in production)
      if (!this.versionSatisfies(depManifest.version, dep.requiredVersion)) {
        missing.push(`${dep.id}@${dep.requiredVersion}`);
      }
    }

    return {
      valid: missing.length === 0,
      missing,
    };
  }

  /**
   * Subscribe to registry events
   */
  subscribe(listener: (event: RegistryEvent) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private emit(type: string, data: unknown): void {
    const event: RegistryEvent = { type, data };
    this.listeners.forEach((listener) => listener(event));
  }

  private versionSatisfies(version: string, range: string): boolean {
    // Simplified check - in production, use semver library
    if (range === '*') return true;
    return version === range;
  }
}

export interface RegistryEvent {
  type: string;
  data: unknown;
}

export const pluginRegistry = new PluginRegistry();
