 * Plugin sandbox: execution context isolation and permission enforcement.
 * Ensures plugins run within defined security boundaries.
 */

import { PluginContext, PluginPermission, ReportingAPI, PluginLogger, PluginError } from './plugin-types';

export interface SandboxConfig {
  level: 'strict' | 'moderate' | 'permissive';
  memoryLimitMb?: number;
  timeoutMs?: number;
  allowedPermissions: PluginPermission[];
}

export class PluginSandbox {
  private config: SandboxConfig;
  private apiProxy: ReportingAPI;
  private logger: PluginLogger;
  private executionLog: ExecutionLogEntry[] = [];
  private permissionDenials: PermissionDenial[] = [];

  constructor(
    config: SandboxConfig,
    apiProxy: ReportingAPI,
    logger: PluginLogger,
  ) {
    this.config = config;
    this.apiProxy = apiProxy;
    this.logger = logger;
  }

  /**
   * Create a sandboxed context for plugin execution
   */
  createContext(pluginContext: PluginContext): SandboxedPluginContext {
    const self = this;

    return {
      manifest: pluginContext.manifest,
      logger: this.logger,
      config: pluginContext.config,
      runtime: pluginContext.runtime,
      api: this.createRestrictedAPI(pluginContext),
    };
  }

  /**
   * Create a restricted API proxy based on permissions
   */
  private createRestrictedAPI(context: PluginContext): ReportingAPI {
    const self = this;
    const { allowedPermissions } = this.config;

    return {
      reports: {
        list: async (query) => {
          self.checkPermission('read:reports', context.manifest.id);
          self.logApiCall('reports.list', { query });
          return self.apiProxy.reports.list(query);
        },
        get: async (id) => {
          self.checkPermission('read:reports', context.manifest.id);
          self.logApiCall('reports.get', { id });
          return self.apiProxy.reports.get(id);
        },
        create: async (data) => {
          self.checkPermission('write:reports', context.manifest.id);
          self.logApiCall('reports.create', { data: Object.keys(data) });
          return self.apiProxy.reports.create(data);
        },
        update: async (id, data) => {
          self.checkPermission('write:reports', context.manifest.id);
          self.logApiCall('reports.update', { id, fields: Object.keys(data) });
          return self.apiProxy.reports.update(id, data);
        },
        delete: async (id) => {
          self.checkPermission('delete:reports', context.manifest.id);
          self.logApiCall('reports.delete', { id });
          return self.apiProxy.reports.delete(id);
        },
        export: async (id, format) => {
          self.checkPermission('read:reports', context.manifest.id);
          self.logApiCall('reports.export', { id, format });
          return self.apiProxy.reports.export(id, format);
        },
      },
      config: {
        get: async (key) => {
          self.checkPermission('read:secrets', context.manifest.id);
          self.logApiCall('config.get', { key });
          return self.apiProxy.config.get(key);
        },
        set: async (key, value) => {
          self.checkPermission('read:secrets', context.manifest.id);
          self.logApiCall('config.set', { key, valueType: typeof value });
          return self.apiProxy.config.set(key, value);
        },
      },
      events: {
        on: (event, handler) => {
          self.logApiCall('events.subscribe', { event });
          return self.apiProxy.events.on(event, handler);
        },
        emit: async (event, data) => {
          self.logApiCall('events.emit', { event, dataType: typeof data });
          return self.apiProxy.events.emit(event, data);
        },
      },
    };
  }

  /**
   * Check if a permission is granted
   */
  private checkPermission(permission: PluginPermission, pluginId: string): void {
    if (!this.config.allowedPermissions.includes(permission)) {
      const denial: PermissionDenial = {
        pluginId,
        permission,
        timestamp: new Date().toISOString(),
      };
      this.permissionDenials.push(denial);

      this.logger.warn(`Permission denied: ${permission}`, { pluginId });
      throw new PluginError(
        `Permission denied: ${permission}`,
        'PERMISSION_DENIED',
        pluginId,
      );
    }
  }

  /**
   * Log an API call for audit trail
   */
  private logApiCall(method: string, params: Record<string, unknown>): void {
    this.executionLog.push({
      timestamp: new Date().toISOString(),
      method,
      params,
    });
  }

  /**
   * Get execution audit log
   */
  getExecutionLog(): ExecutionLogEntry[] {
    return [...this.executionLog];
  }

  /**
   * Get permission denial history
   */
  getPermissionDenials(): PermissionDenial[] {
    return [...this.permissionDenials];
  }

  /**
   * Estimate memory usage (simplified)
   */
  getMemoryUsage(): { usageMb: number; limitMb?: number; percentOfLimit?: number } {
    const usageMb = process.memoryUsage().heapUsed / 1024 / 1024;
    const limitMb = this.config.memoryLimitMb;
    const percentOfLimit = limitMb ? (usageMb / limitMb) * 100 : undefined;

    return { usageMb, limitMb, percentOfLimit };
  }

  /**
   * Check if plugin execution would violate resource constraints
   */
  checkResourceConstraints(): { compliant: boolean; violations: string[] } {
    const violations: string[] = [];
    const { usageMb, limitMb } = this.getMemoryUsage();

    if (limitMb && usageMb > limitMb) {
      violations.push(`Memory usage ${usageMb}MB exceeds limit ${limitMb}MB`);
    }

    return {
      compliant: violations.length === 0,
      violations,
    };
  }
}

export interface SandboxedPluginContext {
  manifest: PluginContext['manifest'];
  logger: PluginLogger;
  config: PluginContext['config'];
  runtime: PluginContext['runtime'];
  api: ReportingAPI;
}

export interface ExecutionLogEntry {
  timestamp: string;
  method: string;
  params: Record<string, unknown>;
}

export interface PermissionDenial {
  pluginId: string;
  permission: PluginPermission;
  timestamp: string;
}
