          'LOAD_FAILED',
          pluginId,
        );
      }

      if (state.state === 'loaded') {
        throw new PluginError(
          `Plugin ${pluginId} is already loaded`,
          'LOAD_FAILED',
          pluginId,
        );
      }

      this.registry.updatePluginState(pluginId, { state: 'loading' });

      // Validate API compatibility
      if (!apiContractManager.isApiVersionCompatible(state.manifest.apiVersion)) {
        throw new PluginError(
          `API version ${state.manifest.apiVersion} not compatible with current API`,
          'API_INCOMPATIBLE',
          pluginId,
        );
      }

      // Check dependencies
      const depCheck = this.registry.validateDependencies(pluginId);
      if (!depCheck.valid) {
        throw new PluginError(
          `Unmet dependencies: ${depCheck.missing.join(', ')}`,
          'DEPENDENCY_UNMET',
          pluginId,
          { missing: depCheck.missing },
        );
      }

      // Load the module
      const module = await this.loadModule(state.manifest);

      // Validate the module export
      if (!this.isValidPluginExport(module)) {
        throw new PluginError(
          'Plugin module does not export valid PluginExport',
          'LOAD_FAILED',
          pluginId,
        );
      }

      // Create plugin context
      const logger = this.createLogger(pluginId);
      const context: PluginContext = {
        manifest: state.manifest,
        logger,
        api: {} as any, // Will be set by loader
        config: {},
        runtime: {
          loadedAt: new Date().toISOString(),
          sandboxLevel: this.config.sandboxConfig.level,
          memoryLimitMb: this.config.sandboxConfig.memoryLimitMb,
          grantedPermissions: this.config.sandboxConfig.allowedPermissions,
        },
      };

      // Create sandbox and API proxy
      const sandbox = new PluginSandbox(this.config.sandboxConfig, {} as any, logger);
      context.api = sandbox.createContext(context).api;

      // Call onLoad hook
      if (module.onLoad) {
        try {
          await Promise.resolve(module.onLoad(context));
        } catch (error) {
          throw new PluginError(
            `onLoad hook failed: ${error instanceof Error ? error.message : String(error)}`,
            'HOOK_ERROR',
            pluginId,
            error,
          );
        }
      }

      // Update registry with loaded plugin
      this.moduleCache.set(pluginId, module);
      this.registry.updatePluginState(pluginId, {
        state: 'loaded',
        module,
        context,
        loadedAt: new Date().toISOString(),
      });
    } catch (error) {
      const pluginError = error instanceof PluginError ? error : new PluginError(
        error instanceof Error ? error.message : String(error),
        'LOAD_FAILED',
        pluginId,
        error,
      );

      this.registry.updatePluginState(pluginId, {
        state: 'error',
        error: pluginError,
      });

      throw pluginError;
    }
  }

  /**
   * Unload a plugin
   */
  async unloadPlugin(pluginId: string): Promise<void> {
    const state = this.registry.getPluginState(pluginId);
    if (!state || state.state !== 'loaded') {
      throw new PluginError(
        `Plugin ${pluginId} is not loaded`,
        'LOAD_FAILED',
        pluginId,
      );
    }

    try {
      this.registry.updatePluginState(pluginId, { state: 'unloading' });

      // Call onBeforeUnload hook
      const module = this.moduleCache.get(pluginId);
      if (module?.onBeforeUnload && state.context) {
        await Promise.resolve(module.onBeforeUnload(state.context));
      }

      // Call onUnload hook
      if (module?.onUnload && state.context) {
        await Promise.resolve(module.onUnload(state.context));
      }

      this.moduleCache.delete(pluginId);
      this.registry.updatePluginState(pluginId, { state: 'unloaded', module: undefined });
    } catch (error) {
      const pluginError = error instanceof PluginError ? error : new PluginError(
        error instanceof Error ? error.message : String(error),
        'HOOK_ERROR',
        pluginId,
        error,
      );

      this.registry.updatePluginState(pluginId, {
        state: 'error',
        error: pluginError,
      });

      throw pluginError;
    }
  }

  /**
   * Reload a plugin (unload then load)
   */
  async reloadPlugin(pluginId: string): Promise<void> {
    const state = this.registry.getPluginState(pluginId);

    if (state?.state === 'loaded') {
      await this.unloadPlugin(pluginId);
    }

    const module = this.moduleCache.get(pluginId);
    if (module?.onReload && state?.context) {
      await Promise.resolve(module.onReload(state.context));
    }

    await this.loadPlugin(pluginId);
  }

  /**
   * Load a plugin module from disk
   */
  private async loadModule(manifest: PluginManifest): Promise<PluginExport> {
    // In a real implementation, this would use dynamic import
    // For now, this is a placeholder that shows the pattern
    try {
      // const module = await import(`file://${pluginPath}/${manifest.main}`);
      // return module.default || module;
      throw new Error('loadModule requires filesystem access in real implementation');
    } catch (error) {
      throw new PluginError(
        `Failed to load module ${manifest.main}`,
        'LOAD_FAILED',
        manifest.id,
        error,
      );
    }
  }

  /**
   * Validate that a module exports a valid PluginExport
   */
  private isValidPluginExport(module: any): module is PluginExport {
    return (
      module &&
      typeof module === 'object' &&
      module.manifest &&
      typeof module.manifest === 'object'
    );
  }

  /**
   * Create a logger bound to a plugin
   */
  private createLogger(pluginId: string): PluginLogger {
    const prefix = `[${pluginId}]`;
    return {
      debug: (msg, data) => console.debug(`${prefix} ${msg}`, data),
      info: (msg, data) => console.info(`${prefix} ${msg}`, data),
      warn: (msg, data) => console.warn(`${prefix} ${msg}`, data),
      error: (msg, err) => console.error(`${prefix} ${msg}`, err),
    };
  }
}
