 * Plugin manager: orchestrates the entire plugin lifecycle.
 * Coordinates loading, unloading, error handling, and event distribution.
 */

import { PluginManifest, PluginError, PluginState } from './plugin-types';
import { PluginRegistry } from './plugin-registry';
import { PluginLoader, LoaderConfig } from './plugin-loader';

export class PluginManager {
  private registry: PluginRegistry;
  private loader: PluginLoader;
  private loadedPlugins: Set<string> = new Set();
  private listeners: Map<string, Set<(data: unknown) => void>> = new Map();

  constructor(registry: PluginRegistry, loaderConfig: LoaderConfig) {
    this.registry = registry;
    this.loader = new PluginLoader(registry, loaderConfig);
    this.registry.subscribe((event) => this.handleRegistryEvent(event));
  }

  /**
   * Initialize the plugin system by loading all discovered plugins
   */
  async initialize(): Promise<InitializationResult> {
    const result: InitializationResult = {
      loaded: [],
      failed: [],
      skipped: [],
    };

    try {
      // Resolve all dependencies
      this.registry.resolveDependencies();

      // Get dependency-ordered plugin list
      const pluginOrder = this.registry.getDependencyOrder();

      // Load plugins in order
      for (const pluginId of pluginOrder) {
        try {
          await this.loadPlugin(pluginId);
          result.loaded.push(pluginId);
        } catch (error) {
          result.failed.push({
            pluginId,
            error: error instanceof Error ? error.message : String(error),
          });
        }
      }

      return result;
    } catch (error) {
      throw new PluginError(
        `Initialization failed: ${error instanceof Error ? error.message : String(error)}`,
        'LOAD_FAILED',
        'system',
        error,
      );
    }
  }

  /**
   * Load a single plugin
   */
  async loadPlugin(pluginId: string): Promise<void> {
    if (this.loadedPlugins.has(pluginId)) {
      return; // Already loaded
    }

    await this.loader.loadPlugin(pluginId);
    this.loadedPlugins.add(pluginId);
    this.emit('plugin:loaded', { pluginId });
  }

  /**
   * Unload a plugin
   */
  async unloadPlugin(pluginId: string): Promise<void> {
    if (!this.loadedPlugins.has(pluginId)) {
      throw new PluginError(
        `Plugin ${pluginId} is not loaded`,
        'LOAD_FAILED',
        pluginId,
      );
    }

    await this.loader.unloadPlugin(pluginId);
    this.loadedPlugins.delete(pluginId);
    this.emit('plugin:unloaded', { pluginId });
  }

  /**
   * Reload a plugin
   */
  async reloadPlugin(pluginId: string): Promise<void> {
    this.emit('plugin:reloadStart', { pluginId });
    await this.loader.reloadPlugin(pluginId);
    this.emit('plugin:reloadComplete', { pluginId });
  }

  /**
   * Get status of all plugins
   */
  getStatus(): PluginStatus[] {
    return this.registry.listPlugins().map((state) => ({
      id: state.id,
      name: state.manifest.name,
      version: state.manifest.version,
      state: state.state,
      loadedAt: state.loadedAt,
      error: state.error?.message,
      dependencies: state.dependencies,
    }));
  }

  /**
   * Get detailed info for a plugin
   */
  getPluginInfo(pluginId: string): PluginInfo | undefined {
    const state = this.registry.getPluginState(pluginId);
    if (!state) return undefined;

    return {
      id: state.id,
      manifest: state.manifest,
      state: state.state,
      loadedAt: state.loadedAt,
      error: state.error,
      dependencies: state.dependencies,
    };
  }

  /**
   * Register event listener for plugin events
   */
  on(event: string, handler: (data: unknown) => void): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(handler);
    return () => {
      this.listeners.get(event)?.delete(handler);
    };
  }

  /**
   * Emit an event to all listeners
   */
  private emit(event: string, data: unknown): void {
    const handlers = this.listeners.get(event);
    if (handlers) {
      handlers.forEach((handler) => {
        try {
          handler(data);
        } catch (error) {
          console.error(`Error in event handler for ${event}:`, error);
        }
      });
    }
  }

  /**
   * Handle registry events
   */
  private handleRegistryEvent(event: any): void {
    this.emit(`registry:${event.type}`, event.data);
  }

  /**
   * Hook system: invoke all registered hooks for an event
   */
  async invokeHook(hookName: string, data: unknown): Promise<void> {
    const plugins = this.registry.listLoadedPlugins();

    // Sort by priority (higher = earlier)
    const sorted = plugins.sort((a, b) => {
      const aPriority = this.getHookPriority(a.manifest, hookName);
      const bPriority = this.getHookPriority(b.manifest, hookName);
      return bPriority - aPriority;
    });

    for (const plugin of sorted) {
      if (!plugin.context) continue;

      const hookFn = (plugin.module as any)?.[hookName];
      if (typeof hookFn === 'function') {
        try {
          await Promise.resolve(hookFn(plugin.context, data));
        } catch (error) {
          console.error(`Hook ${hookName} failed for plugin ${plugin.id}:`, error);
          this.emit('hook:error', {
            pluginId: plugin.id,
            hookName,
            error,
          });
        }
      }
    }
  }

  private getHookPriority(manifest: PluginManifest, hookName: string): number {
    const hook = manifest.hooks?.find((h) => h.name === hookName);
    return hook?.priority ?? 500; // Default priority
  }
}

export interface InitializationResult {
  loaded: string[];
  failed: { pluginId: string; error: string }[];
  skipped: string[];
}

export interface PluginStatus {
  id: string;
  name: string;
  version: string;
  state: string;
  loadedAt?: string;
  error?: string;
  dependencies: any[];
}

export interface PluginInfo extends PluginStatus {
  manifest: PluginManifest;
  error?: PluginError;
}
