  license: 'MIT',
};

// Plugin state
let isInitialized = false;
let exportCount = 0;

export const onLoad = async (context: PluginContext): Promise<void> => {
  context.logger.info('PDF Export plugin loading...');

  // Validate configuration
  if (!context.config.templateDir) {
    throw new Error('templateDir configuration required');
  }

  // Initialize templates
  try {
    // In real implementation: await loadTemplates(context.config.templateDir)
    context.logger.info('PDF templates initialized');
  } catch (error) {
    context.logger.error('Failed to initialize templates', error);
    throw error;
  }

  isInitialized = true;
  context.logger.info('PDF Export plugin ready');
};

export const onReportGenerated = async (
  context: PluginContext,
  report: Report,
): Promise<void> => {
  if (!isInitialized) return;

  context.logger.debug('Processing report for PDF export', { reportId: report.id });

  try {
    // Only auto-export if configured
    if (context.config.autoExport !== true) {
      return;
    }

    // Export the report
    const blob = await context.api.reports.export(report.id, 'pdf');
    exportCount++;

    context.logger.info(`Successfully exported report ${report.id} to PDF`, {
      size: blob.size,
      totalExports: exportCount,
    });
  } catch (error) {
    context.logger.error('Failed to export report', error);
    // Don't re-throw - this is a hook, shouldn't crash the system
  }
};

export const onBeforeUnload = async (context: PluginContext): Promise<void> => {
  context.logger.info('PDF Export plugin shutting down', { totalExports: exportCount });
};

export const onUnload = async (context: PluginContext): Promise<void> => {
  // Cleanup
  isInitialized = false;
  context.logger.info('PDF Export plugin unloaded');
};

export const onError = async (context: PluginContext, error: any): Promise<void> => {
  context.logger.error('Plugin error occurred', error);
  // Send error metrics, etc.
};

export default {
