/**
 * Configure and initialize the plugin system
 */
export function createPluginManager(): PluginManager {
  const registry = new PluginRegistry();

  const loaderConfig: LoaderConfig = {
    // Directories where plugins are installed
    pluginDirs: [
      path.join(process.cwd(), 'plugins'),
      path.join(process.cwd(), 'node_modules/@reporting'),
    ],

    // Sandbox configuration
    sandboxConfig: {
      // Security level: 'strict' (minimal), 'moderate' (default), 'permissive' (all)
      level: 'moderate',

      // Per-plugin memory limit in MB
      memoryLimitMb: 256,

      // Execution timeout for hooks (milliseconds)
      timeoutMs: 30000,

      // Default permissions granted to all plugins
      // Each plugin still declares what it needs
      allowedPermissions: [
        'read:reports',
        'write:reports',
        'read:filesystem',
        'access:network',
      ],
    },
  };

  return new PluginManager(registry, loaderConfig);
}

/**
 * Application initialization with plugins
 */
export async function initializeApplication() {
  const manager = createPluginManager();

  try {
    // Initialize all discovered plugins
    const result = await manager.initialize();

    console.log(`✓ Loaded ${result.loaded.length} plugins`);
    if (result.failed.length > 0) {
      console.warn(`✗ Failed to load ${result.failed.length} plugins:`);
      result.failed.forEach((item) => {
        console.warn(`  - ${item.pluginId}: ${item.error}`);
      });
    }

    // Print plugin status
    const status = manager.getStatus();
    console.log('\nPlugin Status:');
    status.forEach((p) => {
      const icon = p.state === 'loaded' ? '✓' : '✗';
      console.log(
        `  ${icon} ${p.name} (${p.version}) - ${p.state}`,
      );
    });

    // Subscribe to plugin events
    manager.on('plugin:loaded', (data: any) => {
      console.log(`[Event] Plugin loaded: ${data.pluginId}`);
    });

    manager.on('plugin:unloaded', (data: any) => {
      console.log(`[Event] Plugin unloaded: ${data.pluginId}`);
    });

    manager.on('hook:error', (data: any) => {
      console.error(`[Error] Hook ${data.hookName} failed in ${data.pluginId}:`, data.error);
    });

    return manager;
  } catch (error) {
    console.error('Failed to initialize plugin system:', error);
    throw error;
  }
}

