  pluginId: string,
) {
  try {
    await manager.loadPlugin(pluginId);

    const info = manager.getPluginInfo(pluginId);
    console.log(`Loaded plugin: ${info?.name} (${info?.version})`);
    console.log(`  Permissions: ${info?.manifest.permissions?.join(', ')}`);
    console.log(`  Hooks: ${info?.manifest.hooks?.map((h) => h.name).join(', ')}`);

    return info;
  } catch (error) {
    console.error(`Failed to load plugin ${pluginId}:`, error);
    throw error;
  }
}

/**
 * Example: Monitor plugin health
 */
export function setupHealthMonitoring(manager: PluginManager) {
  setInterval(() => {
    const status = manager.getStatus();
    const failedPlugins = status.filter((p) => p.state === 'error');

    if (failedPlugins.length > 0) {
      console.warn(
        `⚠️  ${failedPlugins.length} plugins in error state:`,
      );
      failedPlugins.forEach((p) => {
        console.warn(`  - ${p.id}: ${p.error}`);
      });
    }
  }, 60000); // Check every minute
}

/**
 * Example: Graceful shutdown
 */
export async function shutdownPlugins(manager: PluginManager) {
  console.log('Shutting down plugins...');

  const status = manager.getStatus();
  const loadedPlugins = status.filter((p) => p.state === 'loaded');

  for (const plugin of loadedPlugins) {
    try {
      await manager.unloadPlugin(plugin.id);
      console.log(`✓ Unloaded ${plugin.name}`);
    } catch (error) {
      console.error(`✗ Error unloading ${plugin.name}:`, error);
    }
  }

  console.log('Plugin shutdown complete');
}
