async function monitorHealth() {
  const status = manager.getStatus();

  console.log('\n=== Health Check ===');
  status.forEach((p) => {
    if (p.state === 'loaded') {
      console.log(`✓ ${p.name} - OK`);
    } else if (p.state === 'error') {
      console.log(`✗ ${p.name} - ERROR: ${p.error}`);
    } else {
      console.log(`? ${p.name} - ${p.state}`);
    }
  });

  // Check for failed hooks
  const failedCount = status.filter((p) => p.state === 'error').length;
  if (failedCount > 0) {
    console.warn(`⚠️  ${failedCount} plugins in error state`);
  }
}

await monitorHealth();
