## Step 8: Shutdown

```typescript
async function shutdown() {
  console.log('\n🛑 Shutting down plugins...');

  const status = manager.getStatus();
  const loadedPlugins = status.filter((p) => p.state === 'loaded');

  for (const plugin of loadedPlugins) {
    try {
      await manager.unloadPlugin(plugin.id);
      console.log(`✓ Unloaded ${plugin.name}`);
    } catch (error) {
      console.error(`✗ Error unloading ${plugin.name}:`, error.message);
    }
  }

  console.log('✓ All plugins unloaded');
}

await shutdown();
```

**Output:**
```
🛑 Shutting down plugins...
📦 Plugin unloaded: com.company.export-pdf
✓ Unloaded PDF Export
📦 Plugin unloaded: com.company.audit-logger
✓ Unloaded Audit Logger
📦 Plugin unloaded: com.company.analytics
✓ Unloaded Analytics
✓ All plugins unloaded
```

## Step 9: Error Scenario - Permission Denied

Suppose audit logger doesn't have `delete:reports` permission but tries to use it:

```typescript
// audit-logger/index.ts
export const onReportGenerated = async (context, report) => {
  try {
    // This will fail - permission not declared
    await context.api.reports.delete(report.id);
  } catch (error) {
    if (error.code === 'PERMISSION_DENIED') {
      context.logger.warn('Delete requires permission', {
        needed: 'delete:reports',
        current: context.runtime.grantedPermissions,
      });
    }
  }
};
```

**Logs:**
```
[com.company.audit-logger] ⚠️  Delete requires permission {
  "needed":"delete:reports",
  "current":["read:reports","write:filesystem"]
}
```

## Step 10: Version Incompatibility

New plugin targets API 2.0 but system is 1.0:

```typescript
const newPluginManifest = {
  id: 'com.company.new-feature',
  version: '1.0.0',
  apiVersion: '2.0', // Incompatible!
  // ...
};

registry.register(newPluginManifest);

try {
  await manager.loadPlugin('com.company.new-feature');
} catch (error) {
  if (error.code === 'API_INCOMPATIBLE') {
    console.error(
      `Plugin requires API 2.0, but system is 1.0`,
    );
  }
}
```

## Full Application Flow

```typescript
async function main() {
  // 1. Initialize
  const manager = await createAndInitializeManager();

  // 2. Subscribe to events
  setupEventHandlers(manager);

  // 3. Run application
  const server = startWebServer();

  // 4. Handle report creation
  server.on('report:created', async (report) => {
    await manager.invokeHook('onReportGenerated', report);
  });

  // 5. Handle report deletion
  server.on('report:deleted', async (reportId) => {
    await manager.invokeHook('onReportDeleted', reportId);
  });

  // 6. Monitor health
  setInterval(() => {
    const status = manager.getStatus();
    const errors = status.filter((p) => p.state === 'error');
    if (errors.length > 0) {
      alertOps(`${errors.length} plugins in error state`);
    }
  }, 60000);

  // 7. Graceful shutdown
  process.on('SIGTERM', async () => {
    console.log('Shutting down...');
    await shutdown(manager);
    server.close();
    process.exit(0);
  });
}

main().catch((error) => {
  console.error('Fatal error:', error);
  process.exit(1);
});
```

