## Plugin Registry

The Registry is the source of truth for all plugin metadata, state, and discovery.

### Registry Data Structure

```typescript
interface PluginRegistry {
  // Core plugin metadata
  plugins: Map<string, RegisteredPlugin>;

  // Dependency resolution
  dependencyGraph: DependencyGraph;

  // Runtime state
  activePlugins: Set<string>;
  pluginStates: Map<string, PluginState>;

  // Version negotiation
  apiVersions: Map<string, SemanticVersion[]>;

  // Event subscriptions
  subscribers: Map<RegistryEventType, Set<Subscriber>>;
}

interface RegisteredPlugin {
  id: string;
  manifest: PluginManifest;
  version: SemanticVersion;

  // Where plugin is installed
  location: {
    root: string;
    entryPoint: string;
  };

  // Current runtime state
  state: PluginState;
  loadedAt?: number; // timestamp
  activatedAt?: number;

  // Compatibility info
  apiNegotiation: {
    requestedRange: VersionRange;
    negotiatedVersion: SemanticVersion;
    fallbackVersion?: SemanticVersion;
  };

  // Dependency tracking
  dependencies: {
    required: PluginDependency[];
    optional: PluginDependency[];
    resolved: Map<string, RegisteredPlugin>;
  };

  // Health and diagnostics
  health: {
    status: "healthy" | "degraded" | "unhealthy";
    lastChecked: number;
    errors: PluginError[];
  };

  // Performance metrics
  metrics: {
    loadTime: number;
    activationTime: number;
    lastUsed: number;
    errorRate: number;
  };
}

enum PluginState {
  UNINSTALLED = "uninstalled",
  INSTALLED = "installed",
  LOADING = "loading",
  LOADED = "loaded",
  ACTIVATING = "activating",
  ACTIVE = "active",
  DEACTIVATING = "deactivating",
  DEACTIVATED = "deactivated",
  UNLOADING = "unloading",
  ERROR = "error",
  DISABLED = "disabled"
}

interface PluginDependency {
  id: string;
  versionRange: string;
  optional: boolean;
  api?: {
    version: string;
    methods: string[];
  };
}

type RegistryEventType = 
  | "plugin:registered"
  | "plugin:unregistered"
  | "plugin:stateChange"
  | "plugin:error"
  | "plugin:apiNegotiation"
  | "dependencies:resolved"
  | "dependencies:unresolved";
```

### Registry Operations

```typescript
interface IPluginRegistry {
  // Discovery
  discover(path: string): Promise<PluginManifest[]>;
  register(manifest: PluginManifest, location: string): Promise<string>;
  unregister(pluginId: string): Promise<void>;

  // Lookup
  get(pluginId: string): RegisteredPlugin | null;
  getActive(): RegisteredPlugin[];
  getByCapability(capability: string): RegisteredPlugin[];
  getByDependency(dependsOn: string): RegisteredPlugin[];

  // Version negotiation
  negotiateApiVersion(
    pluginId: string,
    requested: VersionRange
  ): SemanticVersion | null;

  // Dependency resolution
  resolveDependencies(pluginId: string): Promise<Map<string, RegisteredPlugin>>;
  validateDependencies(pluginId: string): ValidationResult;

  // State management
  setState(pluginId: string, state: PluginState): void;
  getState(pluginId: string): PluginState;
  subscribe(event: RegistryEventType, handler: (event: RegistryEvent) => void): Unsubscribe;

  // Health and metrics
  getHealth(pluginId: string): PluginHealth;
  recordMetric(pluginId: string, metric: Metric): void;
  recordError(pluginId: string, error: PluginError): void;

  // Export/import
  export(): Promise<RegistrySnapshot>;
  import(snapshot: RegistrySnapshot): Promise<void>;
}
