## Lifecycle Management

Plugins transition through a well-defined state machine with hooks at each stage.

### Lifecycle State Machine

```
    ┌──────────────┐
    │  UNINSTALLED │
    └──────┬───────┘
           │ install()
           ▼
    ┌──────────────┐
    │  INSTALLED   │◄─────────────────┐
    └──────┬───────┘                  │
           │ load()                   │
           ▼                          │
    ┌──────────────────┐    unload()  │
    │  beforeLoad()    ├──────────────┤
    │  (async hook)    │              │
    └──────┬───────────┘              │
           ▼                          │
    ┌──────────────┐                  │
    │   LOADING    │                  │
    └──────┬───────┘                  │
           │                          │
           ▼                          │
    ┌──────────────┐                  │
    │   LOADED     │                  │
    └──────┬───────┘                  │
           │ activate()               │
           ▼                          │
    ┌──────────────────┐              │
    │ beforeActivate() ├──────────────┤
    │ (async hook)     │              │
    └──────┬───────────┘              │
           ▼                          │
    ┌──────────────┐                  │
    │  ACTIVATING  │                  │
    └──────┬───────┘                  │
           ▼                          │
    ┌──────────────────┐              │
    │  afterActivate() │              │
    │  (async hook)    │              │
    └──────┬───────────┘              │
           ▼                          │
    ┌──────────────┐   deactivate()   │
    │   ACTIVE     ├──────────────────┤
    └──────┬───────┘                  │
           │                          │
           │                          │
    ┌──────┴──────────────────────┐   │
    │ beforeDeactivate()           │   │
    │ (async hook)                 │   │
    └──────┬──────────────────────┘   │
           ▼                          │
    ┌──────────────┐                  │
    │ DEACTIVATING │                  │
    └──────┬───────┘                  │
           ▼                          │
    ┌──────────────────────────────┐  │
    │ afterDeactivate() & unload() │◄─┘
    │ (async hook)                 │
    └──────┬──────────────────────┘
           ▼
    ┌──────────────┐
    │   UNLOADING  │
    └──────┬───────┘
           ▼
    ┌──────────────────┐
    │ beforeUnload()   │
    │ (async hook)     │
    └──────┬───────────┘
           ▼
    ┌──────────────┐
    │  INSTALLED   │
    └──────────────┘
```

### Lifecycle Hooks API

```typescript
interface PluginLifecycleHooks {
  // Before entering LOADING state
  beforeLoad?(context: LoadContext): Promise<void>;

  // After entering LOADED state (entry point executed)
  afterLoad?(context: LoadContext): Promise<void>;

  // Before entering ACTIVATING state
  beforeActivate?(context: ActivationContext): Promise<void>;

  // After entering ACTIVE state (all systems go)
  afterActivate?(context: ActivationContext): Promise<void>;

  // Before entering DEACTIVATING state
  beforeDeactivate?(context: DeactivationContext): Promise<void>;

  // After entering DEACTIVATED state
  afterDeactivate?(context: DeactivationContext): Promise<void>;

  // Before entering UNLOADING state
  beforeUnload?(context: UnloadContext): Promise<void>;

  // Reloading without full unload/load cycle
  onReload?(context: ReloadContext): Promise<void>;

  // Periodic health check
  onHealthCheck?(context: HealthCheckContext): Promise<HealthStatus>;

  // Configuration changed
  onConfigChange?(context: ConfigChangeContext): Promise<void>;

  // Error handler
  onError?(error: PluginError): Promise<void>;
}

interface LoadContext {
  pluginId: string;
  manifest: PluginManifest;
  config: Record<string, any>;
  logger: ILogger;
  registry: IPluginRegistry;
}

interface ActivationContext extends LoadContext {
  dependencies: Map<string, any>;
  hostApi: HostAPI;
}

interface DeactivationContext {
  pluginId: string;
  reason: "unload" | "error" | "manual" | "config-change";
  logger: ILogger;
}

interface UnloadContext extends DeactivationContext {
  shouldPersistCache: boolean;
}

interface ReloadContext {
  pluginId: string;
  previousConfig: Record<string, any>;
  newConfig: Record<string, any>;
  reason: "config-change" | "manual" | "update";
  logger: ILogger;
}

interface HealthCheckContext {
  pluginId: string;
  lastCheck?: HealthStatus;
}

type HealthStatus = 
  | "healthy"
  | { status: "degraded"; issues: string[] }
  | { status: "unhealthy"; reason: string };

interface ConfigChangeContext {
  pluginId: string;
  oldConfig: Record<string, any>;
  newConfig: Record<string, any>;
  changedKeys: string[];
}
```

### Lifecycle Manager Implementation

```typescript
class PluginLifecycleManager {
  async install(manifestPath: string, options?: InstallOptions): Promise<string> {
    // Validate manifest schema
    // Check disk space, dependencies
    // Register in registry
    // Copy/link plugin files
    // Return plugin ID
  }

  async load(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (!plugin) throw new PluginNotFoundError(pluginId);

    this.registry.setState(pluginId, PluginState.LOADING);

    try {
      // 1. Call beforeLoad hook
      await this.callHook(pluginId, "beforeLoad", new LoadContext(...));

      // 2. Resolve dependencies
      const dependencies = await this.registry.resolveDependencies(pluginId);

      // 3. Load entry point in sandbox
      const instance = await this.sandbox.load(plugin.location.entryPoint, {
        config: plugin.manifest.configuration,
        dependencies
      });

      // 4. Store instance reference
      this.loadedInstances.set(pluginId, instance);

      // 5. Call afterLoad hook
      await this.callHook(pluginId, "afterLoad", new LoadContext(...));

      // 6. Update registry state
      this.registry.setState(pluginId, PluginState.LOADED);
      this.registry.recordMetric(pluginId, { type: "load", duration: ... });

    } catch (error) {
      this.registry.setState(pluginId, PluginState.ERROR);
      this.registry.recordError(pluginId, error);
      throw new PluginLoadError(pluginId, error);
    }
  }

  async activate(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (plugin.state !== PluginState.LOADED) {
      throw new InvalidStateError(`Cannot activate plugin in ${plugin.state} state`);
    }

    this.registry.setState(pluginId, PluginState.ACTIVATING);

    try {
      // 1. Call beforeActivate hook
      await this.callHook(pluginId, "beforeActivate", new ActivationContext(...));

      // 2. Register extensions (report types, transformations, etc.)
      await this.registerExtensions(pluginId);

      // 3. Call afterActivate hook
      await this.callHook(pluginId, "afterActivate", new ActivationContext(...));

      // 4. Start health check interval
      this.startHealthCheck(pluginId);

      // 5. Update registry
      this.registry.setState(pluginId, PluginState.ACTIVE);

    } catch (error) {
      this.registry.setState(pluginId, PluginState.ERROR);
      this.registry.recordError(pluginId, error);
      throw new PluginActivationError(pluginId, error);
    }
  }

  async deactivate(pluginId: string, reason: string = "manual"): Promise<void> {
    const plugin = this.registry.get(pluginId);
    if (plugin.state !== PluginState.ACTIVE) {
      throw new InvalidStateError(`Cannot deactivate plugin in ${plugin.state} state`);
    }

    this.registry.setState(pluginId, PluginState.DEACTIVATING);

    try {
      // 1. Stop accepting new requests
      this.sandbox.pause(pluginId);

      // 2. Wait for in-flight requests (with timeout)
      await this.waitForInflightRequests(pluginId, timeout: 30000);

      // 3. Call beforeDeactivate hook
      await this.callHook(pluginId, "beforeDeactivate", new DeactivationContext(reason));

      // 4. Unregister extensions
      await this.unregisterExtensions(pluginId);

      // 5. Call afterDeactivate hook
      await this.callHook(pluginId, "afterDeactivate", new DeactivationContext(reason));

      // 6. Stop health check
      this.stopHealthCheck(pluginId);

      // 7. Update registry
      this.registry.setState(pluginId, PluginState.DEACTIVATED);

    } catch (error) {
      this.registry.recordError(pluginId, error);
      throw new PluginDeactivationError(pluginId, error);
    }
  }

  async reload(pluginId: string, options?: ReloadOptions): Promise<void> {
    const plugin = this.registry.get(pluginId);
    const wasActive = plugin.state === PluginState.ACTIVE;
    const oldConfig = plugin.manifest.configuration;

    try {
      if (wasActive) await this.deactivate(pluginId, "reload");

      // Call onReload hook if implemented
      if (plugin.manifest.hooks?.onReload) {
        await this.callHook(pluginId, "onReload", new ReloadContext(...));
      } else {
        // Full unload + load cycle
        await this.unload(pluginId);
        await this.load(pluginId);
      }

      if (wasActive) await this.activate(pluginId);

    } catch (error) {
      this.registry.setState(pluginId, PluginState.ERROR);
      this.registry.recordError(pluginId, error);
      throw new PluginReloadError(pluginId, error);
    }
  }

  async unload(pluginId: string): Promise<void> {
    const plugin = this.registry.get(pluginId);

    // Ensure deactivated first
    if (plugin.state === PluginState.ACTIVE) {
      await this.deactivate(pluginId, "unload");
    }

    this.registry.setState(pluginId, PluginState.UNLOADING);

    try {
      // 1. Call beforeUnload hook
      await this.callHook(pluginId, "beforeUnload", new UnloadContext(...));

      // 2. Terminate sandbox process
      await this.sandbox.terminate(pluginId);

      // 3. Clean up instance references
      this.loadedInstances.delete(pluginId);

      // 4. Update registry
      this.registry.setState(pluginId, PluginState.INSTALLED);

    } catch (error) {
      this.registry.setState(pluginId, PluginState.ERROR);
      this.registry.recordError(pluginId, error);
      throw new PluginUnloadError(pluginId, error);
    }
  }

  private startHealthCheck(pluginId: string): void {
    const interval = setInterval(async () => {
      try {
        const status = await this.callHook(pluginId, "onHealthCheck", {
          pluginId,
          lastCheck: this.lastHealthStatus.get(pluginId)
        });

        this.lastHealthStatus.set(pluginId, status);

        if (status.status === "unhealthy") {
          this.logger.error(`Plugin ${pluginId} is unhealthy: ${status.reason}`);
          // Could trigger automatic deactivation/reload
        }

      } catch (error) {
        this.logger.error(`Health check failed for ${pluginId}`, error);
      }
    }, 60000); // Every 60 seconds

    this.healthCheckIntervals.set(pluginId, interval);
  }

  private stopHealthCheck(pluginId: string): void {
    const interval = this.healthCheckIntervals.get(pluginId);
    if (interval) {
      clearInterval(interval);
      this.healthCheckIntervals.delete(pluginId);
    }
  }

  private async callHook(
    pluginId: string,
    hookName: string,
    context: any
  ): Promise<any> {
    const plugin = this.registry.get(pluginId);
    const manifest = plugin.manifest;

    // Check if hook is declared in manifest
    if (!manifest.hooks[hookName]) return;

    // Get hook implementation from loaded plugin
    const instance = this.loadedInstances.get(pluginId);
    if (!instance?.[hookName]) return;

    // Call with timeout
    return Promise.race([
      instance[hookName](context),
      this.createTimeout(manifest.resources.timeout.default)
    ]);
  }
}
```

