## Sandboxed Execution

Plugins run in isolated environments with strict boundaries and capability-based access control.

### Sandbox Architecture

```typescript
interface ISandbox {
  // Create isolated execution context
  createContext(pluginId: string, options: SandboxOptions): Promise<SandboxContext>;

  // Load plugin code in context
  load(entryPoint: string, options: LoadOptions): Promise<PluginInstance>;

  // Pause plugin (no new requests)
  pause(pluginId: string): Promise<void>;

  // Resume plugin
  resume(pluginId: string): Promise<void>;

  // Terminate context
  terminate(pluginId: string): Promise<void>;

  // Enforce capability constraints
  enforceCapability(context: SandboxContext, capability: string): void;

  // Monitor resource usage
  getResourceUsage(pluginId: string): ResourceUsage;
}

interface SandboxOptions {
  pluginId: string;
  manifest: PluginManifest;

  // Isolation level
  isolation: "process" | "worker-thread" | "vm-context";

  // Resource limits
  memory: {
    soft: number; // Warning threshold (bytes)
    hard: number; // Kill threshold (bytes)
  };

  cpu: {
    maxUtilization: number; // Percentage (0-100)
  };

  // Timeout for operations
  timeout: {
    default: number;
    operation: Map<string, number>;
  };

  // Network policy
  network: {
    allow: string[]; // Allowlist of URLs
    deny: string[];
    defaultPolicy: "deny" | "allow";
  };

  // Filesystem policy
  filesystem: {
    read: string[];
    write: string[];
    delete: string[];
    temp: string; // Temp directory for plugin
    cache: string; // Cache directory for plugin
  };

  // Environment variables (from manifest.permissions.environment)
  environment: Record<string, string>;
}

interface SandboxContext {
  pluginId: string;
  workerId?: number; // Worker thread ID
  processId?: number; // Child process ID
  capabilities: Set<string>;
  resourceUsage: ResourceUsage;
  state: "active" | "paused" | "terminated";
}

interface ResourceUsage {
  memory: {
    current: number;
    peak: number;
    limit: number;
  };
  cpu: {
    usage: number;
    limit: number;
