### Implementation Strategies

#### Option 1: Worker Threads (Default for lightweight plugins)
```typescript
class WorkerThreadSandbox implements ISandbox {
  private workers: Map<string, Worker> = new Map();
  private capabilities: Map<string, Set<string>> = new Map();

  async load(entryPoint: string, options: LoadOptions): Promise<PluginInstance> {
    const worker = new Worker(entryPoint, {
      workerData: {
        pluginId: options.pluginId,
        manifest: options.manifest,
        config: options.config
      }
    });

    // Enforce capability model: intercept require/import
    const handler: ProxyHandler<any> = {
      get: (target, prop) => {
        if (!this.hasCapability(options.pluginId, `api:${String(prop)}`)) {
          throw new CapabilityError(`Plugin lacks capability for ${String(prop)}`);
        }
        return Reflect.get(target, prop);
      }
    };

    const proxy = new Proxy(hostApi, handler);

    worker.on("message", (msg) => this.handleWorkerMessage(options.pluginId, msg));
    worker.on("error", (err) => this.handleWorkerError(options.pluginId, err));

    this.workers.set(options.pluginId, worker);

    // Wrap plugin exports with capability checks
    return this.wrapPluginExports(worker, options.manifest);
  }

  private wrapPluginExports(
    worker: Worker,
    manifest: PluginManifest
  ): PluginInstance {
    return {
      ...manifest.exports.reduce((acc, exportName) => {
        acc[exportName] = (...args: any[]) => {
          // Verify capability before delegating to worker
          if (!this.hasCapability(manifest.id, `export:${exportName}`)) {
            throw new CapabilityError(...);
          }

          return new Promise((resolve, reject) => {
            const callId = generateId();

            // Setup one-time response listener
            const handler = (msg: WorkerMessage) => {
              if (msg.callId === callId) {
                worker.off("message", handler);
                if (msg.error) reject(new Error(msg.error));
                else resolve(msg.result);
              }
            };

            worker.on("message", handler);

            // Send call to worker (with timeout)
            worker.postMessage({
              type: "call",
              callId,
              method: exportName,
              args,
              timeout: manifest.resources.timeout.operations?.[exportName] 
                || manifest.resources.timeout.default
            });
          });
        };
        return acc;
      }, {})
    };
  }

  async terminate(pluginId: string): Promise<void> {
    const worker = this.workers.get(pluginId);
    if (worker) {
      await worker.terminate();
      this.workers.delete(pluginId);
      this.capabilities.delete(pluginId);
    }
  }

  private hasCapability(pluginId: string, capability: string): boolean {
    const caps = this.capabilities.get(pluginId);
    return caps?.has(capability) || false;
  }
}
```

#### Option 2: Child Process (For plugins needing native modules)
```typescript
class ChildProcessSandbox implements ISandbox {
  private processes: Map<string, ChildProcess> = new Map();

  async load(entryPoint: string, options: LoadOptions): Promise<PluginInstance> {
    const subprocess = fork(require.resolve("./plugin-runner.js"), {
      stdio: ["pipe", "pipe", "pipe", "ipc"],
      env: {
        ...process.env,
        PLUGIN_ID: options.pluginId,
        PLUGIN_CONFIG: JSON.stringify(options.config),
        PLUGIN_MANIFEST: JSON.stringify(options.manifest)
      }
    });

    // Setup memory limits using native modules
    subprocess.on("message", (msg) => {
      if (msg.type === "memory-warning") {
        this.logger.warn(`Plugin ${options.pluginId} exceeding soft memory limit`);
      }
    });

    this.processes.set(options.pluginId, subprocess);

    return this.wrapPluginExports(subprocess, options.manifest);
  }

  async terminate(pluginId: string): Promise<void> {
    const proc = this.processes.get(pluginId);
    if (proc) {
      proc.kill();
      this.processes.delete(pluginId);
    }
  }
}
```

#### Option 3: VM Context (For pure JavaScript, fastest startup)
```typescript
class VMContextSandbox implements ISandbox {
  private contexts: Map<string, VMContext> = new Map();

  async load(entryPoint: string, options: LoadOptions): Promise<PluginInstance> {
    const code = fs.readFileSync(entryPoint, "utf-8");

    const sandbox = {
      console,
      // Restricted globals
      require: (id: string) => {
        if (!this.isAllowedRequire(options.pluginId, id)) {
          throw new CapabilityError(`Cannot require ${id}`);
        }
        return require(id);
      },
      // Provide plugin API
      hostApi: this.createRestrictedHostAPI(options),
      // Plugin can't access top-level objects
      process: undefined,
      global: undefined,
      __dirname: options.manifest.id,
      __filename: entryPoint
    };

    const context = vm.createContext(sandbox);
    vm.runInContext(code, context, {
      filename: entryPoint,
      timeout: options.manifest.resources.timeout.default
    });

    // Extract exports
    const instance = context.exports || context.default;
    this.contexts.set(options.pluginId, context);

    return instance;
  }
}
```

### Capability-Based Access Control

```typescript
class CapabilityEnforcer {
  private capabilities: Map<string, Set<string>> = new Map();
  private auditLog: AuditEvent[] = [];

  enforceCapability(pluginId: string, capability: string): boolean {
    const granted = this.capabilities.get(pluginId)?.has(capability) || false;

    if (!granted) {
      this.auditLog.push({
        timestamp: Date.now(),
        pluginId,
        capability,
        result: "denied"
      });
    }

    return granted;
  }

  // Intercept filesystem access
  interceptFilesystem(
    pluginId: string,
    fs: typeof import("fs")
  ): typeof import("fs") {
    return {
      read: (path, ...args) => {
        if (!this.enforceCapability(pluginId, `fs:read:${this.normalizePath(path)}`)) {
          throw new CapabilityError(`Cannot read ${path}`);
        }
        return fs.read(path, ...args);
      },
      write: (path, ...args) => {
        if (!this.enforceCapability(pluginId, `fs:write:${this.normalizePath(path)}`)) {
          throw new CapabilityError(`Cannot write ${path}`);
        }
        return fs.write(path, ...args);
      },
      // ... other methods
    };
  }

  // Intercept network access
  interceptNetwork(
    pluginId: string,
    http: typeof import("http")
  ): typeof import("http") {
    return {
      request: (url, ...args) => {
        if (!this.enforceCapability(pluginId, `network:${this.normalizeDomain(url)}`)) {
          throw new CapabilityError(`Cannot access ${url}`);
        }
        return http.request(url, ...args);
      }
    };
  }
}
