## Versioned API Contract

The host provides versioned APIs that plugins depend on. Breaking changes are managed through explicit version ranges.

### API Versioning Strategy

```typescript
interface APIVersion {
  major: number;
  minor: number;
  patch: number;

  // Changes in this version
  breaking: string[];
  deprecated: string[];
  added: string[];
}

interface HostAPI {
  // Versioned namespace
  v1: HostAPIv1;
  v2: HostAPIv2;

  // Get current version
  getVersion(): SemanticVersion;

  // Check if plugin is compatible
  isCompatible(pluginId: string): boolean;
}

// API v1.2.0
interface HostAPIv1 {
  Reports: {
    create(spec: ReportSpec): Promise<Report>;
    update(id: string, spec: Partial<ReportSpec>): Promise<Report>;
    delete(id: string): Promise<void>;
    query(filter: ReportFilter): Promise<Report[]>;
  };

  Data: {
    fetch(source: string, query: DataQuery): Promise<DataTable>;
    transform(table: DataTable, transform: Transform): Promise<DataTable>;
    cache(key: string, data: any, ttl: number): Promise<void>;
  };

  Templates: {
    compile(source: string, variables: Record<string, any>): Promise<string>;
    render(id: string, context: RenderContext): Promise<string>;
  };

  Extensions: {
    registerReportType(type: ReportTypeExtension): Promise<void>;
    registerTransform(transform: TransformExtension): Promise<void>;
  };

  Logger: {
    info(msg: string, context?: any): void;
    warn(msg: string, context?: any): void;
    error(msg: string, error?: Error): void;
    debug(msg: string, context?: any): void;
  };

  Config: {
    get(key: string, defaultValue?: any): any;
    set(key: string, value: any): Promise<void>;
    watch(key: string, handler: (value: any) => void): Unsubscribe;
  };

  Events: {
    emit(event: string, payload: any): void;
    on(event: string, handler: (payload: any) => void): Unsubscribe;
    once(event: string): Promise<any>;
  };
}

// API v2.0.0 (breaking changes)
interface HostAPIv2 extends HostAPIv1 {
  // Replaced synchronous APIs with async
  Reports: {
    create(spec: ReportSpec): Promise<Report>;
