### Version Negotiation

```typescript
class APIVersionNegotiator {
  private versions: Map<string, APIVersion> = new Map();

  negotiate(
    pluginId: string,
    requestedRange: string, // "^1.2.0", "~2.1.0", etc.
    availableVersions: string[]
  ): string | null {
    // Parse version range (e.g., "^1.2.0" → min 1.2.0, max < 2.0.0)
    const range = this.parseVersionRange(requestedRange);

    // Find best matching version
    const compatible = availableVersions
      .map(v => semver.parse(v))
      .filter(v => semver.satisfies(v, range));

    if (compatible.length === 0) {
      return null; // Incompatible
    }

    // Prefer latest patch, then latest minor
    const best = compatible.sort((a, b) => semver.rcompare(a, b))[0];
    return best.version;
  }

  async checkBreakingChanges(
    fromVersion: string,
    toVersion: string
  ): Promise<BreakingChange[]> {
    const changes: BreakingChange[] = [];

    const from = semver.parse(fromVersion);
    const to = semver.parse(toVersion);

    // Collect all breaking changes in between
    for (const [v, metadata] of this.versions.entries()) {
      const version = semver.parse(v);

      if (semver.gt(version, from) && semver.lte(version, to)) {
        changes.push(...metadata.breaking);
      }
    }

    return changes;
  }
}
```

### Deprecation and Migration

```typescript
class DeprecationManager {
  private deprecations: Map<string, Deprecation> = new Map();

  registerDeprecation(key: string, deprecation: Deprecation): void {
    this.deprecations.set(key, deprecation);
  }

  checkDeprecation(apiPath: string): Deprecation | null {
    return this.deprecations.get(apiPath) || null;
  }

  async migrate(
    pluginId: string,
    fromVersion: string,
    toVersion: string
  ): Promise<MigrationGuide> {
    const deprecations = await this.checkBreakingChanges(fromVersion, toVersion);

    return {
      fromVersion,
      toVersion,
      breaking: deprecations.filter(d => d.type === "breaking"),
      deprecated: deprecations.filter(d => d.type === "deprecated"),
      added: deprecations.filter(d => d.type === "added"),
      migrationSteps: deprecations
        .filter(d => d.migrationPath)
        .map(d => d.migrationPath)
    };
  }
}

interface Deprecation {
  apiPath: string;
  version: string;
  type: "breaking" | "deprecated" | "added";
  reason: string;
  replacement?: string;
  migrationPath?: string; // URL or documentation
  removalVersion?: string;
}
