## Inter-Plugin Communication

Plugins can communicate through carefully controlled channels.

### Message Bus

```typescript
interface IMessageBus {
  // Publish event
  publish(event: PluginEvent): Promise<void>;

  // Subscribe to events
  subscribe(
    topic: string,
    handler: (event: PluginEvent) => Promise<void>,
    options?: SubscriptionOptions
  ): Unsubscribe;

  // Request-response pattern
  request(
    targetPluginId: string,
    method: string,
    args: any
  ): Promise<any>;

  // Direct call (requires explicit capability)
  call(
    sourcePluginId: string,
    targetPluginId: string,
    method: string,
    args: any
  ): Promise<any>;
}

interface PluginEvent {
  type: string;
  source: string; // Publishing plugin ID
  data: any;
  timestamp: number;
  correlation?: string; // For request-response
}

class MessageBus implements IMessageBus {
  private subscribers: Map<string, SubscriptionHandler[]> = new Map();
  private pendingRequests: Map<string, PendingRequest> = new Map();

  async publish(event: PluginEvent): Promise<void> {
    const handlers = this.subscribers.get(event.type) || [];

    await Promise.all(
      handlers.map(handler => {
        try {
          return Promise.race([
            handler.callback(event),
            this.timeout(handler.options?.timeout || 30000)
          ]);
        } catch (error) {
          this.logger.error(`Event handler error: ${error.message}`);
        }
      })
    );
  }

  async request(
    targetPluginId: string,
    method: string,
    args: any
  ): Promise<any> {
    const requestId = generateId();
    const correlationId = uuid.v4();

    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        this.pendingRequests.delete(requestId);
        reject(new TimeoutError(`Request to ${targetPluginId}.${method} timed out`));
      }, 30000);

      this.pendingRequests.set(requestId, { resolve, reject, timeout });

      // Send request through message bus as special event
      this.publish({
        type: `__request__:${targetPluginId}:${method}`,
        source: "system",
        data: { args, requestId, correlationId },
        timestamp: Date.now(),
        correlation: correlationId
      });
    });
  }

  async call(
    sourcePluginId: string,
    targetPluginId: string,
    method: string,
    args: any
  ): Promise<any> {
    // Verify capability
    if (!this.canCall(sourcePluginId, targetPluginId, method)) {
      throw new CapabilityError(
        `Plugin ${sourcePluginId} cannot call ${targetPluginId}.${method}`
      );
    }

    // Get target plugin's API
    const target = this.loadedPlugins.get(targetPluginId);
    if (!target) throw new PluginNotFoundError(targetPluginId);

    const apiSurface = target.exports[method];
    if (!apiSurface) throw new MethodNotFoundError(method);

    return apiSurface(...args);
  }
}
```

