        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {"apiKey": {"type": "string"}},
        "required": ["apiKey"]
      }
    },
    "security": {
      "requiresApproval": false,
      "sandboxLevel": "strict"
    }
  }
}

