## 3. Plugin Manifest Schema

Every plugin must include a `plugin.manifest.json` at its root.

### 3.1 Manifest Structure

```json
{
  "$schema": "https://reporting-tool.com/schemas/plugin-manifest@1.json",
  "apiVersion": "1.0",
  "kind": "Plugin",
  "metadata": {
    "name": "advanced-forecasting",
    "id": "com.example.advanced-forecasting",
    "version": "2.1.0",
    "title": "Advanced Forecasting Reports",
    "description": "ML-powered forecasting with confidence intervals",
    "author": {
      "name": "Forecast Team",
      "email": "forecast@example.com",
      "url": "https://example.com"
    },
    "license": "Apache-2.0",
    "homepage": "https://github.com/example/advanced-forecasting",
    "keywords": ["forecasting", "ml", "analytics"]
  },

  "spec": {
    "coreApiVersion": "^1.2.0",
    "minHostVersion": "2024.09.0",
    "maxHostVersion": "2099.12.31",

    "entryPoint": {
      "main": "dist/index.js",
      "types": "dist/index.d.ts"
    },

    "permissions": [
      "charts:read",
      "charts:write",
      "datasets:read",
      "auth:user-info",
      "storage:plugin-data",
      "network:external-ml-service"
    ],

    "dependencies": {
      "analytics-base": "^1.0.0"
    },

    "lifecycle": {
      "onLoad": true,
      "onUnload": true,
      "onReload": true,
      "stateManagement": "persistent"
    },

    "hooks": [
      {
        "name": "report:render",
        "priority": 100,
        "async": true
      },
      {
        "name": "dataset:validate",
        "priority": 50,
        "async": false
      }
    ],

    "configuration": {
      "schema": {
        "type": "object",
        "properties": {
          "mlServiceUrl": {
            "type": "string",
            "description": "ML service endpoint"
          },
          "confidenceLevel": {
            "type": "number",
            "minimum": 0.5,
            "maximum": 0.99,
            "default": 0.95
          },
          "cachePredictions": {
            "type": "boolean",
            "default": true
          }
        },
        "required": ["mlServiceUrl"]
      },
      "ui": {
        "type": "form",
        "sections": [
          {
            "title": "ML Service",
            "fields": ["mlServiceUrl"]
          },
          {
            "title": "Forecasting",
            "fields": ["confidenceLevel", "cachePredictions"]
          }
        ]
      }
    },

    "resources": {
