        "min": "128MB",
        "max": "512MB"
      },
      "cpu": {
        "min": 0.1,
        "max": 1.0
      },
      "timeout": "30s"
    },

    "capabilities": {
      "reportTypes": ["forecast", "sensitivity-analysis"],
      "dataFormats": ["csv", "parquet"],
      "exportFormats": ["pdf", "png", "json"]
    }
  },

  "compatibility": {
    "breaking": [],
    "deprecated": [
      {
        "path": "hooks.forecast:predict",
        "removedIn": "3.0.0",
        "alternative": "hooks.forecast:predict-v2"
      }
    ]
  }
}
```

