## 4. Plugin Registry

### 4.1 Registry Core

```typescript
// registry/plugin-registry.ts

interface PluginMetadata {
  id: string;
  name: string;
  version: string;
  manifest: PluginManifest;
  path: string;
  enabled: boolean;
  loadedAt?: Date;
  status: 'unloaded' | 'loading' | 'loaded' | 'error';
  error?: Error;
}

interface PluginDependency {
  pluginId: string;
  version: string;
  required: boolean;
}

interface RegistryEntry {
  metadata: PluginMetadata;
  dependencies: PluginDependency[];
  dependents: string[]; // plugins that depend on this
  instance?: PluginInstance;
}

export class PluginRegistry {
  private plugins: Map<string, RegistryEntry> = new Map();
  private dependencyGraph: DependencyGraph;
  private eventBus: EventEmitter;
  private config: RegistryConfig;

  constructor(config: RegistryConfig) {
    this.config = config;
    this.dependencyGraph = new DependencyGraph();
    this.eventBus = new EventEmitter();
  }

  /**
   * Discover plugins from configured paths
   */
  async discover(): Promise<PluginMetadata[]> {
    const discovered: PluginMetadata[] = [];

    for (const searchPath of this.config.searchPaths) {
      const manifests = await this.findManifests(searchPath);

      for (const manifestPath of manifests) {
        try {
          const manifest = await this.loadManifest(manifestPath);
          const metadata = this.createMetadata(manifest, manifestPath);

          discovered.push(metadata);
          this.plugins.set(metadata.id, {
            metadata,
            dependencies: this.extractDependencies(manifest),
            dependents: [],
            instance: undefined
          });
        } catch (error) {
          this.eventBus.emit('discovery:error', {
            path: manifestPath,
            error
          });
        }
      }
    }

    // Build dependency graph
    this.rebuildDependencyGraph();

    this.eventBus.emit('discovery:complete', {
      count: discovered.length,
      plugins: discovered
    });

    return discovered;
  }

  /**
   * Get plugin by ID
   */
  getPlugin(id: string): RegistryEntry | undefined {
    return this.plugins.get(id);
  }

  /**
   * Get all plugins
   */
  getAllPlugins(): PluginMetadata[] {
    return Array.from(this.plugins.values()).map(e => e.metadata);
  }

  /**
   * Get enabled plugins in load order (respecting dependencies)
   */
  getLoadOrder(): string[] {
    const enabledPlugins = Array.from(this.plugins.values())
      .filter(e => e.metadata.enabled)
      .map(e => e.metadata.id);

    return this.dependencyGraph.topologicalSort(enabledPlugins);
  }

  /**
   * Check dependency resolution
   */
  resolveDependencies(pluginId: string): {
    satisfied: boolean;
    missing: string[];
    conflicts: string[];
  } {
    const entry = this.plugins.get(pluginId);
    if (!entry) {
      return { satisfied: false, missing: [pluginId], conflicts: [] };
    }

    const missing: string[] = [];
    const conflicts: string[] = [];

    for (const dep of entry.dependencies) {
      const depEntry = this.plugins.get(dep.pluginId);

      if (!depEntry) {
        missing.push(dep.pluginId);
        continue;
      }

      // Check version compatibility
      if (!this.satisfiesVersion(depEntry.metadata.version, dep.version)) {
        conflicts.push(`${dep.pluginId}@${dep.version} (have ${depEntry.metadata.version})`);
      }
    }

    return {
      satisfied: missing.length === 0 && conflicts.length === 0,
      missing,
      conflicts
    };
  }

  /**
   * Enable/disable plugin
   */
  setEnabled(id: string, enabled: boolean): void {
    const entry = this.plugins.get(id);
    if (!entry) throw new Error(`Plugin not found: ${id}`);

    entry.metadata.enabled = enabled;
    this.eventBus.emit('plugin:state-changed', {
      id,
      enabled
    });
  }

  /**
   * Get plugin status
   */
  getStatus(id: string): PluginMetadata['status'] {
    const entry = this.plugins.get(id);
    if (!entry) throw new Error(`Plugin not found: ${id}`);
    return entry.metadata.status;
  }

  /**
   * Set plugin status
   */
  setStatus(id: string, status: PluginMetadata['status'], error?: Error): void {
    const entry = this.plugins.get(id);
    if (!entry) throw new Error(`Plugin not found: ${id}`);

    entry.metadata.status = status;
    entry.metadata.error = error;

    this.eventBus.emit('plugin:status-changed', {
      id,
      status,
      error
    });
  }

  /**
   * Clear plugin error
   */
  clearError(id: string): void {
    const entry = this.plugins.get(id);
    if (!entry) throw new Error(`Plugin not found: ${id}`);

    entry.metadata.error = undefined;
  }

  /**
   * Listen to registry events
   */
  on(event: string, callback: Function): void {
    this.eventBus.on(event, callback);
  }

  /**
   * Remove event listener
   */
  off(event: string, callback: Function): void {
    this.eventBus.off(event, callback);
  }

  private extractDependencies(manifest: PluginManifest): PluginDependency[] {
    if (!manifest.spec.dependencies) return [];

    return Object.entries(manifest.spec.dependencies).map(([id, version]) => ({
      pluginId: id,
      version,
      required: true
    }));
  }

  private satisfiesVersion(have: string, want: string): boolean {
    // Use semver library for proper version matching
    return semver.satisfies(have, want);
  }

  private rebuildDependencyGraph(): void {
    this.dependencyGraph.clear();

    for (const [pluginId, entry] of this.plugins) {
      this.dependencyGraph.addNode(pluginId);

      for (const dep of entry.dependencies) {
        this.dependencyGraph.addEdge(pluginId, dep.pluginId);

        // Track dependent plugins
        const depEntry = this.plugins.get(dep.pluginId);
        if (depEntry && !depEntry.dependents.includes(pluginId)) {
          depEntry.dependents.push(pluginId);
        }
      }
    }
  }

  private async loadManifest(path: string): Promise<PluginManifest> {
    const content = await fs.promises.readFile(path, 'utf-8');
    const manifest = JSON.parse(content);

    // Validate against schema
    const schema = await this.loadSchema();
    const validation = ajv.compile(schema);

    if (!validation(manifest)) {
      throw new ValidationError('Invalid manifest', validation.errors);
    }

    return manifest;
  }

  private async findManifests(searchPath: string): Promise<string[]> {
    // Recursively find all plugin.manifest.json files
    const manifests: string[] = [];
    // Implementation uses glob or recursive fs traversal
    return manifests;
  }

  private createMetadata(manifest: PluginManifest, path: string): PluginMetadata {
    return {
      id: manifest.metadata.id,
      name: manifest.metadata.name,
      version: manifest.metadata.version,
      manifest,
      path: dirname(path),
      enabled: true,
      status: 'unloaded'
    };
  }
}
