### 4.2 Dependency Graph

```typescript
// registry/dependency-graph.ts

class DependencyGraph {
  private nodes: Set<string> = new Set();
  private edges: Map<string, Set<string>> = new Map();

  addNode(id: string): void {
    this.nodes.add(id);
    if (!this.edges.has(id)) {
      this.edges.set(id, new Set());
    }
  }

  addEdge(from: string, to: string): void {
    this.addNode(from);
    this.addNode(to);
    this.edges.get(from)!.add(to);
  }

  /**
   * Topological sort using Kahn's algorithm
   * Returns plugins in load order (dependencies first)
   */
  topologicalSort(plugins: string[]): string[] {
    const inDegree = new Map<string, number>();
    const subgraph = new Map<string, Set<string>>();

    // Initialize with only requested plugins
    for (const plugin of plugins) {
      if (!this.nodes.has(plugin)) continue;
      inDegree.set(plugin, 0);
      subgraph.set(plugin, new Set(this.edges.get(plugin) || []));
    }

    // Count in-degrees within subgraph
    for (const [node, deps] of subgraph) {
      for (const dep of deps) {
        if (subgraph.has(dep)) {
          inDegree.set(dep, (inDegree.get(dep) || 0) + 1);
        }
      }
    }

    // Find all nodes with no incoming edges
    const queue = Array.from(subgraph.keys())
      .filter(node => inDegree.get(node) === 0);

    const sorted: string[] = [];

    while (queue.length > 0) {
      const node = queue.shift()!;
      sorted.push(node);

      // Process dependencies
      for (const neighbor of this.edges.get(node) || []) {
        if (!subgraph.has(neighbor)) continue;

        inDegree.set(neighbor, inDegree.get(neighbor)! - 1);
        if (inDegree.get(neighbor) === 0) {
          queue.push(neighbor);
        }
      }
    }

    // Check for cycles
    if (sorted.length !== subgraph.size) {
      throw new Error('Circular dependency detected in plugin dependencies');
    }

    return sorted;
  }

  /**
   * Get all transitive dependencies
   */
  getTransitiveDependencies(pluginId: string): Set<string> {
    const visited = new Set<string>();
    const queue = [pluginId];

    while (queue.length > 0) {
      const current = queue.shift()!;
      if (visited.has(current)) continue;
      visited.add(current);

      const deps = this.edges.get(current) || new Set();
      queue.push(...Array.from(deps));
    }

    visited.delete(pluginId);
    return visited;
  }

  clear(): void {
    this.nodes.clear();
    this.edges.clear();
  }
}
