### 5.2 Lifecycle Manager Implementation

```typescript
// lifecycle/lifecycle-manager.ts

interface PluginInstance {
  id: string;
  version: string;
  exports: PluginExports;
  context: PluginContext;
  state: PluginState;
  hooks: Map<string, PluginHook[]>;
}

interface PluginExports {
  onLoad?: () => Promise<void>;
  onUnload?: () => Promise<void>;
  onReload?: () => Promise<void>;
  hooks?: Record<string, PluginHook>;
  configure?: (config: any) => Promise<void>;
}

interface PluginContext {
  pluginId: string;
  version: string;
  api: CoreAPI;
  storage: PluginStorage;
  logger: Logger;
  config: any;
}

interface PluginState {
  data: Map<string, any>;
  persistent: boolean;
}

export class LifecycleManager {
  private instances: Map<string, PluginInstance> = new Map();
  private registry: PluginRegistry;
  private apiFactory: CoreAPIFactory;
  private sandboxFactory: SandboxFactory;
  private eventBus: EventEmitter;
  private loadLocks: Map<string, Promise<void>> = new Map();

  constructor(registry: PluginRegistry, apiFactory: CoreAPIFactory) {
    this.registry = registry;
    this.apiFactory = apiFactory;
    this.sandboxFactory = new SandboxFactory();
    this.eventBus = new EventEmitter();
  }

  /**
   * Load all enabled plugins in dependency order
   */
  async loadAll(): Promise<{
    loaded: string[];
    failed: Array<{ id: string; error: Error }>;
  }> {
    const loadOrder = this.registry.getLoadOrder();
    const loaded: string[] = [];
    const failed: Array<{ id: string; error: Error }> = [];

    for (const pluginId of loadOrder) {
      try {
        await this.load(pluginId);
        loaded.push(pluginId);
      } catch (error) {
        failed.push({ id: pluginId, error: error as Error });
        this.registry.setStatus(pluginId, 'error', error as Error);

        // Don't load plugins that depend on this one
        const dependents = this.getDependents(pluginId);
        for (const dependent of dependents) {
          this.registry.setEnabled(dependent, false);
        }
      }
    }

    this.eventBus.emit('lifecycle:load-all-complete', { loaded, failed });
    return { loaded, failed };
  }

  /**
   * Load a single plugin
   */
  async load(pluginId: string): Promise<PluginInstance> {
    // Prevent duplicate load attempts
    if (this.loadLocks.has(pluginId)) {
      return this.loadLocks.get(pluginId)!;
    }

    const loadPromise = this._loadInternal(pluginId);
    this.loadLocks.set(pluginId, loadPromise);

    try {
      const instance = await loadPromise;
      this.loadLocks.delete(pluginId);
      return instance;
    } catch (error) {
      this.loadLocks.delete(pluginId);
      throw error;
    }
  }

  private async _loadInternal(pluginId: string): Promise<PluginInstance> {
    const entry = this.registry.getPlugin(pluginId);
    if (!entry) throw new Error(`Plugin not found: ${pluginId}`);

    this.registry.setStatus(pluginId, 'loading');

    try {
      // Verify dependencies
      const depCheck = this.registry.resolveDependencies(pluginId);
      if (!depCheck.satisfied) {
        throw new Error(
          `Unresolved dependencies: missing=[${depCheck.missing.join(', ')}], ` +
          `conflicts=[${depCheck.conflicts.join(', ')}]`
        );
      }

      // Load dependencies first
      for (const dep of entry.dependencies) {
        if (!this.instances.has(dep.pluginId)) {
          await this.load(dep.pluginId);
        }
      }

      // Create sandbox
      const sandbox = await this.sandboxFactory.create({
        pluginId,
        version: entry.metadata.version,
        manifest: entry.metadata.manifest,
        resourceLimits: this.parseResourceLimits(entry.metadata.manifest)
      });

      // Create core API with permissions
      const permissions = entry.metadata.manifest.spec.permissions || [];
      const api = this.apiFactory.create(pluginId, permissions);

      // Create plugin context
      const context: PluginContext = {
        pluginId,
        version: entry.metadata.version,
        api,
        storage: new PluginStorage(pluginId, entry.metadata.manifest.spec.lifecycle?.stateManagement),
        logger: new PluginLogger(pluginId),
        config: entry.metadata.manifest.spec.configuration?.schema || {}
      };

      // Load plugin module
      const moduleExports = await this.loadPluginModule(
        entry.metadata.path,
        entry.metadata.manifest.spec.entryPoint.main,
        sandbox,
        context
      );

      // Create instance
      const instance: PluginInstance = {
        id: pluginId,
        version: entry.metadata.version,
        exports: moduleExports,
        context,
        state: {
          data: new Map(),
          persistent: entry.metadata.manifest.spec.lifecycle?.stateManagement === 'persistent'
        },
        hooks: new Map()
      };

      // Register hooks
      this.registerHooks(instance, entry.metadata.manifest);

      // Call onLoad hook
      if (moduleExports.onLoad) {
        await this.executeHookWithTimeout(
          pluginId,
          moduleExports.onLoad.bind(instance.exports),
          30000,
          'onLoad'
        );
      }

      this.instances.set(pluginId, instance);
      entry.instance = instance;

      this.registry.setStatus(pluginId, 'loaded');
      entry.metadata.loadedAt = new Date();

      this.eventBus.emit('lifecycle:load', { id: pluginId, instance });

      return instance;
    } catch (error) {
      this.registry.setStatus(pluginId, 'error', error as Error);
      this.eventBus.emit('lifecycle:load-error', { id: pluginId, error });
      throw error;
    }
  }

  /**
   * Unload a plugin
   */
  async unload(pluginId: string): Promise<void> {
    const instance = this.instances.get(pluginId);
    if (!instance) return;

    this.registry.setStatus(pluginId, 'unloading');

    try {
      // Check for dependents
      const dependents = this.getDependents(pluginId);
      if (dependents.length > 0) {
        throw new Error(
          `Cannot unload ${pluginId}: depended on by [${dependents.join(', ')}]`
        );
      }

      // Persist state if needed
      if (instance.state.persistent) {
        await instance.context.storage.persist(instance.state.data);
      }

      // Call onUnload hook
      if (instance.exports.onUnload) {
        await this.executeHookWithTimeout(
          pluginId,
          instance.exports.onUnload.bind(instance.exports),
          30000,
          'onUnload'
        );
      }

      this.instances.delete(pluginId);

      const entry = this.registry.getPlugin(pluginId);
      if (entry) {
        entry.instance = undefined;
        this.registry.setStatus(pluginId, 'unloaded');
      }

      this.eventBus.emit('lifecycle:unload', { id: pluginId });
    } catch (error) {
      this.registry.setStatus(pluginId, 'error', error as Error);
      this.eventBus.emit('lifecycle:unload-error', { id: pluginId, error });
      throw error;
    }
  }

  /**
   * Reload a plugin (hot reload)
   */
  async reload(pluginId: string): Promise<PluginInstance> {
    const entry = this.registry.getPlugin(pluginId);
    if (!entry) throw new Error(`Plugin not found: ${pluginId}`);

    this.registry.setStatus(pluginId, 'reloading');

    try {
      const dependents = this.getDependents(pluginId);

      // Unload dependents first
      for (const dependent of dependents) {
        await this.unload(dependent);
      }

      // Unload and reload the plugin
      const wasEnabled = entry.metadata.enabled;
      await this.unload(pluginId);

      const instance = await this.load(pluginId);

      // Reload dependents
      for (const dependent of dependents) {
        if (this.registry.getPlugin(dependent)?.metadata.enabled) {
          await this.load(dependent);
        }
      }

      this.eventBus.emit('lifecycle:reload', { id: pluginId, instance });

      return instance;
    } catch (error) {
      this.registry.setStatus(pluginId, 'error', error as Error);
      this.eventBus.emit('lifecycle:reload-error', { id: pluginId, error });
      throw error;
    }
  }

  /**
   * Get loaded instance
   */
  getInstance(pluginId: string): PluginInstance | undefined {
    return this.instances.get(pluginId);
  }

  /**
   * Get all loaded instances
   */
  getAllInstances(): PluginInstance[] {
    return Array.from(this.instances.values());
  }

  /**
   * Listen to lifecycle events
   */
  on(event: string, callback: Function): void {
    this.eventBus.on(event, callback);
  }

  /**
   * Unload all plugins
   */
  async unloadAll(): Promise<{ unloaded: string[]; errors: Array<{ id: string; error: Error }> }> {
    const unloaded: string[] = [];
    const errors: Array<{ id: string; error: Error }> = [];

    // Unload in reverse order of load
    const loadOrder = this.registry.getLoadOrder();
    for (const pluginId of loadOrder.reverse()) {
      try {
        await this.unload(pluginId);
        unloaded.push(pluginId);
      } catch (error) {
        errors.push({ id: pluginId, error: error as Error });
      }
    }

    this.eventBus.emit('lifecycle:unload-all-complete', { unloaded, errors });
    return { unloaded, errors };
  }

  private registerHooks(
    instance: PluginInstance,
    manifest: PluginManifest
  ): void {
    for (const hookDef of manifest.spec.hooks || []) {
      if (instance.exports.hooks?.[hookDef.name]) {
        const hook = instance.exports.hooks[hookDef.name];
        const hooks = instance.hooks.get(hookDef.name) || [];
        hooks.push({
          ...hookDef,
          handler: hook.bind(instance.exports)
        });
        instance.hooks.set(hookDef.name, hooks);
      }
    }
  }

  private async executeHookWithTimeout(
    pluginId: string,
    fn: Function,
    timeout: number,
    hookName: string
  ): Promise<any> {
    return Promise.race([
      fn(),
      new Promise((_, reject) =>
        setTimeout(
          () => reject(new Error(`Hook ${hookName} timed out after ${timeout}ms`)),
          timeout
        )
      )
    ]);
  }

  private async loadPluginModule(
    pluginPath: string,
    entryPoint: string,
    sandbox: Sandbox,
    context: PluginContext
  ): Promise<PluginExports> {
    const modulePath = join(pluginPath, entryPoint);
    // Load and execute in sandbox
    return sandbox.loadModule(modulePath, context);
  }

  private getDependents(pluginId: string): string[] {
    const entry = this.registry.getPlugin(pluginId);
    return entry?.dependents || [];
  }

  private parseResourceLimits(manifest: PluginManifest): ResourceLimits {
    const spec = manifest.spec.resources;
    return {
      memory: this.parseSize(spec?.memory?.max || '512MB'),
      timeout: this.parseDuration(spec?.timeout || '30s'),
      cpu: spec?.cpu?.max || 1.0
    };
  }

  private parseSize(size: string): number {
    // Parse "512MB" to bytes
    const match = size.match(/^(\d+(?:\.\d+)?)(B|KB|MB|GB)$/);
    if (!match) throw new Error(`Invalid size: ${size}`);
    const [, value, unit] = match;
    const multipliers = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 };
    return parseFloat(value) * multipliers[unit as keyof typeof multipliers];
  }

  private parseDuration(duration: string): number {
    // Parse "30s" to milliseconds
    const match = duration.match(/^(\d+(?:\.\d+)?)(ms|s|m|h)$/);
    if (!match) throw new Error(`Invalid duration: ${duration}`);
    const [, value, unit] = match;
    const multipliers = { ms: 1, s: 1000, m: 60000, h: 3600000 };
    return parseFloat(value) * multipliers[unit as keyof typeof multipliers];
  }
}
