## 6. Sandboxed Execution

### 6.1 Sandbox Architecture

```typescript
// sandbox/sandbox.ts

interface SandboxConfig {
  pluginId: string;
  version: string;
  manifest: PluginManifest;
  resourceLimits: ResourceLimits;
}

interface ResourceLimits {
  memory: number; // bytes
  timeout: number; // ms
  cpu: number; // 0-1 scale
}

export class Sandbox {
  private vm: vm.Context;
  private config: SandboxConfig;
  private resourceMonitor: ResourceMonitor;
  private accessControl: AccessControl;

  constructor(config: SandboxConfig) {
    this.config = config;
    this.resourceMonitor = new ResourceMonitor(config.resourceLimits);
    this.accessControl = new AccessControl(config.manifest.spec.permissions || []);

    // Create isolated VM context
    this.vm = vm.createContext({
      // Global objects allowed in sandbox
      console: {
        log: (...args: any[]) => console.log(`[${config.pluginId}]`, ...args),
        warn: (...args: any[]) => console.warn(`[${config.pluginId}]`, ...args),
        error: (...args: any[]) => console.error(`[${config.pluginId}]`, ...args)
      },
      setTimeout,
      setInterval,
      // Math, JSON, etc are automatically available
      Math,
      JSON,
      Object,
      Array,
      String,
      Number,
      Boolean,
      Date,
      RegExp,
      Error,
      Promise,
      Map,
      Set,
      WeakMap,
      WeakSet
    });

    // Freeze built-ins to prevent tampering
    Object.freeze(this.vm.Object);
    Object.freeze(this.vm.Object.prototype);
  }

  /**
   * Load and execute a plugin module
   */
  async loadModule(modulePath: string, context: PluginContext): Promise<PluginExports> {
    // Read module source
    const source = await fs.promises.readFile(modulePath, 'utf-8');

    // Wrap module with plugin context injection
    const wrappedSource = this.wrapModule(source, context);

    // Start resource monitoring
    const stopMonitoring = this.resourceMonitor.start();

    try {
      // Execute in sandbox
      const script = new vm.Script(wrappedSource, {
        filename: modulePath,
        displayErrors: true
      });

      const result = script.runInContext(this.vm, {
        timeout: this.config.resourceLimits.timeout
      });

      // If module exports a function (module.exports = function), call it
      // Otherwise assume it's an object with exports
      if (typeof result === 'function') {
        return result(context);
      }

      return result;
    } catch (error) {
      throw new SandboxExecutionError(
        `Failed to load plugin ${this.config.pluginId}`,
        error as Error
      );
    } finally {
      stopMonitoring();
    }
  }

  /**
   * Call a function in the sandbox
   */
  async call(fn: Function, args: any[], timeout?: number): Promise<any> {
    const stopMonitoring = this.resourceMonitor.start();

    try {
      return await Promise.race([
        Promise.resolve(fn(...args)),
        new Promise((_, reject) =>
          setTimeout(
            () => reject(new Error('Function call timeout')),
            timeout || this.config.resourceLimits.timeout
          )
        )
      ]);
    } catch (error) {
      throw new SandboxExecutionError(
        `Error calling function in ${this.config.pluginId}`,
        error as Error
      );
    } finally {
      stopMonitoring();
    }
  }

  /**
   * Check if an operation is permitted
   */
  canAccess(permission: string): boolean {
    return this.accessControl.check(permission);
  }

  /**
   * Get sandbox metadata
   */
  getMetadata() {
    return {
      pluginId: this.config.pluginId,
      version: this.config.version,
      resourceLimits: this.config.resourceLimits,
      permissions: this.accessControl.getPermissions()
    };
  }

  private wrapModule(source: string, context: PluginContext): string {
    return `
    (function(pluginContext) {
      const module = { exports: {} };
      const exports = module.exports;

      // Create access-controlled API proxy
      const api = new Proxy(pluginContext.api, {
        get: (target, prop) => {
          if (!this.accessControl.check('api:' + String(prop))) {
            throw new Error('Permission denied: ' + String(prop));
          }
          return target[prop];
        }
      });

      // Execute plugin code
      ${source}

      return module.exports;
    })
    `;
  }

  destroy(): void {
    this.resourceMonitor.stop();
    // Clean up VM context
    Object.keys(this.vm).forEach(key => {
      delete (this.vm as any)[key];
    });
  }
}

/**
 * Monitor resource usage
 */
class ResourceMonitor {
  private limits: ResourceLimits;
  private startTime?: number;
  private startMemory?: number;
  private checkInterval?: NodeJS.Timeout;

  constructor(limits: ResourceLimits) {
    this.limits = limits;
  }

  start(): () => void {
    this.startTime = Date.now();
    this.startMemory = process.memoryUsage().heapUsed;

    this.checkInterval = setInterval(() => {
      const elapsed = Date.now() - this.startTime!;
      const memory = process.memoryUsage().heapUsed - this.startMemory!;

      if (elapsed > this.limits.timeout) {
        throw new Error(`Timeout: ${elapsed}ms exceeds limit of ${this.limits.timeout}ms`);
      }

      if (memory > this.limits.memory) {
        throw new Error(
          `Memory exceeded: ${memory} bytes exceeds limit of ${this.limits.memory} bytes`
        );
      }
    }, 100);

    return () => this.stop();
  }

  stop(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
    }
  }
}

/**
 * Permission-based access control
 */
class AccessControl {
  private permissions: Set<string>;
  private permissionTrie: PermissionTrie;

  constructor(permissions: string[]) {
    this.permissions = new Set(permissions);
    this.permissionTrie = new PermissionTrie(permissions);
  }

  check(permission: string): boolean {
    // Support wildcards: "charts:*" permits "charts:read", "charts:write"
    return this.permissionTrie.matches(permission);
  }

  getPermissions(): string[] {
    return Array.from(this.permissions);
  }
}

/**
 * Efficient permission matching with wildcard support
 */
class PermissionTrie {
  private root: TrieNode = {};

  constructor(permissions: string[]) {
    for (const perm of permissions) {
      this.insert(perm);
    }
  }

  insert(permission: string): void {
    const parts = permission.split(':');
    let node = this.root;

    for (const part of parts) {
      if (!node[part]) {
        node[part] = {};
      }
      node = node[part];
    }

    node['$'] = true; // Mark as valid permission
  }

  matches(permission: string): boolean {
    const parts = permission.split(':');
    return this._matches(parts, this.root, 0);
  }

  private _matches(parts: string[], node: any, index: number): boolean {
    if (index === parts.length) {
      return node['$'] === true;
    }

    const part = parts[index];

    // Exact match
    if (node[part]) {
      if (this._matches(parts, node[part], index + 1)) {
        return true;
      }
    }

    // Wildcard match
    if (node['*']) {
      return true;
    }

    return false;
  }
}

interface TrieNode {
  [key: string]: any;
}

export class SandboxFactory {
  async create(config: SandboxConfig): Promise<Sandbox> {
    return new Sandbox(config);
  }
}
