## 7. Versioned Core API Contract

### 7.1 API Versioning Strategy

```typescript
// api/api-contract.ts

/**
 * Core API Contract - the interface plugins can depend on
 * 
 * Versioning:
 * - MAJOR: Breaking changes (removed methods, changed signatures)
 * - MINOR: Backward-compatible additions (new methods, new optional params)
 * - PATCH: Bug fixes, no API changes
 * 
 * Compatibility guarantee: Plugins built for v1.x work with any v1.y where y >= x
 */

export const CORE_API_VERSION = '2.1.0';

// Version history for migration support
export const API_VERSIONS = [
  { version: '1.0.0', supportedUntil: '2024-12-31', status: 'deprecated' },
  { version: '1.5.0', supportedUntil: '2025-12-31', status: 'stable' },
  { version: '2.0.0', supportedUntil: '2026-12-31', status: 'stable' },
  { version: '2.1.0', supportedUntil: '2027-12-31', status: 'current' }
];

/**
 * Core API v1 (deprecated)
 */
export interface CoreAPIv1 {
  charts: ChartsAPIv1;
  datasets: DatasetsAPIv1;
  auth: AuthAPIv1;
}

interface ChartsAPIv1 {
  register: (type: string, factory: ChartFactory) => void;
  create: (config: ChartConfig) => Promise<Chart>;
}

interface DatasetsAPIv1 {
  fetch: (id: string) => Promise<Dataset>;
  list: () => Promise<Dataset[]>;
}

interface AuthAPIv1 {
  getCurrentUser: () => User;
}

/**
 * Core API v2 (current)
 * 
 * Breaking changes from v1:
 * - DatasetsAPI: list() now returns paginated results
 * - ChartsAPI: New onRender hook
 * 
 * Backward-compatible additions:
 * - New storage API
 * - New validation API
 * - Optional permissions parameter on all APIs
 */
export interface CoreAPI {
  // Charts API
  charts: {
    register: (type: string, factory: ChartFactory, options?: ChartRegisterOptions) => void;
    create: (config: ChartConfig, options?: ChartCreateOptions) => Promise<Chart>;
    list: () => Promise<Chart[]>;
    delete: (id: string) => Promise<void>;
    on: (event: 'render' | 'error', handler: Function) => void;
    off: (event: 'render' | 'error', handler: Function) => void;
  };

  // Datasets API
  datasets: {
    fetch: (id: string, options?: FetchOptions) => Promise<Dataset>;
    list: (options?: ListOptions) => Promise<PaginatedResults<Dataset>>;
    validate: (dataset: Dataset) => Promise<ValidationResult>;
    transform: (dataset: Dataset, transformFn: TransformFunction) => Promise<Dataset>;
  };

  // Authentication API
  auth: {
    getCurrentUser: () => User;
    isAuthorized: (resource: string, action: string) => boolean;
    // NEW in v2.1
    getPermissions: () => string[];
  };

  // Storage API (new in v2)
  storage: {
    get: (key: string) => Promise<any>;
    set: (key: string, value: any, ttl?: number) => Promise<void>;
    delete: (key: string) => Promise<void>;
    clear: () => Promise<void>;
  };

  // Validation API (new in v2)
  validation: {
    registerSchema: (name: string, schema: JSONSchema) => void;
    validate: (data: any, schemaName: string) => ValidationResult;
  };

  // Events API (new in v2)
  events: {
    emit: (event: string, data: any) => void;
    on: (event: string, handler: Function) => void;
    off: (event: string, handler: Function) => void;
  };

  // Reporting API (new in v2.1)
  reporting: {
    getReportContext: () => ReportContext;
    registerReportType: (name: string, handler: ReportHandler) => void;
  };
}

/**
 * API v2.1 with full typing
 */
export interface ChartFactory {
  (data: Dataset, config: ChartConfig): Chart;
}

export interface ChartConfig {
  title: string;
  type: string;
  data: Dataset;
  options?: Record<string, any>;
}

export interface ChartRegisterOptions {
