  metadata?: Record<string, any>;
}

export interface Column {
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean';
}

export interface PaginatedResults<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
  hasMore: boolean;
}

export interface FetchOptions {
  cache?: boolean;
  timeout?: number;
}

export interface ListOptions {
  page?: number;
