}

/**
 * API adapter for backward compatibility
 */
export class APIAdapter {
  private v1Api: CoreAPIv1;
  private v2Api: CoreAPI;

  constructor(v2Api: CoreAPI) {
    this.v2Api = v2Api;
    this.v1Api = this.createV1Adapter();
  }

  private createV1Adapter(): CoreAPIv1 {
    return {
      charts: {
        register: (type: string, factory: ChartFactory) => {
          // Call v2 API
          this.v2Api.charts.register(type, factory);
        },
        create: async (config: ChartConfig) => {
          return this.v2Api.charts.create(config);
        }
      },
      datasets: {
        fetch: async (id: string) => {
          return this.v2Api.datasets.fetch(id);
        },
        list: async () => {
          // v1 returned Dataset[], v2 returns PaginatedResults
          const result = await this.v2Api.datasets.list();
          return result.items;
        }
      },
      auth: {
        getCurrentUser: () => {
          return this.v2Api.auth.getCurrentUser();
        }
      }
    };
  }

  getV1(): CoreAPIv1 {
    return this.v1Api;
  }

  getV2(): CoreAPI {
    return this.v2Api;
  }
}

/**
 * API factory with version negotiation
 */
export class CoreAPIFactory {
  private implementations: Map<string, APIImplementation> = new Map();

  constructor() {
    this.registerImplementation('1.5.0', new APIv1Impl());
    this.registerImplementation('2.0.0', new APIv2Impl());
    this.registerImplementation('2.1.0', new APIv21Impl());
  }

  /**
   * Create API instance for plugin with version requirements
   */
  create(pluginId: string, permissions: string[], requiredVersion: string): CoreAPI {
    // Find best matching implementation
    const impl = this.findBestImplementation(requiredVersion);
    if (!impl) {
      throw new Error(`No API implementation available for version ${requiredVersion}`);
    }

    return impl.create(pluginId, permissions);
  }

  registerImplementation(version: string, impl: APIImplementation): void {
    this.implementations.set(version, impl);
  }

  private findBestImplementation(requiredVersion: string): APIImplementation | null {
    // Use semver to find best match
    const versions = Array.from(this.implementations.keys()).sort(semver.rcompare);

    for (const version of versions) {
      if (semver.satisfies(version, requiredVersion)) {
        return this.implementations.get(version)!;
      }
    }

    return null;
  }
}

interface APIImplementation {
  create(pluginId: string, permissions: string[]): CoreAPI;
}
