// src/index.ts

import { PluginContext, CoreAPI, Dataset, ChartConfig, Report } from '@reporting/plugin-api';
import { ForecastEngine } from './forecast';
import { createChartFactory } from './charts';

// Export plugin interface
export interface ForecastPlugin {
  onLoad(): Promise<void>;
  onUnload(): Promise<void>;
  onReload(): Promise<void>;
  hooks: {
    'report:render': ReportRenderHook;
    'dataset:validate': DatasetValidateHook;
  };
}

export async function onLoad(this: any) {
  const context: PluginContext = this;
  const { api, config, logger, storage } = context;

  logger.info('Loading Advanced Forecasting Plugin v2.1.0');

  // Initialize forecast engine
  const engine = new ForecastEngine({
    apiUrl: config.mlServiceUrl,
    confidenceLevel: config.confidenceLevel
  });

  // Register chart type
  api.charts.register('forecast', createChartFactory(engine), {
    default: false
  });

  // Register report type
  api.reporting.registerReportType('forecast', async (reportContext, dataset) => {
    logger.info(`Generating forecast for dataset ${reportContext.datasetId}`);

    try {
      // Validate dataset
      const validation = await api.datasets.validate(dataset);
      if (!validation.valid) {
        throw new Error(`Dataset validation failed: ${validation.errors?.[0]?.message}`);
      }

      // Check cache
      const cacheKey = `forecast:${reportContext.datasetId}:${reportContext.userId}`;
      const cached = await api.storage.get(cacheKey);
      if (cached && config.cachePredictions) {
        logger.info('Using cached forecast');
        return cached;
      }

      // Generate forecast
      const forecast = await engine.forecast(dataset, reportContext.filters);

      // Store in cache
      await api.storage.set(cacheKey, forecast, 3600);

      // Emit event
      api.events.emit('forecast:generated', {
        datasetId: reportContext.datasetId,
        timestamp: new Date()
      });

      logger.info('Forecast generated successfully');

      return {
        id: `forecast-${reportContext.reportId}`,
        title: 'ML Forecast Report',
        content: {
          data: forecast.predictions,
          confidence: forecast.confidenceLevel,
          timestamp: new Date().toISOString()
        },
        exportFormats: ['pdf', 'png', 'json']
      };
    } catch (error) {
      logger.error('Forecast generation failed', error);
      throw error;
    }
  });

  // Register validation hooks
  api.events.on('dataset:updated', async (event) => {
    logger.debug(`Cache invalidated for ${event.datasetId}`);
    await api.storage.delete(`forecast:${event.datasetId}:*`);
  });

  logger.info('Advanced Forecasting Plugin loaded successfully');
}

export async function onUnload(this: any) {
  const context: PluginContext = this;
  const { logger } = context;

  logger.info('Unloading Advanced Forecasting Plugin');
  // Cleanup resources
}

export async function onReload(this: any) {
  const context: PluginContext = this;
  const { logger } = context;

  logger.info('Reloading Advanced Forecasting Plugin');
  await onUnload.call(this);
  await onLoad.call(this);
}

export const hooks = {
  'report:render': async (report: Report) => {
    // Hook implementation
  },
  'dataset:validate': async (dataset: Dataset) => {
    // Validation logic
  }
};
