## 9. Error Handling & Resilience

### 9.1 Error Isolation

```typescript
// error-handling/error-handler.ts

export class PluginErrorHandler {
  /**
   * Catch and isolate errors from plugin execution
   */
  static async executeWithIsolation<T>(
    pluginId: string,
    fn: () => Promise<T>,
    fallback?: T
  ): Promise<T> {
    try {
      return await fn();
    } catch (error) {
      const pluginError = new PluginExecutionError(pluginId, error as Error);

      // Log error
      logger.error(pluginError);

      // Emit error event
      eventBus.emit('plugin:error', pluginError);

      // If host requires this plugin, escalate
      // Otherwise, use fallback or re-throw
      if (fallback !== undefined) {
        logger.warn(`Using fallback for ${pluginId}`);
        return fallback;
      }

      throw pluginError;
    }
  }

  /**
   * Catch hook execution errors
   */
  static async executeHook(
    pluginId: string,
    hookName: string,
    fn: Function,
    ...args: any[]
  ): Promise<any> {
    try {
      return await fn(...args);
    } catch (error) {
      const hookError = new HookExecutionError(
        pluginId,
        hookName,
        error as Error
      );

      logger.error(hookError);

      // Don't let one hook failure cascade
      // Continue with other hooks
      eventBus.emit('hook:error', hookError);

      return undefined;
    }
  }
}

export class PluginExecutionError extends Error {
  constructor(
    public pluginId: string,
    public originalError: Error
  ) {
    super(`Plugin ${pluginId} failed: ${originalError.message}`);
    this.name = 'PluginExecutionError';
  }
}

export class HookExecutionError extends Error {
  constructor(
    public pluginId: string,
    public hookName: string,
    public originalError: Error
  ) {
    super(
      `Hook ${hookName} in plugin ${pluginId} failed: ${originalError.message}`
    );
    this.name = 'HookExecutionError';
  }
}
