  'auth:user-info': 'Access current user information',
  'auth:check-permission': 'Check if user has specific permission',
  'storage:plugin-data': 'Read/write plugin-specific data',
  'storage:shared-data': 'Access shared data storage',
  'network:external-apis': 'Make HTTP requests to external services',
