  'events:subscribe': 'Subscribe to events',
  'reporting:create': 'Create reports',
  'reporting:export': 'Export reports in various formats'
};

/**
 * Validate plugin permissions at load time
 */
export function validatePermissions(
  requestedPermissions: string[]
): { valid: boolean; invalid: string[] } {
  const allPermissions = Object.values(PERMISSION_CATEGORIES).flat();
  const invalid = requestedPermissions.filter(p => !allPermissions.includes(p));

  return {
    valid: invalid.length === 0,
    invalid
  };
}
