## 11. Deployment & Operations

### 11.1 Plugin Installation

```typescript
// deployment/plugin-installer.ts

export class PluginInstaller {
  async install(source: string, options?: InstallOptions): Promise<PluginMetadata> {
    // source can be:
    // - Local path: /path/to/plugin
    // - NPM package: @scope/plugin-name@1.2.3
    // - Git repository: https://github.com/org/plugin.git
    // - HTTP URL: https://registry.example.com/plugins/plugin-1.2.3.tar.gz

    let pluginPath: string;

    if (source.startsWith('/') || source.startsWith('./')) {
      // Local path
      pluginPath = resolve(source);
    } else if (source.startsWith('http')) {
      // Download from HTTP
      pluginPath = await this.downloadPlugin(source);
    } else if (source.includes('/')) {
      // Git repository or NPM package
      pluginPath = await this.installFromRegistry(source);
    }

    // Extract plugin
    const extractedPath = await this.extractPlugin(pluginPath);

    // Validate manifest
    const manifest = await this.validateManifest(extractedPath);

    // Verify signature (if required)
    if (options?.verifySignature) {
      await this.verifySignature(extractedPath, manifest);
    }

    // Install dependencies
    if (options?.installDeps) {
      await this.installDependencies(extractedPath);
    }

    // Register with registry
    const metadata = this.registry.getPlugin(manifest.metadata.id);
    if (!metadata) {
      throw new Error(`Failed to register plugin ${manifest.metadata.id}`);
    }

    return metadata;
  }

  async uninstall(pluginId: string): Promise<void> {
    const entry = this.registry.getPlugin(pluginId);
    if (!entry) throw new Error(`Plugin not found: ${pluginId}`);

    // Check for dependents
    if (entry.dependents.length > 0) {
      throw new Error(
        `Cannot uninstall ${pluginId}: required by [${entry.dependents.join(', ')}]`
      );
    }

    // Unload if loaded
    if (this.lifecycleManager.getInstance(pluginId)) {
      await this.lifecycleManager.unload(pluginId);
    }

    // Remove files
    await fs.promises.rm(entry.metadata.path, { recursive: true });

    // Remove from registry
    this.registry.remove(pluginId);
  }

  async update(pluginId: string, version: string): Promise<PluginMetadata> {
    const entry = this.registry.getPlugin(pluginId);
    if (!entry) throw new Error(`Plugin not found: ${pluginId}`);

    const newVersion = await this.fetchVersion(pluginId, version);

    // Check compatibility
    const manifest = newVersion.manifest;
    const hostVersion = this.getHostVersion();

    if (!semver.satisfies(hostVersion, manifest.spec.minHostVersion)) {
      throw new Error(
        `Host ${hostVersion} does not meet minimum version ${manifest.spec.minHostVersion}`
      );
    }

    // Reload with new version
    await this.lifecycleManager.reload(pluginId);

    return entry.metadata;
  }
}

export interface InstallOptions {
  verifySignature?: boolean;
  installDeps?: boolean;
  autoEnable?: boolean;
}
```

### 11.2 Plugin Configuration Management

```typescript
// config/plugin-config-manager.ts

export class PluginConfigManager {
  private configDir: string;
  private configs: Map<string, any> = new Map();
  private validators: Map<string, JSONSchemaValidator> = new Map();

  /**
   * Load plugin configuration
   */
  async loadConfig(pluginId: string): Promise<any> {
    const configPath = join(this.configDir, `${pluginId}.json`);

    try {
      const content = await fs.promises.readFile(configPath, 'utf-8');
      const config = JSON.parse(content);

      // Validate against manifest schema
      const entry = this.registry.getPlugin(pluginId);
      if (entry?.metadata.manifest.spec.configuration?.schema) {
        const schema = entry.metadata.manifest.spec.configuration.schema;
        const validator = new JSONSchemaValidator(schema);

        if (!validator.validate(config)) {
          throw new ConfigValidationError(pluginId, validator.errors);
        }
      }

      this.configs.set(pluginId, config);
      return config;
    } catch (error) {
      // Return default config if not found
      return this.getDefaultConfig(pluginId);
    }
  }

  /**
   * Save plugin configuration
   */
  async saveConfig(pluginId: string, config: any): Promise<void> {
    // Validate
    const entry = this.registry.getPlugin(pluginId);
    if (entry?.metadata.manifest.spec.configuration?.schema) {
      const schema = entry.metadata.manifest.spec.configuration.schema;
      const validator = new JSONSchemaValidator(schema);

      if (!validator.validate(config)) {
        throw new ConfigValidationError(pluginId, validator.errors);
      }
    }

    // Save to file
    const configPath = join(this.configDir, `${pluginId}.json`);
    await fs.promises.writeFile(
      configPath,
      JSON.stringify(config, null, 2),
      'utf-8'
    );

    this.configs.set(pluginId, config);

    // Notify plugin if loaded
    const instance = this.lifecycleManager.getInstance(pluginId);
    if (instance?.exports.configure) {
      await instance.exports.configure(config);
    }
  }

  private getDefaultConfig(pluginId: string): any {
    const entry = this.registry.getPlugin(pluginId);
    if (!entry) return {};

    const configSchema = entry.metadata.manifest.spec.configuration?.schema;
    if (!configSchema?.properties) return {};

    // Build config from defaults
    const config: any = {};
    for (const [key, prop] of Object.entries(configSchema.properties)) {
      if ((prop as any).default !== undefined) {
        config[key] = (prop as any).default;
      }
    }

    return config;
  }
}
