## 12. Monitoring & Telemetry

### 12.1 Plugin Metrics

```typescript
// monitoring/plugin-metrics.ts

export interface PluginMetrics {
  pluginId: string;
  version: string;
  loadTime: number; // ms
  memoryUsage: number; // bytes
  callCount: Record<string, number>; // hook calls
  errorCount: number;
  lastError?: Error;
  uptime: number; // ms since load
  permissions: string[];
}

export class PluginMetricsCollector {
  private metrics: Map<string, PluginMetrics> = new Map();

  /**
   * Track plugin load
   */
  recordLoad(
    pluginId: string,
    version: string,
    duration: number,
    memory: number
  ): void {
    this.metrics.set(pluginId, {
      pluginId,
      version,
      loadTime: duration,
      memoryUsage: memory,
      callCount: {},
      errorCount: 0,
      uptime: 0,
      permissions: []
    });
  }

  /**
   * Track hook execution
   */
  recordHookCall(pluginId: string, hookName: string): void {
    const metrics = this.metrics.get(pluginId);
    if (!metrics) return;

    metrics.callCount[hookName] = (metrics.callCount[hookName] || 0) + 1;
  }

  /**
   * Track error
   */
  recordError(pluginId: string, error: Error): void {
    const metrics = this.metrics.get(pluginId);
    if (!metrics) return;

    metrics.errorCount++;
    metrics.lastError = error;
  }

  /**
   * Get metrics
   */
  getMetrics(pluginId: string): PluginMetrics | undefined {
    const metrics = this.metrics.get(pluginId);
    if (metrics) {
      metrics.uptime = Date.now() - metrics.uptime;
    }
    return metrics;
  }

  /**
   * Export metrics for monitoring
   */
  exportMetrics(): Record<string, PluginMetrics> {
    return Object.fromEntries(this.metrics);
  }
}
