## 3. Plugin Manifest Schema

Every plugin must include a `plugin.json` manifest in its root directory.

### 3.1 JSON Schema Definition

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Plugin Manifest",
  "type": "object",
  "required": [
    "id",
    "name",
    "version",
    "apiVersion",
    "description",
    "author"
  ],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^[a-z0-9]([a-z0-9-]*[a-z0-9])?$",
      "maxLength": 64,
      "description": "Unique plugin identifier. Cannot be changed. Used for registry and permissions."
    },
    "name": {
      "type": "string",
      "maxLength": 100,
      "description": "Human-readable plugin name (can change between versions)"
    },
    "version": {
      "type": "string",
      "pattern": "^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$",
      "description": "Semantic version (MAJOR.MINOR.PATCH[-prerelease][+metadata])"
    },
    "apiVersion": {
      "type": "string",
      "enum": ["1.0", "2.0", "3.0"],
      "description": "Target API contract version. Determines available methods and guarantees."
    },
    "description": {
      "type": "string",
      "maxLength": 500,
      "description": "Brief description of plugin functionality"
    },
    "author": {
      "type": "object",
      "required": ["name"],
      "properties": {
        "name": { "type": "string" },
        "email": { "type": "string", "format": "email" },
        "url": { "type": "string", "format": "uri" }
      }
    },
    "license": {
      "type": "string",
      "enum": ["MIT", "Apache-2.0", "GPL-3.0", "Proprietary"],
      "default": "Proprietary"
    },
    "repository": {
      "type": "object",
      "properties": {
        "type": { "type": "string", "enum": ["git"] },
        "url": { "type": "string", "format": "uri" }
      }
    },
    "main": {
      "type": "string",
      "default": "index.js",
      "description": "Entry point file (relative to plugin root)"
    },
    "permissions": {
      "type": "array",
      "items": {
        "type": "string",
