      },
      "description": "Required plugins by ID and minimum API version. Example: {\"plugin-a\": \"1.0\", \"plugin-b\": \"2.0\"}"
    },
    "conflicts": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id"],
        "properties": {
          "id": { "type": "string" },
          "reason": { "type": "string" }
        }
      },
      "description": "Plugin IDs that cannot be loaded simultaneously with this one"
    },
    "capabilities": {
      "type": "array",
      "items": { "type": "string" },
      "examples": ["export:pdf", "export:excel", "datasource:mysql", "datasource:postgres"],
