## 4. Plugin Registry

The registry maintains the canonical state of all known plugins and their metadata.

### 4.1 Registry Interface

```typescript
interface PluginRegistry {
  // Discovery
  list(filter?: RegistryFilter): Promise<PluginMetadata[]>;
  getById(id: string, version?: string): Promise<PluginMetadata | null>;
  findByCapability(capability: string): Promise<PluginMetadata[]>;
  getCompatibleVersions(id: string, apiVersion: string): Promise<string[]>;

  // Registration
  register(manifest: PluginManifest, path: string): Promise<RegistrationResult>;
  unregister(id: string, version: string): Promise<void>;

  // Validation
  validateManifest(manifest: PluginManifest): RegistryValidationError[];
  validateDependencies(manifest: PluginManifest): DependencyResolution;

  // Versioning
  getLatestVersion(id: string): Promise<string | null>;
  getMigrationPath(id: string, fromVersion: string, toVersion: string): Promise<MigrationGuide | null>;

  // Metadata
  getMetadata(id: string, version: string): Promise<PluginMetadata>;
  updateMetadata(id: string, version: string, updates: Partial<PluginMetadata>): Promise<void>;

  // Events
  onRegistered: Event<{id: string; version: string}>;
  onUnregistered: Event<{id: string; version: string}>;
}

interface PluginMetadata {
  id: string;
  version: string;
  name: string;
  description: string;
  apiVersion: string;
  author: Author;
  license: string;
  permissions: string[];
  dependencies: Record<string, string>;
  capabilities: string[];
  resourceLimits: ResourceLimits;
  registeredAt: Date;
  lastUpdatedAt: Date;
  installCount: number;
  avgRating?: number;
  deprecated?: boolean;
  deprecationMessage?: string;
}

interface RegistryFilter {
  apiVersion?: string;
  capabilities?: string[];
  permissions?: string[];
  deprecated?: boolean;
}

interface RegistrationResult {
  success: boolean;
  pluginId: string;
  version: string;
  warnings: string[];
  errors?: string[];
}

interface DependencyResolution {
  satisfied: boolean;
  missing: {id: string; required: string}[];
  incompatible: {id: string; have: string; required: string}[];
  conflicts: {id: string; reason: string}[];
}
```

### 4.2 Registry Storage

The registry persists to `~/.reporting-tool/registry.db` (SQLite) with the following schema:

```sql
CREATE TABLE plugins (
  id TEXT NOT NULL,
  version TEXT NOT NULL,
  manifest JSONB NOT NULL,
  path TEXT NOT NULL,
  apiVersion TEXT NOT NULL,
  registeredAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  lastUpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  enabled BOOLEAN DEFAULT true,
  installCount INTEGER DEFAULT 0,
  avgRating FLOAT,
  deprecated BOOLEAN DEFAULT false,
  deprecationMessage TEXT,
  PRIMARY KEY (id, version),
  UNIQUE (id, path)
);

CREATE TABLE plugin_capabilities (
  pluginId TEXT NOT NULL,
  version TEXT NOT NULL,
  capability TEXT NOT NULL,
  PRIMARY KEY (pluginId, version, capability),
  FOREIGN KEY (pluginId, version) REFERENCES plugins(id, version) ON DELETE CASCADE
);

CREATE TABLE plugin_conflicts (
  pluginId TEXT NOT NULL,
  version TEXT NOT NULL,
  conflictWithId TEXT NOT NULL,
  reason TEXT,
  PRIMARY KEY (pluginId, version, conflictWithId),
  FOREIGN KEY (pluginId, version) REFERENCES plugins(id, version) ON DELETE CASCADE
);

CREATE TABLE migration_guides (
  fromPluginId TEXT NOT NULL,
  fromVersion TEXT NOT NULL,
  toVersion TEXT NOT NULL,
  guide JSONB NOT NULL,
  createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (fromPluginId, fromVersion, toVersion)
);
```

