## 5. Lifecycle Hooks

Plugins follow a well-defined lifecycle with observable state transitions and recovery semantics.

### 5.1 Lifecycle State Machine

```
┌─────────┐
│ Unknown │ (Plugin not yet registered)
└────┬────┘
     │ register()
     ▼
┌──────────────────┐
│   Registered     │ (In registry, available for loading)
│                  │
│ - Manifest valid │
│ - Deps available │
└────┬──────────────┘
     │ load()
     ▼
┌──────────────────┐
│   Initializing   │ (Calling onLoad hook)
└────┬──────────────┘
     │ onLoad resolves
     ▼
┌──────────────────┐
│    Active        │ (Ready to handle requests)
│                  │
│ - onLoad done    │
│ - Hooks firing   │
└────┬──────────────┘
     │
     ├─ reload() ──→ Reloading ──→ Active
     │
     ├─ error occurs ──→ Error (recoverable)
     │
     └─ unload() ──→ Unloading ──→ Unloaded
          │                      │
          └──────────────────────┘

┌──────────────┐
│ Unloaded     │ (onUnload complete, removed from active set)
│              │
│ - onUnload   │
│   complete   │
└──────────────┘

┌──────────────┐
│ Error        │ (Plugin crashed or permission denied)
│              │
│ - Non-fatal  │
│ - Quarantine │
└──────────────┘
```

### 5.2 Lifecycle Hook API

```typescript
interface PluginLifecycle {
  // Called once when plugin is loaded into memory
  // Perform initialization, validate config, connect to external systems
  onLoad(api: PluginAPI, config: PluginConfig): Promise<void>;

  // Called when plugin is being unloaded (e.g., system shutdown, plugin update)
  // Cleanup resources, close connections, persist state if needed
  onUnload(): Promise<void>;

  // Called before reload (if plugin supports hot reload)
  // Optional: validate whether reload is safe
  onBeforeReload?(): Promise<void>;

  // Called after reload completes successfully
  // Re-initialize if needed, restore state
  onReloadComplete?(): Promise<void>;

  // Called when plugin is suspended (e.g., quota exceeded, permission revoked)
  // Gracefully pause operations
  onSuspend?(reason: SuspendReason): Promise<void>;

  // Called when plugin resumes from suspension
  // Resume normal operations
  onResume?(): Promise<void>;
}

enum SuspendReason {
  RESOURCE_LIMIT_EXCEEDED = "RESOURCE_LIMIT_EXCEEDED",
  PERMISSION_REVOKED = "PERMISSION_REVOKED",
  ADMIN_INITIATED = "ADMIN_INITIATED",
  CRASH_RECOVERY = "CRASH_RECOVERY",
  DEPENDENCY_UNAVAILABLE = "DEPENDENCY_UNAVAILABLE"
}

interface PluginConfig {
  id: string;
  version: string;
  userConfig: Record<string, any>;
  environment: {
    apiVersion: string;
    pluginApiUrl: string;
    toolVersion: string;
    workingDirectory: string;
  };
}
```

### 5.3 Lifecycle Management

```typescript
interface PluginLifecycleManager {
  // Loading
  load(id: string, version?: string, config?: PluginConfig): Promise<LoadResult>;
  unload(id: string, version?: string): Promise<void>;
  reload(id: string, version?: string): Promise<ReloadResult>;

  // State queries
  getState(id: string, version?: string): PluginState;
  isActive(id: string): boolean;
  listActive(): PluginInstance[];

  // Events (Observable)
  onStateChange: Event<StateChangeEvent>;
  onError: Event<PluginErrorEvent>;
  onHealthCheck: Event<HealthCheckEvent>;

  // Coordination
  resolveLoadOrder(pluginIds: string[]): Promise<string[]>;
