## 6. Sandboxed Execution Boundary

Plugins execute in isolated contexts with enforced permission gates and resource limits.

### 6.1 Sandbox Architecture

```typescript
interface PluginSandbox {
  // Execute user-provided code in isolated context
  execute<T>(
    pluginId: string,
    version: string,
    functionName: string,
    args: unknown[],
    options?: ExecutionOptions
  ): Promise<T>;

  // Execute with timeout and resource limits
  executeWithLimits<T>(
    handler: () => Promise<T>,
    limits: ResourceLimits,
    timeout: number
  ): Promise<T>;

  // Permission enforcement
  checkPermission(pluginId: string, permission: string): boolean;
  grantPermission(pluginId: string, permission: string): void;
  revokePermission(pluginId: string, permission: string): void;

  // Context isolation
  createContext(pluginId: string, version: string): SandboxContext;
  destroyContext(pluginId: string, version: string): Promise<void>;
}

interface SandboxContext {
  pluginId: string;
  version: string;
  permissions: Set<string>;
  resourceLimits: ResourceLimits;
  globals: Record<string, any>;

  // Restricted API surface (only whitelisted functions/modules available)
  eval(code: string, globals?: Record<string, any>): Promise<any>;

  // Event dispatch within context
  emit(event: string, data: any): void;
  on(event: string, handler: (data: any) => void): void;
}

interface ExecutionOptions {
  timeout?: number;
  memoryLimit?: number;
  cpuLimit?: number;
  isolated?: boolean; // true = new context per call
  cacheable?: boolean;
}

interface ResourceLimits {
  maxMemoryMb: number;
  maxCpuPercent: number;
  maxExecutionTimeMs: number;
  maxNetworkConnections?: number;
  maxFileDescriptors?: number;
}
```

