### 6.3 Sandbox Implementation Patterns

For **Node.js runtime**, use VM contexts:

```typescript
import vm from 'vm';
import { Worker } from 'worker_threads';

class NodeSandbox implements PluginSandbox {
  private contexts = new Map<string, vm.Context>();
  private workers = new Map<string, Worker>();

  async execute<T>(
    pluginId: string,
    version: string,
    functionName: string,
    args: unknown[],
    options?: ExecutionOptions
  ): Promise<T> {
    const context = this.createContext(pluginId, version);

    try {
      // Check permissions before execution
      if (!this.permissions.canAccess(pluginId, `execute:${functionName}`)) {
        throw new Error(`Permission denied: ${pluginId} cannot execute ${functionName}`);
      }

      // Execute in Worker thread with resource limits
      const result = await this.executeInWorker<T>(
        pluginId,
        version,
        functionName,
        args,
        options
      );

      return result;
    } finally {
      if (options?.isolated) {
        this.destroyContext(pluginId, version);
      }
    }
  }

  private async executeInWorker<T>(
    pluginId: string,
    version: string,
    functionName: string,
    args: unknown[],
    options?: ExecutionOptions
  ): Promise<T> {
    const worker = this.getOrCreateWorker(pluginId, version);

    return new Promise((resolve, reject) => {
      const timeout = options?.timeout ?? 30000;
      const timer = setTimeout(() => {
        reject(new Error(`Execution timeout after ${timeout}ms`));
      }, timeout);

      worker.once('message', (result) => {
        clearTimeout(timer);
        if (result.error) {
          reject(new Error(result.error));
        } else {
          resolve(result.value);
        }
      });

      worker.once('error', reject);
      worker.once('exit', (code) => {
        if (code !== 0) {
          reject(new Error(`Worker exited with code ${code}`));
        }
      });

      worker.postMessage({
        pluginId,
        version,
        functionName,
        args,
        limits: options
      });
    });
  }

  private getOrCreateWorker(pluginId: string, version: string): Worker {
    const key = `${pluginId}@${version}`;
    if (!this.workers.has(key)) {
      const worker = new Worker('./plugin-worker.js');
      this.workers.set(key, worker);
    }
    return this.workers.get(key)!;
  }
}
```

For **browser-based** plugins, use Web Workers and CSP headers:

```typescript
class BrowserSandbox implements PluginSandbox {
  private workers = new Map<string, SharedWorker>();

  async execute<T>(
    pluginId: string,
    version: string,
    functionName: string,
    args: unknown[],
    options?: ExecutionOptions
  ): Promise<T> {
    if (!this.permissions.canAccess(pluginId, `execute:${functionName}`)) {
      throw new Error(`Permission denied`);
    }

    return this.executeInSharedWorker<T>(
      pluginId,
      version,
      functionName,
      args,
      options
    );
  }

  private executeInSharedWorker<T>(
    pluginId: string,
    version: string,
    functionName: string,
    args: unknown[],
    options?: ExecutionOptions
  ): Promise<T> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(
        () => reject(new Error('Execution timeout')),
        options?.timeout ?? 30000
      );

      const handler = (event: MessageEvent) => {
        clearTimeout(timeout);
        worker.port.removeEventListener('message', handler);

        const { result, error } = event.data;
        if (error) reject(new Error(error));
        else resolve(result);
      };

      const key = `${pluginId}@${version}`;
      const worker = this.getOrCreateWorker(key);

      worker.port.addEventListener('message', handler);
      worker.port.start();
      worker.port.postMessage({
        pluginId,
        version,
        functionName,
        args
      });
    });
  }
}
```

