## 7. Versioned API Contract

Plugins interact with the host via a versioned, stable API. Breaking changes are gated by major versions.

### 7.1 API Version Strategy

Each API version is stable and fully backward compatible within that major version.

```
API v1.x  (Current)
├─ Introduced: Reporting tool v1.0
├─ Methods: report(), export(), query(), registerHook()
├─ Response format: JSON
├─ Guarantees: Stable through v1.99
└─ Deprecated: Methods marked since v1.5

API v2.x  (Future)
├─ Introduced: Reporting tool v2.0
├─ Methods: All v1 + batch(), stream(), webhook()
├─ Response format: JSON (backward compatible)
├─ Guarantees: Stable through v2.99
├─ Breaking changes from v1: Parameter name changes, removed methods
└─ Migration guide: For v1 → v2 conversion

API v3.x  (Future major version)
├─ Likely: Reporting tool v3.0
└─ TBD
```

### 7.2 API Contract Definition

```typescript
// API v1.0 (stable)
namespace ReportingAPI_v1 {
  interface PluginAPI {
    // Report operations
    report: {
      list(filter?: ReportFilter): Promise<Report[]>;
      get(reportId: string): Promise<Report>;
      create(params: CreateReportParams): Promise<Report>;
      update(reportId: string, params: UpdateReportParams): Promise<Report>;
      delete(reportId: string): Promise<void>;
      execute(reportId: string, params?: ExecutionParams): Promise<ExecutionResult>;
    };

    // Export operations
    export: {
      toPdf(reportId: string, options?: PdfOptions): Promise<Buffer>;
      toJson(reportId: string): Promise<string>;
      toCsv(reportId: string): Promise<string>;
      register(format: string, handler: ExportHandler): void;
    };

    // Query operations
    query: {
      execute(sql: string, params?: any[]): Promise<QueryResult>;
      executeNamed(queryName: string, params?: Record<string, any>): Promise<QueryResult>;
      validate(sql: string): Promise<ValidationResult>;
    };

    // Data source operations
    datasource: {
      list(): Promise<DataSource[]>;
      get(id: string): Promise<DataSource>;
      testConnection(config: DataSourceConfig): Promise<boolean>;
    };

    // Hook registration
    hooks: {
      register(eventName: string, handler: EventHandler): string; // Returns hook ID
      unregister(hookId: string): void;
      emit(eventName: string, data: any): Promise<void>;
    };

    // Logging
    logger: {
      debug(message: string, data?: any): void;
      info(message: string, data?: any): void;
      warn(message: string, data?: any): void;
      error(message: string, error?: Error): void;
    };

    // Configuration
    config: {
      get(key: string): any;
      set(key: string, value: any): Promise<void>;
      getSchema(): object;
    };

    // Utility
    utils: {
      generateId(): string;
      formatDate(date: Date, format: string): string;
      parseDate(dateStr: string, format: string): Date;
    };

    // Capability detection
    hasCapability(capability: string): boolean;
    getCapabilities(): string[];
  }

  interface Report {
    id: string;
    name: string;
    description: string;
    createdAt: Date;
    updatedAt: Date;
    datasourceId: string;
    query: string;
    parameters: Record<string, any>;
    scheduleExpression?: string;
    lastExecutedAt?: Date;
    lastExecutionStatus?: 'SUCCESS' | 'FAILED' | 'TIMEOUT';
  }

  interface CreateReportParams {
    name: string;
    description?: string;
    datasourceId: string;
    query: string;
    parameters?: Record<string, any>;
    scheduleExpression?: string;
  }

  interface UpdateReportParams extends Partial<CreateReportParams> {
    // Only include fields to update
  }

  interface ExecutionParams {
    parameters?: Record<string, any>;
    timeoutSeconds?: number;
  }

  interface ExecutionResult {
    reportId: string;
    executionId: string;
    status: 'SUCCESS' | 'FAILED' | 'TIMEOUT' | 'CANCELLED';
    startedAt: Date;
    completedAt: Date;
    duration: number;
    rowCount?: number;
    data?: any[];
    error?: string;
  }

  interface PdfOptions {
    pageSize?: 'A4' | 'Letter';
    orientation?: 'portrait' | 'landscape';
    includeCharts?: boolean;
    includeMetadata?: boolean;
    watermark?: string;
  }

  interface QueryResult {
    columns: ColumnInfo[];
    rows: any[];
    rowCount: number;
    executionTimeMs: number;
  }

  interface ColumnInfo {
    name: string;
    type: string; // 'string', 'number', 'boolean', 'date', 'json'
    nullable: boolean;
  }

  interface DataSource {
    id: string;
    name: string;
    type: 'mysql' | 'postgres' | 'mongodb' | 'bigquery' | 'custom';
    connectionStatus: 'CONNECTED' | 'DISCONNECTED' | 'ERROR';
    lastTestedAt?: Date;
  }

  type EventHandler = (data: any) => Promise<void> | void;

  interface EventData {
    [key: string]: any;
    // Reserved fields:
    // timestamp: Date
    // source: string (plugin ID)
  }
}

// API v2.0 (future - adding capabilities)
namespace ReportingAPI_v2 {
  interface PluginAPI extends ReportingAPI_v1.PluginAPI {
