### 7.3 API Usage in Plugins

```typescript
// Example plugin using v1 API
export async function onLoad(api: PluginAPI, config: PluginConfig) {
  // Check API version
  if (!api.hasCapability('export:pdf')) {
    throw new Error('This plugin requires PDF export capability');
  }

  // Use v1 API
  api.logger.info('PDF Exporter initializing...');

  // Register hook
  api.hooks.register('export:start', async (data) => {
    api.logger.debug('Export started', { reportId: data.reportId });
  });

  // Publish capability
  config.capabilities?.push('export:pdf-advanced');
}

export async function exportToPdf(
  api: PluginAPI,
  reportId: string,
  options: PdfExportOptions
): Promise<Buffer> {
  // Get report
  const report = await api.report.get(reportId);

  // Execute report
  const result = await api.report.execute(reportId);

  // Emit hook
  await api.hooks.emit('export:start', {
    reportId,
    format: 'pdf'
  });

  // Generate PDF (implementation detail)
  const pdfBuffer = generatePdf(result.data, options);

  // Emit completion
  await api.hooks.emit('export:complete', {
    reportId,
    format: 'pdf',
    size: pdfBuffer.length
  });

  return pdfBuffer;
}
```

### 7.4 Capability-Based API Detection

Plugins can query available capabilities at runtime:

```typescript
interface CapabilityRegistry {
  // Query capabilities
  has(capability: string): boolean;
  get(capability: string): CapabilityInfo | null;
  list(): CapabilityInfo[];
  list(filter: CapabilityFilter): CapabilityInfo[];

  // Capability info
  getSince(capability: string): string; // e.g., "1.2.0"
  getDeprecatedSince(capability: string): string | null;
  getRemovedAt(capability: string): string | null;
  getMigrationPath(oldCapability: string, newCapability: string): string | null;
}

interface CapabilityInfo {
  name: string;
  description: string;
  apiVersion: string;
  introducedIn: string; // e.g., "1.5.0"
  deprecatedSince?: string;
  removedIn?: string; // If removed
  alternativeCapability?: string; // If deprecated
}

// Usage in plugin
export async function onLoad(api: PluginAPI, config: PluginConfig) {
  const capabilities = api.getCapabilities();

  // Gracefully handle API differences
  if (capabilities.includes('stream:queryStream')) {
    // Use v2.0+ streaming API
    for await (const row of api.stream.queryStream(sql)) {
      processRow(row);
    }
  } else {
    // Fallback to v1 pagination
    const result = await api.query.execute(sql);
    result.rows.forEach(processRow);
  }
}
```

