## 10. Example: Implementing a Plugin

```typescript
// plugins/exporter-slack/src/index.ts
import { PluginAPI, PluginConfig } from '@reporting-tool/plugin-api-v1';

interface SlackConfig {
  webhookUrl: string;
  channel: string;
  mentionOnError: boolean;
}

let config: SlackConfig;
let api: PluginAPI;

export async function onLoad(
  pluginApi: PluginAPI,
  pluginConfig: PluginConfig
): Promise<void> {
  api = pluginApi;

  // Validate config
  config = pluginConfig.userConfig as SlackConfig;
  if (!config.webhookUrl) {
    throw new Error('webhookUrl is required');
  }

  // Verify permission to call external APIs
  if (!api.hasCapability('access:external')) {
    throw new Error('This plugin requires access:external permission');
  }

  // Register hooks
  api.hooks.register('report:completed', onReportCompleted);
  api.hooks.register('report:failed', onReportFailed);

  api.logger.info('Slack exporter loaded', {
    channel: config.channel
  });
}

export async function onUnload(): Promise<void> {
  api.logger.info('Slack exporter unloading');
  // Cleanup resources if needed
}

async function onReportCompleted(event: any): Promise<void> {
  const { reportId, executionTime } = event;

  try {
    const report = await api.report.get(reportId);
    const result = await api.report.execute(reportId);

    await sendToSlack({
      text: `✅ Report completed`,
      fields: [
        { title: 'Report', value: report.name },
        { title: 'Duration', value: `${executionTime}ms` },
        { title: 'Rows', value: String(result.rowCount) }
      ]
    });
  } catch (error) {
    api.logger.error('Failed to send Slack message', error as Error);
  }
}

async function onReportFailed(event: any): Promise<void> {
  const { reportId, error } = event;

  try {
    const report = await api.report.get(reportId);
    const message: any = {
      text: `❌ Report failed`,
      fields: [
        { title: 'Report', value: report.name },
        { title: 'Error', value: error.message }
      ]
    };

    if (config.mentionOnError) {
      message.text = `<!here> ${message.text}`;
    }

    await sendToSlack(message);
  } catch (err) {
    api.logger.error('Failed to send error notification', err as Error);
  }
}

async function sendToSlack(payload: any): Promise<void> {
  const response = await fetch(config.webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      channel: config.channel,
      attachments: [payload]
    })
  });

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.statusText}`);
  }
}

