```typescript
// Migration guide provided to plugin developers
// File: MIGRATION_V1_TO_V2.md

// Before (v1.0):
export async function onLoad(api: PluginAPI_v1, config: PluginConfig) {
  const results = await api.query.execute(sql);
  // Process results array
  results.rows.forEach(row => processRow(row));
}

// After (v2.0 - with streaming):
export async function onLoad(api: PluginAPI_v2, config: PluginConfig) {
  // v1 methods still work
  const results = await api.query.execute(sql);
  results.rows.forEach(row => processRow(row));

  // OR use new streaming API for large datasets
  for await (const row of api.stream.queryStream(sql)) {
    processRow(row);
  }
}

// Timeline:
// - v1.0 released: Month 1
// - v2.0 released: Month 12 (v1 still supported)
// - v1 deprecation announced: Month 12
// - v1 support ends: Month 24 (v2 becomes minimum)
// - v1 completely removed: Month 30
```

