### 4.3 Version Resolution Algorithm

```typescript
function resolvePluginVersion(
  requestedId: string,
  requestedVersion: string,
  platformVersion: string,
  loadedPlugins: Map<string, LoadedPlugin>
): string {
  const candidates = registry.getVersions(requestedId);

  // Filter 1: Platform compatibility
  const compatible = candidates.filter(v => 
    semver.satisfies(platformVersion, registry.get(requestedId, v).platform.minVersion)
  );

  // Filter 2: Requested version range
  const matching = compatible.filter(v => 
    semver.satisfies(v, requestedVersion)
  );

  // Filter 3: Dependency resolution (diamond problem)
  const feasible = matching.filter(v => {
    const deps = registry.resolveDependencies(requestedId, v);
    return !checkForConflicts(deps, loadedPlugins);
  });

  // Return highest compatible version
  return semver.maxSatisfying(feasible, requestedVersion);
}
```

