interface PluginLifecycleHooks {
  // Called immediately after plugin code is loaded, before dependencies
  onLoad?(context: PluginContext): Promise<void>;

  // Called before plugin is unloaded, cleanup resources
  onUnload?(context: PluginContext): Promise<void>;

  // Called before reload sequence starts
  onBeforeReload?(context: PluginContext): Promise<void>;

  // Called after successful reload
  onAfterReload?(context: PluginContext): Promise<void>;

  // Called when plugin configuration changes
  onConfigChange?(context: PluginContext, oldConfig: any): Promise<void>;

  // Called on critical errors, plugin may self-heal or fail
  onError?(context: PluginContext, error: PluginError): Promise<ErrorRecoveryAction>;

  // Periodic health check, return health status
  onHealthCheck?(context: PluginContext): Promise<HealthCheckResult>;

  // Called when API version compatibility check fails
  onAPIVersionMismatch?(context: PluginContext): Promise<void>;
}

type ErrorRecoveryAction = 'retry' | 'disable' | 'unload' | 'fatal';

interface PluginError extends Error {
