### 5.3 Load Sequence

```typescript
async function loadPlugin(id: string, version: string): Promise<LoadedPlugin> {
  // 1. Pre-flight checks (registry, manifest, dependencies)
  const descriptor = registry.get(id, version);
  validateManifest(descriptor.manifest);

  // 2. Resolve dependencies
  const depGraph = registry.resolveDependencies(id, version);
  for (const dep of depGraph.resolutionPath) {
    if (!isLoaded(dep)) {
      await loadPlugin(dep.id, dep.version);
    }
  }

  // 3. Allocate sandbox resources
  const sandbox = sandboxBroker.allocate(id, version, descriptor.manifest.capabilities);

  // 4. Load plugin code into sandbox
  const pluginModule = await sandboxBroker.loadModule(
    descriptor.manifest.entrypoint,
    sandbox
  );

  // 5. Instantiate plugin
  const PluginClass = pluginModule[descriptor.manifest.mainExport];
  const instance = new PluginClass(createPluginContext(sandbox, descriptor));

  // 6. Call onLoad hook
  if (instance.onLoad) {
    await withTimeout(
      instance.onLoad(createPluginContext(sandbox, descriptor)),
      descriptor.manifest.lifecycle.gracefulShutdownTimeout
    );
  }

  // 7. Validate post-load state
  if (instance.getStatus?.() === 'failed') {
    throw new PluginLoadError('Plugin failed self-check after onLoad');
  }

  // 8. Register in runtime cache
  runtime.plugins.set(`${id}:${version}`, {
    descriptor,
    instance,
    sandbox,
    loadedAt: new Date(),
    lastHealthCheck: new Date(),
    callCount: 0,
    errorCount: 0
  });

  return instance;
}
```

### 5.4 Unload Sequence

```typescript
async function unloadPlugin(id: string, version: string): Promise<void> {
  const loaded = runtime.plugins.get(`${id}:${version}`);
  if (!loaded) return;

  // 1. Check for dependent plugins
  const dependents = registry.get(id).requiredBy;
  if (dependents.length > 0 && !options.force) {
    throw new PluginInUseError(`Cannot unload, required by: ${dependents.join(', ')}`);
  }

  // 2. Stop accepting new requests
  loaded.sandbox.setAcceptingRequests(false);

  // 3. Call onUnload hook
  if (loaded.instance.onUnload) {
    await withTimeout(
      loaded.instance.onUnload(createPluginContext(loaded.sandbox, loaded.descriptor)),
      loaded.descriptor.manifest.lifecycle.gracefulShutdownTimeout
    );
  }

  // 4. Wait for in-flight requests to complete
  await loaded.sandbox.waitForInflightRequests(5000);

  // 5. Release resources
  loaded.sandbox.deallocate();

  // 6. Unregister from runtime
  runtime.plugins.delete(`${id}:${version}`);
}
```

### 5.5 Reload Sequence

```typescript
async function reloadPlugin(id: string, version: string): Promise<void> {
  const loaded = runtime.plugins.get(`${id}:${version}`);

  // 1. Call onBeforeReload hook
  if (loaded.instance.onBeforeReload) {
    await loaded.instance.onBeforeReload(createPluginContext(loaded.sandbox, loaded.descriptor));
  }

  // 2. Drain current instance
  loaded.sandbox.setAcceptingRequests(false);
  await loaded.sandbox.waitForInflightRequests(5000);

  // 3. Unload old instance (without calling onUnload)
  loaded.sandbox.deallocate();
  runtime.plugins.delete(`${id}:${version}`);

  // 4. Load new instance
  const newInstance = await loadPlugin(id, version);

  // 5. Call onAfterReload hook
  if (newInstance.onAfterReload) {
    await newInstance.onAfterReload(createPluginContext(sandbox, descriptor));
  }
}
```

