## 6. Sandboxed Execution Boundary

### 6.1 Sandbox Architecture

```typescript
interface ISandbox {
  id: string;
  pluginId: string;
  pluginVersion: string;

  // Capability enforcement
  enforceCapability(cap: Capability, args: any[]): boolean;
  getPermissions(): Permission[];
  requestCapability(cap: Capability, justification: string): Promise<boolean>;

  // Resource management
  getAllocatedResources(): ResourceAllocation;
  updateResourceLimits(limits: Partial<ResourceAllocation>): void;

  // Execution
  execute<T>(fn: () => Promise<T>, context?: ExecutionContext): Promise<T>;
  createProxy(target: any, permissions: Permission[]): any;

  // Monitoring
  getMetrics(): SandboxMetrics;
  recordCall(methodName: string, duration: number, error?: Error): void;

  // Lifecycle
  setAcceptingRequests(accept: boolean): void;
  waitForInflightRequests(timeoutMs: number): Promise<void>;
  deallocate(): Promise<void>;
}

interface ResourceAllocation {
  memory: { limit: string; warning: string };
  cpu: { limit: string; period: number };
  fileHandles: { limit: number };
  networkConnections: { limit: number };
  fileSystemQuota: { read: number; write: number; delete: boolean };
}
```

### 6.2 Capability Model

```typescript
type Capability = 
  | 'data:read' | 'data:write' | 'data:delete'
  | 'file:read' | 'file:write' | 'file:delete'
  | 'network:http' | 'network:db'
  | 'env:read' | 'env:write'
  | 'process:spawn' | 'process:signal'
  | 'cache:read' | 'cache:write'
  | 'crypto:sign' | 'crypto:verify'
  | 'audit:read';

interface Permission {
  capability: Capability;
  resource?: string | string[]; // glob patterns
  conditions?: {
    timeWindow?: { start: number; end: number };
    rateLimit?: { requests: number; period: number };
    requiresApproval?: boolean;
  };
  expiresAt?: Date;
}

// Sandbox checks capabilities on every external call
class SandboxProxy {
  intercept(target: string, method: string, args: any[]): boolean {
    const required = this.getRequiredCapability(target, method);
    if (!this.permissions.has(required)) {
      throw new PermissionDeniedError(
        `Plugin requires ${required} to call ${target}.${method}`
      );
    }

    if (this.isRateLimited(required)) {
      throw new RateLimitExceededError();
    }

    this.recordCapabilityUsage(required);
    return true;
  }
}
