### 8.2 Error Handling Flow

```typescript
async function executePluginFunction<T>(
  pluginId: string,
  functionName: string,
  args: any[],
  timeout: number = 30000
): Promise<T> {
  try {
    const loaded = runtime.plugins.get(pluginId);
    if (!loaded) throw new PluginNotLoadedError(pluginId);

    // Call with timeout
    const result = await Promise.race([
      callPluginFunction(loaded.instance, functionName, args),
      new Promise((_, reject) => 
        setTimeout(() => reject(new PluginExecutionTimeoutError()), timeout)
      )
    ]);

    loaded.sandbox.recordCall(functionName, Date.now(), null);
    return result;

  } catch (err) {
    const pluginError = normalizeError(err, 'execution', pluginId);

    // Log with full context
    logger.error(`Plugin ${pluginId} execution failed`, {
      error: pluginError,
      function: functionName,
      args: sanitizeArgs(args),
      phase: pluginError.phase,
      recoverable: pluginError.recoverable
    });

    // Call plugin's error hook
    const loaded = runtime.plugins.get(pluginId);
    if (loaded?.instance.onError) {
      try {
        const action = await loaded.instance.onError(
          createPluginContext(loaded.sandbox, loaded.descriptor),
          pluginError
        );

        if (action === 'retry') {
          return executePluginFunction(pluginId, functionName, args, timeout);
        } else if (action === 'disable' || action === 'unload') {
          await unloadPlugin(pluginId, loaded.descriptor.manifest.version);
          throw new PluginDisabledError(pluginId);
        } else if (action === 'fatal') {
          throw pluginError;
        }
      } catch (hookErr) {
        logger.error(`onError hook failed for ${pluginId}`, hookErr);
      }
    }

    // Rethrow if not recoverable
    if (!pluginError.recoverable) {
      throw pluginError;
    }

    throw pluginError;
  }
}
```

