export class PluginError extends Error {
  constructor(
    message: string,
    public code: PluginErrorCode,
    public phase: ErrorPhase,
    public plugin: { id: string; version: string },
    public recoverable: boolean,
    public details?: any,
    public timestamp: Date = new Date()
