  LOAD_FAILED = 'E_LOAD_FAILED',
  UNLOAD_TIMEOUT = 'E_UNLOAD_TIMEOUT',
  ENTRY_POINT_NOT_FOUND = 'E_ENTRY_NOT_FOUND',
  PLUGIN_CRASHED = 'E_PLUGIN_CRASHED',
  PERMISSION_DENIED = 'E_PERMISSION_DENIED',
  CAPABILITY_EXCEEDED = 'E_CAPABILITY_EXCEEDED',
  MEMORY_LIMIT_EXCEEDED = 'E_MEMORY_EXCEEDED',
  API_VERSION_MISMATCH = 'E_API_MISMATCH',
  HEALTH_CHECK_FAILED = 'E_HEALTH_CHECK_FAILED',
