## 3. Plugin API Contract (Versioned)

### 3.1 Core Plugin Interface

```typescript
// plugin-api.v1.1.ts
// This is the primary API version; v2.0 will arrive in Q4 2026

export const PLUGIN_API_VERSION = "1.1";

/**
 * The Plugin class is the entry point for all plugins.
 * Every plugin MUST export this as default export.
 */
export abstract class Plugin {
  abstract id: string;
  abstract version: string;

  /**
   * Called when plugin is loaded into memory.
   * Perform initialization, resource allocation here.
   * Must complete within 5 seconds.
   */
  abstract onLoad(): Promise<void>;

  /**
   * Called when plugin is being unloaded.
   * Clean up resources, close connections.
   * Must complete within 3 seconds.
   */
  abstract onUnload(): Promise<void>;

  /**
   * Called when plugin configuration is updated.
   * Validate new config; if invalid, throw PluginError.
   * Must complete within 2 seconds.
   */
  onConfigChanged?(config: Record<string, any>): Promise<void>;

  /**
   * Hook handlers: map hook name to handler function.
   * Each handler receives context-specific parameters.
   */
  getHooks(): Record<string, HookHandler<any>>;
}

export interface HookHandler<T> {
  (context: T): Promise<HookResult> | HookResult;
}

export interface HookResult {
  success: boolean;
  data?: any;
  error?: PluginError;
  warnings?: string[];
}

/**
 * Standard errors for plugin communication
 */
export class PluginError extends Error {
  constructor(
    public code: string,
    message: string,
    public details?: Record<string, any>
  ) {
    super(message);
    this.name = "PluginError";
  }
}

/**
 * Report Export Hook (v1.0+)
 */
export interface ReportExportContext {
  reportId: string;
  reportName: string;
  reportData: ReportData;
  format: string; // e.g., "pdf", "xlsx", "csv"
  options: Record<string, any>;
  userId: string;
  timestamp: Date;
}

export interface ReportExportResult extends HookResult {
  data?: {
    mimeType: string;
    buffer: Buffer;
    fileName: string;
  };
}

/**
 * Report Validation Hook (v1.0+)
 */
export interface ReportValidationContext {
  report: ReportData;
  strictMode: boolean;
}

export interface ValidationIssue {
  level: "error" | "warning";
  field: string;
  message: string;
}

export interface ReportValidationResult extends HookResult {
  data?: {
    isValid: boolean;
    issues: ValidationIssue[];
  };
}

/**
 * Plugin Configuration Hook (v1.1+)
 */
export interface PluginConfigContext {
  pluginId: string;
  newConfig: Record<string, any>;
  previousConfig: Record<string, any>;
}

/**
 * Host API Surface - accessible within sandboxed execution
 */
export interface HostAPI {
  /**
   * Log plugin activity (v1.0+)
   */
  log(level: "info" | "warn" | "error", message: string, context?: Record<string, any>): void;

  /**
   * Emit events for host consumption (v1.0+)
   */
  emit(eventName: string, data: any): Promise<void>;

  /**
   * Request data from host (v1.1+)
   */
  query(resource: string, filters?: Record<string, any>): Promise<any>;

  /**
   * Store temporary cache data (v1.1+)
   * Cleared on unload; max 10MB per plugin
   */
  cache: {
    set(key: string, value: any, ttl?: number): Promise<void>;
    get(key: string): Promise<any>;
    del(key: string): Promise<void>;
  };

  /**
   * Access plugin-specific configuration (v1.0+)
   */
  getConfig(): Record<string, any>;

  /**
   * Measure performance (v1.1+)
   */
  measure(label: string, fn: () => Promise<void>): Promise<number>;
}

/**
 * Data Models
 */
export interface ReportData {
  id: string;
  name: string;
  description?: string;
  columns: ReportColumn[];
  rows: Record<string, any>[];
  metadata?: Record<string, any>;
}

export interface ReportColumn {
  name: string;
  type: "string" | "number" | "boolean" | "date";
  aggregation?: "sum" | "avg" | "count" | "max" | "min";
}
```

### 3.2 API Version Lifecycle

- **v1.0** (Released Q1 2026): Core hooks, logging, basic host API
- **v1.1** (Released Q3 2026): Configuration hooks, query API, caching, measurement
- **v2.0** (Planned Q4 2026): Streaming hooks, custom UI components, async data loading
  - v1.0 plugins continue working with compatibility layer
  - v1.1 plugins continue working without changes
  - New features in v2.0 only

**Deprecation Policy**: Minor version support continues for 12 months; major version overlap for 6 months.

