## 3. Plugin Registry

### Registry Interface

```typescript
interface PluginRegistry {
  // Discovery & Registration
  register(manifest: PluginManifest, source: PluginSource): Promise<RegisteredPlugin>;
  unregister(pluginId: string, version: string): Promise<void>;
  discover(query: DiscoveryQuery): Promise<PluginMetadata[]>;

  // Resolution
  resolve(reference: PluginReference): Promise<PluginBundle>;
  getLatestVersion(pluginId: string): Promise<string>;
  getVersions(pluginId: string): Promise<string[]>;

  // Validation & Integrity
  validateManifest(manifest: PluginManifest): Promise<ValidationResult>;
  verifyIntegrity(bundle: PluginBundle): Promise<boolean>;

  // Lifecycle events
  onPluginRegistered: EventEmitter<RegistrationEvent>;
  onPluginUnregistered: EventEmitter<UnregistrationEvent>;
  onPluginUpdated: EventEmitter<UpdateEvent>;
}

interface PluginReference {
  name: string;
  version?: string;  // defaults to latest
  constraint?: string;  // e.g., "^1.2.0"
}

interface PluginBundle {
  manifest: PluginManifest;
  code: ArrayBuffer;  // Compiled JS bundle
  assets: Map<string, ArrayBuffer>;
  signature: CryptographicSignature;  // Code integrity
  checksums: Map<string, string>;  // Asset integrity (SHA256)
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
  metadata: {
    analyzedAt: ISO8601;
    schemaVersion: string;
  };
}
```

