## 4. Lifecycle Hooks & State Machine

### Plugin Lifecycle States

```
        ┌─────────────────────────────────────────┐
        │         UNREGISTERED (initial)           │
        └─────────────────────────────────────────┘
                           │
                      (register)
                           ▼
        ┌─────────────────────────────────────────┐
        │      REGISTERED (manifest valid)         │
        └─────────────────────────────────────────┘
                           │
                       (load)
                           ▼
        ┌─────────────────────────────────────────┐
        │   LOADING (dependencies resolved)        │
        └─────────────────────────────────────────┘
                           │
             ┌─────────────┴──────────────┐
             ▼                            ▼
      (success)                      (failure)
             │                            │
             ▼                            ▼
        ┌────────────────┐         ┌──────────────┐
        │    LOADED      │         │  LOAD_ERROR  │
        │ (ready to use) │         │ (auto-retry  │
        └────────────────┘         │  or manual)  │
             │ │ │                 └──────────────┘
    ┌────────┘ │ └──────┬──────────────────┘
    │          │        │
    │    (reload)   (unload)
    │          │        │
    ▼          ▼        ▼
┌──────┐  ┌──────┐  ┌────────────┐
│RELOAD│  │ UNLOAD│ │UNREGISTERED│
│ING   │→ │ING   │→│            │
└──────┘  └──────┘  └────────────┘
    │
    └─→ LOADED (resume)
```

### Hook System

```typescript
type PluginLifecycleHook = (context: PluginContext) => Promise<void>;

interface PluginLifecycle {
  // Called after dependencies resolved, before first use
  onLoad: PluginLifecycleHook;

  // Called after plugin is fully initialized and exposed to host
  onReady: PluginLifecycleHook;

  // Called before reload (graceful shutdown)
  onBeforeUnload: PluginLifecycleHook;

  // Called on unload (cleanup)
  onUnload: PluginLifecycleHook;

  // Periodic health check; if fails, plugin is unloaded
  onHealthCheck: (context: PluginContext) => Promise<HealthStatus>;

  // Called on config changes (hot-update)
  onConfigUpdate: (config: unknown, context: PluginContext) => Promise<void>;

  // Called when a dependency is updated
  onDependencyUpdate: (depName: string, newVersion: string, context: PluginContext) => Promise<void>;
}

interface PluginContext {
  pluginId: string;
  version: string;
  config: unknown;
  manifest: PluginManifest;
  logger: Logger;
  emit: (eventName: string, payload: unknown) => void;
  capabilities: CapabilityChecker;
  resourceMonitor: ResourceMonitor;
}

interface HealthStatus {
  healthy: boolean;
  timestamp: ISO8601;
  reason?: string;
  details?: Record<string, unknown>;
}
```

### Lifecycle Manager Implementation

```typescript
class PluginLifecycleManager {
  private state = new Map<string, PluginState>();
  private timers = new Map<string, NodeJS.Timer>();
  private locks = new Map<string, Mutex>();

  async load(pluginId: string, version: string): Promise<Plugin> {
    const lock = this.getOrCreateLock(pluginId);
    return lock.runExclusive(async () => {
      const existing = this.state.get(pluginId);

      if (existing?.status === 'LOADED') {
        return existing.instance;
      }

      if (existing?.status === 'LOADING') {
        return this.waitForLoad(pluginId);
      }

      this.state.set(pluginId, { status: 'LOADING', startedAt: now() });

      try {
        const bundle = await this.registry.resolve({ name: pluginId, version });
        const instance = await this.instantiate(bundle);

        await this.executeHook(instance, 'onLoad');
        await this.startHealthChecks(pluginId, instance);

        this.state.set(pluginId, { 
          status: 'LOADED', 
          instance, 
          loadedAt: now() 
        });

        await this.executeHook(instance, 'onReady');
        return instance;
      } catch (err) {
        this.state.set(pluginId, { 
          status: 'LOAD_ERROR', 
          error: err, 
          failedAt: now() 
        });
        throw new PluginLoadError(`Failed to load ${pluginId}@${version}`, err);
      }
    });
  }

  async unload(pluginId: string): Promise<void> {
    const lock = this.getOrCreateLock(pluginId);
    return lock.runExclusive(async () => {
      const state = this.state.get(pluginId);

      if (!state || state.status !== 'LOADED') {
        return;
      }

      this.state.set(pluginId, { status: 'UNLOADING' });
      this.stopHealthChecks(pluginId);

      try {
        await this.executeHook(state.instance, 'onBeforeUnload', { timeout: 5000 });
        await this.executeHook(state.instance, 'onUnload', { timeout: 10000 });
      } catch (err) {
        this.logger.error('Error during unload hooks', { pluginId, err });
      }

      state.instance.destroy();
      this.state.delete(pluginId);
    });
  }

  async reload(pluginId: string): Promise<Plugin> {
    const lock = this.getOrCreateLock(pluginId);
    return lock.runExclusive(async () => {
      this.state.set(pluginId, { status: 'RELOADING' });

      const version = this.state.get(pluginId)?.version;
      await this.unload(pluginId);
      return this.load(pluginId, version);
    });
  }

  private startHealthChecks(pluginId: string, plugin: Plugin): void {
    const manifest = plugin.manifest;
    const config = manifest.spec?.signals?.healthCheck;

    if (!config) return;

    const interval = parseInterval(config.interval);
    const timeout = parseInterval(config.timeout);

    const timer = setInterval(async () => {
      try {
        const status = await Promise.race([
          plugin.onHealthCheck?.({ /* context */ }),
          delay(timeout).then(() => ({ healthy: false, reason: 'timeout' }))
        ]);

        if (!status.healthy && config.required) {
          this.logger.warn('Plugin failed health check', { pluginId, status });
          await this.unload(pluginId);
        }
      } catch (err) {
        this.logger.error('Health check error', { pluginId, err });
      }
    }, interval);

    this.timers.set(pluginId, timer);
  }

  private stopHealthChecks(pluginId: string): void {
    const timer = this.timers.get(pluginId);
    if (timer) clearInterval(timer);
    this.timers.delete(pluginId);
  }

  private async executeHook(
    plugin: Plugin,
    hookName: keyof PluginLifecycle,
    options?: { timeout?: number }
  ): Promise<void> {
    const hook = plugin[hookName];
    if (!hook) return;

    const timeout = options?.timeout ?? 30000;
    await Promise.race([
      hook(plugin.context),
      delay(timeout).then(() => {
        throw new Error(`Hook ${hookName} exceeded ${timeout}ms timeout`);
      })
    ]);
  }
}
```

