## 5. Sandboxed Execution Boundary

### Capability-Based Security Model

```typescript
type Capability = 
  | 'datasource:read' 
  | 'datasource:write'
  | 'query:execute'
  | 'network:http'
  | 'network:ws'
  | 'filesystem:read'
  | 'filesystem:write'
  | 'ui:register'
  | 'ui:listen'
  | 'cryptography:sign'
  | 'cryptography:encrypt'
  | 'process:spawn';

interface CapabilityChecker {
  has(capability: Capability): boolean;
  hasAll(...capabilities: Capability[]): boolean;
  hasAny(...capabilities: Capability[]): boolean;
  require(capability: Capability): void;  // throws if missing
}

class CapabilityError extends Error {
  constructor(capability: Capability, context: string) {
    super(`Plugin denied capability: ${capability} (context: ${context})`);
    this.capability = capability;
  }
}
```

### Sandbox Implementation

```typescript
interface SandboxConfig {
  capabilities: Capability[];
  resources: ResourceLimits;
  timeout: number;
  environmentVariables?: Record<string, string>;
  // For browser/worker-based sandboxing
  workerScript?: string;
  // For process-based sandboxing
  isolateOptions?: V8.IsolateOptions;
}

class PluginSandbox {
  private worker: Worker | IsolateContext;
  private capabilities: CapabilityChecker;
  private resourceMonitor: ResourceMonitor;

  constructor(config: SandboxConfig) {
    this.capabilities = new CapabilityChecker(config.capabilities);
    this.resourceMonitor = new ResourceMonitor(config.resources);

    // Use Web Workers (browser) or Node Worker threads (server)
    if (typeof Worker !== 'undefined') {
      this.worker = new Worker(config.workerScript);
    } else {
      this.worker = new IsolateContext(config.isolateOptions);
    }
  }

  async execute<T>(
    fn: (sandbox: SandboxContext) => Promise<T>,
    timeout: number
  ): Promise<T> {
    return Promise.race([
      this.executeInWorker(fn),
      delay(timeout).then(() => {
        throw new TimeoutError(`Plugin execution exceeded ${timeout}ms`);
      })
    ]);
  }

  private async executeInWorker<T>(
    fn: (sandbox: SandboxContext) => Promise<T>
  ): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = randomId();

      const handler = (msg: WorkerMessage) => {
        if (msg.id !== id) return;

        this.worker.removeEventListener('message', handler);
        this.worker.removeEventListener('error', errorHandler);

        if (msg.type === 'success') {
          resolve(msg.result);
        } else if (msg.type === 'error') {
          reject(new Error(msg.error));
        }
      };

      const errorHandler = (err: ErrorEvent) => {
        this.worker.removeEventListener('message', handler);
        this.worker.removeEventListener('error', errorHandler);
        reject(err);
      };

      this.worker.addEventListener('message', handler);
      this.worker.addEventListener('error', errorHandler);

      this.worker.postMessage({
        type: 'execute',
        id,
        fn: fn.toString()
      });
    });
  }

  destroy(): void {
    if (this.worker instanceof Worker) {
      this.worker.terminate();
    } else {
      this.worker.dispose();
    }
  }
}

// Worker-side execution context
class SandboxContext {
  constructor(
    private capabilities: CapabilityChecker,
    private resourceMonitor: ResourceMonitor,
    private logger: Logger
  ) {}

  // APIs available to sandboxed code
  async queryData(datasourceId: string, query: Query): Promise<DataTable> {
    this.capabilities.require('datasource:read');
    this.resourceMonitor.track('query', query);
    // actual implementation
  }

  async httpRequest(config: FetchConfig): Promise<Response> {
    this.capabilities.require('network:http');
    this.resourceMonitor.track('http', config.url);
    // enforce resource limits on response size
  }

  registerUIComponent(name: string, component: UIDefinition): void {
    this.capabilities.require('ui:register');
    this.logger.info('Plugin registered UI component', { name });
  }

  // ...more API methods
}
```

### Resource Enforcement

```typescript
interface ResourceLimits {
  memory: { max: string; soft: string };  // e.g., "512Mi", "256Mi"
  cpu: { max: string; soft: string };      // e.g., "2000m", "1000m"
  disk: { max: string };                   // e.g., "1Gi"
  networkBandwidth?: { max: string };      // e.g., "100Mbps"
}

class ResourceMonitor {
  private metrics: ResourceMetrics = {};

  track(category: string, item: unknown): void {
    const size = estimateSize(item);
    this.metrics[category] = (this.metrics[category] || 0) + size;

    if (this.exceedsSoftLimit(category)) {
      this.logger.warn('Plugin approaching soft resource limit', { category });
    }

    if (this.exceedsHardLimit(category)) {
      throw new ResourceExhaustedError(`Hard limit exceeded for ${category}`);
    }
  }

  report(): ResourceReport {
    return {
      timestamp: now(),
      metrics: { ...this.metrics }
    };
  }
}
```

