## 6. Versioned API Contract

### API Versioning Strategy

**Rule**: Breaking changes require a new `apiVersion`. Minor/patch changes are backward-compatible within a version.

```typescript
// v1 API - stable, widely supported
interface PluginAPIv1 {
  query: DataQueryAPI;
  datasource: DataSourceAPI;
  ui: UIRegistrationAPI;
  events: EventEmitterAPI;
}

// v2 API - adds new capabilities, no breaking changes to v1
interface PluginAPIv2 extends PluginAPIv1 {
  cache: CacheAPI;
  schedule: SchedulerAPI;
  customTypes: TypeDefinitionAPI;
}

// When introducing breaking change:
// interface PluginAPIv3 extends Omit<PluginAPIv2, 'deprecated'> {
//   newAPI: ReplacementAPI;
// }
```

### API Surface

```typescript
// All plugins get this object in their context
interface PluginHost {
  version: string;  // e.g., "2.5.0"
  apiVersion: string;  // e.g., "v1" or "v2"

  // Data access
  data: {
    query(datasourceId: string, sql: string, options?: QueryOptions): Promise<DataTable>;
    getDatasources(): Promise<DatasourceInfo[]>;
    createDataset(name: string, data: unknown[]): Promise<string>;
  };

  // UI registration & rendering
  ui: {
    registerComponent(
      name: string,
      definition: ComponentDefinition,
      options?: RegisterComponentOptions
    ): string;  // returns component ID

    registerVisualization(
      name: string,
      config: VisualizationConfig
    ): string;

    invalidate(componentId: string): void;
  };

  // Events & observability
  events: {
    on(eventName: string, listener: EventListener): void;
    emit(eventName: string, payload: unknown): void;
    once(eventName: string, listener: EventListener): void;
  };

  // Storage & caching (v2+)
  storage?: {
    get(key: string): Promise<unknown>;
    set(key: string, value: unknown, ttl?: Duration): Promise<void>;
    delete(key: string): Promise<void>;
  };

  // Scheduling (v2+)
