### Version Negotiation

```typescript
// Plugin declares what API versions it supports
// manifest.spec.compatibility.apiVersion can be:
// - Exact: "v1"
// - Range: "v1 || v2"
// - Constraint: ">=v1, <v3"

class APIDispatcher {
  dispatch(pluginId: string): PluginHost {
    const manifest = this.registry.get(pluginId);
    const requested = manifest.spec.compatibility.apiVersion;
    const available = this.host.supportedVersions;

    const negotiated = semver.maxSatisfying(available, requested);
    if (!negotiated) {
      throw new CompatibilityError(
        `Plugin ${pluginId} requires API version ${requested}, host supports ${available}`
      );
    }

    return this.getAPIVersion(negotiated);
  }

  getAPIVersion(version: string): PluginHost {
    switch (version) {
      case 'v1': return new APIv1();
      case 'v2': return new APIv2();
      default: throw new Error(`Unknown API version: ${version}`);
    }
  }
}
