## 8. Distribution & Integrity

### Package Format

```
plugin-name-1.2.3.tar.gz
├── manifest.json
├── plugin.js                  (webpack bundle)
├── plugin.js.map              (source map)
├── ui/
│   ├── index.html
│   └── bundle.js
├── README.md
├── LICENSE
├── .checksums                 (SHA256 hashes)
└── .signature                 (cryptographic signature)
```

### Integrity Verification

```typescript
interface IntegrityVerification {
  sign(bundle: PluginBundle, privateKey: string): CryptographicSignature;
  verify(bundle: PluginBundle, publicKey: string): Promise<boolean>;
}

class PluginPackageSigner {
  async sign(bundlePath: string, privateKeyPath: string): Promise<void> {
    const files = await readDir(bundlePath);
    const checksums = new Map<string, string>();

    for (const file of files) {
      if (file === '.signature') continue;
      const content = await readFile(path.join(bundlePath, file));
      checksums.set(file, sha256(content));
    }

    const manifest = JSON.stringify({
      timestamp: now(),
      checksums: Object.fromEntries(checksums)
    }, null, 2);

    const privateKey = await readFile(privateKeyPath);
    const signature = sign(manifest, privateKey);

    await writeFile(
      path.join(bundlePath, '.signature'),
      JSON.stringify(signature, null, 2)
    );
  }

  async verify(bundlePath: string, publicKeyPath: string): Promise<boolean> {
    const signature = JSON.parse(
      await readFile(path.join(bundlePath, '.signature'), 'utf-8')
    );

    const files = (await readDir(bundlePath)).filter(f => f !== '.signature');
    const checksums = new Map<string, string>();

    for (const file of files) {
      const content = await readFile(path.join(bundlePath, file));
      checksums.set(file, sha256(content));
    }

    const manifest = JSON.stringify({
      timestamp: signature.timestamp,
      checksums: Object.fromEntries(checksums)
    }, null, 2);

    const publicKey = await readFile(publicKeyPath);
    return verify(manifest, signature.value, publicKey);
  }
}
```

