## 13. Example: Building a Custom Datasource Plugin

```typescript
// src/plugin.ts
import { PluginLifecycle, PluginContext, HealthStatus } from '@reporting/plugin-sdk';

interface PostgresConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;  // encrypted in manifest
  maxConnections?: number;
}

export default class PostgresDatasourcePlugin implements PluginLifecycle {
  private context: PluginContext;
  private config: PostgresConfig;
  private pool: pg.Pool;

  async onLoad(context: PluginContext): Promise<void> {
    this.context = context;
    this.config = context.config as PostgresConfig;

    this.context.logger.info('PostgreSQL datasource loading', {
      host: this.config.host
    });

    // Create connection pool
    this.pool = new pg.Pool({
      host: this.config.host,
      port: this.config.port,
      database: this.config.database,
      user: this.config.user,
      password: this.config.password,
      max: this.config.maxConnections || 10
    });

    this.pool.on('error', (err) => {
      this.context.logger.error('Pool error', { err });
    });
  }

  async onReady(context: PluginContext): Promise<void> {
    // Register the datasource with the reporting tool
    context.capabilities.require('datasource:write');

    context.host.data.registerDatasource({
      id: 'postgres',
      name: 'PostgreSQL',
      description: 'Direct PostgreSQL queries',
      capabilities: ['adhoc', 'templated', 'schema-inference'],
      queryHandler: (sql: string) => this.executeQuery(sql)
    });
  }

  async onBeforeUnload(context: PluginContext): Promise<void> {
    // Drain connection pool gracefully
    context.logger.info('Draining connection pool');
    await this.pool.drain();
  }

  async onUnload(context: PluginContext): Promise<void> {
    // Force close remaining connections
    await this.pool.end();
    context.logger.info('Pool closed');
  }

  async onHealthCheck(): Promise<HealthStatus> {
    try {
      const client = await this.pool.connect();
      await client.query('SELECT 1');
      client.release();

      return {
        healthy: true,
        timestamp: new Date().toISOString()
      };
    } catch (err) {
      return {
        healthy: false,
        reason: `Database connection failed: ${err.message}`,
        timestamp: new Date().toISOString()
      };
    }
  }

  private async executeQuery(sql: string): Promise<DataTable> {
    const client = await this.pool.connect();
    try {
      const result = await client.query(sql);
      return this.convertResult(result);
    } finally {
      client.release();
    }
  }

  private convertResult(result: pg.QueryResult): DataTable {
    // Convert pg result to DataTable format
    return {
      columns: result.fields.map(f => ({ name: f.name, type: mapPgType(f.dataTypeID) })),
      rows: result.rows,
      rowCount: result.rowCount
    };
  }
}
```

